'use strict';

/* =================================================================
   COINFOLK 3 — Make it rain
   1. Monetization  (the only place that talks to ads and payments)
   2. Game data     (worlds, coin materials, machines, upgrades,
                     monsters, items, achievements and the story)
   3. Save, load and migration
   4. Economy
   5. Actions
   6. Screens
   7. Modals
   8. Effects, sound and music
   9. Surprises     (golden coins, coin rain, the helicopter, monsters)
  10. Achievements
  11. Game loop and start-up
   ================================================================= */

/* --- Languages --- */
// Coinfolk is written in English. When the phone (or Settings) asks for
// another language, index.html loads a file from lang/ before this one; it
// holds the translations, keyed by the English text. tr('Text') and
// T`Text ${x}` look a text up, P(n, one, other) picks the right plural, and
// anything missing stays English, so a language never breaks the game.
const LANG = (typeof window !== 'undefined' && window.COINFOLK_LANG) || null;
// Every language, in its own words. // i18n: skip
const LANGS = [['en', 'English'], ['sv', 'Svenska'], ['de', 'Deutsch'], ['es', 'Español'], ['fr', 'Français'], ['ru', 'Русский'], ['uk', 'Українська'], ['ja', '日本語'], ['zh', '简体中文']]; // i18n: skip
const LANG_KEY = 'coinfolk-lang'; // i18n: skip
const fillIn = (text, values) => (values.length ? text.replace(/\{(\d+)\}/g, (m, i) => (i < values.length ? String(values[i]) : m)) : text);

function tr(text) {
  return (LANG && LANG.t[text]) || text;
}

// A template: the key is the English text with {0}, {1}… where the values go.
function T(parts, ...values) {
  if (!LANG) {
    let text = parts[0];
    for (let i = 0; i < values.length; i++) text += values[i] + parts[i + 1];
    return text;
  }
  let key = parts[0];
  for (let i = 0; i < values.length; i++) key += `{${i}}${parts[i + 1]}`;
  return fillIn(LANG.t[key] || key, values);
}

// Plurals: P(n, '{0} brick', '{0} bricks'). A translation can have more
// forms (Russian has three), picked by the language's own rules.
const pluralRules = LANG && typeof Intl !== 'undefined' && Intl.PluralRules ? new Intl.PluralRules(LANG.locale || LANG.code) : null;
function P(n, one, other, ...values) {
  const shown = values.length ? values : [n];
  let text = n === 1 ? one : other;
  if (LANG) {
    const forms = LANG.p && LANG.p[one];
    if (forms) text = forms[pluralRules ? pluralRules.select(n) : 'other'] || forms.other || text;
    else text = LANG.t[text] || text;
  }
  return fillIn(text, shown);
}
const listFormat = LANG && typeof Intl !== 'undefined' && Intl.ListFormat ? new Intl.ListFormat(LANG.locale || LANG.code, { style: 'long', type: 'conjunction' }) : null;
// The page is in the game's language, not always English.
if (LANG && document.documentElement) document.documentElement.lang = LANG.locale || LANG.code;

// The language picked in Settings ('auto' follows the phone).
function languageChoice() {
  try {
    return localStorage.getItem(LANG_KEY) || 'auto';
  } catch (error) {
    return 'auto';
  }
}
const languageName = code => (LANGS.find(([id]) => id === code) || LANGS[0])[1];

// The words written straight into index.html.
function translatePage() {
  if (!LANG) return;
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    const text = node.nodeValue.trim();
    if (text && LANG.t[text]) node.nodeValue = node.nodeValue.replace(text, LANG.t[text]);
  }
  document.querySelectorAll('[aria-label], [title], [placeholder]').forEach(el => {
    for (const attr of ['aria-label', 'title', 'placeholder']) {
      const value = el.getAttribute(attr);
      if (value && LANG.t[value]) el.setAttribute(attr, LANG.t[value]);
    }
  });
}

