/* -----------------------------------------------------------------
   1. MONETIZATION
   Everything here is optional for the player. In the Android app,
   ads come from AdMob and purchases from Google Play. On the website,
   ads run as a short demo and the store is closed.
   ----------------------------------------------------------------- */
const isNativeApp = () => Boolean(window.Capacitor?.isNativePlatform?.());

// AdMob rewarded ads, including the EU consent form Google requires.
const NativeAds = {
  available: false,
  loaded: false,
  loading: null,
  privacyOptions: false,
  asked: null,

  plugin() {
    return window.Capacitor?.Plugins?.AdMob;
  },

  async init() {
    const AdMob = this.plugin();
    if (!AdMob) return;
    try {
      let consent = await AdMob.requestConsentInfo();
      if (consent.isConsentFormAvailable && consent.status === 'REQUIRED') {
        consent = await AdMob.showConsentForm();
      }
      this.privacyOptions = consent.privacyOptionsRequirementStatus === 'REQUIRED';
      if (this.asked) this.asked();
      if (!consent.canRequestAds) return;
      await AdMob.initialize({ initializeForTesting: APP_CONFIG.adsTestMode });
      this.available = true;
      this.preload();
    } catch (error) {
      console.warn('Ads could not start.', error);
    }
  },

  preload() {
    const AdMob = this.plugin();
    if (!AdMob || !this.available || this.loaded || this.loading) return this.loading;
    this.loading = AdMob.prepareRewardVideoAd({ adId: APP_CONFIG.rewardedAdUnitId, isTesting: APP_CONFIG.adsTestMode })
      .then(() => { this.loaded = true; })
      .catch(error => {
        this.loaded = false;
        console.warn('Ad failed to load.', error);
      })
      .finally(() => { this.loading = null; });
    return this.loading;
  },

  // Resolves true only when Google reports that the reward was earned.
  async show() {
    const AdMob = this.plugin();
    if (!AdMob || !this.available) return false;
    if (!this.loaded) {
      await this.preload();
      if (!this.loaded) return false;
    }
    this.loaded = false;
    let rewarded = false;
    let finish;
    const closed = new Promise(resolve => {
      finish = () => setTimeout(resolve, 400); // the reward can arrive just after closing
      setTimeout(resolve, 180000); // safety net
    });
    const handles = await Promise.all([
      AdMob.addListener('onRewardedVideoAdReward', () => { rewarded = true; }),
      AdMob.addListener('onRewardedVideoAdDismissed', () => finish()),
      AdMob.addListener('onRewardedVideoAdFailedToShow', () => finish())
    ]);
    try {
      AdMob.showRewardVideoAd().then(() => { rewarded = true; }).catch(() => finish());
      await closed;
    } finally {
      handles.forEach(handle => {
        try { handle.remove(); } catch (error) { /* already gone */ }
      });
      this.preload();
    }
    return rewarded;
  },

  showPrivacyOptions() {
    const AdMob = this.plugin();
    if (AdMob) AdMob.showPrivacyOptionsForm().catch(error => console.warn(error));
  }
};

// Google Play purchases through cordova-plugin-purchase.
const NativeStore = {
  ready: false,

  init() {
    const purchase = window.CdvPurchase;
    if (!purchase) return;
    const { store, ProductType, Platform } = purchase;
    store.register(products.map(product => ({
      id: product.id,
      type: product.oneTime ? ProductType.NON_CONSUMABLE : ProductType.CONSUMABLE,
      platform: Platform.GOOGLE_PLAY
    })));
    store.when()
      .approved(transaction => {
        // New purchases are delivered once; older ones are only restored.
        transaction.products.forEach(item => (transaction.isAcknowledged ? restoreProduct(item.id) : grantProduct(item.id)));
        return transaction.finish();
      })
      .receiptUpdated(() => {
        if (store.owned('coinfolk_plus')) restoreProduct('coinfolk_plus');
      })
      .productUpdated(() => {
        if (currentScreen === 'shop') refresh();
      });
    store.error(error => console.warn('Store error', error));
    store.initialize([Platform.GOOGLE_PLAY]).then(() => {
      this.ready = true;
      refresh();
    });
  },

  price(id) {
    return window.CdvPurchase?.store.get(id)?.pricing?.price || null;
  },

  async order(id) {
    const purchase = window.CdvPurchase;
    const offer = purchase?.store.get(id)?.getOffer();
    if (!offer) {
      notify(tr('This item is not available right now. Try again later.'));
      return;
    }
    const error = await offer.order();
    if (error && error.code !== purchase.ErrorCode.PAYMENT_CANCELLED) {
      notify(tr('The purchase did not go through. You have not been charged.'));
    }
  }
};

const Monetization = {
  lastAdMessage: '',

  get adsConnected() {
    return isNativeApp() && NativeAds.available;
  },

  get paymentsConnected() {
    return isNativeApp() && NativeStore.ready;
  },

  async showRewardedAd(placement) {
    this.lastAdMessage = '';
    if (state.plus) return true; // Coinfolk Plus: ad rewards without the ad
    if (!isNativeApp()) return playDemoAd();
    if (!NativeAds.available) {
      this.lastAdMessage = tr('Ads are not available right now. Try again later.');
      return false;
    }
    const earned = await NativeAds.show();
    if (!earned) this.lastAdMessage = tr('No reward this time. The ad was closed early or did not load.');
    return earned;
  },

  // Starts a store purchase. Delivery happens when Google Play approves it.
  async purchase(productId) {
    if (!this.paymentsConnected) {
      notify(isNativeApp() ? tr('The store is still loading. Try again in a moment.') : tr('Purchases are available in the Android app.'));
      return;
    }
    await NativeStore.order(productId);
  },

  price(productId) {
    return this.paymentsConnected ? NativeStore.price(productId) : null;
  }
};

// Android back button and leaving the app (Capacitor App plugin).
const NativeApp = {
  plugin() {
    return window.Capacitor?.Plugins?.App;
  },

  init() {
    const App = this.plugin();
    if (!App) return;
    try {
      App.addListener('backButton', () => handleBack());
      App.addListener('pause', () => {
        appPaused = true;
        save();
        Music.suspend();
        Reminders.plan();
      });
      App.addListener('resume', () => {
        appPaused = false;
        Music.wake();
        Reminders.clear();
      });
    } catch (error) {
      console.warn('The back button could not be set up.', error);
    }
  },

  exit() {
    save();
    const App = this.plugin();
    if (App) App.exitApp();
  }
};

