// 3.18: goals come in many smaller steps, and they never run out. Between two
// of the old goals the new steps share that goal's diamonds, so everyone gets
// what they got before, just more often. After the last step: `more`, either
// the next nice number (1, 2, 3, 5, 7.5 × 10ⁿ), ×`times` or +`add` each time.
const GOAL_STEPS = {
  taps: { steps: [[25, 1], [50, 2], [100, 2], [200, 2], [300, 2], [500, 2], [750, 2], [1e3, 2], [2e3, 5], [3e3, 5], [5e3, 5], [7.5e3, 5], [1e4, 5], [2e4, 10], [3e4, 10], [5e4, 10], [7.5e4, 10], [1e5, 10], [2e5, 20], [3e5, 20], [5e5, 20], [7.5e5, 20], [1e6, 20]], more: { nice: true, diamonds: 20 } },
  fortune: { steps: [[100, 2], [1e3, 3], [1e4, 3], [1e5, 3], [1e6, 4], [1e7, 8], [1e8, 8], [1e9, 9], [1e10, 16], [1e11, 17], [1e12, 17], [1e13, 33], [1e14, 33], [1e15, 34], [1e16, 50], [1e17, 50], [1e18, 50]], more: { times: 10, diamonds: 50 } },
  level: { steps: [[5, 2], [10, 3], [15, 3], [20, 3], [25, 4], [30, 5], [35, 5], [40, 5], [45, 5], [50, 5], [55, 10], [60, 10], [65, 10], [70, 10], [75, 10], [80, 20], [85, 20], [90, 20], [95, 20], [100, 20], [110, 30], [120, 30], [130, 30], [140, 30], [150, 30]], more: { add: 10, diamonds: 30 } },
  worlds: { steps: [[2, 10], [3, 15], [4, 15], [5, 15], [6, 20], [7, 20], [8, 20], [9, 30], [10, 30], [11, 30], [12, 30]], more: { add: 1, diamonds: 30 } },
  bosses: { steps: [[1, 5], [2, 3], [3, 4], [4, 4], [5, 4], [7, 6], [9, 6], [11, 6], [13, 6], [15, 6], [18, 12], [21, 12], [24, 12], [27, 12], [30, 12], [36, 24], [42, 24], [48, 24], [54, 24], [60, 24]], more: { add: 10, diamonds: 25 } },
  machines: { steps: [[10, 5], [20, 2], [30, 2], [40, 3], [50, 3], [60, 4], [70, 4], [80, 4], [90, 4], [100, 4], [150, 10], [200, 15], [250, 15], [300, 15], [350, 15], [400, 15], [450, 15], [500, 15], [600, 24], [700, 24], [800, 24], [900, 24], [1000, 24]], more: { add: 100, diamonds: 25 } },
  golden: { steps: [[1, 5], [3, 5], [5, 5], [10, 5], [15, 8], [20, 8], [30, 8], [40, 8], [50, 8], [75, 20], [100, 20], [150, 20], [200, 20]], more: { add: 50, diamonds: 20 } },
  helicopters: { steps: [[1, 10], [2, 6], [3, 6], [4, 6], [5, 7], [7, 12], [10, 12], [13, 12], [16, 12], [20, 12]], more: { add: 5, diamonds: 12 } },
  monsters: { steps: [[1, 5], [3, 5], [5, 5], [10, 5], [15, 8], [20, 8], [30, 8], [40, 8], [50, 8], [75, 20], [100, 20], [150, 20], [200, 20]], more: { add: 50, diamonds: 20 } },
  secrets: { steps: [[1, 5], [4, 10], [8, 15], [16, 20], [25, 20], [40, 25], [60, 25]], more: { add: 25, diamonds: 25 } },
  loyal: { steps: [[2, 5], [3, 5], [5, 15], [7, 15], [10, 20], [14, 20], [21, 30], [30, 30]], more: { add: 30, diamonds: 30 } }
};

// The next nice number after a value: 1, 2, 3, 5, 7.5, 10, 20, 30, …
function niceAfter(value) {
  const power = Math.pow(10, Math.floor(Math.log10(value) + 1e-9));
  const next = [1, 2, 3, 5, 7.5, 10].map(m => m * power).find(n => n > value * (1 + 1e-9));
  return next || power * 10;
}

// Step n (from 0) of a goal: [goal, diamonds].
function goalStep(group, n) {
  const plan = GOAL_STEPS[group.id];
  if (n < plan.steps.length) return plan.steps[n];
  let goal = plan.steps[plan.steps.length - 1][0];
  for (let k = plan.steps.length; k <= n; k++) {
    goal = plan.more.nice ? niceAfter(goal) : plan.more.times ? goal * plan.more.times : goal + plan.more.add;
  }
  return [goal, plan.more.diamonds];
}

// A save from before 3.18 counts the old goals: as many new steps as reach that far.
function goalStepsUpTo(group, oldClaimed) {
  if (!oldClaimed) return 0;
  const reached = group.tiers[Math.min(oldClaimed, group.tiers.length) - 1][0];
  return GOAL_STEPS[group.id].steps.filter(([goal]) => goal <= reached).length;
}

