const ITEM_BY_ID = Object.fromEntries(ITEM_TYPES.map(type => [type.id, type]));
// What a treasure gives at a level (in %, or in its own unit).
const itemValue = (type, level) => Math.round(type.per * level * 100) / 100;

// How the treasures and the critter notes can be sorted.
const TREASURE_SORTS = [['rarity', tr('Rarity')], ['level', tr('Level')], ['name', tr('Name')]];
// How much moves on the screen just for show, for a calmer screen or a
// longer battery. What you play with (bosses, critters, golden coins)
// always moves.
const EFFECTS = [['all', tr('All')], ['fewer', tr('Fewer')], ['off', tr('Off')]];
const EFFECT_NOTES = {
  all: tr('Everything moves and sparkles.'),
  fewer: tr('The background holds still. No coin showers, sparks or shakes.'),
  off: tr('Nothing moves just for show. Calmest, and easiest on the battery.')
};
const effectsAll = () => state.settings.effects === 'all';
const effectsOff = () => state.settings.effects === 'off';
const CRITTER_SORTS = [['world', tr('World')], ['rarity', tr('Rarity')], ['name', tr('Name')], ['beaten', tr('Beaten')]];
// When a fight drops a treasure of the same rarity as the critter's
// favourite, this is how often it is the favourite.
const FAVORITE_DROP = 0.5;

