const GEYSER_SVG = '<svg viewBox="0 0 70 220" preserveAspectRatio="none" aria-hidden="true"><path d="M24 220C22 160 18 90 10 40C6 18 20 4 35 4S64 18 60 40C52 90 48 160 46 220Z" fill="#ff8a3c" opacity=".55"/><path d="M28 220C27 160 25 100 22 50C20 26 28 14 35 14S50 26 48 50C45 100 43 160 42 220Z" fill="#ffd27a"/><path d="M32 220C32 160 31 110 30 60C29 40 32 30 35 30S41 40 40 60C39 110 38 160 38 220Z" fill="#fff6e0"/><g fill="#ffd27a"><circle cx="8" cy="30" r="3"/><circle cx="62" cy="24" r="2.6"/><circle cx="14" cy="10" r="2"/><circle cx="56" cy="8" r="2.2"/></g><g fill="#fff" opacity=".75"><circle cx="24" cy="12" r="8"/><circle cx="40" cy="7" r="9"/><circle cx="52" cy="15" r="7"/></g></svg>';

const helperFor = number => HELPERS[worldSkin(number).id];

// The fight starts: the world's helper folds out of the background.
function helpBegin() {
  const info = boss && helperFor(boss.number);
  const stage = $('coin-stage');
  if (!info || !stage) return;
  $('world-help')?.remove();
  Object.assign(SOUNDS, HELP_SOUNDS);
  boss.help = { used: false, dazedUntil: 0 };
  const el = document.createElement('button');
  el.id = 'world-help';
  el.className = `world-help ${worldSkin(boss.number).id}`;
  el.setAttribute('aria-label', info.tip);
  el.innerHTML = `<span class="help-glow"></span><span class="help-ring"></span>${info.art}`;
  el.addEventListener('pointerdown', event => {
    event.preventDefault();
    event.stopPropagation();
    helpTap();
  });
  el.addEventListener('click', event => {
    if (event.detail === 0) helpTap();
  });
  // Before the stack of multipliers in the corner, which then makes room below it.
  stage.insertBefore(el, $('effects-row'));
  if (!$('boss-daze')) {
    const daze = document.createElement('div');
    daze.id = 'boss-daze';
    daze.className = 'boss-daze';
    daze.setAttribute('aria-hidden', 'true');
    daze.innerHTML = '<i><b></b></i><i><b></b></i><i><b></b></i>';
    stage.appendChild(daze);
  }
}

// A good read or a weak spot knocks the boss silly for a moment: now the helper glows.
function bossDaze(now = Date.now()) {
  const h = boss && boss.help;
  if (!h || h.used || boss.done) return;
  h.dazedUntil = now + HELP.daze;
  const daze = $('boss-daze');
  const point = bossPoint({ x: 50, y: 4 });
  if (daze && point) {
    daze.style.left = `${point.x.toFixed(1)}px`;
    daze.style.top = `${point.y.toFixed(1)}px`;
  }
  $('app').classList.add('boss-dazed');
  const el = $('world-help');
  if (el) {
    el.classList.remove('ready');
    void el.offsetWidth;
    el.style.setProperty('--daze', `${HELP.daze}ms`);
    el.classList.add('ready');
  }
  // The first time ever, Pip points it out right when it counts.
  if (!state.story.help) {
    state.story.help = true;
    pipSay(helperFor(boss.number).tip, 'happy', 2600, true);
  }
}

function helpCalm() {
  $('app').classList.remove('boss-dazed');
  const el = $('world-help');
  if (el) el.classList.remove('ready');
}

function helpTick(now) {
  const h = boss && boss.help;
  if (!h || !h.dazedUntil || now < h.dazedUntil) return;
  h.dazedUntil = 0;
  helpCalm();
}

function helpTap() {
  const h = boss && boss.help;
  const info = h && helperFor(boss.number);
  const el = $('world-help');
  if (!info || !el || h.used || !canHitBoss() || readsDizzy()) return;
  const hit = Date.now() < h.dazedUntil;
  h.used = true;
  h.dazedUntil = 0;
  helpCalm();
  el.classList.add('used', 'go');
  const target = bossPoint({ x: 50, y: 30 });
  if (!hit) {
    // Too soon: the boss sees it coming and steps aside.
    const app = $('app');
    app.classList.add('boss-sidestep');
    setTimeout(() => app.classList.remove('boss-sidestep'), 800);
  }
  const fighting = boss;
  const wait = helpShot(info, el, target);
  setTimeout(() => helpLand(fighting, info, target, hit), wait);
}

// What the helper drops or throws comes forward onto the boss.
function helpShot(info, el, target) {
  const layer = $('fx-layer');
  const stage = $('coin-stage');
  if (!layer || !stage || !target || calmMotion()) return 0;
  const s = stage.getBoundingClientRect();
  const fx = document.createElement('div');
  if (info.path === 'rise') {
    const feet = bossPoint({ x: 50, y: 98 }) || target;
    fx.className = 'help-geyser';
    fx.style.cssText = `left:${target.x.toFixed(1)}px;top:${feet.y.toFixed(1)}px`;
    fx.innerHTML = GEYSER_SVG;
    layer.appendChild(fx);
    setTimeout(() => fx.remove(), 1100);
    return Math.round(HELP.fly * 0.45);
  }
  const item = el.querySelector(info.path === 'beam' ? '.h-src' : '.h-item');
  const box = (item || el).getBoundingClientRect();
  const from = { x: box.left + box.width / 2 - s.left, y: box.top + box.height / 2 - s.top };
  const dx = target.x - from.x;
  const dy = target.y - from.y;
  if (info.path === 'beam') {
    fx.className = `help-beam ${info.beam}`;
    fx.style.cssText = `left:${from.x.toFixed(1)}px;top:${from.y.toFixed(1)}px;--len:${Math.hypot(dx, dy).toFixed(1)}px;--ang:${Math.atan2(dy, dx).toFixed(3)}rad`;
    fx.innerHTML = '<i></i>';
    layer.appendChild(fx);
    setTimeout(() => fx.remove(), 700);
    return Math.round(HELP.fly * 0.45);
  }
  const r = el.getBoundingClientRect();
  fx.className = `help-shot ${info.path}`;
  fx.style.cssText = `left:${(r.left - s.left).toFixed(1)}px;top:${(r.top - s.top).toFixed(1)}px;width:${r.width.toFixed(1)}px;height:${r.height.toFixed(1)}px;--dx:${dx.toFixed(1)}px;--dy:${dy.toFixed(1)}px;--t:${HELP.fly}ms`;
  fx.innerHTML = `<div class="hs-x"><div class="hs-y">${info.art}</div></div>`;
  layer.appendChild(fx);
  setTimeout(() => fx.remove(), HELP.fly + 160);
  return HELP.fly;
}

function helpLand(fighting, info, target, hit) {
  if (boss !== fighting || !boss || boss.done) return;
  const point = target || bossPoint({ x: 50, y: 30 });
  if (!hit) {
    if (point) spawnWord(point.x, point.y + 40, tr('Too soon!'), 'slip');
    sfx('miss');
    if (!state.story.helpMiss) {
      state.story.helpMiss = true;
      pipSay(info.tip, 'hurt', 3200, true);
    }
    return;
  }
  const damage = boss.max * HELP.share;
  boss.hp = Math.max(0, boss.hp - damage);
  boss.helped = (boss.helped || 0) + 1;
  if (point) {
    spawnFloat(point.x, point.y, damage, true, true);
    spawnWord(point.x, point.y - 38, info.word, 'help');
    helpBurst(point, info.tint);
  }
  sfx(info.sound);
  hitStop(140);
  shakeStage();
  flashBossMood('hurt', 700);
  buzz(45);
  bossRead(null, '', true, true);
  updateBossHud();
  afterBossDamage();
}

function helpBurst(point, tint) {
  const layer = $('fx-layer');
  if (!layer || calmMotion()) return;
  const el = document.createElement('div');
  el.className = 'help-burst';
  el.style.cssText = `left:${point.x.toFixed(1)}px;top:${point.y.toFixed(1)}px;--tint:${tint}`;
  el.innerHTML = '<i></i>'.repeat(8);
  layer.appendChild(el);
  setTimeout(() => el.remove(), 700);
}

function helpClear() {
  $('app').classList.remove('boss-dazed', 'boss-sidestep');
  $('world-help')?.remove();
  document.querySelectorAll('#fx-layer :is(.help-shot, .help-beam, .help-geyser, .help-burst)').forEach(el => el.remove());
}

// The brief's last row: what the world offers in this fight.
function helpBriefRow() {
  const info = helperFor(state.world);
  return info ? `<li class="brief-help"><span class="brief-icon">${info.art}</span><span>${info.tip}</span></li>` : '';
}
// 3.38: the wager. Before some fights the boss offers a bet on the brief: beat it
// without a single slip and the loot is doubled; slip even once and it keeps half.
// Only bosses whose tricks can trip you up offer it (otherwise it would be free),
// and never in the very first fight. 2D: it is a menu choice and a little badge.
const WAGER = { odds: 0.5, win: 2, lose: 0.5 };
const SLIP_TRICKS = ['dark', 'shield', 'gate', 'duel', 'bell', 'hide', 'jest', 'hot'];
const wagerFits = info => info.tricks.some(name => SLIP_TRICKS.includes(name));
const wagerOffer = info => state.stats.bosses >= 1 && wagerFits(info) && Math.random() < WAGER.odds;

function wagerHtml() {
  return `<div class="boss-wager"><p class="wager-line">${tr('Beat me without a single slip, and the loot is doubled. Slip even once, and I keep half.')}</p>
    <div class="wager-buttons"><button class="wager-yes" data-action="wager-yes">${tr('Deal!')}</button><button class="wager-no" data-action="wager-no">${tr('No bet')}</button></div></div>`;
}

// The answer on the brief also starts the fight (not the tap that opened it).
function wagerAnswer(yes) {
  if (!boss || !boss.intro || Date.now() < boss.intro - BOSS_FX.intro + 500) return;
  boss.wager = yes ? 'on' : null;
  beginBossFight();
  if (!yes) return;
  const stage = $('coin-stage');
  if (!stage) return;
  $('boss-wager')?.remove();
  const badge = document.createElement('div');
  badge.id = 'boss-wager';
  badge.className = 'wager-badge';
  badge.innerHTML = `<i aria-hidden="true"></i><span>${tr('Wager: no slips')}</span>`;
  stage.appendChild(badge);
  sfx('token');
}

// A slip: the bet is lost (the fight goes on).
function wagerSlip(x, y) {
  if (!boss || boss.wager !== 'on') return;
  boss.wager = 'lost';
  $('boss-wager')?.classList.add('lost');
  spawnWord(x, y - 46, tr('Wager lost!'), 'slip');
  sfx('miss');
}

const wagerFactor = won => (won.wager === 'on' ? WAGER.win : won.wager === 'lost' ? WAGER.lose : 1);

function wagerClear() {
  $('boss-wager')?.remove();
}

function wagerNote(win) {
  if (win.wager === 'won') return `<p class="loot-note">${tr('You won the wager: double loot!')}</p>`;
  if (win.wager === 'lost') return `<p class="loot-note">${tr('You lost the wager: the boss kept half the loot.')}</p>`;
  return '';
}
// 3.39: tricks of their own. Three bosses get a trick that asks a different question:
// the Bridge Troll's toll (how many?), Chef Inferno's order tickets (how fast?) and
// Foreman Dirk's loose bolt (where?). The signs and tickets are 2D so they read at a
// glance; they hang over a 2.5D boss.
const SIGNATURE = { tollStart: 2, tollMax: 5, tollHeal: 0.03, tollWin: 2500, tollMult: 2, chopMult: 2, chops: 6,
  flipLast: 650, flipMult: 3, hatBonus: 1.25, hatTap: 0.5, hatLine: 31 };

const SIGN_SOUNDS = {
  squeak: () => [[1800, 0.05, 0.02, 'square'], [2300, 0.06, 0.018, 'square'], [1700, 0.09, 0.016, 'triangle']],
  sizzle: () => [[2600, 0.18, 0.012, 'sawtooth'], [2100, 0.22, 0.01, 'sawtooth']]
};

const ORDER_ICONS = {
  chop: '<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M5 5h15.4l3.6 3.4v9.6H5Z" fill="#c8ccd6" stroke="#2a2e3a" stroke-width="1.6" stroke-linejoin="round"/><circle cx="19.4" cy="9.4" r="1.7" fill="#2a2e3a"/><path d="M7 15h15" stroke="#fff" stroke-width="1.3"/><path d="M11.4 18v9" stroke="#6a3a1e" stroke-width="4" stroke-linecap="round"/><path d="M25.6 21.6l3.2-2.2M26.8 25.6l3.4.4M23.6 27.4l1.4 2.8" stroke="#ff8a3c" stroke-width="1.7" stroke-linecap="round"/></svg>',
  simmer: '<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M6 16h20v7a5 5 0 0 1-5 5H11a5 5 0 0 1-5-5Z" fill="#6a6e78" stroke="#1a1c22" stroke-width="1.6"/><path d="M9 20h3M20 20h3" stroke="#9aa0aa" stroke-width="1.2" stroke-linecap="round"/><path d="M4 16h24" stroke="#1a1c22" stroke-width="2.2" stroke-linecap="round"/><path d="M8.6 14c0-2.6 14.8-2.6 14.8 0" fill="#8a8e98" stroke="#1a1c22" stroke-width="1.4"/><circle cx="16" cy="10.8" r="1.5" fill="#1a1c22"/><path class="steam" d="M11 8.4c-1.4-1.6 1.4-2.6 0-4.4M16 7c-1.4-1.6 1.4-2.6 0-4.4M21 8.4c-1.4-1.6 1.4-2.6 0-4.4" stroke="#c8d0da" stroke-width="1.4" fill="none" stroke-linecap="round"/></svg>',
  flip: '<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M3 23h16a4 4 0 0 0 4-4H3Z" fill="#3a3e46" stroke="#1a1c22" stroke-width="1.4" stroke-linejoin="round"/><path d="M23 20l7-2.4" stroke="#6a3a1e" stroke-width="3" stroke-linecap="round"/><g class="pancake"><ellipse cx="12" cy="12" rx="7.4" ry="2.8" fill="#f0b860" stroke="#8a5a1a" stroke-width="1.3"/><path d="M8.6 11.2q3.4-1.1 6.8 0" stroke="#fff0c0" stroke-width=".9" fill="none"/><circle cx="14.6" cy="12.6" r=".7" fill="#c8843a"/></g></svg>'
};

const LOOSE_BOLT_SVG = '<svg viewBox="0 0 40 40" aria-hidden="true"><path d="M4 9q-2.6 3.6 0 7.2M36 9q2.6 3.6 0 7.2" stroke="#ffd34d" stroke-width="2.2" fill="none" stroke-linecap="round"/><g class="bolt-head"><path d="M20 6l11 6.4v12.8L20 31.6 9 25.2V12.4Z" fill="#c8ccd6" stroke="#2a2e3a" stroke-width="2.4" stroke-linejoin="round"/><circle cx="20" cy="19" r="4.6" fill="#7a7e88" stroke="#2a2e3a" stroke-width="1.8"/><path d="M14 11.4l2.2 1.2M12 16.2l1.4.7" stroke="#fff" stroke-width="1.6" stroke-linecap="round"/><path d="M18 17l4 4" stroke="#2a2e3a" stroke-width="1.4" stroke-linecap="round"/></g></svg>';
const HAT_SVG = '<svg viewBox="20 14 60 24" aria-hidden="true"><path d="M28 32 C30 16 70 16 72 32 Z" fill="#ffcf3a" stroke="#8a6a0a" stroke-width="3"/><rect x="22" y="30" width="56" height="6" rx="3" fill="#ffcf3a" stroke="#8a6a0a" stroke-width="2.5"/><rect x="46" y="18" width="8" height="8" rx="2" fill="#e8a50a"/><path d="M58 32l3 1.6" stroke="#8a6a0a" stroke-width="1.6"/></svg>';

const hasTrick = name => Boolean(boss && BOSS_BY_ID[boss.id].tricks.includes(name));

function signatureBegin() {
  Object.assign(SOUNDS, SIGN_SOUNDS);
}

// The sign over the stage: the troll's toll board or the chef's ticket.
function signShow(kind, html) {
  const stage = $('coin-stage');
  if (!stage) return null;
  let el = $('boss-sign');
  if (!el) {
    el = document.createElement('div');
    el.id = 'boss-sign';
    el.setAttribute('aria-live', 'polite');
    stage.appendChild(el);
  }
  el.className = `boss-sign ${kind}`;
  el.innerHTML = html;
  return el;
}

function signHide() {
  $('boss-sign')?.remove();
}

/* ---------- The Bridge Troll's toll: tap exactly the number on the sign ---------- */
function tollStart(r) {
  r.tolls = (r.tolls || 0) + 1;
  const need = Math.min(SIGNATURE.tollMax, SIGNATURE.tollStart + r.tolls - 1);
  r.toll = { need, paid: 0, over: false };
  signShow('toll', `<b>${need}</b><span class="toll-slots">${'<i></i>'.repeat(need)}</span>`);
  readAura('');
  sfx('token');
}

function tollTap(x, y) {
  const toll = boss.read.toll;
  if (!toll || toll.over) return 0;
  toll.paid++;
  if (toll.paid <= toll.need) {
    document.querySelectorAll('#boss-sign .toll-slots i')[toll.paid - 1]?.classList.add('paid');
    sfx('buy');
    buzz(8, 'tap');
    return 0;
  }
  // One coin too many: he keeps the change, and it does him good.
  toll.over = true;
  boss.hp = Math.min(boss.max, boss.hp + boss.max * SIGNATURE.tollHeal);
  $('boss-sign')?.classList.add('over');
  bossSlip('none', x, y, tr('Keep the change!'));
  updateBossHud();
  return 0;
}

function tollStop(r, now) {
  const toll = r.toll;
  r.toll = null;
  signHide();
  if (!toll || toll.over) return;
  const point = bossPoint({ x: 50, y: 30 });
  if (toll.paid === toll.need) {
    // A fair toll: he steps aside, and the way is open for a moment.
    bossRead(point, tr('Fair toll!'));
    goldWindow(SIGNATURE.tollWin, SIGNATURE.tollMult);
    readAura('gold');
  } else if (point) {
    readWord(point.x, point.y - 20, tr('Too little!'), 'slip', now, 0);
  }
}

/* ---------- Chef Inferno's orders: CHOP! fast, SIMMER hands off, FLIP! on the flip ---------- */
const ORDERS = ['chop', 'simmer', 'flip'];

function ordersStart(r, now) {
  const choices = ORDERS.filter(kind => kind !== r.lastOrder);
  const kind = choices[Math.floor(Math.random() * choices.length)];
  r.lastOrder = kind;
  r.order = { kind, chops: 0, touched: false, flipAt: 0, flipUntil: 0, flipped: false };
  const word = { chop: tr('CHOP!'), simmer: tr('SIMMER'), flip: tr('FLIP!') }[kind];
  signShow(`order ${kind}`, `<span class="order-pin" aria-hidden="true"></span>${ORDER_ICONS[kind]}<b>${word}</b>`);
  if (kind === 'chop') {
    goldWindow(TRICKS.orders.last, SIGNATURE.chopMult);
    readAura('gold');
  } else if (kind === 'simmer') {
    readAura('hush');
    sfx('sizzle');
  } else {
    const room = Math.max(0, TRICKS.orders.last - 700 - SIGNATURE.flipLast);
    r.order.flipAt = now + 500 + Math.random() * room;
    readAura('hush');
  }
  sfx('token');
}

function ordersTick(r, now) {
  const order = r.order;
  if (!order || order.kind !== 'flip') return;
  if (order.flipAt && !order.flipUntil && now >= order.flipAt) {
    order.flipUntil = now + SIGNATURE.flipLast;
    $('boss-sign')?.classList.add('flipping');
    readAura('gold');
    sfx('ting');
  } else if (order.flipUntil && now >= order.flipUntil) {
    order.flipAt = 0;
    order.flipUntil = 0;
    $('boss-sign')?.classList.remove('flipping');
    readAura('');
  }
}

function ordersTap(x, y, now) {
  const r = boss.read;
  const order = r.order;
  if (!order) return 1;
  if (order.kind === 'chop') {
    order.chops++;
    return now < r.goldUntil ? r.goldMult : 1;
  }
  if (order.kind === 'simmer') {
    // Hands off the pot: a tap burns the dish (once), and hits nothing.
    if (!order.touched) {
      order.touched = true;
      bossSlip('combo', x, y, tr('Burnt!'));
    }
    return 0;
  }
  if (order.flipUntil && now < order.flipUntil) {
    if (order.flipped) return 1;
    order.flipped = true;
    bossRead({ x, y }, tr('Perfect!'), true);
    hitStop(90);
    return SIGNATURE.flipMult;
  }
  if (order.flipAt && !order.flipped) {
    bossSlip('time', x, y, tr('Too soon!'));
    return 0;
  }
  return 1;
}

function ordersStop(r) {
  const order = r.order;
  r.order = null;
  signHide();
  if (!order) return;
  const point = bossPoint({ x: 50, y: 30 });
  if (order.kind === 'simmer' && !order.touched) bossRead(point, tr('Perfect!'));
  else if (order.kind === 'chop' && order.chops >= SIGNATURE.chops) bossRead(point, tr('Chopped!'), true);
}

/* ---------- Foreman Dirk's loose bolt: knock his hard hat off ---------- */
function boltStart(now) {
  if (boss.hatOff) return;
  spawnThing('bolt', { x: 71, y: 27.5 }, now + TRICKS.bolt.last, LOOSE_BOLT_SVG, tr('A loose bolt'), boltTap);
  sfx('squeak');
}

function boltTap(item) {
  if (!boss || boss.hatOff) return;
  boss.hatOff = true;
  dropThing(item, 'popped');
  $('app').classList.add('boss-hatless');
  hatFall();
  bossRead(bossPoint({ x: 50, y: 18 }), tr('CLUNK!'));
  sfx('clang');
  shakeStage();
  // The bolt is gone for good, and so is that trick.
  const t = boss.timed;
  t.names = t.names.filter(name => name !== 'bolt');
  t.at = Date.now();
}

// The hat tumbles down and rolls away.
function hatFall() {
  const layer = $('fx-layer');
  const a = bossPoint({ x: 13, y: 5 });
  const b = bossPoint({ x: 87, y: 31.5 });
  if (!layer || !a || !b || calmMotion()) return;
  const el = document.createElement('div');
  el.className = 'hat-fall';
  el.style.cssText = `left:${a.x.toFixed(1)}px;top:${a.y.toFixed(1)}px;width:${(b.x - a.x).toFixed(1)}px;height:${(b.y - a.y).toFixed(1)}px`;
  el.innerHTML = `<i>${HAT_SVG}</i>`;
  layer.appendChild(el);
  setTimeout(() => el.remove(), 1300);
}

// Where on the boss a tap landed, in % of the coin's box.
function moverPct(x, y) {
  const stage = $('coin-stage');
  const mover = $('coin-mover');
  if (!stage || !mover) return null;
  const s = stage.getBoundingClientRect();
  const m = mover.getBoundingClientRect();
  if (!m.width || !m.height) return null;
  return { x: ((x - (m.left - s.left)) / m.width) * 100, y: ((y - (m.top - s.top)) / m.height) * 100 };
}

// While the hard hat is on, taps on it clonk for half; once it is off, every tap hits harder.
function armorFactor(x, y) {
  if (!hasTrick('bolt')) return 1;
  if (boss.hatOff) return SIGNATURE.hatBonus;
  const at = moverPct(x, y);
  if (!at || at.y >= SIGNATURE.hatLine) return 1;
  readWord(x, y, tr('Clonk!'), 'tink', Date.now());
  return SIGNATURE.hatTap;
}

function signatureClear() {
  signHide();
  $('app').classList.remove('boss-hatless', 'boss-bats', 'boss-mirage');
  ['boss-tempo', 'bat-swarm', 'cart-lane'].forEach(id => $(id)?.remove());
}

// The bolt goes when its trick ends, like the other things a trick puts on the boss.
if (!TRICK_THINGS.includes('bolt')) TRICK_THINGS.push('bolt');

/* ======================= 3.40: four more tricks of their own ======================= */
const SIGNATURE2 = { boom: 0.08, burn: 3, cannonTaps: 4, echoLow: 3, echoHigh: 5, loud: 6, bats: 2000, echoes: 5,
  crash: 0.12, mark: 0.24, near: 0.08, mirage: 3 };

Object.assign(SIGN_SOUNDS, {
  fuse: () => [[3000, 0.25, 0.008, 'sawtooth'], [2600, 0.25, 0.006, 'sawtooth']],
  boom: () => [[90, 0.3, 0.12, 'sawtooth'], [60, 0.42, 0.1, 'square']],
  bats: () => [[2400, 0.04, 0.02, 'square'], [2900, 0.04, 0.02, 'square'], [2200, 0.05, 0.018, 'square']]
});

const CANNON_SVG = '<svg viewBox="0 0 84 48" aria-hidden="true"><g class="chest"><path d="M2 30c2-4.4 12-4.4 14 0" fill="#c8945a" stroke="#3a220e" stroke-width="1.4"/><circle cx="5.4" cy="28.2" r="1.3" fill="#ffd34d" stroke="#7a5a10" stroke-width=".5"/><circle cx="12.4" cy="27.8" r="1.1" fill="#ffd34d" stroke="#7a5a10" stroke-width=".5"/><rect x="1" y="30" width="16" height="12" rx="1.5" fill="#a8743e" stroke="#3a220e" stroke-width="1.6"/><path d="M1 34h16" stroke="#3a220e" stroke-width="1.2"/><rect x="7.4" y="32.4" width="3.2" height="3.6" rx=".6" fill="#ffd34d" stroke="#7a5a10" stroke-width=".7"/></g>'
  + '<g class="cannon-turn"><path d="M26 26h28l-4 10H30Z" fill="#8a5a2e" stroke="#3a220e" stroke-width="2" stroke-linejoin="round"/><path d="M24 18C24 13 28 11 34 11H62L68 9V27L62 25H34C28 25 24 23 24 18Z" fill="#3a3e48" stroke="#14161c" stroke-width="2" stroke-linejoin="round"/><ellipse cx="25" cy="18" rx="2.6" ry="6.4" fill="#0a0c10"/><path d="M30 11.4v13.2M58 11v14" stroke="#5a5e68" stroke-width="2"/><path d="M32 14h24" stroke="#7a808c" stroke-width="2" stroke-linecap="round"/><circle cx="71" cy="18" r="3.4" fill="#3a3e48" stroke="#14161c" stroke-width="1.6"/>'
  + '<path class="fuse" d="M70 15C73 10 78 10 78 4" fill="none" stroke="#c8a060" stroke-width="1.6" stroke-dasharray="2 1.2"/><g class="fuse-spark"><circle cx="78" cy="4" r="2.6" fill="#ffd34d"/><path d="M78-1v3M78 6v3M73 4h3M80 4h3" stroke="#ff8a3c" stroke-width="1.2" stroke-linecap="round"/></g>'
  + '<g class="wheel"><circle cx="34" cy="38" r="7" fill="#6a4020" stroke="#2a160a" stroke-width="2"/><path d="M34 31v14M27 38h14" stroke="#3a220e" stroke-width="1.2"/><circle cx="34" cy="38" r="2" fill="#2a160a"/></g><g class="wheel"><circle cx="50" cy="38" r="7" fill="#6a4020" stroke="#2a160a" stroke-width="2"/><path d="M50 31v14M43 38h14" stroke="#3a220e" stroke-width="1.2"/><circle cx="50" cy="38" r="2" fill="#2a160a"/></g></g></svg>';
const BUCKET_SVG = '<svg viewBox="0 0 40 40" aria-hidden="true"><path d="M9 14C9 5 31 5 31 14" fill="none" stroke="#3a3e46" stroke-width="1.6"/><path d="M8 14h24l-3 22H11Z" fill="#9a6a3a" stroke="#2a1a0c" stroke-width="2" stroke-linejoin="round"/><path d="M14 15v20M20 15v21M26 15v20" stroke="#6a4420" stroke-width="1"/><path d="M8.6 19h22.8M10 30h20" stroke="#3a3e46" stroke-width="2"/><ellipse cx="20" cy="14" rx="11" ry="3" fill="#7ac0f0" stroke="#2a6a9a" stroke-width="1.2"/><path d="M15 13.4q2.4-1.2 4.8 0" stroke="#e8f6ff" stroke-width="1" fill="none"/></svg>';
const CART_SVG = '<svg viewBox="0 0 64 44" aria-hidden="true"><path d="M10 12C12 4 22 6 26 9C30 3 40 4 44 9C48 6 54 8 54 12Z" fill="#6a6058" stroke="#2a2420" stroke-width="1.4"/><path d="M20 8l2-1.6 1.6 1.2-1 1.8ZM36 6.6l2-1 1.2 1.4-1.6 1.2ZM46 9l1.4-.8.8 1.2-1.4.8Z" fill="#ffd34d" stroke="#7a5a10" stroke-width=".5"/><path d="M8 12h48l-5 20H13Z" fill="#7a5a3a" stroke="#2a1a0c" stroke-width="2" stroke-linejoin="round"/><path d="M10 18h44M12 25h40" stroke="#5a3a1e" stroke-width="1.4"/><path d="M7 12h50" stroke="#3a3e46" stroke-width="3" stroke-linecap="round"/><g fill="#a8acb4"><circle cx="14" cy="15" r=".9"/><circle cx="50" cy="15" r=".9"/></g><g class="wheel"><circle cx="20" cy="36" r="6" fill="#3a3e46" stroke="#14161c" stroke-width="2"/><path d="M20 31v10M15 36h10" stroke="#7a7e88" stroke-width="1.2"/></g><g class="wheel"><circle cx="44" cy="36" r="6" fill="#3a3e46" stroke="#14161c" stroke-width="2"/><path d="M44 31v10M39 36h10" stroke="#7a7e88" stroke-width="1.2"/></g></svg>';
const LEVER_SVG = '<svg viewBox="0 0 40 48" aria-hidden="true"><g class="lever-arm"><path d="M20 36L12 10" stroke="#14161c" stroke-width="6" stroke-linecap="round"/><path d="M20 36L12 10" stroke="#7a7e88" stroke-width="3.6" stroke-linecap="round"/><circle cx="12" cy="9" r="5.2" fill="#d8283a" stroke="#6a0a14" stroke-width="1.6"/><circle cx="10.4" cy="7.4" r="1.4" fill="#ff9aa0"/></g><path d="M8 34h24l3 10H5Z" fill="#6a4a2a" stroke="#22170e" stroke-width="2" stroke-linejoin="round"/><circle cx="20" cy="36" r="3" fill="#3a3e46" stroke="#14161c" stroke-width="1.4"/><path d="M10 40h20" stroke="#4a3018" stroke-width="1.2"/></svg>';
const BAT_SVG = '<svg viewBox="0 0 40 24" aria-hidden="true"><path d="M20 8C17 4 13 4 11 7C8 3 3 4 1 8C4 8 6 10 7 13C9 10 12 10 14 12C15 10 17 10 20 14C23 10 25 10 26 12C28 10 31 10 33 13C34 10 36 8 39 8C37 4 32 3 29 7C27 4 23 4 20 8Z" fill="#4a3a62" stroke="#120a1c" stroke-width="1.2"/><path d="M11 7.4C9.4 9 8 10 7 12.4M29 7.4C30.6 9 32 10 33 12.4M14 11.6L16 9M26 11.6L24 9" stroke="#8a7ab0" stroke-width=".8" fill="none"/><path d="M18 6l-1-3M22 6l1-3" stroke="#0e0a14" stroke-width="1.2" stroke-linecap="round"/><circle cx="18.4" cy="9.6" r=".9" fill="#ffd23a"/><circle cx="21.6" cy="9.6" r=".9" fill="#ffd23a"/></svg>';

// A flight from a point on the stage to the boss, then a burst (the cannonball, the cart).
function signFly(from, html, kind, ms, done) {
  const layer = $('fx-layer');
  const to = bossPoint({ x: 50, y: 40 });
  if (!layer || !from || !to || calmMotion()) {
    done(to);
    return;
  }
  const el = document.createElement('div');
  el.className = `sign-fly ${kind}`;
  el.style.cssText = `left:${from.x.toFixed(1)}px;top:${from.y.toFixed(1)}px;--dx:${(to.x - from.x).toFixed(1)}px;--dy:${(to.y - from.y).toFixed(1)}px;--t:${ms}ms`;
  el.innerHTML = `<div class="sf-x"><div class="sf-y">${html}</div></div>`;
  layer.appendChild(el);
  setTimeout(() => {
    el.remove();
    done(to);
  }, ms);
}

function bigHit(share, point, word, tint) {
  if (!boss || boss.done) return;
  const damage = boss.max * share;
  boss.hp = Math.max(0, boss.hp - damage);
  if (point) {
    spawnFloat(point.x, point.y, damage, true, true);
    spawnWord(point.x, point.y - 38, word, 'help');
    helpBurst(point, tint);
  }
  hitStop(140);
  shakeStage();
  flashBossMood('hurt', 700);
  buzz(50);
  updateBossHud();
  afterBossDamage();
}

/* ---------- Rustbeard's cannon: douse the fuse (safe) or turn the cannon (greedy) ---------- */
function cannonStart(r, now) {
  r.cannon = { turns: 0, done: false };
  const ms = TRICKS.cannon.last;
  const cannon = spawnThing('cannon', { x: -9, y: 94 }, now + ms + 400, CANNON_SVG, tr('The cannon'), cannonTap);
  if (cannon) cannon.el.style.setProperty('--fuse', `${ms}ms`);
  spawnThing('bucket', { x: 132, y: 96 }, now + ms + 400, BUCKET_SVG, tr('A bucket of water'), bucketTap);
  sfx('fuse');
}

function cannonTap(item) {
  const c = boss.read.cannon;
  if (!c || c.done) return;
  c.turns++;
  // It swings round in four steps (never edge-on, so you can always see it).
  item.el.style.setProperty('--turn', String([1, 0.62, 0.2, -0.62, -1][c.turns]));
  sfx('clack');
  buzz(10, 'tap');
  if (c.turns < SIGNATURE2.cannonTaps) return;
  // Turned all the way round: it fires at his own ship.
  c.done = true;
  item.el.classList.add('fired');
  sfx('boom');
  const box = item.el.getBoundingClientRect();
  const stage = $('coin-stage').getBoundingClientRect();
  const from = { x: box.left + box.width * 0.7 - stage.left, y: box.top + box.height * 0.38 - stage.top };
  signFly(from, '<i class="cannonball"></i>', 'ball', 300, (point) => {
    bigHit(SIGNATURE2.boom, point, tr('BOOM!'), '#ff8a3c');
    bossRead(null, '', true, true);
    boss.timed.at = Date.now();
  });
}

function bucketTap(item) {
  const c = boss.read.cannon;
  if (!c || c.done) return;
  c.done = true;
  item.el.classList.add('tipped');
  for (const thing of boss.fx) if (thing.kind === 'cannon') thing.el.classList.add('doused');
  sfx('splash');
  bossRead(bossPoint({ x: -9, y: 80 }), tr('Doused!'), true);
  boss.timed.at = Date.now() + 500;
}

function cannonStop(r, now) {
  const c = r.cannon;
  r.cannon = null;
  if (!c || c.done) return;
  // The fuse burned down: the shot hits your treasure and costs time.
  sfx('boom');
  shakeStage();
  boss.until = Math.max(now + 1000, boss.until - SIGNATURE2.burn * 1000);
  const point = bossPoint({ x: -9, y: 80 });
  if (point) {
    spawnWord(point.x + 20, point.y - 30, tr('BOOM!'), 'slip');
    spawnWord(point.x + 20, point.y, `−${SIGNATURE2.burn}s`, 'stolen');
  }
  updateBossHud();
}

/* ---------- Madame Squeak's echo cave: calm taps echo, hammering brings the bats ---------- */
function tempoStart(r) {
  r.tempo = { taps: [], echoes: 0, batsUntil: 0 };
  const stage = $('coin-stage');
  if (stage && !$('boss-tempo')) {
    const meter = document.createElement('div');
    meter.id = 'boss-tempo';
    meter.className = 'tempo-meter';
    meter.setAttribute('aria-hidden', 'true');
    meter.innerHTML = '<i></i>'.repeat(7);
    stage.appendChild(meter);
  }
  readAura('');
  sfx('echo');
}

function tempoDraw(rate) {
  const meter = $('boss-tempo');
  if (!meter) return;
  meter.querySelectorAll('i').forEach((bar, k) => bar.classList.toggle('on', k < rate));
  meter.dataset.state = rate > SIGNATURE2.loud ? 'loud' : rate >= SIGNATURE2.echoLow ? 'good' : 'slow';
}

function tempoTap(x, y, now) {
  const tempo = boss.read.tempo;
  if (!tempo) return 1;
  if (now < tempo.batsUntil) {
    readWord(x, y, tr('Bats!'), 'tink', now);
    return 0;
  }
  tempo.taps = tempo.taps.filter(at => now - at < 1000);
  tempo.taps.push(now);
  const rate = tempo.taps.length;
  tempoDraw(rate);
  if (rate > SIGNATURE2.loud) {
    // Too loud: the ring overflows and the bats pour out over the coin.
    tempo.batsUntil = now + SIGNATURE2.bats;
    tempo.taps = [];
    $('app').classList.add('boss-bats');
    batSwarm(true);
    bossSlip('none', x, y, tr('Too loud!'));
    sfx('bats');
    return 0;
  }
  if (rate >= SIGNATURE2.echoLow && rate <= SIGNATURE2.echoHigh) {
    tempo.echoes++;
    echoRing(x, y);
    return 2;
  }
  return 1;
}

// The bats pour out of the dark and flap over the coin.
function batSwarm(on) {
  $('bat-swarm')?.remove();
  const stage = $('coin-stage');
  if (!on || !stage) return;
  const swarm = document.createElement('div');
  swarm.id = 'bat-swarm';
  swarm.className = 'bat-swarm';
  swarm.setAttribute('aria-hidden', 'true');
  swarm.innerHTML = Array.from({ length: 6 }, (_, k) => `<i style="--k:${k}">${BAT_SVG}</i>`).join('');
  stage.appendChild(swarm);
}

function echoRing(x, y) {
  const layer = $('fx-layer');
  if (!layer || calmMotion()) return;
  const el = document.createElement('i');
  el.className = 'echo-ring';
  el.style.cssText = `left:${x.toFixed(1)}px;top:${y.toFixed(1)}px`;
  layer.appendChild(el);
  setTimeout(() => el.remove(), 700);
}

function tempoTick(r, now) {
  const tempo = r.tempo;
  if (!tempo) return;
  if (tempo.batsUntil && now >= tempo.batsUntil) {
    tempo.batsUntil = 0;
    $('app').classList.remove('boss-bats');
    batSwarm(false);
  }
  const rate = tempo.taps.filter(at => now - at < 1000).length;
  tempoDraw(rate);
}

function tempoStop(r) {
  const tempo = r.tempo;
  r.tempo = null;
  $('boss-tempo')?.remove();
  $('app').classList.remove('boss-bats');
  batSwarm(false);
  if (tempo && tempo.echoes >= SIGNATURE2.echoes) bossRead(bossPoint({ x: 50, y: 30 }), tr('IN TUNE!'), true);
}

/* ---------- Minecart Mike's lever: pull it as the runaway cart passes the mark ---------- */
function leverStart(r, now) {
  const ms = TRICKS.lever.last;
  r.lever = { start: now, ms, pulled: false };
  const stage = $('coin-stage');
  if (stage) {
    $('cart-lane')?.remove();
    const lane = document.createElement('div');
    lane.id = 'cart-lane';
    lane.className = 'cart-lane';
    lane.setAttribute('aria-hidden', 'true');
    lane.style.setProperty('--run', `${ms}ms`);
    lane.innerHTML = `<span class="cart-mark" style="left:${SIGNATURE2.mark * 100}%"></span><div class="cart-run"><span class="mine-cart">${CART_SVG}</span></div>`;
    stage.appendChild(lane);
  }
  spawnThing('lever', { x: 136, y: 84 }, now + ms, LEVER_SVG, tr('The lever'), leverPull);
  sfx('rumble');
}

function leverPull(item) {
  const lever = boss.read.lever;
  if (!lever || lever.pulled) return;
  lever.pulled = true;
  item.el.classList.add('pulled');
  sfx('clack');
  const progress = (Date.now() - lever.start) / lever.ms;
  const lane = $('cart-lane');
  if (Math.abs(progress - SIGNATURE2.mark) > SIGNATURE2.near) {
    // Too soon or too late: the points switch, but the cart is not there.
    const point = bossPoint({ x: 136, y: 70 });
    if (point) spawnWord(point.x - 30, point.y - 20, progress < SIGNATURE2.mark ? tr('Too soon!') : tr('Too late!'), 'slip');
    return;
  }
  // Right on the mark: the cart swings onto his track and crashes into him.
  lane?.classList.add('switched');
  const box = lane?.querySelector('.mine-cart')?.getBoundingClientRect();
  const stage = $('coin-stage').getBoundingClientRect();
  const from = box ? { x: box.left + box.width / 2 - stage.left, y: box.top + box.height / 2 - stage.top } : null;
  signFly(from, CART_SVG, 'cart', 360, (point) => {
    bigHit(SIGNATURE2.crash, point, tr('CRASH!'), '#c9a050');
    bossRead(null, '', true, true);
    boss.timed.at = Date.now();
  });
}

// The lever glows gold while the cart is on the mark.
function leverTick(r, now) {
  const lever = r.lever;
  if (!lever || lever.pulled) return;
  const near = Math.abs((now - lever.start) / lever.ms - SIGNATURE2.mark) <= SIGNATURE2.near;
  for (const item of boss.fx) if (item.kind === 'lever') item.el.classList.toggle('ready', near);
}

function leverStop(r) {
  r.lever = null;
  $('cart-lane')?.remove();
}

/* ---------- Sandy Sam's mirage: three Sams in the heat, only one with a shadow ---------- */
function mirageStart(r, now) {
  const real = Math.floor(Math.random() * SIGNATURE2.mirage);
  r.mirage = { real, found: false };
  $('app').classList.add('boss-mirage');
  [-14, 50, 114].forEach((x, k) => {
    const isReal = k === real;
    const item = spawnThing(`mirage ${isReal ? 'real' : 'fake'}`, { x, y: 52 }, now + TRICKS.mirage.last + 400,
      `${bossSvg(boss.id, 'idle')}${isReal ? '<span class="mirage-drops" aria-hidden="true"><i></i><i></i><i></i></span>' : ''}`,
      tr('Sandy Sam'), isReal ? mirageFound : mirageFake);
    if (item) item.real = isReal;
  });
  sfx('gust');
}

function mirageFound(item) {
  const m = boss.read.mirage;
  if (!m || m.found) return;
  m.found = true;
  const r = boss.read;
  dropThing(item, 'popped');
  // There he is: he jumps back out, wide open for a moment.
  r.popUntil = Date.now() + READS.pop;
  r.popFirst = false;
  goldWindow(READS.pop, READS.popMult);
  bossRead(bossPoint({ x: 50, y: 30 }), tr('Found you!'));
  boss.timed.at = Date.now();
}

function mirageFake(item) {
  const m = boss.read.mirage;
  if (!m || m.found) return;
  dropThing(item, 'popped');
  const point = bossPoint(item);
  sfx('poof');
  bossSlip('dizzy', point ? point.x : 0, point ? point.y : 0, tr('Just sand!'));
}

function mirageStop(r) {
  r.mirage = null;
  $('app').classList.remove('boss-mirage');
  for (const item of [...(boss ? boss.fx : [])]) {
    if (item.kind.startsWith('mirage')) dropThing(item);
  }
}

if (!TRICK_THINGS.includes('cannon')) TRICK_THINGS.push('cannon', 'bucket', 'lever');
/* -----------------------------------------------------------------
   6. SCREENS
   ----------------------------------------------------------------- */
function setText(id, value) {
  const el = typeof id === 'string' ? $(id) : id;
  if (el && el.textContent !== value) el.textContent = value;
}

function setHtml(id, value) {
  const el = $(id);
  if (el && el.innerHTML !== value) el.innerHTML = value;
}

function screenTitle(eyebrow, title, text) {
  return `<div class="screen-title"><div class="eyebrow">${eyebrow}</div><h2>${title}<span>.</span></h2>${text ? `<p>${text}</p>` : ''}</div>`;
}

function sectionHead(title, label = '') {
  return `<div class="section-head"><h3>${title}</h3>${label ? `<span>${label}</span>` : ''}</div>`;
}

/* --- Pictures keep their place (3.21.1) --- */
// A hidden screen stops its CSS animations and starts them over when it is
// shown again, so the coin that five fireflies made long ago popped up again on
// every return to the coin. So when the coin screen hides, note how far each
// one-off animation in the world picture and on the golden coin had come, and
// when it shows again, put each where it would be by now.
const ANIM_KEEP = ['#world-scene', '#golden-layer'];
let animKept = null;

function animsKept() {
  if (!document.getAnimations) return [];
  const roots = ANIM_KEEP.map(sel => document.querySelector(sel)).filter(Boolean);
  return document.getAnimations().filter(a => {
    const target = a.effect && a.effect.target;
    return a.animationName && target && roots.some(root => root.contains(target)) && a.effect.getComputedTiming().iterations !== Infinity;
  });
}

function animKeep() {
  animKept = { at: performance.now(), runs: new Map() };
  for (const a of animsKept()) {
    if (a.playState !== 'running') continue;
    const runs = animKept.runs.get(a.effect.target) || {};
    runs[a.animationName] = a.currentTime;
    animKept.runs.set(a.effect.target, runs);
  }
}

function animResume() {
  if (!animKept) return;
  const away = performance.now() - animKept.at;
  for (const a of animsKept()) {
    const was = (animKept.runs.get(a.effect.target) || {})[a.animationName];
    try {
      if (was != null && was + away < a.effect.getComputedTiming().endTime) a.currentTime = was + away;
      else a.finish();
    } catch (error) {
      // An animation that cannot be moved just plays.
    }
  }
  animKept = null;
}

function go(screen) {
  // Machines and upgrades share one tab (3.26).
  if (screen === 'machines') {
    screen = 'upgrades';
    workTab = 'machines';
  }
  // During a boss fight you stay with the boss.
  if (boss && screen !== 'coin') return;
  if (screen === 'city' && !state.city.open) return;
  if (screen !== 'city') cityTalkStop();
  const from = currentScreen;
  currentScreen = screen;
  stepSeenAt(from, screen);
  peekHide();
  Music.follow();
  Music.muffle((screen !== 'coin' && screen !== 'city') || !!inDialogue);
  if (inDialogue && inDialogue.opts.place && inDialogue.opts.place !== screen) dlgEnd('left');
  if (screen === 'city') setTimeout(cityTutorial, 450);
  $('app').dataset.screen = screen;
  const root = document.documentElement;
  root.classList.toggle('lock-scroll', screen === 'coin' && !root.classList.contains('coin-scrolls'));
  if (from === 'coin' && screen !== 'coin') animKeep();
  document.querySelectorAll('.screen').forEach(section => {
    section.classList.toggle('active', section.id === `screen-${screen}`);
  });
  document.querySelectorAll('.nav-item, .hud-go').forEach(item => {
    const active = item.dataset.go === screen;
    item.classList.toggle('active', active);
    if (active) item.setAttribute('aria-current', 'page');
    else item.removeAttribute('aria-current');
  });
  if (screen !== 'coin') {
    stopRain();
  } else {
    fitCoinScreen();
    if (from !== 'coin') syncMonsterWalk();
    if (from !== 'coin') animResume();
  }
  renderScreen();
  updateHud();
  updateBadges();
  window.scrollTo(0, 0);
}

// The coin screen fills the room between the top bar and the tabs exactly,
// so it never scrolls under your fingers.
function fitCoinScreen() {
  const root = document.documentElement;
  const hud = document.querySelector('.hud');
  const room = window.innerHeight - (hud ? hud.offsetHeight : 0);
  if (room > 0) root.style.setProperty('--room', `${Math.round(room)}px`);
  checkCoinFit();
}

// On a tiny screen (or half of a split one), where even the smallest coin
// leaves no room for the rest, the coin screen scrolls like the others.
// Checked whenever the coin screen changes shape (a boss fight, a new card).
function checkCoinFit() {
  const root = document.documentElement;
  const section = $('screen-coin');
  if (!section || currentScreen !== 'coin') return;
  const y = window.scrollY;
  root.classList.remove('coin-scrolls');
  // The scene and the layers for golden coins and rain float above the
  // page, so only the parts in the flow count.
  const parts = [...section.children].filter(el => el.offsetHeight > 0 && !el.matches('.world-scene, .golden-layer, .rain-layer'));
  const last = parts[parts.length - 1];
  const tight = !!last && last.getBoundingClientRect().bottom > section.getBoundingClientRect().bottom + 2;
  root.classList.toggle('coin-scrolls', tight);
  root.classList.toggle('lock-scroll', !tight);
  if (tight && y) window.scrollTo(0, y);
}

// Tapping the tab you're already on jumps to the next heading on the page,
// and from the bottom back to the top. Pages without headings go a
// screenful at a time.
function jumpOnScreen() {
  const section = $(`screen-${currentScreen}`);
  if (!section || currentScreen === 'coin') return;
  const hud = document.querySelector('.hud');
  const offset = (hud ? hud.offsetHeight : 0) + 10;
  const y = window.scrollY;
  const max = Math.max(0, document.documentElement.scrollHeight - window.innerHeight);
  const heads = [...section.querySelectorAll('.section-head')];
  const stops = heads.length ? heads : [...section.querySelectorAll('.card')];
  const step = heads.length ? 24 : window.innerHeight * 0.55;
  const next = stops.map(el => el.getBoundingClientRect().top + y - offset).find(top => top > y + step);
  const top = y >= max - 4 ? 0 : Math.min(max, next === undefined ? max : next);
  window.scrollTo({ top, behavior: 'smooth' });
}

function renderScreen() {
  if (currentScreen === 'coin') renderCoin();
  else if (currentScreen === 'upgrades') renderWorkshop();
  else if (currentScreen === 'worlds') renderWorlds();
  else if (currentScreen === 'city') renderCity();
  else if (currentScreen === 'goals') renderGoals();
  else if (currentScreen === 'shop') renderShop();
  updateScreen();
}

function refresh() {
  renderScreen();
  updateHud();
  updateBadges();
  updateBuddy();
}

// Runs four times a second: only text and button states change here,
// so buttons are never swapped out under the player's finger.
function updateScreen() {
  if (currentScreen === 'coin') updateCoin();
  else if (currentScreen === 'upgrades') {
    updateMachines();
    updateUpgrades();
    updateWorkDots();
  }
  else if (currentScreen === 'worlds') updateWorlds();
  else if (currentScreen === 'city') updateCity();
  else if (currentScreen === 'goals') updateGoals();
  else if (currentScreen === 'shop') updateShop();
  updatePrices();
}

function updatePrices() {
  document.querySelectorAll(`#screen-${currentScreen} [data-price]`).forEach(button => {
    const currency = button.dataset.currency;
    const have = currency === 'diamonds' ? state.diamonds : currency === 'bricks' ? state.city.bricks : state.balance;
    button.disabled = have < Number(button.dataset.price);
  });
}

function updateHud() {
  setText('hud-balance', format(state.balance));
  setText('hud-rate', format(income()));
  setText('hud-diamonds', format(state.diamonds));
  wardrobeCheck();
  updateTreasureButton();
}

const TROPHY_SVG = '<svg class="trophy" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3.5h10v4.5a5 5 0 0 1-10 0z" fill="currentColor"/><path d="M7 5.5H4.6a2.6 2.6 0 0 0 2.9 4.3M17 5.5h2.4a2.6 2.6 0 0 1-2.9 4.3" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="M12 13v4.5M8.5 20.5h7" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>';

function updateBadges() {
  const mark = (screen, kind) => {
    const item = document.querySelector(`.nav-item[data-go="${screen}"]`);
    if (!item) return;
    item.classList.toggle('badge', kind === 'red');
    item.classList.toggle('badge-gold', kind === 'gold');
  };
  let coinBadge = '';
  if (currentScreen !== 'coin') {
    if (golden || heli || monster) coinBadge = 'gold';
    else if (bossReady() || state.balance >= levelCost(state.coinLevel)) coinBadge = 'red';
  }
  mark('coin', coinBadge);
  const top = highestOwned();
  const newMachine = top + 1 < unlockedMachines() && state.balance >= machineCost(top + 1, 1);
  mark('upgrades', newMachine || upgrades.some((_, i) => upgradeUnlocked(i) && !upgradeMaxed(i) && state.balance >= upgradeCost(i)) ? 'red' : '');
  mark('worlds', state.bossBeaten ? 'red' : '');
  const goalsDot = $('hud-goals-dot');
  if (goalsDot) goalsDot.classList.toggle('on', goalsWaiting());
  mark('shop', dailyInfo().claimed ? '' : 'red');
  updateCityTab();
  mark('city', cityNews() ? 'gold' : cityWaiting() ? 'red' : '');
}

/* --- Coin --- */
function levelTitle() {
  const level = state.coinLevel;
  if (materialIndex(level + 1) !== materialIndex(level)) return T`Next: ${material(level + 1).name}, ×${gainText(levelGain(level))} tap power`;
  return T`Next level: +${Math.round((levelGain(level) - 1) * 100)}% tap power`;
}

function levelNote() {
  if (state.bossBeaten) return T`World cleared! The portal to ${worldInfo(state.world + 1).name} is open.`;
  const info = nextBoss();
  const at = bossLevel(info.rank);
  if (state.coinLevel >= at) return T`${info.name} is waiting. Beat ${info.rank === 2 ? tr('the ruler') : tr('this guard')} to go on.`;
  const nextMaterial = (materialIndex(state.coinLevel) + 1) * LEVEL.perMaterial;
  const name = material(nextMaterial).name;
  if (nextMaterial === at) return T`${name} and ${info.name} at level ${at}`;
  return nextMaterial < at
    ? T`${name} at level ${nextMaterial} · ${info.name} at level ${at}`
    : T`${info.name} at level ${at} · ${name} at level ${nextMaterial}`;
}

function bossCardHtml() {
  if (boss) return '';
  if (state.bossBeaten) {
    const next = worldInfo(state.world + 1);
    return T`<button class="boss-offer portal" data-action="travel-ask">
      <span class="boss-icon">${next.symbol}</span>
      <span class="offer-text"><strong>Travel to ${next.name}</strong><small>Everything earns ×${worldBonus(state.world + 1)} more there</small></span>
      <span class="boss-go">GO</span>
    </button>`;
  }
  const info = nextBoss();
  if (!info) return '';
  const rank = info.rank === 2 ? tr('The ruler') : RANK_NAMES[info.rank];
  // The next boss waits a few levels ahead, so you can see it coming.
  if (!bossReady()) {
    return T`<div class="boss-offer locked">
      <span class="boss-face">${bossSvg(info.id)}</span>
      <span class="offer-text"><strong>Next: ${info.name}</strong><small>${rank} · ${info.title}</small></span>
      <span class="boss-lock">LV ${bossLevel(info.rank)}</span>
    </div>`;
  }
  if (bossResting()) {
    return T`<button class="boss-offer resting" data-action="boss-start">
      <span class="boss-face">${bossSvg(info.id, 'happy')}</span>
      <span class="offer-text"><strong>Pip is resting</strong><small>${info.name} waits · ready in <b id="rest-left">${restLeft()}</b></small></span>
      <span class="boss-lock rest" aria-hidden="true">${PLASTER_SVG}</span>
    </button>`;
  }
  return T`<button class="boss-offer" data-action="boss-start">
    <span class="boss-face">${bossSvg(info.id, 'angry')}</span>
    <span class="offer-text"><strong>${info.name} is here!</strong><small>${rank} · ${format(bossHp(state.world, info.rank))} HP · ${bossSeconds()} s</small></span>
    <span class="boss-go">FIGHT</span>
  </button>`;
}

function renderCoin() {
  const info = world();
  // If the label needs two lines, the world's name stays together on the second.
  setText('world-label', T`WORLD ${state.world} · ${info.name.toUpperCase().replace(/ /g, '\u00a0')}`);
  setText('coin-symbol', info.symbol);
  applyCoinLook();
  const level = state.coinLevel;
  const cost = levelCost(level);
  $('coin-card').innerHTML = T`<div class="card level-card">
    <div class="item-icon coin-chip">${info.symbol}</div>
    <div class="item-info">
      <div class="eyebrow">Coin level ${format(level)} · ${material(level).name}</div>
      <div class="item-title">${levelTitle()}</div>
      <div class="progress"><span id="level-progress"></span></div>
      <div class="item-desc small">${levelNoteHtml()}</div>
    </div>
    <button class="buy-button" data-action="level-up" data-price="${cost}">✦ ${format(cost)}<small>LEVEL UP</small></button>
  </div>`;
  $('boss-card').innerHTML = bossCardHtml();
  const locked = $('boss-card').querySelector('.boss-offer.locked');
  const upcoming = locked && nextBoss();
  if (upcoming) {
    locked.dataset.action = 'peek-boss';
    locked.dataset.id = upcoming.id;
    locked.setAttribute('role', 'button');
  }
  $('boost-offer').innerHTML = `<button class="boost-pill" id="offer-button" data-action="ad-boost">
    <span class="boost-play" id="offer-icon">▶</span>
    <span class="boost-text"><strong id="offer-title"></strong><small id="offer-sub"></small></span>
  </button>`;
  checkCoinFit();
}

// Everything that multiplies your coins, stacked in the corner of the coin
// stage: lasting ones on top, short bonuses below. They sit outside the flow
// of the page, so nothing moves when one comes or goes. The 2× boost shows
// on its own button under the logo.
function effectsHtml() {
  // Each chip has a rank: when there are more than three, the two that
  // matter most right now show, and a "+N" chip opens the rest.
  const chips = [];
  const chip = (rank, kind, name, value) => chips.push({ rank, html: `<span class="effect-chip ${kind}"><small>${name}</small><b>${value}</b></span>` });
  if (state.world > 1) chip(4, '', T`${world().symbol} World`, `×${format(worldMult())}`);
  if (state.plus) chip(5, 'purple', tr('Plus'), '2×');
  if (state.perks.auto > 0) chip(6, '', tr('Auto'), `${state.perks.auto}/s`);
  if (state.streak > 0) chip(3, 'streak', T`✹ Streak ${state.streak}`, `+${Math.round((streakMult() - 1) * 100)}%`);
  const running = BOOST_KINDS.filter(kind => boostLeft(kind) > 0);
  if (running.length > 1) chip(2, 'gold boost-total', tr('2× boosts'), `${boostMult()}×`);
  const boostNames = { ad: tr('2× income'), bun: tr('Fresh bun'), rush: tr('Coin Rush') };
  // The ad's 2× has its own button; it gets a chip only to show how the boosts add up.
  for (const kind of running) {
    if (kind !== 'ad' || running.length > 1) chip(running.length > 1 ? 7 : 2, `boost boost-${kind}`, boostNames[kind], `2× · ${clock(boostLeft(kind))}`);
  }
  const frenzy = frenzyRemaining();
  if (frenzy > 0) chip(1, 'gold', tr('Frenzy'), `${FRENZY.power}× · ${Math.ceil(frenzy)}s`);
  const surge = surgeRemaining();
  if (surge > 0) chip(1, 'gold', tr('Tap Surge'), `${SURGE.power}× · ${Math.ceil(surge)}s`);
  const hands = handsRemaining();
  if (hands > 0) chip(1, 'gold', tr('Helping Hands'), `${HANDS.taps}/s · ${Math.ceil(hands)}s`);
  const mania = maniaRemaining();
  if (mania > 0) chip(1, 'green', tr('Machine Mania'), `${MANIA.power}× · ${Math.ceil(mania)}s`);
  if (chips.length <= EFFECT_CHIPS.max || effectsOpen > Date.now()) return chips.map(c => c.html).join('');
  const keep = chips.map((c, i) => ({ ...c, i })).sort((a, b) => a.rank - b.rank || a.i - b.i).slice(0, EFFECT_CHIPS.max - 1).map(c => c.i);
  return chips.filter((_, i) => keep.includes(i)).map(c => c.html).join('')
    + `<span class="effect-chip more"><small>${tr('more')}</small><b>+${chips.length - keep.length}</b></span>`;
}

// The combo meter: a bar that fills while you tap and drains smoothly.
function updateComboMeter() {
  const meter = $('combo-meter');
  if (!meter) return;
  const off = !comboOn();
  if (meter.classList.contains('hidden') !== off) {
    meter.classList.toggle('hidden', off);
    checkCoinFit();
  }
  if (off) return;
  const share = Math.min(combo.value, COMBO.max) / COMBO.max;
  const cover = $('combo-cover');
  if (cover) cover.style.width = `${((1 - share) * 100).toFixed(1)}%`;
  setText('combo-mult', `×${comboMult().toFixed(2)}`);
  meter.classList.toggle('active', combo.value > 0);
  meter.classList.toggle('max', combo.value >= COMBO.max);
}

function updateCoin() {
  freshMark();
  scenePlanetUpdate();
  setText('balance', format(state.balance));
  setText('per-click', format(clickPower()));
  setText('per-second', format(income()));
  setHtml('effects-row', effectsHtml());
  updateNextStep();
  updateComboMeter();
  $('coin-button').classList.toggle('frenzy', frenzyRemaining() > 0);
  const bar = $('level-progress');
  if (bar) bar.style.width = `${Math.min(100, (state.balance / levelCost(state.coinLevel)) * 100)}%`;
  if (boss) updateBossHud();
  updateBoostPill();
}

// The small 2× button under the logo: what it gives, or how long is left.
function updateBoostPill() {
  const button = $('offer-button');
  if (!button) return;
  const left = adsLeft('boost');
  const remaining = boostLeft('ad');
  const running = remaining > 0;
  const full = remaining >= AD.boostCapMinutes * 60 - 30;
  let title = tr('2× income');
  let sub;
  let label;
  if (running) title = clock(remaining);
  if (left < 1) {
    sub = running ? tr('no boosts left') : tr('back tomorrow');
    label = T`No free boosts left today${running ? T`. 2× income: ${clock(remaining)} left` : ''}`;
  } else if (full) {
    sub = tr('full');
    label = T`2× income: ${clock(remaining)} left. The boost is full`;
  } else if (running) {
    sub = T`+${AD.boostMinutes} min`;
    label = T`2× income: ${clock(remaining)} left. Add ${AD.boostMinutes} more minutes. ${left} left today`;
  } else {
    sub = T`${AD.boostMinutes} min · ${state.plus ? tr('free') : tr('ad')}`;
    label = T`2× income for ${AD.boostMinutes} minutes. ${state.plus ? tr('Plus: no ad needed') : tr('Watch a short ad')}. ${left} left today`;
  }
  setText('offer-title', title);
  setText('offer-sub', sub);
  fitLine($('offer-title'), 8.5);
  fitLine($('offer-sub'), 7.5);
  setText('offer-icon', running ? '2×' : '▶');
  if (button.getAttribute('aria-label') !== label) button.setAttribute('aria-label', label);
  button.classList.toggle('running', running);
  button.disabled = left < 1 || full;
}

function updateBossHud() {
  if (!boss) return;
  const now = boss.paused || Date.now();
  const left = boss.intro ? boss.seconds : Math.max(0, Math.ceil((boss.until - now) / 1000));
  setText('boss-time', `${left}s`);
  setText('boss-hp', `${format(boss.hp)} / ${format(boss.max)} HP`);
  const bar = $('boss-bar');
  if (bar) bar.style.width = `${(boss.hp / boss.max) * 100}%`;
  setText('boss-tip', bossTip());
  $('boss-hud').classList.toggle('grimy', boss.grime.length > 0);
}

// One line under the boss bar about what is going on right now.
function bossTip() {
  if (boss.done) return '';
  if (boss.intro) return BOSS_BY_ID[boss.id].title;
  if (boss.grime.length) return TRICKS[boss.blob].tip;
  if (boss.timed && boss.timed.phase === 'on') return TRICKS[boss.timed.name].tip;
  if (boss.rank === 2 && boss.hp / boss.max <= 0.5) return tr('It\'s angry and dodging. Keep after it!');
  if (boss.dodge) return TRICKS.dodge.tip;
  if (state.stats.bosses < 3) return tr('Tap the glowing weak spots for 5× damage.');
  return '';
}

/* --- Upgrades --- */
function upgradeEffect(i) {
  const level = state.upgradeLevels[i];
  switch (i) {
    case U.GOLDEN: return T`×${format(Math.pow(1.5, level))} tap power`;
    case U.OIL: return T`×${format(Math.pow(1.25, level))} machine income`;
    case U.LUCKY: return T`${level * 2}% lucky taps`;
    case U.TRAINER: return T`${bossSeconds()} s per fight`;
    case U.ECHO: return T`${level * 2}% of /sec per tap`;
    case U.MAGNET: return T`+${level * 10}% golden coins`;
    default: return '';
  }
}

// The ×1 / ×10 / ×100 / Max switch, shared by Upgrades and Machines.
function buyModeSwitch(action, current, label) {
  return `<div class="segmented" role="group" aria-label="${label}">${[1, 10, 100, 0].map(mode => `<button data-action="${action}" data-index="${mode}" class="${current === mode ? 'active' : ''}" aria-pressed="${current === mode}">${mode === 0 ? tr('Max') : `×${mode}`}</button>`).join('')}</div>`;
}

function renderUpgrades() {
  let html = '';
  html += buyModeSwitch('upgrade-mode', state.settings.upgradeBuy, tr('How many levels to buy'));
  html += '<div class="list">';
  let teased = false;
  upgrades.forEach((upgrade, i) => {
    if (!upgradeUnlocked(i)) {
      // Only the next one to unlock shows, as with the machines.
      if (teased) return;
      teased = true;
      html += T`<div class="card dim">
        <div class="item-icon">?</div>
        <div class="item-info">
          <div class="item-title">${upgrade.name} <span class="pill">WORLD ${upgrade.world}</span></div>
          <div class="item-desc">Unlocks in ${worldInfo(upgrade.world).name}.</div>
        </div>
      </div>`;
      return;
    }
    const level = state.upgradeLevels[i];
    const { amount, cost } = upgradeQuote(i);
    html += T`<div class="card">
      <div class="item-icon ${upgrade.color || ''}">${upgrade.icon}</div>
      <div class="item-info">
        <div class="item-title">${upgrade.name} <span class="pill">Lv ${level}${upgrade.max ? ` / ${upgrade.max}` : ''}</span></div>
        <div class="item-desc">${upgrade.description} <b>${upgradeEffect(i)}</b></div>
      </div>
      ${upgradeMaxed(i)
        ? tr('<button class="buy-button" disabled>MAX</button>')
        : `<button class="buy-button" data-action="buy-upgrade" data-index="${i}" data-upgrade="${i}" data-price="${cost}"><span class="cost">✦ ${format(cost)}</span><small class="qty">${amount > 1 ? T`+${amount} LEVELS` : tr('UPGRADE')}</small></button>`}
    </div>`;
  });
  html += '</div>';
  $('upgrades-part').innerHTML = html;
}

// In Max mode the number of levels follows your coins.
function updateUpgrades() {
  if (state.settings.upgradeBuy !== 0) return;
  document.querySelectorAll('#screen-upgrades [data-upgrade]').forEach(button => {
    const { amount, cost } = upgradeQuote(Number(button.dataset.upgrade));
    button.dataset.price = String(cost);
    setText(button.querySelector('.cost'), `✦ ${format(cost)}`);
    setText(button.querySelector('.qty'), amount > 1 ? T`+${amount} LEVELS` : tr('UPGRADE'));
  });
}

// A row of buttons to choose how a list is sorted.
function sortSwitch(action, current, options, label) {
  return T`<div class="sort-row"><span>Sort</span><div class="segmented" role="group" aria-label="${label}">${options.map(([id, name]) => `<button data-action="${action}" data-sort="${id}" class="${current === id ? 'active' : ''}" aria-pressed="${current === id}">${name}</button>`).join('')}</div></div>`;
}

// The treasures you have, in the order you chose.
function treasureList() {
  const order = new Map(ITEM_TYPES.map((type, i) => [type.id, i]));
  const found = ITEM_TYPES.filter(type => itemLevel(type.id) > 0);
  const by = {
    rarity: (a, b) => b.rarity - a.rarity || order.get(a.id) - order.get(b.id),
    level: (a, b) => itemLevel(b.id) - itemLevel(a.id) || b.rarity - a.rarity || order.get(a.id) - order.get(b.id),
    name: (a, b) => a.item.localeCompare(b.item)
  }[state.settings.treasureSort];
  return found.sort(by || ((a, b) => b.rarity - a.rarity || order.get(a.id) - order.get(b.id)));
}

function treasureCard(type) {
  const level = itemLevel(type.id);
  const info = RARITIES[type.rarity];
  const maxed = level >= type.max;
  return T`<button class="treasure r-${info.id}${maxed ? ' maxed' : ''}" data-action="treasure" data-id="${type.id}" aria-label="${info.name} ${type.item}, level ${level} of ${type.max}">
    <b>${type.icon}<i class="treasure-count">${maxed ? tr('MAX') : T`Lv ${level}`}</i></b>
    <span>${type.item}</span>
    <i class="rarity-tag ${info.id}">${info.name}</i>
    <em>${treasureEffect(type, level)}</em>
  </button>`;
}

// A treasure still to find shows its rarity, so you know what to hunt for.
function lockedTreasure(type) {
  const info = RARITIES[type.rarity];
  return T`<div class="treasure locked r-${info.id}"><b>?</b><span>???</span><i class="rarity-tag ${info.id}">${info.name}</i><em>Not found yet</em></div>`;
}

const treasureKinds = () => ITEM_TYPES.filter(type => itemLevel(type.id) > 0).length;

// Treasures from fights, kept forever, in their own window.
function treasuresHtml() {
  const found = ITEM_TYPES.filter(type => itemLevel(type.id) > 0);
  let html = collectionTabs('treasures') + T`<div class="eyebrow">${found.length} OF ${ITEM_TYPES.length} FOUND · KEPT FOREVER</div>`;
  if (!found.length) {
    return T`${html}<div class="card dim">
      <div class="item-icon purple">❦</div>
      <div class="item-info"><div class="item-title">No treasures yet</div><div class="item-desc">Monsters walk past the coin now and then. Tap one and win the fight to get a treasure.</div></div>
    </div>`;
  }
  html += sortSwitch('treasure-sort', state.settings.treasureSort, TREASURE_SORTS, tr('Sort your treasures'));
  html += `<div class="treasure-grid">${treasureList().map(treasureCard).join('')}</div>`;
  const missing = ITEM_TYPES.filter(type => !itemLevel(type.id)).sort((a, b) => a.rarity - b.rarity);
  if (missing.length) html += `<div class="treasure-grid">${missing.map(lockedTreasure).join('')}</div>`;
  html += T`<p class="note">Every treasure has one rarity. Find it again and it goes up a level. ${format(state.stats.items)} found in ${format(state.stats.monsters + state.stats.bosses)} fights. Tap one to see how far it can go.</p>`;
  return html;
}

// The chest at the top opens the collection; a dot for new treasures and
// new achievements.
function updateTreasureButton() {
  const dot = $('hud-coll-dot');
  if (dot) dot.classList.toggle('on', treasureKinds() > state.treasuresSeen || newAchievements().length > 0 || wardrobeNew());
}

/* --- Machines --- */
function machineCard(i) {
  const machine = machines[i];
  const count = state.machineCounts[i];
  const next = MILESTONES.find(m => m > count);
  const previous = MILESTONES.filter(m => m <= count).pop() || 0;
  const progress = next ? ((count - previous) / (next - previous)) * 100 : 100;
  const { amount, cost } = machineQuote(i);
  return T`<div class="card">
    <div class="item-icon green">${machine.icon}</div>
    <div class="item-info">
      <div class="item-title">${machine.name} <span class="pill">${format(count)} owned</span></div>
      <div class="item-desc">${machine.description} <b>+${format(machineEach(i))}/s each</b></div>
      <div class="progress green"><span style="width:${progress}%"></span></div>
      <div class="item-desc small">${next ? T`${format(count)} / ${format(next)} → income ×2` : tr('Every milestone reached!')}</div>
    </div>
    <button class="buy-button green" data-action="buy-machine" data-index="${i}" data-machine="${i}" data-price="${cost}"><span class="cost">✦ ${format(cost)}</span><small class="qty">BUY ×${amount}</small></button>
  </div>`;
}

function renderMachines() {
  const lastShown = Math.min(unlockedMachines() - 1, highestOwned() + 1);
  let html = '';
  html += buyModeSwitch('buy-mode', state.settings.buy, tr('How many to buy'));
  html += '<div class="list">';
  for (let i = 0; i <= lastShown; i++) html += machineCard(i);
  const next = lastShown + 1;
  if (next < machines.length) {
    const text = machineUnlocked(next)
      ? T`Unlocks after your first ${machines[lastShown].name}.`
      : T`Unlocks in World ${machines[next].world}: ${worldInfo(machines[next].world).name}.`;
    html += `<div class="card dim">
      <div class="item-icon">?</div>
      <div class="item-info"><div class="item-title">???</div><div class="item-desc">${text}</div></div>
    </div>`;
  }
  html += '</div>';
  $('screen-machines').innerHTML = html;
}

function updateMachines() {
  if (state.settings.buy !== 0) return;
  document.querySelectorAll('#screen-machines [data-machine]').forEach(button => {
    const { amount, cost } = machineQuote(Number(button.dataset.machine));
    button.dataset.price = String(cost);
    setText(button.querySelector('.cost'), `✦ ${format(cost)}`);
    setText(button.querySelector('.qty'), T`BUY ×${amount}`);
  });
}

/* --- Worlds --- */
const worldsKey = () => `${state.friends.join()}|${state.buddy}|${state.daily.days}|${state.settings.critterSort}|${state.world}|${Math.min(state.coinLevel, targetLevel())}|${state.guards}|${state.bossBeaten}|${Boolean(boss)}|${state.stats.bestWorld}|${state.stats.monsters}|${state.stats.bosses}|${wardrobeKey()}|${Object.values(state.places.done).join()}`;

function renderWorlds() {
  const info = world();
  const next = worldInfo(state.world + 1);
  const target = targetLevel();
  const reached = Math.min(state.coinLevel, target);
  const levelDone = state.coinLevel >= target || state.bossBeaten;
  const upNext = nextBoss();
  let button;
  if (state.bossBeaten) button = T`<button class="wide-button" data-action="travel-ask">Travel to ${next.name}</button>`;
  else if (bossReady()) button = T`<button class="wide-button red" data-action="boss-start">Fight ${upNext.name}</button>`;
  else button = T`<button class="wide-button" disabled>Coin level ${bossLevel(upNext.rank)} needed</button>`;
  // The three bosses of this world, in order.
  const bossSteps = bossesOf().map((info, k) => {
    const done = k < nextRank();
    const level = bossLevel(info.rank);
    const status = done ? tr('Beaten') : k === nextRank() && state.coinLevel >= level ? tr('Ready') : T`Lv ${level}`;
    return `<div class="world-step boss-step ${done ? 'done' : ''}"><b>${done ? '✓' : k + 2}</b><span class="boss-mini">${bossSvg(info.id, done ? 'ko' : 'idle')}</span><span>${info.name}<small>${info.rank === 2 ? tr('Ruler · opens the portal') : RANK_NAMES[info.rank]}</small></span><em>${status}</em></div>`;
  }).join('');
  let html = screenTitle(tr('THE GREAT JOURNEY'), tr('Worlds'), tr('Grow your coin, beat the three bosses of each world and travel on. Every new world multiplies everything you earn.')) + exploreCardHtml();
  html += T`<div class="panel world-panel">
    <div class="world-top">
      <span class="world-symbol">${planetSvg(state.world)}</span>
      <div class="world-heading"><div class="eyebrow">World ${state.world} · you are here</div><div class="world-name">${info.name}</div></div>
      <span class="pill gold">×${format(worldMult())}</span>
    </div>
    <div class="world-steps">
      <div class="world-step ${levelDone ? 'done' : ''}"><b>${levelDone ? '✓' : '1'}</b><span>Grow your coin to level ${target}</span><em>${format(reached)} / ${target}</em></div>
      ${bossSteps}
      <div class="world-step"><b>5</b><span>Travel to ${next.name}</span><em>${state.bossBeaten ? tr('Ready') : ''}</em></div>
    </div>
    <div class="progress"><span style="width:${Math.min(100, (reached / target) * 100)}%"></span></div>
    ${button}
    <p class="note">Travelling starts over with coins, coin level, machines and upgrades. ${state.city.open ? tr('You keep diamonds, Forever boosts, your city, goals and stats.') : tr('You keep diamonds, Forever boosts, goals and stats.')}</p>
  </div>`;
  const unlocks = unlocksIn(state.world + 1);
  html += sectionHead(T`Next: ${next.name}`, T`everything ×${format(worldMult(state.world + 1))}`);
  html += `<div class="list">${(unlocks.length ? unlocks : [tr('A tougher boss and bigger rewards')]).map(text => `<div class="card slim">
      <div class="item-icon">${next.symbol}</div>
      <div class="item-info"><div class="item-desc">${text}</div></div>
    </div>`).join('')}</div>`;
  const last = Math.max(WORLDS.length, state.world + 2);
  html += sectionHead(tr('Your journey'), T`${state.world - 1} cleared`);
  html += '<div class="world-map">' + Array.from({ length: last }, (_, k) => {
    const number = k + 1;
    const place = worldInfo(number);
    const status = number < state.world ? 'done' : number === state.world ? 'current' : 'locked';
    const known = number <= state.world + 1;
    const label = status === 'done' ? tr('✓ Cleared') : status === 'current' ? tr('You are here') : T`World ${number}`;
    if (!known) return T`<button class="map-world locked" data-action="peek" aria-label="World ${number}, not found yet"><b>?</b><span>???</span><em>${label}</em></button>`;
    return `<div class="map-world ${status}"><b class="map-planet">${planetSvg(number, 'still')}</b><span>${place.name}</span><em>${label}</em></div>`;
  }).join('') + '</div>';
  html += journalHtml();
  $('screen-worlds').innerHTML = html;
  worldsSignature = worldsKey();
}

// Pip's journal: one chapter for every world you have reached.
function journalChapters() {
  const reached = Math.min(state.stats.bestWorld, WORLDS.length);
  const list = [];
  for (let number = 1; number <= reached; number++) {
    list.push({ index: number - 1, number, title: STORY.chapters[number - 1].title, place: WORLDS[number - 1].name, symbol: WORLDS[number - 1].symbol });
  }
  if (state.stats.bestWorld > WORLDS.length) {
    list.push({ index: STORY.chapters.length, number: WORLDS.length + 1, title: STORY.lap.title, place: tr('The journey goes on'), symbol: '↺' });
  }
  return list;
}

function journalHtml() {
  const chapters = journalChapters();
  let html = sectionHead(tr('Pip’s journal'), P(chapters.length, '{0} chapter', '{0} chapters'));
  html += T`<div class="journal">
    <button class="journal-pip" data-action="pip" aria-label="Say hi to Pip">${pipSvg()}</button>
    <p>Pip writes down every world you visit. Tap a chapter to read it again.</p>
  </div>`;
  html += '<div class="list">' + chapters.map(chapter => T`<button class="card chapter-card" data-action="chapter" data-index="${chapter.index}">
      <span class="item-icon">${chapter.symbol}</span>
      <span class="item-info"><span class="item-title">Chapter ${chapter.number}: ${chapter.title}</span><span class="item-desc">${chapter.place}</span></span>
      <span class="chapter-go">READ</span>
    </button>`).join('') + '</div>';
  html += friendsHtml();
  html += bestiaryHtml();
  html += bossBookHtml();
  return html;
}

// Pip's friends: the ones who came to stay, and shadows of the rest.
function friendsHtml() {
  const count = state.friends.length;
  let html = sectionHead(tr('Pip’s friends'), `${count} of ${FRIENDS.length}`);
  html += '<div class="friends-grid">' + FRIENDS.map((friend, k) => {
    if (state.friends.includes(friend.id)) {
      const buddy = state.buddy === friend.id;
      return T`<button class="critter friend${buddy ? ' buddy' : ''}" data-action="friend" data-id="${friend.id}" aria-label="${friend.name}, Pip's friend">${buddy ? tr('<b class="buddy-tag">WITH PIP</b>') : ''}${friendSvg(friend.id)}<span>${friend.name}</span><em>${friendPerk(friend)}</em></button>`;
    }
    if (friend.planet) return `<div class="critter friend unknown">${friendSvg(friend.id)}<span>???</span><em>${T`On ${worldInfo(friend.planet).name}`}</em></div>`;
    // Friend number k comes with gift number 7 × (k + 1).
    const wait = Math.max(1, GIFT.week * (k + 1) - state.daily.days);
    return `<div class="critter friend unknown">${friendSvg(friend.id)}<span>???</span><em>${k === count ? P(wait, 'In {0} gift', 'In {0} gifts') : tr('Later')}</em></div>`;
  }).join('') + '</div>';
  html += tr('<p class="note">A friend comes to stay with every 7th daily gift, and helps a little for good. Tap one to let them sit with Pip.</p>');
  return html;
}

function buddyButton(friend) {
  return state.buddy === friend.id
    ? T`<button class="modal-action" disabled>✓ ${friend.name} sits with Pip</button>`
    : T`<button class="modal-action" data-action="set-buddy" data-id="${friend.id}">Let ${friend.name} sit with Pip</button>`;
}

// The friend who sits with Pip by the coin.
let buddyShown = null;
function updateBuddy() {
  const el = $('stage-buddy');
  const id = state.buddy || '';
  const shown = id ? `${id}|${outfitOf(id)}` : '';
  if (!el || buddyShown === shown) return;
  buddyShown = shown;
  el.classList.toggle('hidden', !id);
  el.innerHTML = id ? friendSvg(id) : '';
  el.setAttribute('aria-label', id ? T`${FRIEND_BY_ID[id].name}, Pip's friend` : tr('Pip\'s friend'));
}

let buddyTimer;
function pokeBuddy() {
  const friend = FRIEND_BY_ID[state.buddy];
  const el = $('stage-buddy');
  if (!friend || !el) return;
  el.classList.remove('hop');
  void el.offsetWidth;
  el.classList.add('hop');
  buddySay(friend.lines[Math.floor(Math.random() * friend.lines.length)], 2800);
  if (!state.settings.voices) sfx('pip');
  buzz(10);
}

// Pip's notes on the Baron's critters: the ones you have beaten, and shadows of the rest.
function bestiaryHtml() {
  let html = sectionHead(tr('Critters'), T`${kindsBeaten()} of ${MONSTERS.length} beaten`);
  html += sortSwitch('critter-sort', state.settings.critterSort, CRITTER_SORTS, tr('Sort the critters'));
  const order = new Map(MONSTERS.map((kind, i) => [kind.id, i]));
  const wins = kind => state.bestiary[kind.id] || 0;
  const inOrder = (a, b) => order.get(a.id) - order.get(b.id);
  const by = {
    rarity: (a, b) => b.rarity - a.rarity || inOrder(a, b),
    // Critters you haven't met yet have no name, so they come last.
    name: (a, b) => (wins(b) > 0) - (wins(a) > 0) || (wins(a) ? a.name.localeCompare(b.name) : inOrder(a, b)),
    beaten: (a, b) => wins(b) - wins(a) || inOrder(a, b)
  }[state.settings.critterSort] || inOrder;
  html += '<div class="bestiary">' + [...MONSTERS].sort(by).map(kind => {
    const wins = state.bestiary[kind.id] || 0;
    const rarity = rarityOf(kind);
    const inner = `${monsterSvg(kind.id)}<span>${wins ? kind.name : '???'}</span><b class="rarity-tag ${rarity.id}">${rarity.name}</b><em>${wins ? T`Beaten ×${format(wins)}` : T`Lives in World ${kind.world}`}</em>`;
    if (!wins) return `<div class="critter unknown">${inner}</div>`;
    return T`<button class="critter${kind.tale ? ' folk' : ''}" data-action="critter" data-id="${kind.id}" aria-label="${kind.name}: read Pip's notes">${inner}</button>`;
  }).join('') + '</div>';
  return html;
}

// Pip's notes on the bosses: the ones you have beaten, and shadows of the rest.
function bossBookHtml() {
  let html = sectionHead(tr('Bosses'), T`${bossKinds()} of ${BOSSES.length} beaten`);
  html += '<div class="bestiary boss-book">' + BOSSES.map(info => {
    const wins = state.bossLog[info.id] || 0;
    return `<div class="critter${wins ? '' : ' unknown'}">${bossSvg(info.id)}<span>${wins ? info.name : '???'}</span><em>${wins ? T`Beaten ×${format(wins)}` : `${WORLDS[info.world - 1].name} · ${info.rank === 2 ? tr('ruler') : tr('guard')}`}</em></div>`;
  }).join('') + '</div>';
  return html;
}

function updateWorlds() {
  if (worldsKey() !== worldsSignature) renderWorlds();
}

/* --- Goals --- */
const goalsKey = () => goalGroups.map(group => {
  const status = goalState(group);
  return `${status.tier}${status.ready ? 'r' : ''}`;
}).join(',') + `|${state.achievements.length}|${state.achievementsSeen}|${state.quests.day}|${state.quests.list.map(quest => `${quest.id}${questReady(quest) ? 'r' : ''}${quest.claimed ? 'c' : ''}`).join()}|${state.quests.bonus}`;

// Today's three quests, and a bonus for doing all of them.
function questsHtml() {
  ensureQuests();
  const quests = state.quests;
  const done = quests.list.filter(quest => quest.claimed).length;
  let html = sectionHead(tr('Daily quests'), T`${done} of ${quests.list.length} done · new ones tomorrow`);
  html += '<div class="list">' + quests.list.map((quest, i) => {
    const def = QUEST_BY_ID[quest.id];
    const ready = questReady(quest);
    const share = Math.min(100, (quest.progress / quest.goal) * 100);
    return `<div class="card quest${ready ? ' highlight' : ''}${quest.claimed ? ' dim' : ''}">
      <div class="item-icon green">${def.icon}</div>
      <div class="item-info">
        <div class="item-title">${def.text(quest.goal)}</div>
        <div class="progress green"><span id="quest-bar-${i}" style="width:${share.toFixed(1)}%"></span></div>
        <div class="item-desc small"><span id="quest-value-${i}">${format(Math.floor(quest.progress))}</span> / ${format(quest.goal)}</div>
      </div>
      <button class="buy-button green" data-action="claim-quest" data-index="${i}" ${ready ? '' : 'disabled'}>${quest.claimed ? '✓' : ready ? tr('Claim') : `◆ ${def.reward}`}<small>${quest.claimed ? tr('DONE') : ready ? `+${def.reward} ◆` : tr('REWARD')}</small></button>
    </div>`;
  }).join('') + '</div>';
  if (quests.list.length) {
    const ready = questBonusReady();
    html += `<button class="wide-button ${quests.bonus ? '' : 'purple'} quest-bonus" data-action="claim-quest-bonus" ${ready ? '' : 'disabled'}>${quests.bonus ? T`All done today! ${questBonusText()} collected` : ready ? T`Claim the daily bonus: ${questBonusText()}` : T`Finish all three for ${questBonusText()} more`}</button>`;
  }
  return html;
}

function goalCard(group) {
  const status = goalState(group);
  if (status.done) {
    return T`<div class="card dim">
      <div class="item-icon purple">${group.icon}</div>
      <div class="item-info"><div class="item-title">${group.name} <span class="pill green">DONE</span></div><div class="item-desc">Every reward collected.</div></div>
    </div>`;
  }
  const progress = Math.min(100, (status.value / status.goal) * 100);
  return `<div class="card ${status.ready ? 'highlight' : ''}">
    <div class="item-icon purple">${group.icon}</div>
    <div class="item-info">
      <div class="item-title">${group.name} <span class="pill">${T`Lv ${status.tier + 1}`}</span></div>
      <div class="item-desc"><span id="goal-value-${group.id}">${format(Math.min(status.value, status.goal))}</span> / ${format(status.goal)} ${group.unit}</div>
      <div class="progress purple"><span id="goal-bar-${group.id}" style="width:${progress}%"></span></div>
    </div>
    <button class="buy-button purple" data-action="claim-goal" data-id="${group.id}" ${status.ready ? '' : 'disabled'}>${status.ready ? tr('Claim') : `◆ ${status.reward}`}<small>${status.ready ? `+${status.reward} ◆` : tr('REWARD')}</small></button>
  </div>`;
}

function renderGoals() {
  const ready = goalGroups.filter(group => goalState(group).ready).length;
  let html = screenTitle(tr('LITTLE WINS ADD UP'), tr('Goals'), ready ? P(ready, 'You have {0} reward waiting.', 'You have {0} rewards waiting.') : tr('Reach goals and finish daily quests to earn free diamonds.'));
  html += questsHtml();
  html += sectionHead(tr('Goals'));
  const all = goalsReady();
  if (all.count > 1) html += `<button class="wide-button purple claim-all" data-action="claim-all-goals">${T`Claim all · +${all.total} ◆`}</button>`;
  html += '<div class="list">' + goalGroups.map(goalCard).join('') + '</div>';
  html += achievementsCard();
  html += sectionHead(tr('Your story so far'));
  html += T`<div class="stats-grid">
    <div><span>Taps</span><strong id="stat-taps">${format(state.stats.taps)}</strong></div>
    <div><span>Coins earned</span><strong id="stat-lifetime">${format(state.stats.lifetime)}</strong></div>
    <div><span>Best coin level</span><strong>${format(state.stats.bestLevel)}</strong></div>
    <div><span>Bosses beaten</span><strong>${format(state.stats.bosses)}</strong></div>
    <div><span>Monsters beaten</span><strong>${format(state.stats.monsters)}</strong></div>
    <div><span>Best streak</span><strong>${format(state.stats.bestStreak)} wins</strong></div>
    <div><span>Daily quests</span><strong>${format(state.stats.quests)}</strong></div>
    <div><span>Items found</span><strong>${format(state.stats.items)}</strong></div>
    <div><span>Golden coins</span><strong>${format(state.stats.golden)}</strong></div>
    <div><span>Helicopters</span><strong>${format(state.stats.helicopters)}</strong></div>
    <div><span>Time played</span><strong id="stat-time">${formatDuration(state.stats.playSeconds)}</strong></div>
    <div><span>Days in a row</span><strong>${P(state.daily.best, '{0} day', '{0} days')}</strong></div>
  </div>`;
  $('screen-goals').innerHTML = html;
  goalsSignature = goalsKey();
}

function achievementsCard() {
  const got = state.achievements.length;
  const fresh = newAchievements().length;
  return T`${sectionHead(tr('Achievements'), `${got} of ${ACHIEVEMENTS.length}`)}
    <button class="card link-card" data-action="open-achievements">
      <span class="item-icon trophy-icon">${TROPHY_SVG}</span>
      <span class="item-info"><span class="item-title">${got} of ${ACHIEVEMENTS.length} unlocked${fresh ? T` <span class="pill gold">${fresh} NEW</span>` : ''}</span><span class="item-desc">+${got}% taps and income so far. Some achievements are secret.</span></span>
      <span class="chapter-go">OPEN</span>
    </button>`;
}

function achBadge(ach) {
  const done = hasAchievement(ach.id);
  const hidden = ach.secret && !done;
  const fresh = achNewIds.includes(ach.id);
  let bar = '';
  if (!done && ach.stat) {
    const share = Math.min(100, (ach.stat() / achTarget(ach)) * 100);
    bar = `<i class="ach-bar"><i style="width:${share.toFixed(1)}%"></i></i>`;
  }
  return `<button class="ach${done ? ' done' : ''}${ach.secret ? ' secret' : ''}" data-action="ach-info" data-id="${ach.id}" aria-label="${hidden ? tr('Secret achievement') : ach.name}">
    ${fresh ? tr('<em class="ach-new">NEW</em>') : ''}<b>${hidden ? '?' : ach.icon}</b><span>${hidden ? '???' : ach.name}</span>${bar}
  </button>`;
}

function updateGoals() {
  if (goalsKey() !== goalsSignature) {
    renderGoals();
    return;
  }
  goalGroups.forEach(group => {
    const status = goalState(group);
    if (status.done) return;
    setText(`goal-value-${group.id}`, format(Math.min(status.value, status.goal)));
    const bar = $(`goal-bar-${group.id}`);
    if (bar) bar.style.width = `${Math.min(100, (status.value / status.goal) * 100)}%`;
  });
  state.quests.list.forEach((quest, i) => {
    setText(`quest-value-${i}`, format(Math.floor(quest.progress)));
    const bar = $(`quest-bar-${i}`);
    if (bar) bar.style.width = `${Math.min(100, (quest.progress / quest.goal) * 100).toFixed(1)}%`;
  });
  setText('stat-taps', format(state.stats.taps));
  setText('stat-lifetime', format(state.stats.lifetime));
  setText('stat-time', formatDuration(state.stats.playSeconds));
}

/* --- Shop --- */
const CHEST_SVG = '<svg class="gift-chest" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 9.2 C3 5.9 5.5 3.5 8.6 3.5 h6.8 c3.1 0 5.6 2.4 5.6 5.7 Z" fill="currentColor"/><path d="M3 10.6 h7.4 v2.8 h3.2 v-2.8 H21 V19 a2 2 0 0 1 -2 2 H5 a2 2 0 0 1 -2 -2 Z" fill="currentColor"/></svg>';

// A gift in a few characters, for the calendar.
function giftIcon(gift) {
  if (gift.kind === 'coins') return '✦';
  if (gift.kind === 'boost') return '2×';
  if (gift.kind === 'treasure') return CHEST_SVG;
  if (gift.kind === 'friend') {
    const friend = nextFriend();
    return friend ? `<span class="gift-friend">${friendSvg(friend.id)}</span>` : '◆';
  }
  return '◆';
}

function giftShort(gift) {
  if (gift.kind === 'coins' || gift.kind === 'boost') return `${gift.minutes}m`;
  if (gift.kind === 'treasure') return tr('GIFT');
  if (gift.kind === 'friend') return nextFriend() ? tr('FRIEND') : giftDiamonds(gift.amount + GIFT.allFriends);
  return giftDiamonds(gift.amount);
}

// What the claim button says.
function claimLabel(gift) {
  if (gift.kind === 'coins') return T`Claim ✦ ${format(giftCoins(gift.minutes))}`;
  if (gift.kind === 'boost') return T`Claim 2× income for ${gift.minutes} min`;
  if (gift.kind === 'treasure') return tr('Open today\'s treasure');
  if (gift.kind === 'friend' && nextFriend()) return tr('Meet your new friend!');
  return T`Claim +${giftDiamonds(gift.amount + (gift.kind === 'friend' ? GIFT.allFriends : 0))} ◆`;
}

// This week of the calendar, and how far it is to the next friend.
function giftCalendar(info) {
  const start = (info.week - 1) * GIFT.week;
  const days = GIFTS.slice(start, start + GIFT.week).map((gift, k) => {
    const day = start + k + 1;
    const done = info.claimed ? day <= info.day : day < info.day;
    const now = !info.claimed && day === info.day;
    return T`<div class="daily-day gift-${gift.kind} ${done ? 'done' : ''} ${now ? 'today' : ''}"><span>DAY ${day}</span><i>${done ? '✓' : giftIcon(gift)}</i><b>${done ? '' : giftShort(gift)}</b></div>`;
  }).join('');
  const toGo = GIFT.week - (state.daily.days % GIFT.week);
  let line;
  if (!nextFriend()) line = tr('All of Pip\'s friends are here!');
  else if (toGo === 1 && !info.claimed) line = tr('A new friend comes today!');
  else if (toGo === 1) line = tr('A new friend comes tomorrow!');
  else line = T`Next friend in ${toGo} gifts`;
  return T`<div class="daily-track">${days}</div>
    <div class="gift-line"><span>Week ${info.week} of ${GIFTS.length / GIFT.week}</span><span>${line}</span></div>`;
}

function foreverEffect(perk) {
  const level = state.perks[perk.id];
  if (perk.id === 'offline') return T`${offlineCapHours()} h in total`;
  if (perk.id === 'auto') return T`${state.perks.auto} taps/s now`;
  if (perk.id === 'lure') return T`+${Math.round(level * MONSTER.lureStep * 100)}% monsters now`;
  return T`+${level * 10}% now`;
}

function productCard(product) {
  const owned = product.oneTime && state.owned.includes(product.id);
  const ready = Monetization.paymentsConnected;
  const waiting = isNativeApp() ? tr('LOADING') : tr('IN APP');
  const label = owned ? tr('OWNED') : ready ? (Monetization.price(product.id) || tr('BUY')) : waiting;
  const tag = product.tag ? ` <span class="pill ${product.diamonds ? 'purple' : 'gold'}">${product.tag}</span>` : '';
  return `<div class="card ${product.id === 'coinfolk_plus' ? 'highlight' : ''}">
    <div class="item-icon ${product.diamonds ? 'purple' : ''}">${product.icon}</div>
    <div class="item-info"><div class="item-title">${product.name}${tag}</div><div class="item-desc">${product.description}</div></div>
    <button class="buy-button ${product.diamonds ? 'purple' : ''}" data-action="buy-product" data-id="${product.id}" ${owned || !ready ? 'disabled' : ''}>${label}<small>${owned ? tr('THANK YOU') : product.oneTime ? tr('ONE TIME') : tr('DIAMONDS')}</small></button>
  </div>`;
}

// In the app, only items that exist on Google Play are shown, so the game
// also works with ads only. Items appear by themselves once you create them.
function shopProducts() {
  if (!Monetization.paymentsConnected) return products;
  return products.filter(product => NativeStore.price(product.id) || (product.oneTime && state.owned.includes(product.id)));
}

const shopKey = () => {
  const info = dailyInfo();
  return `${info.claimed}|${info.day}|${state.daily.days}|${state.friends.length}|${freeLevelIndex()}|${state.free.watched}|${freeWait() > 0}|${state.plus}|${state.owned.join()}|${Monetization.paymentsConnected}|${shopProducts().map(product => product.id).join()}`;
};

// Free diamonds: the level, what each one gives, the way to the next level and the wait.
function freeCardHtml() {
  const index = freeLevelIndex();
  const level = FREE_LEVELS[index];
  const next = FREE_LEVELS[index + 1];
  const waiting = freeWait() > 0;
  const share = next ? ((state.free.watched - level.at) / (next.at - level.at)) * 100 : 100;
  const toNext = next
    ? P(next.at - state.free.watched, 'Watch {0} more for level {1}: {2}.', 'Watch {0} more for level {1}: {2}.', next.at - state.free.watched, index + 2, freeRewardText(next))
    : tr('The highest level. Thank you for watching!');
  return `<div class="list spaced"><div class="card free-card">
    <div class="item-icon purple">▶</div>
    <div class="item-info">
      <div class="item-title">${tr('Free diamonds')} <span class="pill purple">${T`LEVEL ${index + 1}`}</span></div>
      <div class="item-desc"><b class="free-now">${freeRewardText(level)}</b>${state.plus ? tr('Plus members skip the ad.') : tr('Watch a short ad if you feel like it.')}</div>
      <div class="free-bar" aria-hidden="true"><i style="width:${Math.min(100, share).toFixed(1)}%"></i></div>
      <small class="free-next">${toNext}</small>
      <small class="free-rule">${T`A new one every ${FREE.wait} minutes, or every ${FREE.slowWait} after ${FREE.slowAfter} in a day.`}</small>
    </div>
    <button class="buy-button purple" data-action="ad-diamonds" ${waiting ? 'disabled' : ''}>+${level.diamonds} ◆<small id="free-wait">${waiting ? clock(freeWait()) : state.plus ? tr('COLLECT') : tr('▶ WATCH')}</small></button>
  </div></div>`;
}

function renderShop() {
  const info = dailyInfo();
  syncFree();
  let html = screenTitle(tr('A LITTLE EXTRA SPARKLE'), tr('Shop'), tr('Diamonds buy boosts that make your empire shine, and plenty of them are free.'));
  html += sectionHead(tr('Free every day'), tr('No strings attached'));
  html += T`<div class="panel daily-panel">
    <div class="daily-head"><strong>Daily gift</strong><span class="pill purple">DAY ${info.day} OF ${GIFTS.length}</span></div>
    ${giftCalendar(info)}
    <button class="wide-button purple" data-action="claim-daily" ${info.claimed ? 'disabled' : ''}>${info.claimed ? tr('Come back tomorrow') : claimLabel(info.gift)}</button>
    <p class="note">Skip a day and nothing is lost: the next gift waits for you. Every 7th gift, one of Pip's friends comes to stay.</p>
  </div>`;
  html += freeCardHtml();
  html += sectionHead(tr('Boosts'), tr('Paid with diamonds'));
  html += '<div class="list">' + boosts.map(item => T`<div class="card">
    <div class="item-icon">${item.icon}</div>
    <div class="item-info"><div class="item-title">${item.name}</div><div class="item-desc">${item.description}${item.id === 'rush' ? ' <b id="rush-left"></b>' : ''}</div></div>
    <button class="buy-button purple" data-action="buy-boost" data-id="${item.id}" data-price="${item.cost}" data-currency="diamonds">◆ ${item.cost}<small>USE</small></button>
  </div>`).join('') + '</div>';
  html += sectionHead(tr('Forever boosts'), tr('Kept when you travel'));
  html += '<div class="list">' + forever.map(perk => {
    const level = state.perks[perk.id];
    const cost = foreverCost(perk);
    return T`<div class="card">
      <div class="item-icon purple">${perk.icon}</div>
      <div class="item-info">
        <div class="item-title">${perk.name} <span class="pill">Lv ${level}${perk.max ? ` / ${perk.max}` : ''}</span></div>
        <div class="item-desc">${perk.description} <b>${foreverEffect(perk)}</b></div>
      </div>
      ${foreverMaxed(perk)
        ? tr('<button class="buy-button" disabled>MAX</button>')
        : T`<button class="buy-button purple" data-action="buy-forever" data-id="${perk.id}" data-price="${cost}" data-currency="diamonds">◆ ${cost}<small>UPGRADE</small></button>`}
    </div>`;
  }).join('') + '</div>';
  const forSale = shopProducts();
  if (forSale.length) {
    html += sectionHead(tr('Support Coinfolk'), tr('Optional'));
    html += '<div class="list">' + forSale.map(productCard).join('') + '</div>';
    html += T`<p class="note store-note">Everything in Coinfolk can be earned for free. Purchases only make it faster, and they help keep Coinfolk growing.${isNativeApp() ? '' : tr(' Purchases are available in the Android app.')}</p>`;
  }
  $('screen-shop').innerHTML = html;
  shopSignature = shopKey();
}

function updateShop() {
  if (shopKey() !== shopSignature) {
    renderShop();
    return;
  }
  const remaining = boostLeft('rush');
  setText('rush-left', remaining > 0 ? T`Active · ${clock(remaining)} left` : '');
  if (freeWait() > 0) setText('free-wait', clock(freeWait()));
}

/* --- The City --- */
const isNight = (date = new Date()) => date.getHours() >= CITY.night[0] || date.getHours() < CITY.night[1];
// Where the sun (by day) or the moon (by night) is: low on the left when it
// rises, high at the top in the middle of its time, low on the right before it sets.
function skySpot(date = new Date()) {
  const [dusk, dawn] = CITY.night;
  const hours = date.getHours() + date.getMinutes() / 60;
  const night = isNight(date);
  const start = night ? dusk : dawn;
  const length = night ? 24 - dusk + dawn : dusk - dawn;
  const t = Math.min(1, Math.max(0, (((hours - start) % 24) + 24) % 24 / Math.max(1, length)));
  return { x: r1(252 + 90 * t), y: r1(72 - 44 * Math.sin(Math.PI * t)) };
}
const cityAt = (x, y) => `left:${((x / CITY_VIEW.w) * 100).toFixed(2)}%;top:${((y / CITY_VIEW.h) * 100).toFixed(2)}%`;
const lockedText = b => (b.world > WORLDS.length ? tr('A gift from the King, once the story is over.') : T`Opens in World ${b.world}.`);

// What a building does at a level, in a few words (for the cards) …
function buildingShort(b, level) {
  if (b.id === 'works') return T`${CITY.works[level - 1]} bricks an hour`;
  if (b.id === 'bakery') return T`a bun for ${CITY.bun[level - 1]} min of 2×`;
  if (b.id === 'market') return level > 1 ? T`3 offers a day, ${Math.round(CITY.discount * (level - 1) * 100)}% off` : tr('3 offers a day');
  return `+${b.per * level}% ${ITEM_BY_ID[b.perk].effect}`;
}
// … and in full (for the window).
function buildingAt(b, level) {
  if (b.id === 'works') return T`${CITY.works[level - 1]} bricks an hour, up to ${CITY.works[level - 1] * CITY.worksHours}`;
  if (b.id === 'bakery') return T`A bun every ${CITY.bunHours} hours: 2× income for ${CITY.bun[level - 1]} minutes`;
  return buildingShort(b, level);
}

// Ready for you: what the Brickworks has made, and the Bakery's bun.
function cityChores() {
  let html = '';
  if (cityLevel('works')) html += T`<button class="chore" id="chore-works" data-action="collect-works"><span class="chore-icon brick">${BRICK_ICON}</span><span class="chore-text"><b id="works-title">Brickworks</b><small id="works-note"></small></span></button>`;
  if (cityLevel('bakery')) html += T`<button class="chore" id="chore-bun" data-action="eat-bun"><span class="chore-icon bun">${BUN_ICON}</span><span class="chore-text"><b id="bun-title">Bakery</b><small id="bun-note"></small></span></button>`;
  if (html) return `<div class="city-chores">${html}</div>`;
  return T`<p class="note city-hint">Start with the <b>Brickworks</b>: it makes bricks even while you're away.</p>`;
}

function updateChores() {
  if (cityLevel('works')) {
    const ready = worksReady();
    const full = ready >= worksCap();
    const button = $('chore-works');
    if (button) {
      button.disabled = ready < 1;
      button.classList.toggle('full', full);
    }
    setText('works-title', ready ? P(ready, 'Collect {0} brick', 'Collect {0} bricks') : tr('Brickworks'));
    setText('works-note', full ? tr('Full! Collect them') : T`Next brick in ${clock(worksNext())}`);
    const bubble = $('bubble-works');
    if (bubble) {
      bubble.classList.toggle('hidden', ready < 1);
      bubble.classList.toggle('full', full);
      setText('bubble-works-count', String(ready));
    }
  }
  if (cityLevel('bakery')) {
    const ready = bunReady();
    const room = bunRoom();
    const button = $('chore-bun');
    if (button) button.disabled = !ready || !room;
    setText('bun-title', ready ? (room ? tr('Eat a bun') : tr('A bun is ready')) : tr('Bakery'));
    setText('bun-note', ready ? (room ? T`2× income for ${bunMinutes()} min` : tr('It waits until 2× has room')) : T`Next bun in ${clock(bunWait())}`);
    const bubble = $('bubble-bun');
    if (bubble) bubble.classList.toggle('hidden', !ready || !room);
  }
}

// Things on top of the picture: tags on the empty lots, the bricks and the
// bun that are ready, smoke from the chimneys and a sparkle at level 5.
function cityOverlays() {
  let html = '';
  for (const b of BUILDINGS) {
    const art = CITY_ART[b.id];
    const level = cityLevel(b.id);
    const base = art.row === 'back' ? CITY_VIEW.back : CITY_VIEW.front;
    const top = base - art.h;
    const cx = art.x + art.w / 2;
    if (!level) {
      const open = buildingOpen(b);
      const y = art.row === 'back' ? top + Math.min(28, art.h * 0.32) : base - 17;
      html += `<button class="lot-tag${open ? '' : ' locked'}${canBuild(b) ? ' ready' : ''}" data-action="building" data-id="${b.id}" style="${cityAt(cx, y)}" aria-label="${b.name}: ${open ? tr('not built yet') : lockedText(b)}">${open ? HAMMER_ICON : LOCK_ICON}</button>`;
      continue;
    }
    if (art.smoke) html += `<i class="city-smoke" style="${cityAt(art.x + art.smoke[0], top + art.smoke[1])}"></i>`;
    if (level >= CITY.maxLevel) html += `<i class="city-glint" style="${cityAt(cx, top + Math.min(30, art.h * 0.35))}"></i>`;
    if (cityPop === b.id) html += `<i class="city-dust" style="${cityAt(cx, base - 4)}"></i>`;
  }
  if (cityLevel('works')) {
    const art = CITY_ART.works;
    html += T`<button class="city-bubble works hidden" id="bubble-works" data-action="collect-works" style="${cityAt(art.x + art.smoke[0] - 16, CITY_VIEW.front - art.h + 4)}" aria-label="Collect the bricks">${BRICK_ICON}<b id="bubble-works-count">0</b></button>`;
  }
  html += cityBirdsHtml();
  if (cityLevel('bakery')) {
    const art = CITY_ART.bakery;
    html += T`<button class="city-bubble bun hidden" id="bubble-bun" data-action="eat-bun" style="${cityAt(art.x + art.bubble[0], CITY_VIEW.front - art.h + art.bubble[1] - 17)}" aria-label="Eat the bun">${BUN_ICON}</button>`;
  }
  return html;
}

// Pigeons: they peck about in the street, on a lamp, the fountain or a roof.
// Tap one (or walk past it) and it flies off, to land somewhere else later.
// Spots are [x, y] of the bird's middle in the picture, with the building
// that has to be there for it.
const BIRD_SPOTS = [
  [52, 243.6], [60, 245.6, '', true], [318, 244.6, '', true], [112, 246], [226, 244.4], [336, 245.4, '', true], [40, 245.2],
  [76, 186.6], [147, 186.6, '', true], [211, 186.6], [285, 186.6, '', true],
  [156, 205.6, 'fountain'], [32, 162.2, 'works'], [46, 162.2, 'works', true], [170, 78.6, 'clock']
];
const BIRD_COLORS = ['#9aa3b0', '#7f8a96', '#8a6a5a', '#a8b0bb'];
const birdSpotOpen = i => !BIRD_SPOTS[i][2] || cityLevel(BIRD_SPOTS[i][2]) > 0;
const birdAt = i => cityAt(BIRD_SPOTS[i][0] - 7, BIRD_SPOTS[i][1] - 6);

function birdSvg(color) {
  return `<svg viewBox="-7 -6 14 10" aria-hidden="true"><g class="bird-body">
    <path d="M-2.6 .6l-1.6 1" stroke="${CITY_INK}" stroke-width=".7"/>
    <path class="bird-wing far" d="M-.4 -.8Q-2 -5.6 -5 -5.2Q-3 -2.6 -1.4 .2Z" fill="${darker(color, 0.12)}" stroke="${CITY_INK}" stroke-width=".5"/>
    <ellipse rx="2.6" ry="2" fill="${color}" stroke="${CITY_INK}" stroke-width=".7"/>
    <g class="bird-head"><circle cx="1.8" cy="-1.4" r="1.4" fill="${color}" stroke="${CITY_INK}" stroke-width=".7"/><path d="M3 -1.4l1.1 .3l-1.1 .4" fill="#f6b23a"/><circle cx="2.1" cy="-1.7" r=".3" fill="${CITY_INK}"/></g>
    <path class="bird-legs" d="M-.6 2l-.2 1M.8 2l-.2 1" stroke="${CITY_INK}" stroke-width=".5"/>
    <path class="bird-wing" d="M.4 -.4Q-1.2 -5.8 -4.4 -5.6Q-2.2 -2.6 -.8 .8Z" fill="${lighter(color, 0.18)}" stroke="${CITY_INK}" stroke-width=".55"/>
  </g></svg>`;
}

function cityBirdsHtml() {
  const spots = [0, 1, 2];
  if (cityLevel('fountain')) spots.push(11);
  return spots.map((spot, i) => `<button class="city-bird${BIRD_SPOTS[spot][3] ? ' flip' : ''}" data-action="bird" data-i="${i}" data-spot="${spot}" style="${birdAt(spot)};--peck:${(3.2 + i * 1.3).toFixed(1)}s;--delay:-${(i * 0.9).toFixed(1)}s" aria-label="${tr('A pigeon')}">${birdSvg(BIRD_COLORS[i % BIRD_COLORS.length])}</button>`).join('');
}

// Off it goes, flapping, up and away to one side. A while later it comes
// back to a spot that is free.
function birdFly(i, tapped = false) {
  const el = document.querySelector(`#screen-city .city-bird[data-i="${i}"]`);
  if (!el || el.classList.contains('fly')) return;
  const left = Math.random() < 0.5;
  el.style.setProperty('--fx', `${left ? -150 : 150}px`);
  el.style.setProperty('--fy', `${-90 - Math.round(Math.random() * 40)}px`);
  el.style.setProperty('--face', left ? -1 : 1);
  el.classList.remove('land');
  el.classList.add('fly');
  if (tapped) sfx('flap');
  setTimeout(() => birdLand(el), 9000 + Math.random() * 16000);
}

function birdLand(el) {
  if (!el.isConnected) return;
  const taken = new Set([...document.querySelectorAll('#screen-city .city-bird')].map(bird => bird.dataset.spot));
  const free = BIRD_SPOTS.map((_, k) => k).filter(k => !taken.has(String(k)) && birdSpotOpen(k));
  if (!free.length) {
    setTimeout(() => birdLand(el), 8000);
    return;
  }
  const spot = free[Math.floor(Math.random() * free.length)];
  // Out of sight, it moves to the new spot, then glides in from the side it faces.
  const fromLeft = Math.random() < 0.5;
  el.classList.add('jump');
  el.dataset.spot = String(spot);
  el.setAttribute('style', `${birdAt(spot)};--peck:${(3 + Math.random() * 3).toFixed(1)}s;--delay:-${(Math.random() * 3).toFixed(1)}s;--fx:${fromLeft ? -150 : 150}px;--fy:-110px;--face:${fromLeft ? 1 : -1}`);
  el.classList.toggle('flip', !!BIRD_SPOTS[spot][3]);
  void el.offsetWidth;
  el.classList.remove('jump');
  el.classList.add('land');
  el.classList.remove('fly');
  setTimeout(() => el.classList.remove('land'), 1500);
}

// The coinfolk who live in the city, walking up and down the street, and
// Pip's friends, who come to visit. Tap one and they say something.
function cityFolkHtml() {
  const people = [];
  const count = Math.min(8, Math.max(1, cityBuilt() + 1));
  for (let k = 0; k < count; k++) people.push({ k });
  state.friends.slice(0, 4).forEach(id => people.push({ friend: id }));
  if (isNight()) people.push({ lighter: true });
  const rand = seeded(97 + people.length);
  // Standing still, they spread out along the street (x); walking, each has a pace of its own.
  const lanes = people.map((person, i) => ({ ...person, i, y: 79 + rand() * 8, dur: 17 + rand() * 13, delay: rand() * 30, x: 3 + ((i + 0.5) / people.length) * 86 + (rand() - 0.5) * 5, rev: i % 2 === 1 }));
  lanes.sort((a, b) => a.y - b.y);
  return `<div class="city-folk">${lanes.map(p => {
    const name = p.lighter ? CITY_LIGHTER.name : p.friend ? FRIEND_BY_ID[p.friend].name : T`${CITY_FOLK_NAMES[p.k % CITY_FOLK_NAMES.length]} from ${CITY.name}`;
    const look = p.lighter ? folkLook('lighter') : p.friend ? {} : folkLook(p.k);
    const kind = p.lighter ? ' lighter' : look.kid ? ' kid' : look.old ? ' old' : '';
    // The lamplighter starts his round off the left edge.
    const x = p.lighter ? -8 : p.x;
    return `<div class="folk-lane${p.rev ? ' rev' : ''}" data-x="${x.toFixed(1)}" data-y="${p.y.toFixed(1)}" style="top:${p.y.toFixed(1)}%;--x:${x.toFixed(1)}%"><button class="townie${p.friend ? ' friend' : ''}${kind}" data-action="folk" data-al="down" data-ar="${p.lighter ? 'pole' : look.extra === 'mustache' && look.old ? 'cane' : 'down'}" style="--blink:${(3.2 + (p.i % 5) * 0.7).toFixed(1)}s;--blink-delay:-${((p.i * 1.37) % 4).toFixed(2)}s;--glance:${(6 + (p.i % 4) * 1.3).toFixed(1)}s" data-k="${p.i}"${p.lighter ? ' data-lighter="1" data-folk="0" data-carry="pole"' : p.friend ? ` data-friend="${p.friend}"` : ` data-folk="${p.k}"`} aria-label="${name}">${p.lighter ? folkSvg('lighter') : p.friend ? friendSvg(p.friend) : folkSvg(p.k)}<span class="folk-say"></span></button></div>`;
  }).join('')}</div>`;
}

/* --- 3.19: The coinfolk have things to do --- */
// Places in the street, as x in the picture: doors in the front row, the
// market stalls, the fountain and the lamps. People walk on the cobbles
// (their lanes) and step up to a door to go in.
const FOLK_PLACES = {
  works: { door: 32, carry: 'brick' },
  bakery: { door: 127, carry: 'bread' },
  gym: { door: 248, carry: 'dumbbell' },
  market: { stalls: [306, 340], carry: 'basket' },
  fountain: { stand: [166, 192] },
  lamps: [76, 147, 211, 285]
};
const FOLK = { doorY: 78.4, speed: 4.6, chat: 5, birdNear: 3.4 };
let cityPeople = [];
const folkStill = () => state.settings.effects !== 'all' || calmMotion();
const pct = x => (x / CITY_VIEW.w) * 100;

// Everyone in the street, read from the page after it is drawn.
function cityLifeInit() {
  const now = Date.now();
  cityPeople = [...document.querySelectorAll('#screen-city .folk-lane')].map(lane => {
    const townie = lane.querySelector('.townie');
    const x = Number(lane.dataset.x) || 0;
    const y = Number(lane.dataset.y) || 84;
    const kid = townie.classList.contains('kid');
    const old = townie.classList.contains('old');
    return {
      lane, townie, i: Number(townie.dataset.k), x, y, laneY: y, from: x, fromY: y, at: now, dur: 0,
      w: townie.classList.contains('friend') ? 8.4 : kid ? 5.4 : 6.6,
      speed: FOLK.speed * (kid ? 1.3 : old ? 0.62 : 0.85 + Math.random() * 0.3),
      friend: !!townie.dataset.friend, lighter: !!townie.dataset.lighter,
      steps: [], busyUntil: now + 300 + Math.random() * 2500, held: false, chatAt: 0,
      kid, old, cane: townie.dataset.ar === 'cane', temper: FOLK_TEMPERS[Number(townie.dataset.k) % FOLK_TEMPERS.length], scaredUntil: 0, greetUntil: 0
    };
  });
}

// Where someone is right now, in the middle of a walk too.
function folkNow(p, now) {
  const t = p.dur > 0 ? Math.min(1, Math.max(0, (now - p.at) / p.dur)) : 1;
  return { x: p.from + (p.x - p.from) * t, y: p.fromY + (p.y - p.fromY) * t };
}

function folkGo(p, x, y, now, slow = 1) {
  const here = folkNow(p, now);
  const dist = Math.hypot(x - here.x, (y - here.y) * 0.7);
  const seconds = Math.max(0.25, dist / (p.speed * slow * weatherPace()));
  p.from = here.x;
  p.fromY = here.y;
  p.x = x;
  p.y = y;
  p.at = now;
  p.dur = seconds * 1000;
  p.lane.style.transition = `transform ${seconds.toFixed(2)}s linear, top ${seconds.toFixed(2)}s ease-in-out`;
  p.lane.style.transform = `translateX(${x.toFixed(2)}%)`;
  p.lane.style.top = `${y.toFixed(2)}%`;
  if (Math.abs(x - here.x) > 0.3) p.lane.classList.toggle('left', x < here.x);
  p.lane.classList.add('walking');
  p.busyUntil = now + p.dur;
}

// Stops right where they are (to talk to you), and later carries on.
function folkHold(i, hold) {
  const p = cityPeople.find(person => person.i === i);
  if (!p) return;
  const now = Date.now();
  if (hold) {
    const here = folkNow(p, now);
    p.lane.style.transition = 'none';
    p.lane.style.transform = `translateX(${here.x.toFixed(2)}%)`;
    p.lane.style.top = `${here.y.toFixed(2)}%`;
    p.from = p.x = here.x;
    p.fromY = p.y = here.y;
    p.dur = 0;
    p.lane.classList.remove('walking');
    p.townie.classList.remove('chat');
    p.say = null;
    sayShow(p, '');
    p.held = true;
    // A walk to a door or a stall is forgotten; back to the street first.
    p.steps = Math.abs(p.y - p.laneY) > 0.5 ? [now2 => folkGo(p, p.x, p.laneY, now2, 0.6)] : [];
  } else {
    p.held = false;
    p.busyUntil = now + 800;
  }
}

const folkWait = (p, ms) => now => { p.busyUntil = now + ms; };
const folkWalk = (p, x, y = null) => now => folkGo(p, Math.max(-9, Math.min(97, x)), y == null ? p.laneY : y, now);
// Stand facing something on the left or the right.
const folkFace = (p, left) => () => { p.lane.classList.toggle('left', left); };

// Picks what to do next, by what is built.
function folkPlan(p, now) {
  if (weatherShown === 'storm' && !p.lighter) return stormPlan(p, now);
  if (p.lighter) return lighterRound(p);
  const built = id => cityLevel(id) > 0;
  const options = [['stroll', 4]];
  if (p.kid && weatherShown === 'snow') options.push(['snowman', 6]);
  if (p.kid && (weatherShown === 'rain' || citySky.after === 'rain') && cityPuddles.length) options.push(['puddle', 5]);
  if (!p.friend && built('bakery')) options.push(['bakery', 2]);
  if (!p.friend && built('works')) options.push(['works', 1.2]);
  if (!p.friend && built('gym')) options.push(['gym', 1.2]);
  if (built('market')) options.push(['market', 2]);
  if (built('fountain')) options.push(['fountain', weatherShown === 'heat' ? 6 : 1.8]);
  let roll = Math.random() * options.reduce((sum, [, w]) => sum + w, 0);
  let errand = 'stroll';
  for (const [name, w] of options) {
    roll -= w;
    if (roll <= 0) {
      errand = name;
      break;
    }
  }
  const at = x => pct(x) - p.w / 2;
  const steps = [];
  // Whatever they carried home, they put away on the next errand.
  steps.push(() => { delete p.townie.dataset.carry; });
  if (errand === 'stroll') {
    steps.push(folkWalk(p, 1 + Math.random() * 88), folkWait(p, (1200 + Math.random() * 3500) * (weatherShown === 'aurora' ? 2.5 : 1)));
  } else if (errand === 'market') {
    const stall = FOLK_PLACES.market.stalls[Math.floor(Math.random() * 2)];
    steps.push(folkWalk(p, at(stall), p.laneY), folkWait(p, 2400 + Math.random() * 3000), () => { p.townie.dataset.carry = 'basket'; }, folkWait(p, 600));
  } else if (errand === 'snowman') {
    steps.push(folkWalk(p, pct(SNOWMAN_X) + 3.4 + Math.random() * 3), folkFace(p, true), now2 => {
      p.townie.classList.add('building');
      p.busyUntil = now2 + 5000 + Math.random() * 4000;
    }, () => { p.townie.classList.remove('building'); }, folkWait(p, 600));
  } else if (errand === 'puddle') {
    const pd = cityPuddles[Math.floor(Math.random() * cityPuddles.length)];
    steps.push(folkWalk(p, pct(pd.x) - p.w / 2, Math.min(p.laneY + 2, (pd.y - 27) / CITY_VIEW.h * 100)), now2 => {
      p.townie.classList.add('hop');
      puddleSplash(pd);
      p.busyUntil = now2 + 1300;
    }, () => { p.townie.classList.remove('hop'); }, folkWait(p, 500));
  } else if (errand === 'fountain') {
    const spot = FOLK_PLACES.fountain.stand[Math.floor(Math.random() * 2)];
    steps.push(folkWalk(p, at(spot)), folkFace(p, spot > 179), folkWait(p, 700), now2 => tossCoin(p, now2), folkWait(p, 2600 + Math.random() * 2500));
  } else {
    // In through the door, a while inside, and out with something to carry.
    const place = FOLK_PLACES[errand];
    const x = at(place.door);
    steps.push(folkWalk(p, x), now2 => folkGo(p, x, FOLK.doorY, now2, 0.5), now2 => {
      p.townie.classList.add('inside');
      p.busyUntil = now2 + 5000 + Math.random() * 9000;
    }, now2 => {
      p.townie.classList.remove('inside');
      p.townie.dataset.carry = place.carry;
      p.busyUntil = now2 + 500;
    }, now2 => folkGo(p, x, p.laneY, now2, 0.5), folkWait(p, 400 + Math.random() * 1200));
  }
  p.steps = steps;
}

// The lamplighter's round: from the left, every lamp in turn, then off to
// the right, and a while later round again.
function lighterRound(p) {
  const steps = [];
  for (const x of FOLK_PLACES.lamps) {
    const at = pct(x) - p.w * 0.94;
    steps.push(folkWalk(p, at), folkFace(p, false), now => {
      p.townie.classList.add('reach');
      lampFlare(x);
      p.busyUntil = now + 1400;
    }, () => { p.townie.classList.remove('reach'); });
  }
  steps.push(folkWalk(p, 104), folkWait(p, 15000 + Math.random() * 20000), now => {
    // Back to the start, out of sight.
    p.lane.style.transition = 'none';
    p.lane.style.transform = 'translateX(-9%)';
    p.from = p.x = -9;
    p.dur = 0;
    p.busyUntil = now + 200;
  });
  p.steps = steps;
}

// A lamp the lamplighter reaches up to flares for a moment.
function lampFlare(x) {
  document.querySelectorAll(`#screen-city .lamp-light[data-x="${x}"]`).forEach(light => {
    light.classList.remove('flare');
    void light.getBoundingClientRect();
    light.classList.add('flare');
  });
}

// A coin into the fountain, for luck: up in an arc and plop.
function tossCoin(p, now) {
  const layer = document.querySelector('#screen-city .city-folk');
  if (!layer || typeof Element.prototype.animate !== 'function') return;
  const here = folkNow(p, now);
  const coin = document.createElement('i');
  coin.className = 'toss-coin';
  const x0 = here.x + p.w / 2;
  const y0 = here.y + 3;
  const x1 = pct(179);
  const y1 = (207 / CITY_VIEW.h) * 100;
  coin.style.left = `${x0}%`;
  coin.style.top = `${y0}%`;
  layer.appendChild(coin);
  const view = layer.getBoundingClientRect();
  const dx = ((x1 - x0) / 100) * view.width;
  const dy = ((y1 - y0) / 100) * view.height;
  coin.animate([
    { transform: 'translate(0, 0) scale(1)', opacity: 1 },
    { transform: `translate(${dx / 2}px, ${dy / 2 - view.height * 0.12}px) scale(1.1)`, opacity: 1, offset: 0.5 },
    { transform: `translate(${dx}px, ${dy}px) scale(.6)`, opacity: 0 }
  ], { duration: 900, easing: 'ease-in-out' }).onfinish = () => coin.remove();
}

// Four times a second, with the city: who goes where next.
function cityLifeTick(now) {
  if (!cityPeople.length || !cityPeople[0].lane.isConnected) return;
  folkLooks(now);
  // Fewer effects (or calm motion): they finish their step and stand still.
  if (folkStill()) {
    cityPeople.forEach(p => { if (now >= p.busyUntil) p.lane.classList.remove('walking'); });
    return;
  }
  const birds = [...document.querySelectorAll('#screen-city .city-bird:not(.fly)')];
  for (const p of cityPeople) {
    if (p.held) continue;
    if (p.say) sayTick(p, now);
    if (now >= p.busyUntil - 30) p.lane.classList.remove('walking');
    if (now < p.busyUntil) {
      // Someone walking by makes the pigeons in the street fly off.
      if (p.lane.classList.contains('walking') && birds.length) {
        const here = folkNow(p, now);
        for (const bird of birds) {
          const spot = BIRD_SPOTS[Number(bird.dataset.spot)];
          if (spot && spot[1] > 228 && Math.abs(pct(spot[0]) - (here.x + p.w / 2)) < FOLK.birdNear) birdFly(Number(bird.dataset.i));
        }
      }
      continue;
    }
    if (!p.steps.length) {
      // Two who meet in the street stop for a little chat now and then.
      // (Whoever they meet is standing in the street, not walking or indoors.)
      const mate = !p.lighter && now > p.chatAt && cityPeople.find(q => q !== p && !q.held && !q.lighter && now > q.chatAt && !q.lane.classList.contains('walking') && !q.townie.classList.contains('inside') && Math.abs(q.y - q.laneY) < 0.5 && Math.abs(q.x - p.x) < FOLK.chat);
      if (mate && weatherShown !== 'storm' && Math.random() < 0.5) {
        const lines = chatLines();
        const ms = lines.length * WEATHER.sayStep + 600;
        for (const [a, b] of [[p, mate], [mate, p]]) {
          a.lane.classList.toggle('left', b.x < a.x);
          a.townie.classList.add('chat');
          a.busyUntil = now + ms;
          a.chatAt = now + ms + 25000;
          a.say = { lines, start: now, role: a === p ? 0 : 1 };
          a.greetUntil = now + 1000;
          a.steps.unshift(() => {
            a.townie.classList.remove('chat');
            a.say = null;
            sayShow(a, '');
          });
        }
        continue;
      }
      folkPlan(p, now);
    }
    const step = p.steps.shift();
    if (step) step(now);
  }
}

// Tap someone in the street and they talk to you in a box of their own,
// letter by letter, in their own voice, with their face beside it. Tap the
// box to hear the rest at once, or to close it. Tap someone else and the
// box is theirs.
const TALK_BOX = `<div class="talk-box" id="talk-box" data-action="talk-next" role="status" aria-live="polite"><span class="talk-face" id="talk-face" aria-hidden="true"></span><span class="talk-body"><b class="talk-name" id="talk-name"></b><span class="talk-text" id="talk-text"></span></span><i class="talk-next" aria-hidden="true"></i></div>`;
let cityTalk = null;

function cityTalkStop() {
  if (!cityTalk) return;
  const { el, friend, typer } = cityTalk;
  if (typer) typer.stop();
  clearTimeout(cityTalk.timer);
  folkHold(Number(el.dataset.k), false);
  el.classList.remove('talk', 'typing');
  if (el.parentElement) el.parentElement.classList.remove('paused');
  if (friend) setFace(el, FRIEND_LOOKS[friend.id], 'idle');
  const box = $('talk-box');
  if (box) box.classList.remove('show', 'done');
  cityTalk = null;
}

function folkTalk(k) {
  const el = document.querySelector(`#screen-city .townie[data-k="${k}"]`);
  const box = $('talk-box');
  if (!el || !box) return;
  cityTalkStop();
  const friend = FRIEND_BY_ID[el.dataset.friend];
  const folk = Number(el.dataset.folk) || 0;
  const lighter = !!el.dataset.lighter;
  const lines = lighter ? CITY_LIGHTER.lines : friend ? friend.lines : isNight() ? CITY_NIGHT_CHATTER : CITY_CHATTER;
  folkHold(Number(k), true);
  const line = lines[Math.floor(Math.random() * lines.length)];
  el.classList.add('talk', 'typing');
  el.parentElement.classList.add('paused');
  if (friend) setFace(el, FRIEND_LOOKS[friend.id], 'happy');
  $('talk-face').innerHTML = friend ? friendSvg(friend.id, 'happy') : folkSvg(lighter ? 'lighter' : folk);
  $('talk-face').dataset.al = 'down';
  $('talk-face').dataset.ar = 'down';
  $('talk-face').dataset.carry = friend ? '' : el.dataset.carry || '';
  setText('talk-name', lighter ? CITY_LIGHTER.name : friend ? friend.name : CITY_FOLK_NAMES[folk % CITY_FOLK_NAMES.length]);
  box.classList.remove('done');
  box.classList.add('show');
  const talk = { el, friend };
  cityTalk = talk;
  talk.typer = typeLine($('talk-text'), line, lighter ? VOICES.lighter : friend ? VOICES[friend.id] || VOICES.pip : VOICES.folk[folk % VOICES.folk.length], () => {
    el.classList.remove('typing');
    box.classList.add('done');
    talk.timer = setTimeout(() => {
      if (cityTalk === talk) cityTalkStop();
    }, Math.min(6000, 2200 + line.length * 40));
  });
  if (!state.settings.voices) sfx('folk');
  buzz(10);
}

// A tap on the box: the rest of the line at once, or close it.
function talkNext() {
  if (!cityTalk) return;
  if (cityTalk.typer && !cityTalk.typer.done) cityTalk.typer.finish();
  else cityTalkStop();
}

function buildingCard(b) {
  const level = cityLevel(b.id);
  if (!buildingOpen(b)) {
    return `<div class="card city-card locked">
      <span class="city-thumb">${buildingSvg(b.id, 0, 'ghost')}</span>
      <div class="item-info"><div class="item-title">${b.name}</div><div class="item-desc">${lockedText(b)}</div></div>
    </div>`;
  }
  const max = buildingMaxed(b);
  const cost = buildCost(b);
  const pill = level ? `<span class="pill${max ? ' gold' : ''}">${max ? tr('MAX') : `LV ${level}/${CITY.maxLevel}`}</span>` : tr('<span class="pill brick">NEW</span>');
  const desc = level ? `<b>${buildingShort(b, level)}</b>` : T`Build it: <b>${buildingShort(b, 1)}</b>`;
  const next = level && !max ? T`<div class="item-desc small">Next: ${buildingShort(b, level + 1)}</div>` : '';
  return `<div class="card city-card${level ? '' : ' unbuilt'}" id="city-card-${b.id}">
    <button class="city-thumb" data-action="building" data-id="${b.id}" aria-label="${b.name}">${buildingSvg(b.id, level, level ? '' : 'preview')}</button>
    <div class="item-info"><div class="item-title">${b.name} ${pill}</div><div class="item-desc">${desc}</div>${next}</div>
    ${max
      ? tr('<button class="buy-button" disabled>MAX<small>LEVEL</small></button>')
      : `<button class="buy-button brick lego-button" data-action="city-build" data-id="${b.id}" data-price="${cost}" data-currency="bricks">${BRICK_ICON} ${format(cost)}<small>${level ? tr('UPGRADE') : tr('BUILD')}</small></button>`}
  </div>`;
}

function marketHtml() {
  let html = sectionHead(tr('Market'), tr('New offers every day'));
  html += '<div class="list">' + MARKET.map(offer => {
    const sold = offerSold(offer);
    const open = offerOpen(offer);
    const price = marketPrice(offer);
    let what = open ? tr('<b>A treasure</b>, like the ones critters drop') : tr('Every treasure you have is at its max.');
    let icon = CHEST_SVG;
    if (offer.id === 'coins') {
      what = T`<b id="market-coins">✦ ${format(giftCoins(offer.minutes))}</b>, an hour of income`;
      icon = '✦';
    } else if (offer.id === 'diamonds') {
      what = `<b>+${offer.amount} ◆</b>`;
      icon = '◆';
    }
    return `<div class="card market-card">
      <div class="item-icon${offer.id === 'diamonds' ? ' purple' : ''}">${icon}</div>
      <div class="item-info"><div class="item-title">${offer.name}</div><div class="item-desc">${what}</div></div>
      ${!open
        ? tr('<button class="buy-button" disabled>NONE<small>LEFT</small></button>')
        : sold
        ? tr('<button class="buy-button" disabled>SOLD<small>TOMORROW</small></button>')
        : T`<button class="buy-button brick" data-action="market-buy" data-id="${offer.id}" data-price="${price}" data-currency="bricks">${BRICK_ICON} ${price}<small>BUY</small></button>`}
    </div>`;
  }).join('') + '</div>';
  return html;
}

function brickSourcesHtml() {
  const guard = CITY.boss + Math.min(state.world, CITY.bossWorlds);
  const rows = [
    ['❦', tr('Critters'), T`${CITY.critter[0]} to ${CITY.critter[CITY.critter.length - 1]} bricks each. Rare, big and shiny ones drop more.`],
    ['⚔', tr('Bosses'), T`${guard} from a guard in this world, and ${guard * CITY.ruler} from the ruler. More in later worlds.`],
    [BRICK_ICON, tr('Brickworks'), cityLevel('works') ? T`${worksRate()} an hour, even while you're away. It holds ${worksCap()}.` : tr('Build it, and it makes bricks even while you\'re away.')],
    ['★', tr('Daily quests'), T`${CITY.quests} bricks for doing all three.`]
  ];
  return sectionHead(tr('Bricks'), tr('Where they come from')) + `<div class="panel brick-sources">${rows.map(([icon, name, text]) => `<div class="brick-row"><span class="item-icon">${icon}</span><span class="brick-text"><b>${name}</b><small>${text}</small></span></div>`).join('')}</div>`;
}

let citySignature = '';
const cityKey = () => [state.city.open, BUILDINGS.map(b => cityLevel(b.id)).join(''), cityOpenCount(), state.friends.join(), wardrobeKey(), isNight(), state.settings.effects,
  today(), state.city.market.day, state.city.market.bought.join(), materialIndex(state.coinLevel), state.world, gamesKey()].join('|');

function renderCity() {
  const section = $('screen-city');
  if (!section) return;
  // A new day at the Market first: it is part of what the page shows.
  if (cityLevel('market')) syncMarket();
  // Seeing the city counts as seeing what's new in it.
  if (state.city.open) state.city.known = cityOpenCount();
  // The page is only drawn again when the city changes, so the coinfolk
  // keep walking instead of jumping back to where they started.
  if (cityKey() === citySignature && (section.childElementCount || !state.city.open)) {
    updateChores();
    return;
  }
  citySignature = cityKey();
  cityTalkStop();
  if (!state.city.open) {
    section.innerHTML = '';
    return;
  }
  let html = screenTitle(tr('PIP’S CITY'), CITY.name, tr('Critters and bosses drop bricks. Build with them: every building helps for good, and the city stays when you travel.'));
  html += T`<div class="panel city-panel">
    <div class="city-view${isNight() ? ' night' : ''}">${citySceneSvg()}${cityOverlays() + '<div class="city-ground" id="city-ground"></div>'}${cityFolkHtml() + '<div class="city-weather" id="city-weather"></div>'}${TALK_BOX}</div>
    <div class="city-bar">
      <span class="brick-count">${BRICK_ICON}<b id="city-bricks">${format(state.city.bricks)}</b><small>bricks</small></span>
      <span class="pill">CITY LEVEL ${cityLevelTotal()}</span>
    </div>
    ${cityChores()}
  </div>`;
  html += gamesHtml();
  html += sectionHead(tr('Buildings'), T`${cityBuilt()} of ${BUILDINGS.length} built`);
  html += `<div class="list">${BUILDINGS.map(buildingCard).join('')}</div>`;
  if (cityLevel('market')) html += marketHtml();
  html += brickSourcesHtml();
  section.innerHTML = html;
  cityPop = '';
  cityMinute = -1;
  updateChores();
  cityLifeInit();
  weatherShown = '';
  weatherKey = '';
  weatherTick(Date.now());
}

// Four times a second: numbers, timers and the clock hands, nothing else.
let cityMinute = -1;
function updateCity() {
  if (cityKey() !== citySignature) {
    renderCity();
    return;
  }
  if (!state.city.open) return;
  setText('city-bricks', format(state.city.bricks));
  updateChores();
  weatherTick(Date.now());
  cityLifeTick(Date.now());
  const coins = $('market-coins');
  if (coins) setText(coins, `✦ ${format(giftCoins(60))}`);
  document.querySelectorAll('#screen-city .lot-tag[data-id]').forEach(tag => tag.classList.toggle('ready', canBuild(BUILDING_BY_ID[tag.dataset.id])));
  // The building window, if it is open.
  const shown = modalType === 'building' && BUILDING_BY_ID[buildingShown];
  if (shown && !lego) {
    if (buildingKey(shown) !== buildingSignature) renderModal();
    else {
      const status = $('building-status');
      if (status) setHtml('building-status', buildingStatus(shown));
      setText('building-bricks', format(state.city.bricks));
    }
  }
  const now = new Date();
  if (now.getMinutes() !== cityMinute) {
    cityMinute = now.getMinutes();
    const { hour, minute } = clockAngles(now);
    document.querySelectorAll('.clock-h').forEach(hand => hand.setAttribute('transform', `rotate(${hour.toFixed(1)} 28 49)`));
    document.querySelectorAll('.clock-m').forEach(hand => hand.setAttribute('transform', `rotate(${minute} 28 49)`));
    const sky = skySpot(now);
    document.querySelectorAll('.city-svg .sky-sun').forEach(body => body.setAttribute('transform', `translate(${sky.x} ${sky.y})`));
  }
}

// The City tab shows up once the city is open.
function updateCityTab() {
  const tab = document.querySelector('.nav-item[data-go="city"]');
  if (tab) tab.classList.toggle('hidden', !state.city.open);
  const nav = document.querySelector('.nav');
  if (nav) nav.classList.toggle('seven', state.city.open);
}
// Something new in the city you haven't seen, or something waiting there.
const cityNews = () => state.city.open && cityOpenCount() > state.city.known;
const cityWaiting = () => state.city.open && ((bunReady() && bunRoom()) || worksReady() >= Math.max(1, Math.ceil(worksCap() / 2)) || BUILDINGS.some(canBuild));

// What the Brickworks and the Bakery are up to, for their window.
function buildingStatus(b) {
  if (b.id === 'works' && cityLevel('works')) {
    const ready = worksReady();
    return ready ? T`<b>${ready} of ${worksCap()} bricks are ready.</b>` : T`The next brick is done in ${clock(worksNext())}.`;
  }
  if (b.id === 'bakery' && cityLevel('bakery')) {
    if (!bunReady()) return T`The next bun is done in ${clock(bunWait())}.`;
    return bunRoom() ? tr('<b>A fresh bun is ready!</b>') : tr('<b>A fresh bun is ready!</b> It waits until your 2× income has room for all of it.');
  }
  return '';
}
// The window is drawn again only when what you can do in it changes.
let buildingSignature = '';
const buildingKey = b => [b.id, cityLevel(b.id), buildingOpen(b), worksReady() > 0, bunReady(), bunRoom(), state.city.bricks >= buildCost(b)].join('|');

function buildingModalHtml(b) {
  buildingSignature = buildingKey(b);
  const level = cityLevel(b.id);
  const open = buildingOpen(b);
  const max = buildingMaxed(b);
  const cost = buildCost(b);
  const status = !open ? tr('NOT OPEN YET') : max ? tr('MAX LEVEL') : level ? T`LEVEL ${level} OF ${CITY.maxLevel}` : tr('NOT BUILT YET');
  const rows = [];
  if (level) rows.push([tr('Now'), buildingAt(b, level)]);
  if (!max) rows.push([level ? tr('Next level') : tr('Level 1'), buildingAt(b, level + 1)]);
  if (level + 1 < CITY.maxLevel) rows.push([T`Level ${CITY.maxLevel}`, buildingAt(b, CITY.maxLevel)]);
  const doing = buildingStatus(b);
  const extra = doing ? `<p class="modal-copy center" id="building-status">${doing}</p>` : '';
  const actions = [];
  if (b.id === 'works' && worksReady() > 0) actions.push(`<button class="modal-action brick" data-action="collect-works">${P(worksReady(), 'Collect {0} brick', 'Collect {0} bricks')}</button>`);
  if (b.id === 'bakery' && bunReady() && bunRoom()) actions.push(tr('<button class="modal-action brick" data-action="eat-bun">Eat the bun</button>'));
  if (open && !max) actions.push(`<button class="modal-action lego-button${actions.length ? ' soft' : ' brick'}" data-action="city-build" data-id="${b.id}" ${state.city.bricks < cost ? 'disabled' : ''}>${level ? T`Hold to upgrade · ${BRICK_ICON} ${format(cost)}` : T`Hold to build · ${BRICK_ICON} ${format(cost)}`}</button>`);
  const play = GAMES.find(one => one.building === b.id);
  if (play && level) actions.push(`<button class="modal-action soft" data-action="game-open" data-id="${play.id}">▶ ${play.name}</button>`);
  actions.push(tr('<button class="modal-action soft" data-action="close">Back to the city</button>'));
  return `<div class="eyebrow center">${CITY.name.toUpperCase()} · ${status}</div>
    <div class="building-hero">${buildingSvg(b.id, level, open ? (level ? '' : 'preview') : 'ghost')}</div>
    <h2 id="modal-title" class="center">${b.name}<span>.</span></h2>
    <p class="modal-copy center">${b.about}</p>
    ${open ? '' : `<p class="modal-copy center"><b>${lockedText(b)}</b></p>`}
    <div class="credits">${rows.map(([name, value]) => `<div><span>${name}</span><strong>${value}</strong></div>`).join('')}</div>
    ${extra}
    ${open && !max && state.city.bricks < cost ? T`<p class="note center">You have <span id="building-bricks">${format(state.city.bricks)}</span> of ${format(cost)} bricks.</p>` : ''}
    <div class="modal-actions">${actions.join('')}</div>`;
}

/* --- Games in Coinbury (3.25) --- */
// Three little games, each in its own building. The first three rounds of
// each a day win a prize; after that they are just for fun.
const GAMES = [
  { id: 'oven', building: 'bakery', name: tr('The Bun Oven'), about: tr('Take each bun out when it is golden. Too soon, and it is doughy; too late, and it is burnt!') },
  { id: 'memory', building: 'bank', name: tr('Treasure Pairs'), about: tr('Turn two cards at a time and find the pairs. The fewer turns, the bigger the prize.') },
  { id: 'tower', building: 'works', name: tr('The Brick Tower'), about: tr('Tap to drop each brick onto the tower. Whatever hangs over falls off.') }
];
const GAME_BY_ID = Object.fromEntries(GAMES.map(g => [g.id, g]));
const GAME_PRIZES = 3;
const GAME_ICONS = {
  oven: BUN_ICON,
  memory: svgIcon('<rect x="2.6" y="5" width="10" height="14" rx="2" fill="currentColor" opacity=".55" transform="rotate(-10 7.6 12)"/><rect x="10.6" y="4.6" width="10" height="14" rx="2" fill="currentColor" transform="rotate(8 15.6 11.6)"/>'),
  tower: svgIcon('<path d="M3.5 18.5 h17 v3 h-17 Z M5.5 14.5 h13 v3 h-13 Z M7 10.5 h10 v3 H7 Z M8.5 6.5 h7 v3 h-7 Z M10 2.5 h4 v3 h-4 Z" fill="currentColor"/>')
};
let gameShown = '';
let gameFresh = false;
let game = null;

const gameOpen = g => cityLevel(g.building) > 0;
const gamesPlayed = id => (state.games.day === today() ? state.games.played[id] || 0 : 0);
const prizesLeft = id => Math.max(0, GAME_PRIZES - gamesPlayed(id));
const gamesKey = () => GAMES.map(g => `${gameOpen(g) ? 1 : 0}${prizesLeft(g.id)}`).join('');
const gameRand = ([a, b]) => a + Math.random() * (b - a);
function shuffled(list) {
  const out = list.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

// The row of games under City.
function gamesHtml() {
  return sectionHead(tr('Games')) + `<div class="game-row">${GAMES.map(g => {
    const open = gameOpen(g);
    const left = prizesLeft(g.id);
    const note = !open ? T`Needs: ${BUILDING_BY_ID[g.building].name}` : left ? T`Prizes today: ${left} of ${GAME_PRIZES}` : tr('For fun today');
    return `<button class="game-tile${open ? '' : ' locked'}${open && left ? ' fresh' : ''}" data-action="game-open" data-id="${g.id}"><span class="game-icon">${GAME_ICONS[g.id]}</span><b>${g.name}</b><small>${note}</small></button>`;
  }).join('')}</div>`;
}

// The game's window: its picture, a line, and Start (or Play again).
function gameHtml() {
  const g = GAME_BY_ID[gameShown];
  const b = BUILDING_BY_ID[g.building];
  return `<div class="game-wrap" data-game="${g.id}">
    <div class="eyebrow">${CITY.name.toUpperCase()} · ${b.name.toUpperCase()}</div>
    <h2 id="modal-title">${g.name}<span>${LANG && ['ja', 'zh'].includes(LANG.code) ? '。' : '.'}</span></h2>
    <div class="game-stage game-${g.id}" id="game-stage">${GAME_COVERS[g.id]()}</div>
    <p class="game-line" id="game-line">${g.about}</p>
    <div class="modal-actions" id="game-actions">${gameButtons(false)}</div>
    <p class="note center" id="game-note">${gameNote(g)}</p>
  </div>`;
}

function gameButtons(again) {
  if (placeRound) {
    const n = PLACE_BY_ID[placeRound.id].n;
    return `<button class="modal-action" data-action="game-start">${again ? tr('Play again') : tr('Start')}</button><button class="modal-action soft" data-action="open-globe" data-n="${n}">${T`Back to ${worldInfo(n).name}`}</button>`;
  }
  return `<button class="modal-action" data-action="game-start">${again ? tr('Play again') : tr('Start')}</button>${tr('<button class="modal-action soft" data-action="close">Back to the city</button>')}`;
}

function gameNote(g) {
  if (placeRound) return PLACE_BY_ID[placeRound.id].name;
  const left = prizesLeft(g.id);
  const best = state.games.best[g.id];
  const prize = left ? T`Prizes today: ${left} of ${GAME_PRIZES}` : tr('Today\'s three prizes are won. Play just for fun!');
  if (!best) return prize;
  return `${prize} · ${g.id === 'memory' ? T`Fewest turns: ${best}` : T`Best: ${best}`}`;
}

function gameStart() {
  const g = GAME_BY_ID[gameShown];
  const stage = $('game-stage');
  if (!g || (!gameOpen(g) && !placeRound) || !stage) return;
  gameStop();
  const games = state.games;
  if (games.day !== today()) {
    games.day = today();
    games.played = { oven: 0, memory: 0, tower: 0 };
  }
  // A round with a prize counts from its start, so a bad one can't be dropped for a better.
  const prize = !placeRound && games.played[g.id] < GAME_PRIZES;
  if (prize) games.played[g.id]++;
  save();
  game = { id: g.id, prize, stage, raf: 0, last: 0, timers: [], tick: null, over: false, run: null };
  setHtml('game-actions', '');
  setHtml('game-line', g.about);
  setHtml('game-note', gameNote(g));
  GAME_PLAY[g.id](stage);
  gameLoop();
}

function gameLoop() {
  const run = game;
  run.last = performance.now();
  const frame = now => {
    if (game !== run || run.over) return;
    if (!run.stage.isConnected) {
      gameStop();
      return;
    }
    // A step is never longer than 1/20 s: away from the app, the game waits.
    const dt = Math.min(0.05, Math.max(0, (now - run.last) / 1000));
    run.last = now;
    if (run.tick) run.tick(dt);
    if (game === run && !run.over) run.raf = requestAnimationFrame(frame);
  };
  run.raf = requestAnimationFrame(frame);
}

function gameStop() {
  if (!game) return;
  cancelAnimationFrame(game.raf);
  game.timers.forEach(clearTimeout);
  game.over = true;
  if (game.stage) game.stage.onpointerdown = null;
  game = null;
}

function gameLater(fn, ms) {
  const run = game;
  if (!run) return;
  run.timers.push(setTimeout(() => {
    if (game === run) fn();
  }, ms));
}

// A word that rises from a spot in the game: Perfect!, Burnt! …
function gameWord(anchor, text, kind = '') {
  const stage = game && game.stage;
  if (!stage || !anchor) return;
  const s = stage.getBoundingClientRect();
  const r = anchor.getBoundingClientRect();
  const el = document.createElement('span');
  el.className = `game-word${kind ? ` ${kind}` : ''}`;
  el.textContent = text;
  el.style.left = `${(r.left - s.left + r.width / 2).toFixed(1)}px`;
  el.style.top = `${(r.top - s.top + r.height / 2).toFixed(1)}px`;
  stage.appendChild(el);
  setTimeout(() => el.remove(), 900);
}

// The end of a round: the score, a record, and the prize if it is a prize round.
function gameOver(result) {
  const run = game;
  if (!run || run.over) return;
  run.over = true;
  cancelAnimationFrame(run.raf);
  run.stage.onpointerdown = null;
  const g = GAME_BY_ID[run.id];
  const best = state.games.best;
  const better = result.score > 0 && (g.id === 'memory' ? !best.memory || result.score < best.memory : result.score > (best[g.id] || 0));
  if (better) best[g.id] = result.score;
  const placed = placeRound ? placeGameOver(result) : null;
  const prize = placed ? placed.prize : run.prize ? GAME_PRIZE[g.id](result) : '';
  save();
  refresh();
  const lines = [`<b>${result.text}</b>`];
  if (prize) lines.push(T`Prize: ${prize}`);
  else lines.push(run.prize || placed ? tr('No prize this time.') : tr('Today\'s three prizes are won. Play just for fun!'));
  if (better) lines.push(`<em class="game-record">${tr('New record!')}</em>`);
  setHtml('game-line', lines.join('<br>'));
  setHtml('game-actions', gameButtons(true));
  setHtml('game-note', gameNote(g));
  sfx(prize ? 'claim' : 'pop');
  if (prize) buzz(30);
}

/* The Bun Oven: buns go in one by one and bake from dough to golden to burnt.
   A tap takes one out: golden is perfect (2 points), nearly golden is good (1). */
const OVEN = { buns: 10, spots: 6, golden: [1.9, 2.7], perfect: 0.12, good: 0.28, burnt: 1.65, gap: [0.35, 0.95], bunAt: 16 };
const OVEN_STOPS = [[0, [246, 231, 200]], [0.62, [241, 205, 141]], [1, [226, 156, 66]], [1.3, [168, 98, 43]], [1.65, [62, 40, 26]]];
const OVEN_WORDS = { perfect: tr('Perfect!'), good: tr('Good'), doughy: tr('Too soon'), burnt: tr('Burnt!') };

function ovenColor(p) {
  if (p <= 0) return OVEN_STOPS[0][1];
  for (let k = 1; k < OVEN_STOPS.length; k++) {
    const [at, rgb] = OVEN_STOPS[k];
    if (p <= at) {
      const [from, prev] = OVEN_STOPS[k - 1];
      const t = (p - from) / (at - from);
      return prev.map((c, i) => Math.round(c + (rgb[i] - c) * t));
    }
  }
  return OVEN_STOPS[OVEN_STOPS.length - 1][1];
}

const ovenHtml = (buns = '') => `<div class="oven-box"><div class="oven-hood"><i></i><i></i><i></i></div><div class="oven-window"><div class="oven-tray">${Array.from({ length: OVEN.spots }, (_, k) => `<span class="oven-spot">${buns[k] || ''}</span>`).join('')}</div></div>`
  + `<div class="oven-foot"><span>${BUN_ICON}<b id="oven-made">0</b></span><span>★<b id="oven-points">0</b></span></div></div>`;

function ovenPlay(stage) {
  stage.innerHTML = ovenHtml();
  const spots = [...stage.querySelectorAll('.oven-spot')];
  const run = { t: 0, next: 0.4, made: 0, done: 0, taken: 0, points: 0, buns: [] };
  game.run = run;
  stage.onpointerdown = event => {
    const spot = event.target.closest('.oven-spot');
    const bun = spot && run.buns.find(b => b.spot === spot && !b.out);
    if (bun) ovenTake(run, bun, '');
  };
  game.tick = dt => {
    run.t += dt;
    if (run.made < OVEN.buns && run.t >= run.next) {
      const free = spots.filter(spot => !run.buns.some(b => b.spot === spot && !b.gone));
      if (free.length) {
        const spot = free[Math.floor(Math.random() * free.length)];
        const el = document.createElement('i');
        el.className = 'oven-bun';
        spot.appendChild(el);
        run.buns.push({ spot, el, born: run.t, golden: gameRand(OVEN.golden), out: false, gone: false });
        run.made++;
      }
      run.next = run.t + gameRand(OVEN.gap);
    }
    for (const bun of run.buns) {
      if (bun.out) continue;
      const p = (run.t - bun.born) / bun.golden;
      const [r, g, b] = ovenColor(p);
      bun.el.style.setProperty('--crust', `rgb(${r}, ${g}, ${b})`);
      bun.el.classList.toggle('golden', Math.abs(p - 1) <= OVEN.perfect);
      if (p >= OVEN.burnt) ovenTake(run, bun, 'burnt');
    }
    if (run.done >= OVEN.buns && run.buns.every(b => b.gone)) {
      gameOver({ score: run.points, text: T`Points: ${run.points} of ${OVEN.buns * 2}` });
    }
  };
}

function ovenTake(run, bun, forced) {
  const p = (run.t - bun.born) / bun.golden;
  const off = Math.abs(p - 1);
  const grade = forced || (off <= OVEN.perfect ? 'perfect' : off <= OVEN.good ? 'good' : p < 1 ? 'doughy' : 'burnt');
  const points = grade === 'perfect' ? 2 : grade === 'good' ? 1 : 0;
  bun.out = true;
  run.done++;
  run.points += points;
  if (points) run.taken++;
  setText('oven-points', run.points);
  setText('oven-made', run.taken);
  bun.el.classList.remove('golden');
  bun.el.classList.add('out', grade);
  gameWord(bun.spot, OVEN_WORDS[grade], grade);
  sfx(grade === 'perfect' ? 'lucky' : grade === 'good' ? 'pop' : grade === 'burnt' ? 'burn' : 'miss');
  gameLater(() => {
    bun.el.remove();
    bun.gone = true;
  }, 420);
}

/* Treasure Pairs: twelve cards, six pairs of the game's treasures. */
function memoryRound(stage) {
  const kinds = shuffled(ITEM_TYPES).slice(0, 6);
  const deck = shuffled([...kinds, ...kinds]);
  stage.innerHTML = `<div class="mem-grid">${deck.map((type, i) => `<button class="mem-card" data-i="${i}" aria-label="${tr('Card')}"><span class="mem-back">✦</span><span class="mem-face r-${RARITIES[type.rarity].id}">${type.icon}</span></button>`).join('')}</div>`
    + `<div class="game-count">${T`Turns: ${'<b id="mem-turns">0</b>'}`}</div>`;
  const run = { deck, open: [], pairs: 0, turns: 0, lock: false };
  game.run = run;
  stage.onpointerdown = event => {
    const card = event.target.closest('.mem-card');
    if (!card || run.lock || card.classList.contains('up')) return;
    card.classList.add('up');
    sfx('clack');
    run.open.push(card);
    if (run.open.length < 2) return;
    const [a, b] = run.open;
    run.open = [];
    run.turns++;
    setText('mem-turns', run.turns);
    if (deck[a.dataset.i] === deck[b.dataset.i]) {
      a.classList.add('match');
      b.classList.add('match');
      run.pairs++;
      sfx('token');
      if (run.pairs === kinds.length) gameLater(() => gameOver({ score: run.turns, text: T`All pairs found! Turns: ${run.turns}` }), 650);
      return;
    }
    run.lock = true;
    gameLater(() => {
      a.classList.remove('up');
      b.classList.remove('up');
      run.lock = false;
    }, 820);
  };
}

/* The Brick Tower: a brick slides to and fro above the tower; a tap drops it.
   What hangs over falls off, and the next brick is only as wide as what stayed.
   Spot on keeps the width, and three spot on in a row make it a little wider. */
const TOWER = { brick: 18, ground: 26, width: 0.46, speed: 120, faster: 7, fastest: 330, perfect: 0.04, grow: 8, view: 0.55 };

function towerBrick(run, left, width, floor, kind = '') {
  const el = document.createElement('i');
  el.className = `tower-brick${floor % 2 ? ' odd' : ''}${kind ? ` ${kind}` : ''}`;
  el.style.left = `${left.toFixed(1)}px`;
  el.style.width = `${width.toFixed(1)}px`;
  el.style.bottom = `${TOWER.ground + floor * TOWER.brick}px`;
  run.world.appendChild(el);
  return el;
}

function towerPlay(stage) {
  stage.innerHTML = `<div class="tower-box"><div class="tower-world"><div class="tower-ground"></div></div><div class="game-count tower-count">${T`Floors: ${'<b id="tower-floors">0</b>'}`}</div></div>`;
  const W = stage.clientWidth || 300;
  const width = Math.round(W * TOWER.width);
  const run = { W, H: stage.clientHeight || 300, world: stage.querySelector('.tower-world'), floors: 0, top: { left: Math.round((W - width) / 2), width }, mover: null, perfect: 0, speed: TOWER.speed, shift: 0, falling: false };
  game.run = run;
  towerBrick(run, run.top.left, run.top.width, 0, 'base');
  towerNext(run);
  stage.onpointerdown = () => towerDrop(run);
  game.tick = dt => {
    const m = run.mover;
    if (!m || run.falling) return;
    m.x += m.dir * run.speed * dt;
    const max = run.W - m.width;
    if (m.x <= 0) {
      m.x = 0;
      m.dir = 1;
    } else if (m.x >= max) {
      m.x = max;
      m.dir = -1;
    }
    m.el.style.left = `${m.x.toFixed(1)}px`;
  };
}

function towerNext(run) {
  const floor = run.floors + 1;
  const fromLeft = floor % 2 === 1;
  const width = run.top.width;
  const x = fromLeft ? 0 : run.W - width;
  run.mover = { el: towerBrick(run, x, width, floor, 'moving'), x, width, dir: fromLeft ? 1 : -1, floor };
}

function towerDrop(run) {
  const m = run.mover;
  if (!m || run.falling || !game || game.over) return;
  const prev = run.top;
  const left = Math.max(m.x, prev.left);
  const right = Math.min(m.x + m.width, prev.left + prev.width);
  const overlap = right - left;
  if (overlap <= 0) {
    // Missed: the brick falls, and the tower is done.
    run.falling = true;
    m.el.classList.remove('moving');
    m.el.classList.add('fall', m.x < prev.left ? 'to-left' : 'to-right');
    sfx('escape');
    gameLater(() => gameOver({ score: run.floors, text: T`Tower height: ${run.floors}` }), 900);
    return;
  }
  m.el.classList.remove('moving');
  // Spot on: within what the brick moves in 1/25 s (never less than 5 pixels).
  if (Math.abs(m.x - prev.left) <= Math.max(5, run.speed * TOWER.perfect)) {
    run.perfect++;
    let x = prev.left;
    let width = prev.width;
    if (run.perfect % 3 === 0) {
      const grow = Math.max(0, Math.min(TOWER.grow, Math.round(run.W * TOWER.width) - width));
      x = Math.max(0, Math.min(run.W - width - grow, x - grow / 2));
      width += grow;
    }
    m.el.style.left = `${x.toFixed(1)}px`;
    m.el.style.width = `${width.toFixed(1)}px`;
    run.top = { left: x, width };
    gameWord(m.el, tr('Perfect!'), 'perfect');
    sfx('token');
  } else {
    run.perfect = 0;
    // The part that hangs over falls off.
    const cutLeft = m.x < prev.left;
    const bit = cutLeft ? [m.x, prev.left - m.x] : [right, m.x + m.width - right];
    const piece = towerBrick(run, bit[0], bit[1], m.floor, `fall ${cutLeft ? 'to-left' : 'to-right'}`);
    setTimeout(() => piece.remove(), 900);
    m.el.style.left = `${left.toFixed(1)}px`;
    m.el.style.width = `${overlap.toFixed(1)}px`;
    run.top = { left, width: overlap };
    sfx('clack');
  }
  run.floors++;
  setText('tower-floors', run.floors);
  run.speed = Math.min(TOWER.fastest, run.speed + TOWER.faster);
  // The view climbs with the tower.
  const shift = Math.max(0, TOWER.ground + (run.floors + 3) * TOWER.brick - run.H * TOWER.view);
  if (shift !== run.shift) {
    run.shift = shift;
    run.world.style.transform = `translateY(${shift.toFixed(1)}px)`;
  }
  towerNext(run);
}

// Before a game starts: its picture, still.
const GAME_COVERS = {
  oven: () => ovenHtml(['<i class="oven-bun" style="--crust: rgb(232, 170, 84)"></i>', '', '<i class="oven-bun" style="--crust: rgb(244, 220, 172)"></i>', '', '<i class="oven-bun" style="--crust: rgb(226, 156, 66)"></i>', '']),
  memory: () => `<div class="mem-grid">${'<span class="mem-card"><span class="mem-back">✦</span></span>'.repeat(12)}</div>`,
  tower: () => `<div class="tower-box"><div class="tower-world"><div class="tower-ground"></div>${[[27, 46], [29, 42], [31, 38], [33, 33]].map(([x, w], k) => `<i class="tower-brick${k % 2 ? ' odd' : ''}${k ? '' : ' base'}" style="left: ${x}%; width: ${w}%; bottom: ${TOWER.ground + k * TOWER.brick}px"></i>`).join('')}</div></div>`
};
const GAME_PLAY = { oven: ovenPlay, memory: memoryRound, tower: towerPlay };

// The prizes: coins (and a bun for a near-perfect batch), diamonds for few
// turns, and bricks for every four floors (at least one, at most ten).
const GAME_PRIZE = {
  oven(result) {
    const coins = giftCoins(result.score / 4);
    earn(coins);
    let text = `✦ ${format(coins)}`;
    if (result.score >= OVEN.bunAt) {
      addBoost('bun', bunMinutes(), CITY.bunCap);
      text += ` + ${tr('a fresh bun (2× income)')}`;
    }
    return text;
  },
  memory(result) {
    const gems = result.score <= 8 ? 3 : result.score <= 11 ? 2 : 1;
    state.diamonds += gems;
    return `${gems} ◆`;
  },
  tower(result) {
    const bricks = Math.min(10, Math.ceil(result.score / 4));
    if (!bricks) return '';
    addBricks(bricks);
    return `${bricks} ${BRICK_ICON}`;
  }
};

function cityIntroHtml() {
  const welcome = state.city.welcome;
  return T`<div class="eyebrow">NEW · THE CITY</div>
    <h2 id="modal-title">A city of our own<span>!</span></h2>
    ${storyBubble([tr('Look what the critters were carrying: bricks! The Baron\'s critters have been pinching bricks from coinfolk for years.'), T`Let's build a city with them. A shiny one, far away from the grey. I'm calling it ${CITY.name}!`])}
    <div class="city-intro-art">${buildingSvg('works', 1)}${buildingSvg('bakery', 1)}</div>
    <p class="modal-copy">From now on, critters and bosses drop bricks.${welcome ? T` The ones you have beaten already left <b>${format(welcome)} bricks</b> behind.` : ''} Your city is under <b>City</b> at the bottom, and it stays when you travel.</p>
    <div class="modal-actions"><button class="modal-action" data-action="go-city">Let's build</button><button class="modal-action soft" data-action="close">Later</button></div>`;
}

function boughtHtml() {
  const got = lastBuy;
  const type = got && got.item && ITEM_BY_ID[got.item.type];
  const rarity = type && RARITIES[type.rarity];
  return T`<div class="eyebrow center">FROM THE MARKET · A TREASURE</div>
    ${type ? `<div class="loot-card ${rarity.id}">
      <div class="loot-icon">${type.icon}</div>
      <div class="loot-rarity">${rarity.name} · ${levelNews(got.item)}</div>
      <h2 id="modal-title">${type.item}</h2>
      <p>${treasureEffect(type, got.item.level)}</p>
    </div>` : T`<h2 id="modal-title" class="center">Diamonds instead<span>!</span></h2><div class="boss-loot">${got && got.item ? lootRowHtml(got.item) : ''}</div>`}
    <p class="modal-copy center">Your treasures are behind the chest at the top.</p>
    <button class="modal-action" data-action="close">Lovely</button>`;
}

/* -----------------------------------------------------------------
   7. MODALS
   ----------------------------------------------------------------- */
const isModalOpen = () => modalType !== '';

// A window that opens by itself (a caught helicopter, a won fight) ignores
// taps for a moment, so a finger that was still tapping can't close it.
const MODAL_GUARD = { ms: 650, types: ['loot', 'bosswin', 'cleared', 'heli', 'fight'] };
let modalOpenedAt = 0;
let backdropPressed = false;
const modalGuarded = () => MODAL_GUARD.types.includes(modalType) && Date.now() - modalOpenedAt < MODAL_GUARD.ms;

function openModal(type, replace = false) {
  if (type === 'daily' && dailyInfo().claimed) return;
  if (type === 'away' && !pendingAway) return;
  if (modalType && !replace) {
    if (modalType !== type && !modalQueue.includes(type)) modalQueue.push(type);
    return;
  }
  if (modalType === 'giveup' && type !== 'giveup') resumeBossTimer();
  const box = document.querySelector('#modal-backdrop .modal');
  if (box && modalType !== type) box.scrollTop = 0;
  modalType = type;
  modalOpenedAt = Date.now();
  $('modal-backdrop').classList.remove('hidden');
  $('modal-backdrop').dataset.type = type;
  renderModal();
  musicMuffleNow();
}

// After an update, what's new shows once. A new player (or one who hasn't
// heard Pip's story yet) has nothing to compare with, so it just counts as seen.
let newsShown = [];
let historyFrom = '';

function checkWhatsNew() {
  const seen = state.seenVersion;
  if (seen === VERSION) return;
  state.seenVersion = VERSION;
  if (isNewPlayer || !state.story.prologue) return;
  // If we know which version you had, everything since then; otherwise the newest.
  newsShown = seen ? CHANGELOG.filter(entry => compareVersions(entry.version, seen) > 0).slice(0, 3) : CHANGELOG.slice(0, 1);
  if (newsShown.length) openModal('whatsnew');
  // Worlds 9 to 12 were the second round before 3.8. If that is where you
  // are, you are in one of the new worlds now, so Pip tells you about it.
  if ((!seen || compareVersions(seen, '3.8') < 0) && state.world >= 9 && state.world <= 12) openModal('arrived');
  // The same for worlds 13 to 16, which were the second round before 3.11.
  if ((!seen || compareVersions(seen, '3.11') < 0) && state.world >= 13 && state.world <= 16) openModal('arrived');
}

const changeList = entry => `<ul class="modal-list changes">${entry.notes.map(note => `<li>${note}</li>`).join('')}</ul>`;

function closeModal() {
  if (lego && lego.art.closest('#modal-content')) legoClear();
  if (!modalType) return;
  if (modalType === 'away') collectAway(1);
  if (modalType === 'giveup') resumeBossTimer();
  if (modalType === 'prologue') state.story.prologue = true;
  if (modalType === 'fight' && fight) fleeFight();
  if (modalType === 'game') {
    gameStop();
    placeRound = null;
  }
  if (modalType === 'globe') globeClosed();
  modalType = '';
  confirmReset = false;
  $('modal-backdrop').classList.add('hidden');
  musicMuffleNow();
  if (cityTourWaits) {
    cityTourWaits = false;
    setTimeout(cityTutorial, 450);
  }
  save();
  refresh();
  const next = modalQueue.shift();
  if (next) setTimeout(() => openModal(next), 180);
}

// One achievement up close: what to do, how far you are, and the reward.
function achievementDetail(ach) {
  const done = hasAchievement(ach.id);
  const hidden = ach.secret && !done;
  let progress = '';
  if (ach.stat) {
    const value = ach.stat();
    const target = achTarget(ach);
    progress = `<div class="ach-progress">
      <div class="progress${done ? ' green' : ''}"><span style="width:${Math.min(100, (value / target) * 100).toFixed(1)}%"></span></div>
      <div class="ach-count"><b>${format(value)}</b> / ${format(target)} ${ach.unit}</div>
    </div>`;
  }
  const when = state.achievementTimes[ach.id];
  const date = done && when ? new Date(when).toLocaleDateString((LANG && (LANG.locale || LANG.code)) || 'en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) : '';
  return T`<div class="ach-hero${done ? ' done' : ''}${ach.secret ? ' secret' : ''}"><b>${hidden ? '?' : ach.icon}</b></div>
    <div class="eyebrow center">${ach.secret ? tr('SECRET') : tr('ACHIEVEMENT')} · ${done ? tr('UNLOCKED') : tr('NOT YET')}</div>
    <h2 id="modal-title" class="center">${hidden ? '???' : ach.name}</h2>
    <p class="modal-copy center">${hidden ? T`<b>Hint:</b> ${ach.hint}` : ach.text}</p>
    ${progress}
    <div class="ach-reward"><span>Reward</span><strong>+${achievementReward(ach)} ◆ and +1% taps and income</strong></div>
    ${date ? T`<p class="note center">Unlocked ${date}</p>` : ''}
    <div class="modal-actions"><button class="modal-action soft" data-action="open-achievements">All achievements</button></div>`;
}

// A speech bubble for Pip or the Baron.
/* --- Pip talks (3.21) --- */
// Pip (or a boss) says things in a bubble near the bottom, letter by letter in
// his own voice, just as he talks by the coin. Pip comes over from his place by
// the coin (or hops in from the left) and the rest of the screen goes dim, with
// a light on whatever he points at. A tap shows the whole line, the next tap
// goes on. A line can wait until the player has done something (`wait`; then
// only the lit thing can be tapped), point at a thing (`mark`), or end with
// answers to pick from (`answers`). Skip ends it all.
const DLG = { poll: 200, come: 380, leave: 480 };
let inDialogue = null;

function dlgPanel() {
  let el = $('dlg');
  if (el) return el;
  el = document.createElement('div');
  el.id = 'dlg';
  el.className = 'dlg hidden';
  el.setAttribute('role', 'dialog');
  el.innerHTML = `<div class="dlg-face" id="dlg-face"></div>
    <div class="dlg-box"><b class="dlg-name" id="dlg-name"></b><p class="dlg-text" id="dlg-text" aria-live="polite"></p>
    <div class="dlg-gifts" id="dlg-gifts"></div><div class="dlg-note" id="dlg-note"></div>
    <div class="dlg-answers" id="dlg-answers"></div><i class="dlg-more" aria-hidden="true">▾</i></div>
    <button class="dlg-skip" id="dlg-skip" type="button"></button>`;
  document.body.appendChild(el);
  el.addEventListener('pointerdown', event => {
    if (event.target.closest('button, .dlg-gifts')) return;
    event.preventDefault();
    dlgPress();
  });
  $('dlg-skip').addEventListener('click', () => {
    if (inDialogue && performance.now() < inDialogue.skipQuiet) return;
    dlgEnd('skip');
  });
  window.addEventListener('resize', () => {
    const t = inDialogue;
    if (!t || t.k < 0) return;
    dlgPlace(el);
    dlgMark(t.lines[t.k].mark, t.lines[t.k].round);
  });
  return el;
}

// The dim layer behind the bubble. A tap on it goes on, like a tap on the
// bubble; the hole where Pip points lets taps through while he waits.
function dlgScrim() {
  let el = $('dlg-scrim');
  if (el) return el;
  el = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  el.id = 'dlg-scrim';
  el.setAttribute('class', 'dlg-scrim off');
  el.setAttribute('aria-hidden', 'true');
  el.setAttribute('preserveAspectRatio', 'none');
  el.innerHTML = '<path class="dim" fill-rule="evenodd"/><rect class="block" width="100%" height="100%"/>';
  document.body.appendChild(el);
  el.addEventListener('pointerdown', event => {
    event.preventDefault();
    dlgPress();
  });
  el.getBoundingClientRect();
  return el;
}

// Plays the lines; resolves with 'done', 'skip', an answer's value, or 'busy'.
function dialogue(lines, opts = {}) {
  if (inDialogue) return Promise.resolve('busy');
  const el = dlgPanel();
  return new Promise(resolve => {
    inDialogue = { lines, opts, k: -1, resolve, typer: null, waiting: null, finish: null, start: 0, quietUntil: performance.now() + DLG_TAPS.calm, skipQuiet: 0 };
    $('dlg-skip').textContent = tr('Skip');
    el.classList.toggle('no-skip', opts.skip === false);
    dlgCome(el, lines[0]);
  });
}

// Something that would open a window by itself waits until Pip has finished.
const dlgAfter = [];
function afterTalk(fn) {
  if (!inDialogue) fn();
  else dlgAfter.push(fn);
}

function dlgPlace(el) {
  const nav = document.querySelector('.nav');
  const top = isModalOpen();
  el.classList.toggle('top', top);
  const sign = $('world-sign');
  if (sign) sign.classList.toggle('aside', top);
  el.style.bottom = !top && nav ? `${Math.max(12, window.innerHeight - nav.getBoundingClientRect().top + 10)}px` : '';
}

// Where Pip comes from and goes back to: his place by the coin, or else the
// left edge of the screen. As a move of his face in the bubble.
let dlgGone = 0;
function dlgHome(face) {
  const f = face.getBoundingClientRect();
  const pip = $('stage-pip');
  if (currentScreen === 'coin' && pip && pip.getClientRects().length > 0) {
    const p = pip.getBoundingClientRect();
    return { pip, x: p.left + p.width / 2 - (f.left + f.width / 2), y: p.top + p.height / 2 - (f.top + f.height / 2), s: f.width ? p.width / f.width : 1 };
  }
  return { pip: null, x: -(f.left + f.width + 30), y: 0, s: 1 };
}

function dlgMove(face, home) {
  face.style.setProperty('--fx', `${home.x.toFixed(1)}px`);
  face.style.setProperty('--fy', `${home.y.toFixed(1)}px`);
  face.style.setProperty('--fs', home.s.toFixed(3));
}

// The screen goes dim and Pip comes over; he starts talking once he is there.
function dlgCome(el, first) {
  const face = $('dlg-face');
  const who = first.who || 'pip';
  // A new talk while Pip was on his way back: he just stays.
  const stay = el.classList.contains('leaving');
  clearTimeout(dlgGone);
  el.classList.remove('hidden', 'leaving', 'done', 'waiting');
  face.classList.remove('come', 'go');
  hushPip();
  const scrim = dlgScrim();
  scrim.classList.add('hold');
  scrim.classList.remove('off');
  scrim.classList.toggle('light', inDialogue.opts.dim === 'light');
  Music.muffle(true);
  dlgHole(null);
  setHtml('dlg-face', speakerSvg(who, first.mood || (who === 'pip' ? 'happy' : 'idle')));
  $('dlg-name').textContent = speakerName(who);
  $('dlg-text').textContent = '';
  $('dlg-answers').innerHTML = '';
  dlgPlace(el);
  if (who !== 'pip' || stay || calmMotion()) {
    dlgNext();
    return;
  }
  const home = dlgHome(face);
  if (home.pip) home.pip.classList.add('away');
  dlgMove(face, home);
  face.classList.add('come');
  inDialogue.start = setTimeout(dlgNext, DLG.come);
}

// The bubble goes, the screen lights up again and Pip goes back to his place.
function dlgLeave() {
  const el = $('dlg');
  const scrim = $('dlg-scrim');
  if (scrim) scrim.classList.add('off');
  if (!el || el.classList.contains('hidden')) return;
  const face = $('dlg-face');
  const pip = $('stage-pip');
  const done = () => {
    el.classList.add('hidden');
    el.classList.remove('leaving');
    face.classList.remove('come', 'go');
    if (pip) pip.classList.remove('away');
  };
  clearTimeout(dlgGone);
  if (calmMotion() || !face.querySelector('.pip-svg')) {
    done();
    return;
  }
  face.classList.remove('come');
  dlgMove(face, dlgHome(face));
  face.classList.add('go');
  el.classList.add('leaving');
  dlgGone = setTimeout(done, DLG.leave);
}

// Light up what the line points at, scrolled into view if need be. Taps go on
// with the talk, except through the light while Pip waits for the player.
// Pip's journal on the Worlds screen, scrolled up to its heading.
function journalShow() {
  const journal = document.querySelector('#screen-worlds .journal');
  const head = journal && journal.previousElementSibling;
  if (!head) return;
  const hud = document.querySelector('.hud');
  const top = Math.max(0, head.getBoundingClientRect().top + window.scrollY - (hud ? hud.offsetHeight : 0) - 10);
  window.scrollTo({ top, behavior: calmMotion() ? 'auto' : 'smooth' });
}

function dlgLight(line) {
  const target = line.mark && document.querySelector(line.mark);
  // A line that scrolls by itself (`follow`) has the light follow its thing.
  if (line.follow) {
    const t = inDialogue;
    let n = 0;
    const tick = setInterval(() => {
      if (inDialogue !== t || t.lines[t.k] !== line || ++n > 14) {
        clearInterval(tick);
        return;
      }
      dlgMark(line.mark, line.round);
    }, 100);
  } else if (target && target.scrollIntoView && target.getClientRects().length) {
    const r = target.getBoundingClientRect();
    if (r.top < 0 || r.bottom > window.innerHeight) target.scrollIntoView({ block: 'center' });
  }
  dlgScrim().classList.toggle('hold', !line.wait);
  dlgMark(line.mark, line.round);
}

// The dim layer with a hole (round, or a rounded box) around `r`. `clear`:
// nothing dimmed at all, for a step whose thing cannot be found.
function dlgHole(r, round = false, clear = false) {
  const scrim = $('dlg-scrim');
  if (!scrim) return;
  const w = window.innerWidth;
  const h = window.innerHeight;
  const n = v => Math.round(v * 10) / 10;
  let d = `M0 0H${w}V${h}H0Z`;
  if (r) {
    const pad = 10;
    if (round) {
      const rad = n(Math.max(r.width, r.height) / 2 + pad);
      const cx = n(r.left + r.width / 2);
      const cy = n(r.top + r.height / 2);
      d += `M${n(cx - rad)} ${cy}a${rad} ${rad} 0 1 0 ${n(rad * 2)} 0a${rad} ${rad} 0 1 0 ${n(-rad * 2)} 0Z`;
    } else {
      const x = n(r.left - pad);
      const y = n(r.top - pad);
      const bw = n(r.width + pad * 2);
      const bh = n(r.height + pad * 2);
      const k = n(Math.min(16, bw / 2, bh / 2));
      d += `M${n(x + k)} ${y}H${n(x + bw - k)}a${k} ${k} 0 0 1 ${k} ${k}V${n(y + bh - k)}a${k} ${k} 0 0 1 ${-k} ${k}H${n(x + k)}a${k} ${k} 0 0 1 ${-k} ${-k}V${n(y + k)}a${k} ${k} 0 0 1 ${k} ${-k}Z`;
    }
  }
  scrim.setAttribute('viewBox', `0 0 ${w} ${h}`);
  scrim.querySelector('.dim').setAttribute('d', d);
  scrim.classList.toggle('clear', clear);
}

function dlgNext() {
  const t = inDialogue;
  if (!t) return;
  clearInterval(t.waiting);
  t.k++;
  if (t.k >= t.lines.length) {
    dlgEnd('done');
    return;
  }
  const line = t.lines[t.k];
  const el = $('dlg');
  const who = line.who || 'pip';
  dlgPlace(el);
  setHtml('dlg-face', speakerSvg(who, line.mood || (who === 'pip' ? 'happy' : 'idle')));
  $('dlg-name').textContent = speakerName(who);
  $('dlg-answers').innerHTML = '';
  dlgGifts(line.gifts);
  setHtml('dlg-note', '');
  const home = $('stage-pip');
  if (home && who === 'pip' && currentScreen === 'coin') home.classList.add('away');
  el.classList.remove('done', 'waiting');
  if (line.start) line.start();
  dlgLight(line);
  if (line.wait) {
    el.classList.add('waiting');
    t.waiting = setInterval(() => {
      if (inDialogue !== t) return;
      dlgMark(line.mark, line.round);
      if (!line.wait()) return;
      clearInterval(t.waiting);
      if (t.finish) t.finish();
      setTimeout(() => {
        if (inDialogue !== t || t.lines[t.k] !== line) return;
        // Whoever is still tapping (the coin, say) does not tap the next line away.
        t.quietUntil = performance.now() + DLG_TAPS.calm;
        t.skipQuiet = t.quietUntil;
        dlgNext();
      }, 450);
    }, DLG.poll);
  }
  dlgType(line.text, () => {
    el.classList.add('done');
    if (line.note) setHtml('dlg-note', line.note);
    if (!line.answers) return;
    $('dlg-answers').innerHTML = line.answers.map(a => `<button class="dlg-answer${a.soft ? ' soft' : ''}" type="button" data-value="${a.value}">${a.label}</button>`).join('');
    $('dlg-answers').querySelectorAll('button').forEach(b => b.addEventListener('click', () => dlgEnd(b.dataset.value)));
  });
}

// The line appears letter by letter in the speaker's voice, the same way Pip
// talks by the coin.
function dlgType(text, done) {
  const t = inDialogue;
  const who = t.lines[t.k].who || 'pip';
  if (t.typer) t.typer.stop();
  t.finish = () => t.typer && t.typer.finish();
  t.typer = typeLine($('dlg-text'), text, voiceOf(who), () => {
    t.finish = null;
    done();
  });
}

function dlgTap() {
  const t = inDialogue;
  if (!t) return;
  // A tap while Pip is still on his way: he starts talking at once.
  if (t.k < 0) {
    clearTimeout(t.start);
    dlgNext();
    return;
  }
  if (t.finish) {
    t.finish();
    return;
  }
  const line = t.lines[t.k];
  if (line.answers || line.wait) return;
  dlgNext();
}

function dlgEnd(value) {
  const t = inDialogue;
  if (!t) return;
  if (t.typer) t.typer.stop();
  clearTimeout(t.start);
  clearInterval(t.waiting);
  inDialogue = null;
  dlgMark(null);
  dlgLeave();
  Music.muffle(currentScreen !== 'coin' && currentScreen !== 'city');
  if (t.opts.end) t.opts.end(value);
  t.resolve(value);
  setTimeout(() => {
    if (!inDialogue) dlgAfter.splice(0).forEach(fn => fn());
  }, DLG.leave + 80);
}

// A ring around the thing Pip talks about.
function dlgMark(sel, round = false) {
  let ring = $('dlg-mark');
  const target = sel ? document.querySelector(sel) : null;
  const shown = !!(target && target.getClientRects().length);
  const t = inDialogue;
  const line = t && t.k >= 0 ? t.lines[t.k] : null;
  dlgHole(shown ? target.getBoundingClientRect() : null, round, !!(line && line.wait && !shown));
  if (!shown) {
    if (ring) ring.classList.add('hidden');
    return;
  }
  if (!ring) {
    ring = document.createElement('div');
    ring.id = 'dlg-mark';
    ring.className = 'dlg-mark hidden';
    document.body.appendChild(ring);
  }
  const r = target.getBoundingClientRect();
  ring.style.left = `${r.left - 6}px`;
  ring.style.top = `${r.top - 6}px`;
  ring.style.width = `${r.width + 12}px`;
  ring.style.height = `${r.height + 12}px`;
  ring.classList.toggle('round', round);
  ring.classList.remove('hidden');
}

// A story text in short lines: whole sentences, short ones kept together.
function dlgLines(paragraphs) {
  const cjk = /^(ja|zh)/.test((LANG && LANG.code) || '');
  const min = cjk ? 16 : 40;
  const out = [];
  for (const paragraph of paragraphs) {
    const sentences = (paragraph.match(/[^.!?。！？]+[.!?。！？]*["”»’)」]*\s*/g) || [paragraph]).map(s => s.trim()).filter(Boolean);
    let line = '';
    for (const sentence of sentences) {
      line = line ? `${line}${cjk ? '' : ' '}${sentence}` : sentence;
      if (line.length >= min) {
        out.push(line);
        line = '';
      }
    }
    if (line) out.push(line);
  }
  return out;
}

// A new player meets Pip: the first chapter of the story, a line at a time,
// and then the first steps. It takes the place of the old welcome window.
function welcomeLines() {
  let taps = 0;
  // 3.34: only hello before the first tap. The rest of the story waits for the
  // first guard (baronLines), the diary for the first win (diaryLines).
  return [{ text: dlgLines(STORY.chapters[0].text)[0], mood: 'happy' },
    { text: tr('Tap our coin! Every tap earns coins.'), mark: '#coin-button', round: true, start: () => { taps = state.stats.taps; }, wait: () => state.stats.taps >= taps + 10 },
    { text: tr('That\'s it! Coins buy upgrades and machines. Machines keep earning, even while you\'re away.'), mark: '.nav-item[data-go="upgrades"]' }
  ];
}

// The first guard arrives: now Pip tells who we are up against.
function baronLines() {
  const story = dlgLines(STORY.chapters[0].text).slice(1).map((text, k) => ({ text, mood: k % 3 === 2 ? 'idle' : 'happy' }));
  return [...story, { text: tr('When the coin is strong enough, the guards come. Beat them to reach the next world.') }];
}

// After the first win: Pip shows his diary, and then the daily gift.
function diaryLines() {
  return [
    { text: tr('I write it all down in my diary. Tap Worlds to have a look!'), mark: '.nav-item[data-go="worlds"]', wait: () => currentScreen === 'worlds' },
    { text: tr('Here it is! Every chapter, to read again whenever you like. Off we go!'), mark: '#screen-worlds .journal + .list', start: journalShow, follow: true }
  ];
}

// A new player: the first guard not beaten yet. The coin screen stays simple.
const isFresh = () => state.world === 1 && state.stats.guards === 0 && state.stats.bestWorld <= 1 && !state.bossBeaten;

// The coin screen keeps to the coin for a new player.
const freshMark = () => $('app').classList.toggle('fresh', isFresh());

// Four times a second, from the game's tick (never in the middle of something
// that refreshes the screen, like the end of a fight before its win scene):
// the first steps that wait for their moment.
function firstSteps() {
  if (state.story.diary || !state.story.prologue || state.stats.guards < 1) return;
  if (inDialogue || isModalOpen() || boss || fight || currentScreen !== 'coin') return;
  state.story.diary = true;
  save();
  dialogue(diaryLines(), { end: () => {
    if (currentScreen === 'worlds') go('coin');
    setTimeout(() => openModal('daily'), calmMotion() ? 0 : DLG.leave + 60);
  } });
}

function startWelcome() {
  return dialogue(welcomeLines(), { end: () => {
    // From his diary back to the coin, where the game is.
    if (currentScreen === 'worlds') go('coin');
    state.story.prologue = true;
    save();
  } });
}

let cityTourWaits = false;

// The first visit to the city: Pip shows how to build the Brickworks. It can
// be skipped; leaving the city halfway means it starts over next time.
function cityTutorial() {
  if (state.story.city || inDialogue || currentScreen !== 'city' || !state.city.open) return;
  if (isModalOpen()) {
    cityTourWaits = true;
    return;
  }
  if (cityLevel('works') > 0) {
    state.story.city = true;
    return;
  }
  const works = BUILDING_BY_ID.works;
  if (state.city.bricks < buildCost(works)) addBricks(buildCost(works) - state.city.bricks);
  dialogue([
    { text: tr('Welcome to Coinbury! Critters and bosses drop bricks, and with them we build our city.') },
    { text: tr('Every building helps us for good. Let\'s start with the Brickworks: tap it.'), mark: '.city-svg .lot[data-id="works"]', wait: () => modalType === 'building' && buildingShown === 'works' },
    { text: tr('Now hold the button until it\'s built.'), mark: '#modal-content [data-action="city-build"]', wait: () => cityLevel('works') > 0 },
    { text: tr('The Brickworks makes bricks all day, even while you\'re away. Come back now and then to collect them.') },
    { text: tr('The more we build, the more the city helps. Have fun!') }
  ], { place: 'city', end: value => {
    if (value === 'left') return;
    state.story.city = true;
    save();
  } });
}

/* --- Pip's handbook (3.23) --- */
// How the game works, a page at a time. A page opens the first time you meet
// what it is about, and new pages get a dot on the book until you read them.
const CHEST_ICON = svgIcon('<path d="M3 9.2 C3 5.9 5.5 3.5 8.6 3.5 h6.8 c3.1 0 5.6 2.4 5.6 5.7 Z" fill="currentColor"/><path d="M3 10.6 h7.4 v2.8 h3.2 v-2.8 H21 V19 a2 2 0 0 1 -2 2 H5 a2 2 0 0 1 -2 -2 Z" fill="currentColor"/>');
const HANDBOOK = [
  { id: 'coin', icon: () => coinDisc(material(state.coinLevel)), title: tr('The coin'), when: () => true,
    text: [tr('Tap the coin to earn coins, and level it up so every tap is worth more.'), tr('Every ten levels it turns to a new metal, and your taps get a big boost.')] },
  { id: 'machines', icon: () => machines[0].icon, title: tr('Upgrades and machines'), when: () => true,
    text: [tr('Upgrades make your taps and machines stronger. Machines earn coins on their own, even while you are away.'), tr('At 25, 50, 100 and more of one machine, all of them earn double.')] },
  { id: 'gifts', icon: () => '◆', title: tr('Gifts and goals'), when: () => true,
    text: [tr('A new gift waits every day you visit.'), tr('Goals and daily quests give diamonds. You find them under the ★ at the top.')] },
  { id: 'golden', icon: () => '<span class="hb-golden">✦</span>', title: tr('Golden coins'), when: () => state.stats.golden > 0,
    text: [tr('Now and then a golden coin turns up. Tap it before it fades!'), tr('It gives a bonus: lots of coins, stronger taps, Helping Hands and more.')] },
  { id: 'critters', icon: () => monsterSvg('rustling', 'happy'), title: tr('Critters'), when: () => state.stats.monsters > 0,
    text: [tr('The Baron\'s critters run by now and then. Tap one to fight it.'), tr('Beaten critters drop coins and sometimes a treasure. Pip notes them all under Worlds.')] },
  { id: 'bosses', icon: () => bossSvg('goose', 'angry'), title: tr('Bosses'), when: () => state.stats.bosses > 0,
    text: [tr('Every world has two guards and a ruler. They come when your coin reaches their level.'), tr('Tap fast before the time runs out. Glowing weak spots take 5× damage, and every boss has a trick.')] },
  { id: 'streak', icon: () => '✹', title: tr('Hot streaks'), when: () => state.stats.bestStreak > 1,
    text: [tr('Win boss fights in a row for a hot streak: more taps, more income and better loot.'), tr('Lose a fight or give up, and the streak is over.')] },
  { id: 'treasures', icon: () => CHEST_ICON, title: tr('Treasures'), when: () => treasureKinds() > 0,
    text: [tr('Treasures come from bosses and critters. Each one gives a small bonus for good.'), tr('The rarer, the stronger. Find the same one again and it levels up.')] },
  { id: 'worlds', icon: () => world().symbol, title: tr('New worlds'), when: () => state.stats.bestWorld > 1 || state.bossBeaten,
    text: [tr('Beat a ruler and the portal to the next world opens. There, everything earns more.'), tr('Coins, levels, machines and upgrades start over. Diamonds, treasures and the city stay.')] },
  { id: 'combo', icon: () => BOLT_ICON, title: tr('The combo meter'), when: () => state.stats.bestWorld >= FEATURE_WORLD.combo,
    text: [tr('Tap fast and the combo meter fills up, for up to 2× per tap. Slow down and it drains.')] },
  { id: 'city', icon: () => buildingSvg('works', 1), title: tr('Bricks and the city'), when: () => state.city.open,
    text: [T`Critters and bosses drop bricks. With them you build ${CITY.name}, under City.`, tr('The Brickworks makes bricks all day, even while you are away. Every building helps you for good.')] },
  { id: 'rain', icon: () => '☂', title: tr('Coin rain'), when: () => state.stats.bestWorld >= FEATURE_WORLD.rain,
    text: [tr('Now and then coins fall from the sky. Catch as many as you can!')] },
  { id: 'friends', icon: () => '♥', title: tr('Pip\'s friends'), when: () => state.friends.length > 0,
    text: [tr('Every 7th daily gift brings one of Pip\'s friends. Each one helps a little, for good.'), tr('Tap a friend under Worlds to let them sit with Pip.')] },
  { id: 'secrets', icon: () => KEY_ICON, title: tr('Secrets and keys'), when: () => state.stats.secrets > 0 || state.secrets.keys.length > 0,
    text: [tr('Every world hides a secret. Tap things in the picture and see what happens!'), tr('Three keys are hidden in the worlds. They fit the lock at the top of Settings.')] },
  { id: 'games', icon: () => GAME_ICONS.tower, title: tr('Games in Coinbury'), when: () => GAMES.some(gameOpen),
    text: [tr('The Bakery, the Bank and the Brickworks each have a little game. You find them under City.'), tr('The first three rounds of each game a day win a prize. After that, play just for fun.')] },
  { id: 'weather', icon: () => '☂', title: tr('Weather in Coinbury'), when: () => state.city.open,
    text: [tr('Coinbury has weather: rain, storms, snow, fog, wind and more. What comes depends on the world you are in, and it can change every quarter of an hour.'),
      tr('After the rain, look for the pot of gold at the end of the rainbow. In a thunderstorm the lightning can leave bricks in the street. And on windy days, hold on to your hat!')] }
];
const HANDBOOK_EVERY = 2000;
let handbookAt = 0;
let hbShown = '';

const hbOpen = page => state.handbook.open.includes(page.id);

// Opens the pages whose time has come. `quiet`: without a word (at the start).
function handbookTick(quiet = false) {
  const book = state.handbook;
  for (const page of HANDBOOK) {
    if (hbOpen(page) || !page.when()) continue;
    book.open.push(page.id);
    book.fresh.push(page.id);
    if (!quiet) afterTalk(() => notify(T`New page in Pip's handbook: ${page.title}`));
  }
  updateBookDot();
}

function updateBookDot() {
  const dot = $('hud-book-dot');
  if (dot) dot.classList.toggle('on', HANDBOOK.some(page => state.handbook.fresh.includes(page.id)));
}

function hbBadge(page) {
  if (!hbOpen(page)) return `<button class="ach secret hb locked" data-action="hb-locked" aria-label="${tr('Not found yet')}"><b>?</b><span>???</span></button>`;
  const fresh = state.handbook.fresh.includes(page.id);
  return `<button class="ach done hb" data-action="hb-page" data-id="${page.id}">${fresh ? tr('<em class="ach-new">NEW</em>') : ''}<b>${page.icon()}</b><span>${page.title}</span></button>`;
}

function handbookHtml() {
  const found = HANDBOOK.filter(hbOpen).length;
  return `<div class="eyebrow">${T`${found} OF ${HANDBOOK.length} PAGES`}</div>
    <h2 id="modal-title">${tr('Pip\'s handbook')}<span>.</span></h2>
    <p class="modal-copy">${tr('How the game works, a page at a time. New pages fill in as you play.')}</p>
    <div class="ach-grid hb-grid">${HANDBOOK.map(hbBadge).join('')}</div>`;
}

function handbookPageHtml(page) {
  return `<div class="ach-hero done hb-hero"><b>${page.icon()}</b></div>
    <div class="eyebrow center">${T`PAGE ${HANDBOOK.indexOf(page) + 1} OF ${HANDBOOK.length}`}</div>
    <h2 id="modal-title" class="center">${page.title}</h2>
    ${page.text.map(line => `<p class="modal-copy center">${line}</p>`).join('')}
    <div class="modal-actions"><button class="modal-action soft" data-action="open-handbook">${tr('All pages')}</button></div>`;
}

/* --- Scenes (3.22) --- */
// Wins and new worlds are little scenes in Pip's bubble. With SCENE_MODE.on false
// the plain windows show instead, as before 3.22 (the older tests use that).
const SCENE_MODE = { on: true };
// Taps that come too soon are not meant for the bubble: right after Pip goes
// on by himself, or in a quick run (still tapping the coin, say). A tap counts
// after a short pause.
const DLG_TAPS = { calm: 700, gap: 320 };
let dlgLastTap = 0;

function dlgPress() {
  const now = performance.now();
  const quick = now - dlgLastTap < DLG_TAPS.gap;
  dlgLastTap = now;
  const t = inDialogue;
  if (!t || quick || now < t.quietUntil) return;
  dlgTap();
}

// Bosses talk in voices of their own: the Baron low and grumbly, the Goose a
// honk, the others by rank (rulers lowest), each a little different.
const BOSS_VOICES = { goose: [560, 'sawtooth'], baron: [200, 'sawtooth'], ironbaron: [170, 'sawtooth'] };
function voiceOf(who) {
  const own = VOICES[who];
  if (own && typeof own[0] === 'number') return own;
  if (BOSS_VOICES[who]) return BOSS_VOICES[who];
  const info = BOSS_BY_ID[who];
  if (!info) return VOICES.pip;
  let h = 7;
  for (const ch of who) h = (h * 31 + ch.charCodeAt(0)) % 9973;
  return [[430, 330, 240][info.rank] + (h % 120), ['square', 'triangle', 'sawtooth'][h % 3]];
}

// The words of a bit of HTML, for typing out.
function htmlText(html) {
  const box = document.createElement('div');
  box.innerHTML = html;
  return box.textContent;
}

// Little icons in the bubble: what we got, what is new here. A tap on one
// shows what it is.
function dlgGifts(gifts) {
  const row = $('dlg-gifts');
  if (!row) return;
  const list = (gifts || []).filter(Boolean);
  row.innerHTML = list.map((gift, k) => `<button class="gift${gift.kind ? ` ${gift.kind.split(' ').map(kind => `g-${kind}`).join(' ')}` : ''}${gift.peek ? '' : ' flat'}" type="button" data-k="${k}" style="--d:${(0.15 + k * 0.1).toFixed(2)}s"><span class="gift-icon">${gift.icon}</span><small>${gift.label}</small></button>`).join('');
  row.querySelectorAll('.gift').forEach(button => button.addEventListener('click', () => {
    const gift = list[Number(button.dataset.k)];
    if (gift && gift.peek) peekShow(gift.peek());
  }));
  if (list.some(gift => gift.reward)) setTimeout(() => sfx('loot'), 150);
}

// A small card about one thing: a boss, a treasure, something new. A tap
// anywhere closes it (and does nothing else).
function peekShow(html) {
  let el = $('peek');
  if (!el) {
    el = document.createElement('div');
    el.id = 'peek';
    el.className = 'peek hidden';
    el.setAttribute('role', 'dialog');
    document.body.appendChild(el);
    el.addEventListener('pointerdown', event => event.stopPropagation());
    el.addEventListener('click', event => {
      event.stopPropagation();
      peekHide();
    });
  }
  el.innerHTML = `<div class="peek-card">${html}</div>`;
  el.classList.remove('hidden');
}

function peekHide() {
  const el = $('peek');
  if (el) el.classList.add('hidden');
}

function peekHtml(icon, title, lines, kind = '') {
  return `<div class="peek-icon${kind ? ` ${kind.split(' ').map(one => `p-${one}`).join(' ')}` : ''}">${icon}</div><strong class="peek-title">${title}</strong>${lines.filter(Boolean).map(line => `<p>${line}</p>`).join('')}`;
}

function bossPeek(info, number = state.world) {
  const tricks = info.tricks.map(id => TRICKS[id] && TRICKS[id].tip);
  const loot = `+${info.rank === 2 ? bossReward(number) : guardReward(number)} ◆${state.city.open ? ` · +${bossBricks(info.rank, number)} ${BRICK_ICON}` : ''}`;
  return peekHtml(bossSvg(info.id, 'idle'), info.name, [`${RANK_NAMES[info.rank]} · ${info.title}`, T`Comes at coin level ${bossLevel(info.rank, number)}.`, ...tricks, loot], 'boss');
}

// A coin in a metal's colours.
function coinDisc(look, symbol = world().symbol) {
  return `<span class="coin-disc" style="--c1:${look.light};--c2:${look.mid};--c3:${look.dark}">${symbol}</span>`;
}

function materialPeek(level) {
  const look = material(level);
  return peekHtml(coinDisc(look), look.name, [T`Your coin turns to ${look.name} at coin level ${level}.`, T`×${gainText(levelGain(level - 1))} tap power`], 'coin');
}

function itemGift(item) {
  if (!item) return null;
  if (!item.type) return { icon: '◆', label: `+${item.diamonds}`, kind: 'gem', reward: true };
  const type = ITEM_BY_ID[item.type];
  const rarity = RARITIES[type.rarity];
  return { icon: type.icon, label: type.item, kind: `item ${rarity.id}`, reward: true,
    peek: () => peekHtml(type.icon, type.item, [`<b style="color: var(--color-rarity-${rarity.id})">${rarity.name}</b> · ${levelNews(item)}`, treasureEffect(type, item.level)], `item ${rarity.id}`) };
}

function bossGift(info, number = state.world) {
  return { icon: bossSvg(info.id, 'idle'), label: info.name, kind: 'boss', peek: () => bossPeek(info, number) };
}

function winGifts(win) {
  return [itemGift(win.item), itemGift(win.twin), itemGift(win.extra),
    { icon: '◆', label: `+${win.diamonds}`, kind: 'gem', reward: true },
    win.coins ? { icon: '✦', label: `+${format(win.coins)}`, kind: 'coin', reward: true } : null,
    win.bricks ? { icon: BRICK_ICON, label: `+${win.bricks}`, kind: 'brick', reward: true } : null];
}

// What opens in a world, as icons: its bonus, new machines and upgrades, new
// things to do, new houses for the city, new critters, and its three bosses.
function newHereGifts(number) {
  const info = worldInfo(number);
  const gifts = [{ icon: info.symbol, label: `×${format(worldMult(number))}`, kind: 'world' }];
  const feature = (icon, html) => {
    const name = htmlText((html.match(/<b>(.*?)<\/b>/) || ['', ''])[1]).replace(/[:：]\s*$/, '');
    return { icon, label: name, peek: () => peekHtml(icon, name, [html]) };
  };
  machines.forEach(m => {
    if (m.world === number) gifts.push({ icon: m.icon, label: m.name, peek: () => peekHtml(m.icon, m.name, [T`New machine: <b>${m.name}</b>`, m.description]) });
  });
  upgrades.forEach(u => {
    if (u.world === number) gifts.push({ icon: u.icon, label: u.name, peek: () => peekHtml(u.icon, u.name, [T`New upgrade: <b>${u.name}</b>`, u.description]) });
  });
  if (FEATURE_WORLD.combo === number) gifts.push(feature(BOLT_ICON, tr('<b>The combo meter:</b> tap fast for up to 2× per tap')));
  if (FEATURE_WORLD.rain === number) gifts.push(feature('☂', tr('<b>Coin rain:</b> now and then, coins fall from the sky')));
  if (CITY.world === number) gifts.push(feature(BRICK_ICON, T`<b>The City:</b> critters and bosses drop bricks, to build ${CITY.name} with`));
  BUILDINGS.forEach(b => {
    if (b.world === number && number > CITY.world) gifts.push({ icon: buildingSvg(b.id, 1), label: b.name, kind: 'house', peek: () => peekHtml(buildingSvg(b.id, 1), b.name, [T`New in the City: <b>${b.name}</b>`], 'house') });
  });
  const critters = MONSTERS.filter(kind => kind.world === number && number > 1);
  if (critters.length) {
    gifts.push({ icon: monsterSvg(critters[0].id, 'happy'), label: `${tr('Critters')} ×${critters.length}`, kind: 'critter',
      peek: () => peekHtml(monsterSvg(critters[0].id, 'happy'), tr('Critters'), [`<span class="peek-critters">${critters.map(kind => `<span><i>${monsterSvg(kind.id, 'happy')}</i><small>${kind.name}</small></span>`).join('')}</span>`], 'critter') });
  }
  if (number <= WORLDS.length) bossesOf(number).forEach(boss => gifts.push(bossGift(boss, number)));
  return gifts;
}

// What starts over and what you keep, as the travel window says it.
function travelNote(next) {
  const box = document.createElement('div');
  box.innerHTML = travelList(next);
  return [...box.querySelectorAll('li')].slice(-2).map(li => `<p>${li.innerHTML}</p>`).join('');
}

// A win: the boss says its last word, Pip shows what we got, and then what
// comes next, with the choices as answers.
function bossWinScene(win) {
  const info = BOSS_BY_ID[win.id];
  const notes = `${win.twin ? mirrorNote : ''}${win.greedy ? T`<p class="loot-note">The Greedy Purse made the coins ${GREED}×!</p>` : ''}${wagerNote(win)}`;
  dialogue([
    { who: win.id, mood: 'hurt', text: bossLine(info, 1, win.number) },
    { text: tr('Look what we got!'), gifts: winGifts(win), note: notes },
    winNextLine(win)
  ], { auto: true, scene: win.rank === 2 ? 'cleared' : 'bosswin' }).then(answer => winAnswer(win, answer));
}

function winNextLine(win) {
  const more = !win.extra && adsLeft('treasure') >= 1 ? [{ label: state.plus ? tr('✦ Take one more treasure') : tr('▶ Watch an ad for one more treasure'), value: 'ad', soft: true }] : [];
  if (win.rank === 2) {
    const next = worldInfo(win.number + 1);
    return { text: T`The portal to ${next.name} is open!`, gifts: newHereGifts(next.number), note: travelNote(next),
      answers: [{ label: T`Travel to ${next.name}`, value: 'travel' }, { label: tr('Stay a little longer'), value: 'stay', soft: true }, ...more] };
  }
  const next = bossesOf(win.number)[win.rank + 1];
  if (!next) return { text: tr('Onward!'), answers: [{ label: tr('Onward!'), value: 'close' }, ...more] };
  const ready = bossReady() && nextBoss() === next;
  return { text: ready ? T`Next up: ${next.name}. Ready when you are!` : T`Next up: ${next.name}, at coin level ${bossLevel(next.rank, win.number)}.`,
    gifts: [bossGift(next, win.number)],
    answers: ready ? [{ label: T`Fight ${next.name}`, value: 'fight' }, { label: tr('Not yet'), value: 'close', soft: true }, ...more] : [{ label: tr('Onward!'), value: 'close' }, ...more] };
}

function winAnswer(win, answer) {
  const scene = win.rank === 2 ? 'cleared' : 'bosswin';
  if (answer === 'busy') openModal(scene, true);
  else if (answer === 'fight') startBoss();
  else if (answer === 'travel') travel();
  else if (answer === 'ad') {
    adTreasure(win, () => dialogue([{ text: tr('One more treasure!'), gifts: [itemGift(win.extra)] }, winNextLine(win)], { auto: true, scene })
      .then(again => winAnswer(win, again)));
  }
}

// The portal, from the card under the coin: Pip tells what is new over there,
// with Travel and Stay as answers, as after a ruler's win.
function portalScene() {
  const next = worldInfo(state.world + 1);
  return dialogue([{ text: T`The portal to ${next.name} is open!`, gifts: newHereGifts(next.number), note: travelNote(next),
    answers: [{ label: T`Travel to ${next.name}`, value: 'travel' }, { label: tr('Stay a little longer'), value: 'stay', soft: true }] }], { scene: 'portal' })
    .then(answer => {
      if (answer === 'busy') openModal('travel');
      else if (answer === 'travel') travel();
    });
}

// A new world: its name comes in on a sign, Pip tells how the chapter begins
// (all of it is in his diary), and then what is new here.
function arrivalScene(number = state.world) {
  const story = dlgLines(chapterFor(number).text.map(htmlText)).slice(0, 2);
  worldSign(number);
  return dialogue([
    ...story.map(text => ({ text })),
    { text: tr('The whole story is in my diary, under Worlds.'), mark: '.nav-item[data-go="worlds"]' },
    { text: T`Everything you earn here is ×${format(worldMult(number))}. And this is new:`, gifts: newHereGifts(number) }
  ], { auto: true, dim: 'light', scene: 'arrived' }).then(answer => {
    worldSignHide();
    return answer;
  });
}

function worldSign(number) {
  let el = $('world-sign');
  if (!el) {
    el = document.createElement('div');
    el.id = 'world-sign';
    el.setAttribute('aria-hidden', 'true');
    document.body.appendChild(el);
  }
  const info = worldInfo(number);
  el.className = 'world-sign';
  el.innerHTML = `<b>${info.symbol}</b><span>${T`WORLD ${number} · ${info.name.toUpperCase().replace(/ /g, ' ')}`}</span>`;
}

function worldSignHide() {
  const el = $('world-sign');
  if (!el) return;
  el.classList.add('leaving');
  setTimeout(() => {
    if (el.classList.contains('leaving')) el.className = 'world-sign hidden';
  }, 400);
}

// What comes next under the coin, as icons: the next metal and the next boss,
// each at its level. A tap on one shows more about it.
function levelNoteHtml() {
  const info = !state.bossBeaten && nextBoss();
  if (!info) return levelNote();
  const at = bossLevel(info.rank);
  if (state.coinLevel >= at) return levelNote();
  const metal = (materialIndex(state.coinLevel) + 1) * LEVEL.perMaterial;
  const chips = [
    [metal, `<button class="next-chip" type="button" data-action="peek-material" data-level="${metal}">${coinDisc(material(metal))}<small>${T`LV ${metal}`}</small></button>`],
    [at + 0.5, `<button class="next-chip boss" type="button" data-action="peek-boss" data-id="${info.id}">${bossSvg(info.id)}<small>${T`LV ${at}`}</small></button>`]
  ];
  return `<span class="next-chips">${chips.sort((a, b) => a[0] - b[0]).map(chip => chip[1]).join('')}</span>`;
}

function storyBubble(lines, who = 'pip', mood = 'idle') {
  const text = (Array.isArray(lines) ? lines : [lines]).map(line => `<p>${line}</p>`).join('');
  const info = BOSS_BY_ID[who];
  const baron = who === 'baron' || who === 'ironbaron';
  return `<div class="story ${info ? `boss${baron ? ' baron' : ''}` : 'pip'}">
    <div class="story-face">${info ? bossSvg(who, mood) : pipSvg(mood)}</div>
    <div class="story-text">${text}<em>${info ? info.name : tr('Pip')}</em></div>
  </div>`;
}

const chapterFor = number => (number > WORLDS.length ? STORY.lap : STORY.chapters[number - 1]);



// "a, b and c", leaving out the empty ones.
function andList(parts) {
  const list = parts.filter(Boolean);
  if (listFormat && list.length > 1) return listFormat.format(list);
  return list.length > 1 ? T`${list.slice(0, -1).join(', ')} and ${list[list.length - 1]}` : list[0] || '';
}

function bossLootHtml(win) {
  return `<div class="boss-loot">
    ${lootRowHtml(win.item)}
    ${win.twin ? `${lootRowHtml(win.twin, '+ ')}${mirrorNote}` : ''}
    <div class="loot-line"><span>+${win.diamonds} ◆</span>${win.coins ? `<span>+${format(win.coins)} ✦</span>` : ''}${win.bricks ? `<span class="loot-bricks">+${win.bricks} ${BRICK_ICON}</span>` : ''}</div>
    ${win.greedy ? T`<p class="loot-note">The Greedy Purse made the coins ${GREED}×!</p>` : ''}
  </div>`;
}

function travelList(next) {
  const unlocks = unlocksIn(next.number);
  return T`<ul class="modal-list">
    <li><b>In ${next.name}</b> everything you earn is ×${format(worldMult(next.number))}.</li>
    ${unlocks.map(text => `<li>${text}</li>`).join('')}
    <li><b>Starts over:</b> coins, coin level, machines and upgrades.${itemLevel('headstart') ? T` Your Head Start Boots start the coin at level ${1 + itemLevel('headstart')}.` : ''}</li>
    <li>${state.city.open ? tr('<b>You keep:</b> diamonds, treasures, Forever boosts, your city, goals and stats.') : tr('<b>You keep:</b> diamonds, treasures, Forever boosts, goals and stats.')}</li>
  </ul>`;
}

function renderModal() {
  const content = $('modal-content');
  if (modalType === 'away') {
    if (!pendingAway) {
      closeModal();
      return;
    }
    const capped = pendingAway.seconds > offlineCapHours() * 3600;
    content.innerHTML = T`<div class="modal-icon gold">☾</div>
      <div class="eyebrow">WELCOME BACK</div>
      <h2 id="modal-title">Your machines kept busy<span>.</span></h2>
      <p class="modal-copy">You were away for ${formatDuration(pendingAway.seconds)}.${capped ? T` Machines earn for up to ${offlineCapHours()} hours while you're away. Offline Vault in the Shop makes that longer.` : ''}</p>
      <div class="modal-big">✦ ${format(pendingAway.amount)}</div>
      <div class="modal-actions">
        <button class="modal-action" data-action="collect-away">Collect</button>
        <button class="modal-action soft" data-action="ad-double-away">${state.plus ? tr('Collect 2× with Plus') : tr('▶ Watch an ad to collect 2×')}</button>
      </div>`;
  } else if (modalType === 'daily') {
    const info = dailyInfo();
    content.innerHTML = T`<div class="modal-icon">◆</div>
      <div class="eyebrow">A LITTLE SOMETHING FOR YOU</div>
      <h2 id="modal-title">Your daily sparkle<span>.</span></h2>
      <p class="modal-copy">Good to see you! A new gift waits every day you visit, and every 7th gift brings one of Pip\'s friends.</p>
      ${giftCalendar(info)}
      <button class="modal-action purple" data-action="claim-daily" ${info.claimed ? 'disabled' : ''}>${info.claimed ? tr('Already claimed today') : claimLabel(info.gift)}</button>`;
  } else if (modalType === 'bosswin') {
    const win = lastBossWin;
    if (!win) {
      closeModal();
      return;
    }
    const info = BOSS_BY_ID[win.id];
    const next = bossesOf(win.number)[win.rank + 1];
    const ready = next && bossReady() && nextBoss() === next;
    content.innerHTML = T`<div class="eyebrow center">WORLD ${win.number} · ${RANK_NAMES[win.rank].toUpperCase()} BEATEN</div>
      <h2 id="modal-title" class="center">${info.name} is beaten<span>!</span></h2>
      ${storyBubble(bossLine(info, 1, win.number), info.id, 'hurt')}
      ${bossLootHtml(win)}
      ${extraTreasureHtml(win)}
      ${next ? T`<p class="modal-copy center">Next: <b>${next.name}</b>, ${next.rank === 2 ? tr('the ruler') : tr('the second guard')}, at coin level ${bossLevel(next.rank, win.number)}.${ready ? tr(' You are ready now!') : ''}</p>` : ''}
      <div class="modal-actions">
        ${ready ? T`<button class="modal-action fight" data-action="boss-start">Fight ${next.name}</button>` : ''}
        <button class="modal-action${ready ? ' soft' : ''}" data-action="close">${ready ? tr('Not yet') : tr('Onward!')}</button>
      </div>`;
  } else if (modalType === 'cleared' || modalType === 'travel') {
    const next = worldInfo(state.world + 1);
    const win = modalType === 'cleared' ? lastBossWin : null;
    const info = win && BOSS_BY_ID[win.id];
    content.innerHTML = T`<div class="modal-icon gold">${win ? '♛' : next.symbol}</div>
      <div class="eyebrow">${win ? T`WORLD ${state.world} CLEARED` : tr('THE PORTAL IS OPEN')}</div>
      <h2 id="modal-title">${win ? T`${info.name} is beaten` : T`Travel to ${next.name}`}<span>${win ? '!' : '?'}</span></h2>
      ${win ? T`${storyBubble(bossLine(info, 1, win.number), info.id, 'hurt')}${bossLootHtml(win)}${extraTreasureHtml(win)}<p class="modal-copy">The portal to <b>${next.name}</b> is open.</p>` : ''}
      ${travelList(next)}
      <div class="modal-actions">
        <button class="modal-action" data-action="travel">Travel to ${next.name}</button>
        <button class="modal-action soft" data-action="close">Stay a little longer</button>
      </div>`;
  } else if (modalType === 'arrived') {
    const info = world();
    const unlocks = unlocksIn(state.world);
    content.innerHTML = T`<div class="eyebrow">WORLD ${state.world} · ${chapterFor(state.world).title.toUpperCase()}</div>
      <h2 id="modal-title">Welcome to ${info.name}<span>.</span></h2>
      ${storyBubble(chapterFor(state.world).text)}
      <p class="modal-copy">Everything you earn is now <b>×${format(worldMult())}</b>. Three bosses guard this world: two guards on the way, and the ruler at coin level ${targetLevel()}.</p>
      ${unlocks.length ? `<ul class="modal-list">${unlocks.map(text => `<li>${text}</li>`).join('')}</ul>` : ''}
      <button class="modal-action" data-action="close">Let's go</button>`;
  } else if (modalType === 'prologue') {
    const chapter = STORY.chapters[0];
    content.innerHTML = T`<div class="eyebrow">CHAPTER 1 · THE MEADOW</div>
      <h2 id="modal-title">${chapter.title}<span>!</span></h2>
      ${storyBubble(chapter.text)}
      <p class="modal-copy">Pip writes every chapter down. Read them again any time under Worlds.</p>
      <button class="modal-action" data-action="close">Let's grow this coin</button>`;
  } else if (modalType === 'chapter') {
    const lap = chapterShown >= STORY.chapters.length;
    const chapter = lap ? STORY.lap : STORY.chapters[chapterShown];
    const place = lap ? tr('Round again') : WORLDS[chapterShown].name;
    content.innerHTML = T`<div class="eyebrow">CHAPTER ${chapterShown + 1} · ${place.toUpperCase()}</div>
      <h2 id="modal-title">${chapter.title}<span>.</span></h2>
      ${storyBubble(chapter.text)}
      <button class="modal-action" data-action="close">Close the journal</button>`;
  } else if (modalType === 'fight') {
    renderFight(content);
  } else if (modalType === 'loot') {
    const loot = lastLoot;
    if (!loot) {
      closeModal();
      return;
    }
    const type = ITEM_BY_ID[loot.type];
    const rarity = type && RARITIES[type.rarity];
    content.innerHTML = T`<div class="eyebrow center">YOU BEAT THE ${loot.monster.toUpperCase()}!</div>
      ${loot.tale ? T`<p class="tale"><b>New in Pip's notes.</b> ${loot.tale}</p>` : ''}
      ${type ? `<div class="loot-card ${rarity.id}">
        <div class="loot-icon">${type.icon}</div>
        <div class="loot-rarity">${rarity.name} · ${levelNews(loot)}</div>
        <h2 id="modal-title">${type.item}</h2>
        <p>${treasureEffect(type, loot.level)}</p>
      </div>` : T`<h2 id="modal-title" class="center">Diamonds instead<span>!</span></h2><div class="boss-loot">${lootRowHtml(loot)}</div>`}
      ${loot.twin ? `<div class="boss-loot">${lootRowHtml(loot.twin, '+ ')}${mirrorNote}</div>` : ''}
      <p class="modal-copy center">It also dropped ${andList([`<b>✦ ${format(loot.coins)}</b>`, loot.bricks ? `<b>${P(loot.bricks, '{0} brick', '{0} bricks')}</b>` : '', loot.gem ? '<b>1 ◆</b>' : ''])}.${loot.greedy ? T` The Greedy Purse made the coins ${GREED}×!` : ''} Your treasures are behind the chest at the top.</p>
      ${extraTreasureHtml(loot)}
      <button class="modal-action" data-action="close">Collect</button>`;
  } else if (modalType === 'treasure') {
    const type = ITEM_BY_ID[treasureShown];
    const level = type ? itemLevel(type.id) : 0;
    if (!type || !level) {
      closeModal();
      return;
    }
    const rarity = RARITIES[type.rarity];
    const maxed = level >= type.max;
    const droppers = MONSTERS.filter(kind => kind.drop === type.id).map(kind => (state.bestiary[kind.id] ? kind.name : '???'));
    content.innerHTML = T`<div class="eyebrow center">TREASURE · ${maxed ? tr('MAX LEVEL') : T`LEVEL ${level} OF ${type.max}`}</div>
      <div class="loot-card ${rarity.id}">
        <div class="loot-icon">${type.icon}</div>
        <div class="loot-rarity">${rarity.name}</div>
        <h2 id="modal-title">${type.item}</h2>
        <p>${treasureEffect(type, level)}</p>
      </div>
      <div class="credits">
        <div><span>Level</span><strong>${level} of ${type.max}</strong></div>
        ${maxed ? '' : T`<div><span>Next level</span><strong>${treasureEffect(type, level + 1)}</strong></div>
        <div><span>At level ${type.max}</span><strong>${treasureEffect(type, type.max)}</strong></div>`}
        <div><span>Found</span><strong>×${format(state.itemCounts[type.id])}</strong></div>
      </div>
      ${droppers.length ? T`<p class="modal-copy center">Often dropped by ${andList(droppers)}.</p>` : ''}
      <p class="modal-copy center">${maxed ? tr('It is at its highest level, so it won\'t drop again.') : tr('Find it again to raise its level.')}</p>
      <button class="modal-action soft" data-action="open-treasures">Back to the treasures</button>`;
  } else if (modalType === 'critter') {
    const kind = MONSTERS.find(k => k.id === critterShown);
    if (!kind || !state.bestiary[kind.id]) {
      closeModal();
      return;
    }
    const rarity = rarityOf(kind);
    content.innerHTML = T`<div class="eyebrow center">WORLD ${kind.world} · ${worldInfo(kind.world).name.toUpperCase()}</div>
      <div class="critter-big">${monsterSvg(kind.id, 'happy')}</div>
      <h2 id="modal-title" class="center">${kind.name}<span>.</span></h2>
      <p class="modal-copy center">${rarityPill(rarity)}</p>
      ${kind.tale ? `<p class="tale">${kind.tale}</p>` : ''}
      <div class="credits">
        <div><span>Beaten</span><strong>×${format(state.bestiary[kind.id])}</strong></div>
        <div><span>Moves by</span><strong>${{ hop: tr('Hopping'), scuttle: tr('Scuttling'), waddle: tr('Waddling'), float: tr('Floating'), glide: tr('Gliding'), roll: tr('Rolling') }[kind.move] || tr('Walking')}</strong></div>
        ${kind.drop ? T`<div><span>Often drops</span><strong>${ITEM_BY_ID[kind.drop].item} (${RARITIES[ITEM_BY_ID[kind.drop].rarity].name})</strong></div>` : ''}
      </div>
      <button class="modal-action soft" data-action="close">Back to the notes</button>`;
  } else if (modalType === 'credits') {
    content.innerHTML = T`<div class="modal-icon gold">✦</div>
      <div class="eyebrow">CREDITS</div>
      <h2 id="modal-title">Coinfolk<span>.</span></h2>
      <div class="credits">
        <div><span>Made by</span><strong>ShameSauce</strong></div>
        <div><span>Music, pictures and critters</span><strong>Made for Coinfolk</strong></div>
        <div><span>Fonts</span><strong>DM Sans and Space Grotesk</strong><small>SIL Open Font License 1.1</small></div>
        <div><span>Version</span><strong>${VERSION}</strong></div>
      </div>
      <p class="modal-copy center">Thank you for playing! ✦</p>
      <button class="modal-action" data-action="close">Back to the coin</button>`;
    const versionRow = content.querySelector('.credits > div:last-child');
    if (versionRow) versionRow.insertAdjacentHTML('beforebegin', `<div><span>${tr('Instruments in the music')}</span><strong>${tr('Fluid sound font by Frank Wen')}</strong><small>MIT License</small></div>`);
  } else if (modalType === 'devnote') {
    content.innerHTML = T`<div class="modal-icon gold">✎</div>
      <div class="eyebrow">BEHIND THE CURTAIN</div>
      <h2 id="modal-title">Hello from ShameSauce<span>!</span></h2>
      <p class="modal-copy">You found the back room. Thank you for playing Coinfolk and for poking around back here. Pip says hi.</p>
      <div class="credits">
        <div><span>Your taps</span><strong>${format(state.stats.taps)}</strong></div>
        <div><span>Time played</span><strong>${formatDuration(state.stats.playSeconds)}</strong></div>
        <div><span>Monsters beaten</span><strong>${format(state.stats.monsters)}</strong></div>
      </div>
      <button class="modal-action" data-action="close">Back to the coin</button>`;
  } else if (modalType === 'gift') {
    const got = lastGift;
    if (!got) {
      closeModal();
      return;
    }
    if (got.friend) {
      const friend = FRIEND_BY_ID[got.friend];
      content.innerHTML = T`<div class="eyebrow center">DAY ${got.day} GIFT · A NEW FRIEND</div>
        <div class="friend-hero">${friendSvg(friend.id, 'happy')}</div>
        <h2 id="modal-title" class="center">${friend.name} comes to stay<span>!</span></h2>
        <p class="modal-copy center">${friend.about}</p>
        <div class="friend-perk">${friendPerk(friend)}, for good</div>
        <p class="tale center">“${friend.lines[0]}”</p>
        <p class="modal-copy center">And <b>+${got.diamonds} ◆</b> on top.</p>
        <div class="modal-actions">${buddyButton(friend)}<button class="modal-action soft" data-action="close">Lovely</button></div>`;
    } else {
      const type = got.item && ITEM_BY_ID[got.item.type];
      const rarity = type && RARITIES[type.rarity];
      content.innerHTML = T`<div class="eyebrow center">DAY ${got.day} GIFT · A TREASURE</div>
        ${type ? `<div class="loot-card ${rarity.id}">
          <div class="loot-icon">${type.icon}</div>
          <div class="loot-rarity">${rarity.name} · ${levelNews(got.item)}</div>
          <h2 id="modal-title">${type.item}</h2>
          <p>${treasureEffect(type, got.item.level)}</p>
        </div>` : T`<h2 id="modal-title" class="center">Diamonds instead<span>!</span></h2><div class="boss-loot">${lootRowHtml(got.item)}</div>`}
        <p class="modal-copy center">Your treasures are behind the chest at the top.</p>
        <button class="modal-action" data-action="close">Lovely</button>`;
    }
  } else if (modalType === 'building') {
    const b = BUILDING_BY_ID[buildingShown];
    if (!b || !state.city.open) {
      closeModal();
      return;
    }
    content.innerHTML = buildingModalHtml(b);
  } else if (modalType === 'city') {
    content.innerHTML = cityIntroHtml();
  } else if (modalType === 'bought') {
    if (!lastBuy) {
      closeModal();
      return;
    }
    content.innerHTML = boughtHtml();
  } else if (modalType === 'friend') {
    const friend = FRIEND_BY_ID[friendShown];
    if (!friend || !state.friends.includes(friend.id)) {
      closeModal();
      return;
    }
    content.innerHTML = T`<div class="eyebrow center">PIP’S FRIEND · ${friend.metal.toUpperCase()}</div>
      <div class="friend-hero">${friendSvg(friend.id, 'happy')}</div>
      <h2 id="modal-title" class="center">${friend.name}<span>.</span></h2>
      <p class="modal-copy center">${friend.about}</p>
      <div class="friend-perk">${friendPerk(friend)}, for good</div>
      <p class="tale center">“${friend.lines[Math.floor(Math.random() * friend.lines.length)]}”</p>
      <div class="modal-actions">${buddyButton(friend)}<button class="modal-action soft" data-action="close">Back</button></div>`;
  } else if (modalType === 'globe') {
    // Drawn again only when opened: the globe turns by itself in between.
    if (globeFresh || !content.querySelector('#globe-stage')) {
      globeFresh = false;
      content.innerHTML = globeHtml();
      requestAnimationFrame(globeStart);
    } else globeRefresh();
  } else if (modalType === 'wardrobe') {
    content.innerHTML = wardrobeHtml();
  } else if (modalType === 'treasures') {
    content.innerHTML = treasuresHtml();
  } else if (modalType === 'handbook') {
    content.innerHTML = handbookHtml();
  } else if (modalType === 'hb-page') {
    content.innerHTML = handbookPageHtml(HANDBOOK.find(page => page.id === hbShown) || HANDBOOK[0]);
  } else if (modalType === 'achievements') {
    const got = state.achievements.length;
    content.innerHTML = collectionTabs('achievements') + T`<div class="eyebrow">${got} OF ${ACHIEVEMENTS.length} · +${got}% TAPS AND INCOME</div>
      <p class="modal-copy">Tap one to see the details. Secret ones show as ??? until you find them, but each has a hint.</p>
      <div class="ach-grid">${ACHIEVEMENTS.map(achBadge).join('')}</div>`;
  } else if (modalType === 'ach') {
    content.innerHTML = achievementDetail(ACHIEVEMENTS.find(a => a.id === achShown) || ACHIEVEMENTS[0]);
  } else if (modalType === 'heli') {
    const reward = lastHeli || { coins: 0, diamonds: 0 };
    content.innerHTML = T`<div class="heli-meme">
        <div class="meme-caption">Helicopter</div>
        <button class="meme-picture" data-action="encore" aria-label="Helicopter">${heliSvg()}</button>
        <div class="meme-caption">Helicopter</div>
      </div>
      <p class="modal-copy center">You caught the rare helicopter! It dropped <b>✦ ${format(reward.coins)}</b> and <b>${reward.diamonds} ◆</b>.</p>
      <button class="modal-action" data-action="close">Nice!</button>`;
  } else if (modalType === 'giveup') {
    content.innerHTML = T`<div class="modal-icon red">⚔</div>
      <div class="eyebrow">BOSS FIGHT PAUSED</div>
      <h2 id="modal-title">Give up the fight<span>?</span></h2>
      <p class="modal-copy">The boss will wait, and you can try again whenever you like.</p>
      <div class="modal-actions">
        <button class="modal-action" data-action="boss-resume">Keep fighting</button>
        <button class="modal-action soft" data-action="boss-giveup">Give up</button>
      </div>`;
  } else if (modalType === 'quit') {
    content.innerHTML = T`<div class="modal-icon gold">☾</div>
      <div class="eyebrow">LEAVING ALREADY?</div>
      <h2 id="modal-title">See you soon<span>?</span></h2>
      <p class="modal-copy">Your machines keep earning while you're away.</p>
      <div class="modal-actions">
        <button class="modal-action" data-action="stay">Keep playing</button>
        <button class="modal-action soft" data-action="quit">Leave Coinfolk</button>
      </div>`;
  } else if (modalType === 'adboost') {
    const running = boostLeft('ad') > 0;
    content.innerHTML = T`<div class="modal-icon gold">2×</div>
      <div class="eyebrow">2× INCOME</div>
      <h2 id="modal-title">Watch a short video<span>?</span></h2>
      <p class="modal-copy">After the video, everything you earn is doubled for ${running ? T`${AD.boostMinutes} more` : AD.boostMinutes}${''} minutes. ${adsLeft('boost')} left today.</p>
      <div class="modal-actions">
        <button class="modal-action" data-action="ad-boost-go">▶ Watch the video</button>
        <button class="modal-action soft" data-action="close">Not now</button>
      </div>`;
  } else if (modalType === 'whatsnew') {
    const entries = newsShown.length ? newsShown : CHANGELOG.slice(0, 1);
    content.innerHTML = T`<div class="modal-icon gold">✦</div>
      <div class="eyebrow">WHAT'S NEW · VERSION ${entries[0].version}</div>
      <h2 id="modal-title">${entries[0].title}<span>!</span></h2>
      ${entries.map((entry, i) => `${i ? `<h3 class="change-head"><b>${entry.version}</b> ${entry.title}</h3>` : ''}${changeList(entry)}`).join('')}
      <div class="modal-actions">
        <button class="modal-action" data-action="close">Let's play</button>
        <button class="modal-action soft" data-action="open-history">All updates</button>
      </div>`;
  } else if (modalType === 'history') {
    content.innerHTML = T`<div class="modal-icon gold">◷</div>
      <div class="eyebrow">COINFOLK ${VERSION}</div>
      <h2 id="modal-title">Update history<span>.</span></h2>
      ${CHANGELOG.map(entry => `<h3 class="change-head"><b>${entry.version}</b> ${entry.title}</h3>${changeList(entry)}`).join('')}
      <div class="modal-actions">
        ${historyFrom === 'settings' ? tr('<button class="modal-action soft" data-action="back-to-settings">Back to settings</button>') : tr('<button class="modal-action soft" data-action="close">Close</button>')}
      </div>`;
  } else if (modalType === 'jukebox') {
    content.innerHTML = jukeboxHtml();
  } else if (modalType === 'chest') {
    content.innerHTML = chestWindowHtml();
  } else if (modalType === 'game') {
    if (!GAME_BY_ID[gameShown]) {
      closeModal();
      return;
    }
    // Drawn again only when a game is opened: a round goes on underneath other updates.
    if (gameFresh || !content.querySelector(`.game-wrap[data-game="${gameShown}"]`)) {
      gameFresh = false;
      content.innerHTML = gameHtml();
    }
  } else if (modalType === 'language') {
    const choice = languageChoice();
    content.innerHTML = T`<div class="modal-icon gold">文</div>
      <div class="eyebrow">SETTINGS</div>
      <h2 id="modal-title">Language<span>.</span></h2>
      <div class="language-list" role="radiogroup" aria-label="Language">
        <button class="language-option${choice === 'auto' ? ' active' : ''}" data-action="set-language" data-lang="auto" role="radio" aria-checked="${choice === 'auto'}">Like the phone</button>
        ${LANGS.map(([code, name]) => `<button class="language-option${choice === code ? ' active' : ''}" data-action="set-language" data-lang="${code}" lang="${code}" role="radio" aria-checked="${choice === code}">${name}</button>`).join('')}
      </div>
      <p class="note">The game starts again in the new language. Nothing is lost.</p>
      <div class="modal-actions"><button class="modal-action soft" data-action="back-to-settings">Back to settings</button></div>`;
  } else if (modalType === 'spend') {
    const spend = pendingSpend || { cost: 0, name: '' };
    content.innerHTML = `<div class="modal-icon purple">◆</div>
      <div class="eyebrow">${tr('ARE YOU SURE?')}</div>
      <h2 id="modal-title">${T`Spend ◆ ${spend.cost} on ${spend.name}?`}</h2>
      <p class="modal-copy">${T`You have ◆ ${format(state.diamonds)}.`}</p>
      <div class="modal-actions">
        <button class="modal-action" data-action="spend-yes">${tr('Yes, spend them')}</button>
        <button class="modal-action soft" data-action="close">${tr('No')}</button>
      </div>
      <p class="note">${tr('You can turn this question off in Settings, under Confirmations.')}</p>`;
  } else if (modalType === 'remind') {
    content.innerHTML = `<div class="modal-icon gold">${BELL_ICON}</div>
      <div class="eyebrow">${tr('REMINDERS')}</div>
      <h2 id="modal-title">${tr('Shall Pip give you a nudge?')}</h2>
      <p class="modal-copy">${tr('Pip can tell you when the vault is full and when a new daily gift is waiting. At most one of each a day, and you can turn them off in Settings.')}</p>
      <div class="modal-actions">
        <button class="modal-action" data-action="remind-yes">${tr('Yes, remind me')}</button>
        <button class="modal-action soft" data-action="remind-no">${tr('Not now')}</button>
      </div>`;
  } else if (modalType === 'settings') {
    content.innerHTML = settingsHtml();
    lockPlay();
  } else if (modalType === 'help') {
    content.innerHTML = T`<div class="modal-icon gold">✦</div>
      <div class="eyebrow">WELCOME TO COINFOLK</div>
      <h2 id="modal-title">A little guide<span>.</span></h2>
      <ul class="modal-list">
        <li><b>Coin:</b> tap to earn. Level up your coin for stronger taps. Every 10 levels it turns into a new material.</li>
        <li><b>Machines</b> earn on their own, even while you're away.</li>
        <li><b>Bosses:</b> every world has three. Two guards wait on the way, and the ruler at the end holds the portal. Each boss has its own trick, and Pip tells you about it. Tap the glowing weak spots for 5× damage. Bosses grow with you: when a fight starts, the boss sizes you up, so it is always a real fight. A few coin levels past it, boosts, streaks and weak spots make it easier.</li>
        <li><b>Worlds:</b> beat the ruler to travel on. You start over, but everything earns ×${worldBonus(state.world + 1)} more, and each world brings something new.</li>
        <li><b>Hot streak:</b> every fight you win in a row adds 4% to taps and income. Losing or running away ends it.</li>
        <li><b>Combo:</b> from World 2, fast tapping fills the combo meter for up to 2× per tap. Once it is full, it stays full as long as you keep tapping, and drains slowly when you stop.</li>
        <li><b>Monsters</b> walk past the coin now and then. Tap one to fight it. Win, and it drops a treasure that lasts forever. Rare, big and shiny ones drop better loot. Your treasures are behind the chest at the top.</li>
        <li><b>The City:</b> from World 2, critters and bosses drop bricks. Build ${CITY.name} with them under City. Every building helps for good, and your city stays when you travel. Tap the people in the street to hear what they have to say.</li>
        <li><b>Surprises:</b> golden coins with all kinds of bonuses, coin rain and a very rare helicopter.</li>
        <li><b>Buying:</b> hold a buy button to keep buying.</li>
        <li><b>The daily gift:</b> a new gift every day you visit, like diamonds, coins, 2× income or a treasure. Every 7th gift, one of Pip's friends comes to stay and helps out for good.</li>
        <li><b>Goals, daily quests and achievements</b> give free diamonds. Each achievement also adds 1% to taps and income, and some are secret. Goals wait under the ★ at the top, achievements in the chest next to it.</li>
      </ul>
      <button class="modal-action" data-action="close">Let's play</button>`;
  } else if (modalType === 'backup' || modalType === 'backup-load') {
    content.innerHTML = backupHtml();
  } else if (modalType === 'reset') {
    content.innerHTML = T`<div class="modal-icon red">!</div>
      <div class="eyebrow">ARE YOU SURE?</div>
      <h2 id="modal-title">Reset everything<span>?</span></h2>
      <p class="modal-copy">This removes all coins, worlds, diamonds, boosts and goals on this device. It can't be undone.</p>
      <div class="modal-actions">
        <button class="modal-action danger" data-action="reset">Yes, reset all progress</button>
        <button class="modal-action soft" data-action="close">Keep my empire</button>
      </div>`;
  }
}

/* -----------------------------------------------------------------
   8. EFFECTS, SOUND AND MUSIC
   ----------------------------------------------------------------- */
function notify(message) {
  const toast = $('toast');
  toast.textContent = message;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), 2600);
}

function spawnFloat(x, y, amount, lucky, damage = false, layerId = 'fx-layer') {
  const layer = $(layerId);
  if (!layer || layer.childElementCount > 60) return;
  const el = document.createElement('span');
  el.className = `float-number${lucky ? ' crit' : ''}${damage ? ' damage' : ''}`;
  el.textContent = `${damage ? '−' : '+'}${format(amount)}${lucky ? '!' : ''}`;
  if (!damage && funOn('funRainbow')) el.style.color = `hsl(${Math.floor(Math.random() * 360)}, 92%, 70%)`;
  el.style.left = `${x + (Math.random() * 40 - 20)}px`;
  el.style.top = `${y - 20}px`;
  layer.appendChild(el);
  setTimeout(() => el.remove(), 850);
}

function spawnDrops(x, y, count) {
  if (!effectsAll()) return;
  const layer = $('fx-layer');
  for (let k = 0; k < count && layer.childElementCount < 60; k++) {
    const el = document.createElement('span');
    el.className = 'coin-drop';
    el.style.left = `${x}px`;
    el.style.top = `${y}px`;
    el.style.setProperty('--dx', `${Math.round(Math.random() * 160 - 80)}px`);
    layer.appendChild(el);
    setTimeout(() => el.remove(), 900);
  }
}

// A ring that spreads from where you tapped.
function spawnRing(x, y) {
  if (effectsOff()) return;
  const layer = $('fx-layer');
  if (!layer || layer.childElementCount > 60) return;
  const ring = document.createElement('span');
  ring.className = 'tap-ring';
  ring.style.left = `${x}px`;
  ring.style.top = `${y}px`;
  layer.appendChild(ring);
  setTimeout(() => ring.remove(), 450);
}

function bumpBadge() {
  const badge = $('level-badge');
  if (!badge) return;
  badge.classList.remove('bump');
  void badge.offsetWidth;
  badge.classList.add('bump');
}

// The coin turns into a new material: it spins, flashes and throws sparks,
// and a banner names the new metal.
function celebrateMaterial() {
  const look = material(state.coinLevel);
  const stage = $('coin-stage');
  const coin = $('coin-button');
  if (!stage || !coin) return;
  coin.classList.remove('evolve');
  void coin.offsetWidth;
  coin.classList.add('evolve');
  setTimeout(() => coin.classList.remove('evolve'), 1150);
  const flash = document.createElement('div');
  flash.className = 'evolve-flash';
  flash.style.setProperty('--flash', look.light);
  stage.appendChild(flash);
  setTimeout(() => flash.remove(), 1000);
  const layer = $('fx-layer');
  const rect = stage.getBoundingClientRect();
  const cx = (rect.width || 300) / 2;
  const cy = (rect.height || 300) / 2;
  for (let k = 0; effectsAll() && k < 20; k++) {
    const spark = document.createElement('span');
    const angle = (k / 20) * Math.PI * 2;
    const distance = 110 + Math.random() * 60;
    spark.className = 'evolve-spark';
    spark.textContent = k % 3 ? '✦' : '✧';
    spark.style.left = `${cx}px`;
    spark.style.top = `${cy}px`;
    spark.style.color = k % 2 ? look.light : look.mid;
    spark.style.setProperty('--x', `${(Math.cos(angle) * distance).toFixed(0)}px`);
    spark.style.setProperty('--y', `${(Math.sin(angle) * distance).toFixed(0)}px`);
    layer.appendChild(spark);
    setTimeout(() => spark.remove(), 1150);
  }
  stage.querySelectorAll('.evolve-banner').forEach(old => old.remove());
  const banner = document.createElement('div');
  banner.className = 'evolve-banner';
  banner.style.setProperty('--metal-light', look.light);
  banner.style.setProperty('--metal-mid', look.mid);
  banner.style.setProperty('--metal-dark', look.dark);
  banner.innerHTML = T`<small>NEW COIN</small><strong>${look.name}</strong><em>Tap power ×${gainText(levelGain(state.coinLevel - 1))}</em>`;
  stage.appendChild(banner);
  setTimeout(() => banner.remove(), 2700);
  sfx('evolve');
  buzz([30, 60, 90]);
  pipSay(T`Ooh! A ${look.name} coin! So shiny!`, 'happy', 2600, true);
}

function pressCoin() {
  const button = $('coin-button');
  button.classList.add('pressed');
  clearTimeout(pressTimer);
  pressTimer = setTimeout(() => button.classList.remove('pressed'), 90);
}

// A short word that floats up: MISS, SAVED!, −2.5s …
function floatBricks(amount, from) {
  const panel = document.querySelector('#screen-city .city-panel');
  if (!panel || !from || effectsOff()) return;
  const box = from.getBoundingClientRect();
  const room = panel.getBoundingClientRect();
  const el = document.createElement('i');
  el.className = 'brick-float';
  el.innerHTML = `+${amount} ${BRICK_ICON}`;
  el.style.left = `${box.left - room.left + box.width / 2}px`;
  el.style.top = `${box.top - room.top}px`;
  panel.appendChild(el);
  setTimeout(() => el.remove(), 1100);
}

function spawnWord(x, y, text, kind = '') {
  const layer = $('fx-layer');
  if (!layer || layer.childElementCount > 60) return;
  const el = document.createElement('span');
  el.className = `float-word${kind ? ` ${kind}` : ''}`;
  el.textContent = text;
  el.style.left = `${x}px`;
  el.style.top = `${y - 20}px`;
  layer.appendChild(el);
  setTimeout(() => el.remove(), 900);
}

// A big banner across the coin: golden coin bonuses and hot streaks.
function showBonusBanner(eyebrow, title, line, kind = 'gold') {
  const stage = $('coin-stage');
  if (!stage) return;
  stage.querySelectorAll('.bonus-banner').forEach(old => old.remove());
  const banner = document.createElement('div');
  banner.className = `bonus-banner ${kind}`;
  banner.setAttribute('role', 'status');
  banner.innerHTML = `<small>${eyebrow}</small><strong>${title}</strong><em>${line}</em>`;
  stage.appendChild(banner);
  setTimeout(() => banner.remove(), 2700);
}

/* --- Pip, next to the coin --- */
// Pip cheers, worries and chats, but never more than every few seconds
// unless something big happens.
// In between Pip fidgets: waves, hops, stretches, looks around, follows
// passing critters with its eyes, and naps when the coin is left alone.
const PIP = { idle: [5, 11], sleepAfter: 45, acts: { wave: 1900, cheer: 1300, hop: 650, spin: 950, stretch: 1600 } };
let pipTimer;
let pipQuiet = 0;
let pipTyper = null;
let pipChatAt = 0;
let pipIdleAt = 0;
let pipActUntil = 0;
let pipActTimer;
let pipGazeUntil = 0;
let pipAsleep = false;
let pipAwakeAt = Date.now();

// 3.18: Pip and the friend hop to another free spot by the coin now and then.
// The spots are slots in a column left of the coin, and one right of it below
// the chips; never on the coin or on the chips.
const ROAM = { pip: [35, 70], buddy: [45, 90], pitch: 58, size: 52 };
const roam = { pip: { slot: 'L0', home: 'L0', at: 0, until: 0 }, buddy: { slot: 'L1', home: 'L1', at: 0, until: 0 }, checked: 0 };
const roamEl = who => $(who === 'pip' ? 'stage-pip' : 'stage-buddy');

function roamSlots() {
  const stage = $('coin-stage');
  const coin = $('coin-button');
  if (!stage || !coin || !stage.offsetHeight) return null;
  const s = stage.getBoundingClientRect();
  const c = coin.getBoundingClientRect();
  const chips = $('effects-row');
  const chipsBottom = chips && chips.offsetHeight ? chips.getBoundingClientRect().bottom - s.top : -10;
  const slots = {};
  // The two top-left spots are where Pip and the friend have always sat.
  for (let k = 0; k < 2 || 2 + k * ROAM.pitch + ROAM.size <= s.height; k++) {
    const y = 2 + k * ROAM.pitch;
    if (k < 2 || c.left - s.left >= ROAM.size + 2) slots[`L${k}`] = { x: -2, y };
    if (s.right - c.right >= ROAM.size + 2 && y >= chipsBottom + 6) slots[`R${k}`] = { x: s.width - ROAM.size + 2, y, right: true };
  }
  return slots;
}

// Where in a slot each one sits: Pip fills it, the smaller friend sits at its outer edge.
function roamPoint(who, spot) {
  if (who === 'pip') return { x: spot.x, y: spot.y };
  return { x: spot.right ? spot.x + 8 : spot.x + 6, y: spot.y - 2 };
}

function roamPlace(who, slots) {
  const el = roamEl(who);
  const spot = slots && slots[roam[who].slot];
  if (!el) return;
  if (!spot) {
    el.style.left = '';
    el.style.top = '';
    return;
  }
  const { x, y } = roamPoint(who, spot);
  const left = `${Math.round(x)}px`;
  const top = `${Math.round(y)}px`;
  if (el.style.left !== left) el.style.left = left;
  if (el.style.top !== top) el.style.top = top;
}

// A few hops to a new slot; a longer way takes a little longer.
function roamGo(who, key, slots) {
  const el = roamEl(who);
  const to = slots[key];
  if (!el || !to) return;
  const from = slots[roam[who].slot];
  const a = from ? roamPoint(who, from) : to;
  const b = roamPoint(who, to);
  const ms = Math.round(Math.max(700, Math.min(1600, Math.hypot(b.x - a.x, b.y - a.y) * 4.5)));
  const hops = Math.max(1, Math.round(ms / 380));
  roam[who].slot = key;
  roam[who].until = Date.now() + ms;
  el.style.setProperty('--roam-ms', `${ms}ms`);
  el.style.setProperty('--roam-hop', `${Math.round(ms / hops)}ms`);
  el.style.setProperty('--roam-hops', hops);
  el.classList.remove('roam', 'hop', 'wiggle', ...Object.keys(PIP.acts));
  void el.offsetWidth;
  el.classList.add('roam');
  if (who === 'pip') {
    pipActUntil = roam.pip.until + 300;
    pipLook(b.x < a.x ? -1 : 1);
    pipGazeUntil = roam.pip.until;
  }
  roamPlace(who, slots);
  setTimeout(() => {
    if (Date.now() >= roam[who].until) el.classList.remove('roam');
  }, ms + 40);
}

const bubbleShown = id => !!$(id) && $(id).classList.contains('show');

function roamTick(now) {
  if (now < roam.checked) return;
  roam.checked = now + 1000;
  const slots = roamSlots();
  if (!slots) return;
  // Fights, a critter walking by (it walks along the bottom, under them) and calm motion: everyone home.
  const still = !!(boss || fight || monster) || calmMotion();
  for (const who of ['pip', 'buddy']) {
    if (who === 'buddy' && !state.buddy) continue;
    const me = roam[who];
    const other = roam[who === 'pip' ? 'buddy' : 'pip'];
    const taken = who === 'pip' && !state.buddy ? '' : other.slot;
    // A slot that is gone (the chips grew, the phone turned): back home too.
    if ((still || !slots[me.slot]) && me.slot !== me.home) {
      const home = me.home !== taken && slots[me.home] ? me.home : Object.keys(slots).find(key => key !== taken);
      if (home) roamGo(who, home, slots);
      continue;
    }
    roamPlace(who, slots);
    if (still || now < me.until) continue;
    if (!me.at) me.at = now + between(ROAM[who]) * 1000;
    if (now < me.at) continue;
    me.at = now + between(ROAM[who]) * 1000;
    if ((who === 'pip' && pipAsleep) || bubbleShown('pip-bubble') || bubbleShown('buddy-bubble')) continue;
    const free = Object.keys(slots).filter(key => key !== me.slot && key !== taken);
    if (free.length) roamGo(who, free[Math.floor(Math.random() * free.length)], slots);
  }
}

// A speech bubble beside whoever talks, with its tail at their mouth. Up high it
// hangs down from there; down low it grows upwards.
function placeBubble(bubble, el) {
  const stage = $('coin-stage');
  if (!bubble || !el || !stage) return;
  const left = el.style.left ? parseFloat(el.style.left) : el.offsetLeft;
  const top = el.style.top ? parseFloat(el.style.top) : el.offsetTop;
  const width = el.offsetWidth || 52;
  const height = el.offsetHeight || 52;
  const W = stage.clientWidth;
  const H = stage.clientHeight;
  const onRight = left + width / 2 > W / 2;
  const mouth = top + height * 0.62;
  const low = mouth > H * 0.6;
  bubble.dataset.side = onRight ? 'left' : 'right';
  bubble.dataset.tail = low ? 'bottom' : 'top';
  bubble.style.left = onRight ? 'auto' : `${Math.round(left + width + 9)}px`;
  bubble.style.right = onRight ? `${Math.round(W - left + 9)}px` : 'auto';
  bubble.style.top = low ? 'auto' : `${Math.round(Math.max(0, mouth - 17))}px`;
  bubble.style.bottom = low ? `${Math.round(Math.max(0, H - mouth - 17))}px` : 'auto';
}

// The friend by the coin says something, in a bubble of its own.
let buddyTyper = null;
let buddyTalkTimer;
function buddySay(text, ms = 2800) {
  const friend = FRIEND_BY_ID[state.buddy];
  const bubble = $('buddy-bubble');
  const el = $('stage-buddy');
  if (!friend || !bubble || !el || el.classList.contains('hidden') || inDialogue) return;
  hushPip();
  const quick = !!(boss || fight);
  if (!quick && !calmMotion()) ms += Math.min(2400, text.length * 32);
  pipQuiet = Date.now() + ms + 4000;
  if (buddyTyper) buddyTyper.stop();
  placeBubble(bubble, el);
  buddyTyper = typeLine(bubble, text, quick ? null : VOICES[friend.id] || VOICES.pip, null, quick);
  bubble.classList.add('show');
  setFace(el, FRIEND_LOOKS[friend.id], 'happy');
  clearTimeout(buddyTimer);
  buddyTimer = setTimeout(() => setFace(el, FRIEND_LOOKS[friend.id], 'idle'), Math.min(ms, 2400));
  clearTimeout(buddyTalkTimer);
  buddyTalkTimer = setTimeout(() => bubble.classList.remove('show'), ms);
}

function hushBuddy() {
  const bubble = $('buddy-bubble');
  if (!bubble || !bubble.classList.contains('show')) return;
  if (buddyTyper) buddyTyper.stop();
  clearTimeout(buddyTalkTimer);
  bubble.classList.remove('show');
}

function hushPip() {
  const bubble = $('pip-bubble');
  if (!bubble || !bubble.classList.contains('show')) return;
  if (pipTyper) pipTyper.stop();
  clearTimeout(pipTimer);
  bubble.classList.remove('show');
  const pip = $('stage-pip');
  if (pip) {
    pip.classList.remove('talk');
    setFace(pip, PIP_LOOK, boss && !boss.done ? 'scared' : 'idle');
  }
}

// Pip does something for a moment: wave, cheer, hop, spin or stretch.
function pipAct(name, force = false) {
  const pip = $('stage-pip');
  const ms = PIP.acts[name];
  if (!pip || !ms || currentScreen !== 'coin') return;
  const now = Date.now();
  if (!force && now < pipActUntil) return;
  pipWake();
  pip.classList.remove(...Object.keys(PIP.acts));
  void pip.offsetWidth;
  pip.classList.add(name);
  pipActUntil = now + ms;
  clearTimeout(pipActTimer);
  pipActTimer = setTimeout(() => pip.classList.remove(name), ms);
}

// Pip glances one way: -1 left, 1 right, 0 straight ahead.
function pipLook(side) {
  const pip = $('stage-pip');
  if (!pip) return;
  const gaze = side < 0 ? 'left' : side > 0 ? 'right' : '';
  if ((pip.dataset.gaze || '') !== gaze) pip.dataset.gaze = gaze;
}

function pipSleep() {
  const pip = $('stage-pip');
  if (!pip || pipAsleep) return;
  pipAsleep = true;
  pipLook(0);
  pip.classList.add('sleep');
  setFace(pip, PIP_LOOK, 'sleep');
}

// Any touch keeps Pip awake, and wakes it up if it dozed off.
function pipWake() {
  pipAwakeAt = Date.now();
  if (!pipAsleep) return;
  pipAsleep = false;
  const pip = $('stage-pip');
  if (!pip) return;
  pip.classList.remove('sleep');
  setFace(pip, PIP_LOOK, boss && !boss.done ? 'scared' : 'idle');
}

function pipSay(text, mood = 'happy', ms = 2600, force = false, voice = VOICES.pip) {
  const bubble = $('pip-bubble');
  const pip = $('stage-pip');
  if (!bubble || !pip || inDialogue) return;
  const now = Date.now();
  if (!force && now < pipQuiet) return;
  // In a fight Pip says it at once and quietly; otherwise letter by letter,
  // in Pip's voice, and the bubble stays a little longer for it.
  const quick = !!(boss || fight);
  if (!quick && !calmMotion()) ms += Math.min(2400, text.length * 32);
  pipQuiet = now + ms + 6000;
  pipWake();
  hushBuddy();
  placeBubble(bubble, pip);
  if (pipTyper) pipTyper.stop();
  pipTyper = typeLine(bubble, text, quick ? null : voice, null, quick);
  bubble.classList.add('show');
  setFace(pip, PIP_LOOK, mood);
  pip.classList.remove('talk');
  void pip.offsetWidth;
  pip.classList.add('talk');
  clearTimeout(pipTimer);
  pipTimer = setTimeout(() => {
    bubble.classList.remove('show');
    pip.classList.remove('talk');
    setFace(pip, PIP_LOOK, boss && !boss.done ? 'scared' : 'idle');
  }, ms);
}

// Small talk and fidgeting when nothing much is happening.
function pipTick(now) {
  if (currentScreen !== 'coin' || isModalOpen()) return;
  const pip = $('stage-pip');
  if (!pip) return;
  roamTick(now);
  if (boss) {
    pipLook(0);
    return;
  }
  // Pip keeps an eye on any critter walking by.
  if (monster && !pipAsleep) {
    const a = monster.el.getBoundingClientRect();
    const b = pip.getBoundingClientRect();
    if (a.width) pipLook(a.left + a.width / 2 < b.left + b.width / 2 ? -1 : 1);
  } else if (now >= pipGazeUntil) {
    pipLook(0);
  }
  if (!pipAsleep && !monster && !fight && now - pipAwakeAt > PIP.sleepAfter * 1000) pipSleep();
  if (pipAsleep) return;
  if (!pipIdleAt) pipIdleAt = now + between(PIP.idle) * 1000;
  if (now >= pipIdleAt) {
    pipIdleAt = now + between(PIP.idle) * 1000;
    const pick = Math.random();
    if (monster || now < pipActUntil) {
      // Busy watching, or already doing something.
    } else if (pick < 0.3) {
      pipLook(Math.random() < 0.5 ? -1 : 1);
      pipGazeUntil = now + 1600;
    } else if (pick < 0.55) {
      pipAct('wave');
    } else if (pick < 0.75) {
      pipAct('hop');
    } else if (pick < 0.92) {
      pipAct('stretch');
    } else {
      pipAct('spin');
    }
  }
  if (!pipChatAt) {
    pipChatAt = now + between([35, 70]) * 1000;
    return;
  }
  if (now < pipChatAt) return;
  pipChatAt = now + between([60, 120]) * 1000;
  const friend = FRIEND_BY_ID[state.buddy];
  if (friend && Math.random() < 0.3) buddySay(friend.lines[Math.floor(Math.random() * friend.lines.length)], 3000);
  else pipSay(pipChatter(), 'happy', 3400);
}

function pipChatter() {
  const options = [...PIP_CHATTER];
  const info = nextBoss();
  if (info && bossReady()) options.push(T`${info.name} is waiting for us. Ready when you are!`, T`${info.name}? ${info.title}. We can take it!`);
  else if (info) options.push(T`Next up: ${info.name}, at coin level ${bossLevel(info.rank)}.`);
  if (state.streak >= 3) options.push(T`${state.streak} wins in a row! Don't let a critter get away.`);
  if (questsWaiting()) options.push(tr('A daily quest is done! Claim it under the ★ at the top.'));
  if (state.bossBeaten) options.push(tr('The portal is open! Shall we go?'));
  if (state.city.open) {
    options.push(tr('Every critter we beat drops bricks for our city.'));
    if (bunReady() && bunRoom()) options.push(tr('Mmm, I can smell a fresh bun all the way from the City!'));
    if (worksFull()) options.push(tr('The Brickworks is full of bricks. Let\'s go and get them!'));
  }
  return options[Math.floor(Math.random() * options.length)];
}

function pokePip() {
  const pip = $('stage-pip');
  if (!pip) return;
  const dozing = pipAsleep;
  pipWake();
  pip.classList.remove('wiggle');
  void pip.offsetWidth;
  pip.classList.add('wiggle');
  sfx('pip');
  if (dozing) {
    pipSay(PIP_WAKE[Math.floor(Math.random() * PIP_WAKE.length)], 'scared', 2400, true);
    return;
  }
  if (quickTaps('stage-pip', 8, 2500)) {
    unlock('dizzy');
    pipSay(tr('Whoa… the room is spinning…'), 'ko', 2400, true);
    return;
  }
  pipSay(PIP_LINES[Math.floor(Math.random() * PIP_LINES.length)], 'happy', 2400, true);
}

/* --- World scenes: a landscape behind the coin, with a little life in it --- */
// Each scene is drawn on a 360 × 600 canvas. The coin sits in the middle,
// around y 290–480, so the scenery lives on the sides and along the horizon.
// Moving things (fireflies, snow, embers …) are small HTML pieces on top,
// placed in percent of the same canvas, so they line up at any phone width.

// Small seeded random numbers, so a world looks the same every time.
function seeded(seed) {
  let t = seed >>> 0;
  return () => {
    t += 0x6D2B79F5;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

const hsl = (h, s, l, a = 1) => `hsla(${Math.round(h)}, ${Math.round(s)}%, ${l}%, ${a})`;
const at = (x, y) => `left:${(x / 3.6).toFixed(2)}%;top:${(y / 6).toFixed(2)}%`;

function sceneSky(top, middle, bottom) {
  return `<defs><linearGradient id="scn-sky" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2="600">
    <stop offset="0" stop-color="${top}"/><stop offset=".64" stop-color="${middle}"/><stop offset="1" stop-color="${bottom}"/>
  </linearGradient></defs><rect width="360" height="600" fill="url(#scn-sky)"/>`;
}

// Twinkling stars in the top part of the sky.
function sceneStars(rand, count, maxY, color = '#ffffff') {
  let html = '';
  for (let k = 0; k < count; k++) {
    const size = (1 + rand() * 1.8).toFixed(1);
    html += `<i class="fx-star" style="${at(rand() * 360, 8 + rand() * maxY)};--size:${size}px;--d:${(2.4 + rand() * 3).toFixed(1)}s;--delay:-${(rand() * 5).toFixed(1)}s;background:${color}"></i>`;
  }
  return html;
}

// Grass, trees and such are made of simple repeated shapes.
function grassTufts(rand, y0, color) {
  let d = '';
  for (let x = -4; x < 364; x += 7 + rand() * 6) {
    const y = y0 + Math.sin(x / 40) * 4;
    const h = 5 + rand() * 7;
    d += `M${x.toFixed(1)} ${y.toFixed(1)} l2.5 ${(-h).toFixed(1)} l2.5 ${h.toFixed(1)} `;
  }
  return `<path d="${d}" fill="${color}"/>`;
}

function pine(x, y, size, color) {
  const w = size * 0.55;
  return `<path d="M${x} ${y - size} L${x + w * 0.55} ${y - size * 0.62} L${x + w * 0.3} ${y - size * 0.62} L${x + w * 0.8} ${y - size * 0.28} L${x + w * 0.45} ${y - size * 0.28} L${x + w} ${y} L${x - w} ${y} L${x - w * 0.45} ${y - size * 0.28} L${x - w * 0.8} ${y - size * 0.28} L${x - w * 0.3} ${y - size * 0.62} L${x - w * 0.55} ${y - size * 0.62} Z" fill="${color}"/>`;
}

const SCENES = [
  // 1. The Meadow: rolling hills at dusk, a crescent moon and fireflies.
  (h, s, rand) => {
    let art = sceneSky(hsl(h + 95, s * 1.4, 9), hsl(h - 35, s * 1.5, 14), hsl(h, s, 7));
    art += `<circle cx="296" cy="66" r="19" fill="#f4f0cf" opacity=".9"/><circle cx="304" cy="59" r="17" fill="url(#scn-sky)"/>`;
    art += `<path d="M0 392 C60 356 120 368 180 384 S300 350 360 376 V600 H0Z" fill="${hsl(h, s * 0.9, 13)}"/>`;
    art += `<path d="M300 362 h22 v-12 l-11 -9 l-11 9 Z" fill="${hsl(h, s, 9)}"/><rect x="307" y="352" width="5" height="5" fill="#ffd27a" opacity=".85"/>`;
    art += `<path d="M0 432 C70 404 130 420 200 430 S320 408 360 420 V600 H0Z" fill="${hsl(h, s, 10.5)}"/>`;
    art += `<rect x="43" y="380" width="7" height="60" fill="${hsl(h, s, 7.5)}"/>
      <circle cx="47" cy="372" r="25" fill="${hsl(h, s, 8.5)}"/><circle cx="30" cy="386" r="16" fill="${hsl(h, s, 8.5)}"/><circle cx="64" cy="384" r="17" fill="${hsl(h, s, 8.5)}"/>`;
    art += `<path d="M0 468 Q90 452 180 464 T360 458 V600 H0Z" fill="${hsl(h, s * 1.1, 8)}"/>`;
    art += grassTufts(rand, 466, hsl(h, s * 1.1, 8));
    for (let k = 0; k < 14; k++) {
      art += `<circle cx="${(rand() * 360).toFixed(1)}" cy="${(478 + rand() * 60).toFixed(1)}" r="${(1.2 + rand()).toFixed(1)}" fill="${rand() < 0.5 ? '#f3a6c8' : '#f6e48a'}" opacity=".55"/>`;
    }
    let fx = sceneStars(rand, 10, 150, '#eef6d8');
    fx += `<i class="fx-cloud" style="top:10%;--d:95s;--delay:-20s"></i><i class="fx-cloud small" style="top:24%;--d:120s;--delay:-75s"></i>`;
    for (let k = 0; k < 11; k++) {
      fx += `<i class="fx-firefly" style="${at(rand() * 360, 360 + rand() * 190)};--dx:${(rand() * 60 - 30).toFixed(0)}px;--dy:${(rand() * 40 - 20).toFixed(0)}px;--d:${(5 + rand() * 5).toFixed(1)}s;--delay:-${(rand() * 6).toFixed(1)}s"></i>`;
    }
    return { art, fx };
  },

  // 2. The Harbor: the sea, a moon, and a lighthouse with a sweeping beam.
  (h, s, rand) => {
    let art = sceneSky(hsl(h + 15, s * 1.2, 8), hsl(h, s * 1.3, 14), hsl(h, s, 7));
    art += `<defs><radialGradient id="scn-moon"><stop offset="0" stop-color="#fffbe8" stop-opacity=".35"/><stop offset="1" stop-color="#fffbe8" stop-opacity="0"/></radialGradient>
      <linearGradient id="scn-sea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${hsl(h + 5, s * 1.3, 15)}"/><stop offset="1" stop-color="${hsl(h, s, 6)}"/></linearGradient></defs>`;
    art += `<circle cx="66" cy="86" r="52" fill="url(#scn-moon)"/><circle cx="66" cy="86" r="21" fill="#f6f2dc" opacity=".92"/>`;
    art += `<rect y="440" width="360" height="160" fill="url(#scn-sea)"/><rect y="439" width="360" height="2" fill="${hsl(h, s, 22)}" opacity=".6"/>`;
    art += `<path d="M0 432 h96 v8 h-96 Z M10 440 v40 M38 440 v40 M66 440 v40" stroke="${hsl(h, s, 8)}" stroke-width="5" fill="${hsl(h, s, 8)}"/>`;
    art += `<path d="M262 452 C270 430 300 426 326 430 C346 432 360 440 360 452 Z" fill="${hsl(h, s, 7)}"/>`;
    art += `<path d="M296 438 L301 348 L315 348 L320 438 Z" fill="#d9d4c7" opacity=".9"/>
      <path d="M298.4 400 L317.6 400 L318.5 418 L297.5 418 Z M300.3 366 L315.7 366 L316.5 382 L299.5 382 Z" fill="#b5524a" opacity=".9"/>
      <rect x="296" y="340" width="24" height="8" rx="1" fill="${hsl(h, s, 9)}"/>
      <rect x="301" y="326" width="14" height="14" fill="#ffe7a3"/>
      <path d="M298 326 L308 312 L318 326 Z" fill="${hsl(h, s, 9)}"/>`;
    let fx = sceneStars(rand, 16, 200, '#e9f4ff');
    fx += `<i class="fx-beam" style="${at(308, 333)}"></i><i class="fx-lamp" style="${at(308, 333)}"></i>`;
    fx += `<i class="fx-waves" style="top:75%;--d:9s;opacity:.35"></i><i class="fx-waves" style="top:82%;--d:13s;opacity:.25"></i><i class="fx-waves" style="top:90%;--d:17s;opacity:.18"></i>`;
    fx += `<i class="fx-boat" style="${at(160, 424)}"><svg viewBox="0 0 40 30"><path d="M4 22 h32 l-5 7 h-22 Z" fill="${hsl(h, s, 6)}"/><path d="M20 2 v19 M20 4 L33 19 H20 Z" stroke="${hsl(h, s, 6)}" stroke-width="2" fill="${hsl(h, s * 0.5, 30)}"/></svg></i>`;
    return { art, fx };
  },

  // 3. Old Town: rooftops, a clock tower against a big moon, warm windows.
  (h, s, rand) => {
    let art = sceneSky(hsl(h, s * 1.3, 9), hsl(h - 10, s * 1.6, 14), hsl(h, s, 7));
    art += `<defs><radialGradient id="scn-glow"><stop offset="0" stop-color="#f1e6ff" stop-opacity=".3"/><stop offset="1" stop-color="#f1e6ff" stop-opacity="0"/></radialGradient></defs>`;
    art += `<circle cx="58" cy="160" r="64" fill="url(#scn-glow)"/><circle cx="58" cy="160" r="27" fill="#efe7fb" opacity=".85"/>`;
    const roof = hsl(h, s, 8.5);
    art += `<path d="M58 600 V258 L83 214 L108 258 V600 Z" fill="${roof}"/><circle cx="83" cy="282" r="13" fill="#f6e7b7" opacity=".85"/>
      <path d="M83 282 V273 M83 282 L89 286" stroke="${roof}" stroke-width="2.4" stroke-linecap="round"/>`;
    const houses = [[0, 410, 44], [40, 392, 38], [114, 404, 40], [150, 418, 36], [186, 408, 44], [226, 396, 40], [262, 384, 44], [300, 402, 36], [332, 390, 40]];
    const windows = [];
    houses.forEach(([x, y, w], k) => {
      const shade = hsl(h, s, k % 2 ? 9.5 : 8);
      art += `<path d="M${x} 600 V${y} L${x + w / 2} ${y - 18} L${x + w} ${y} V600 Z" fill="${shade}"/>`;
      if (k % 3 === 1) art += `<rect x="${x + w * 0.65}" y="${y - 24}" width="6" height="16" fill="${shade}"/>`;
      for (let row = 0; row < 3; row++) {
        if (rand() < 0.45) {
          const wx = x + 8 + rand() * (w - 20);
          const wy = y + 12 + row * 22;
          windows.push([wx, wy]);
          art += `<rect class="sw" data-spot="win" x="${wx.toFixed(1)}" y="${wy}" width="6" height="8" fill="#ffd27a" opacity=".75"/>`;
        }
      }
    });
    let fx = sceneStars(rand, 12, 150, '#f3eaff');
    windows.slice(0, 4).forEach(([wx, wy], k) => {
      fx += `<i class="fx-window" style="${at(wx + 3, wy + 4)};--d:${(3 + k * 1.3).toFixed(1)}s"></i>`;
    });
    [[40 + 38 * 0.65 + 3, 392 - 24], [262 + 44 * 0.65 + 3, 384 - 24]].forEach(([cx, cy], k) => {
      for (let p = 0; p < 3; p++) fx += `<i class="fx-puff" style="${at(cx, cy)};--d:6s;--delay:-${(p * 2 + k).toFixed(1)}s"></i>`;
    });
    return { art, fx };
  },

  // 4. Sunny Dunes: a huge low sun, dunes, cacti and blowing sand.
  (h, s, rand) => {
    let art = sceneSky(hsl(h - 10, s * 1.1, 9), hsl(h - 14, s * 1.9, 17), hsl(h, s, 7));
    art += `<defs><radialGradient id="scn-sun"><stop offset="0" stop-color="#ffc56b" stop-opacity=".55"/><stop offset="1" stop-color="#ff9a3d" stop-opacity="0"/></radialGradient></defs>`;
    art += `<circle cx="252" cy="352" r="110" fill="url(#scn-sun)"/><circle cx="252" cy="352" r="46" fill="#ffb457" opacity=".8"/>`;
    art += `<path d="M96 400 L120 366 L144 400 Z" fill="${hsl(h, s, 12)}"/><path d="M134 400 L150 378 L166 400 Z" fill="${hsl(h, s, 11)}"/>`;
    art += `<path d="M0 404 C80 380 150 392 220 400 S320 384 360 392 V600 H0Z" fill="${hsl(h, s * 1.1, 13)}"/>`;
    art += `<path d="M0 440 C60 420 140 446 220 436 S320 420 360 430 V600 H0Z" fill="${hsl(h, s * 1.1, 10.5)}"/>`;
    const cactus = (x, y, tall, color) => `<g fill="${color}"><rect x="${x - 5}" y="${y - tall}" width="10" height="${tall}" rx="5"/><path d="M${x - 5} ${y - tall * 0.45} h-8 a4 4 0 0 1 -4 -4 v-${tall * 0.25} a4 4 0 0 1 8 0 v${tall * 0.25 - 8} h4 Z"/><path d="M${x + 5} ${y - tall * 0.6} h8 a4 4 0 0 0 4 -4 v-${tall * 0.2} a4 4 0 0 0 -8 0 v${tall * 0.2 - 8} h-4 Z"/></g>`;
    art += cactus(40, 452, 54, hsl(h, s, 8)) + cactus(322, 446, 44, hsl(h, s, 8));
    art += `<path d="M0 478 C90 462 170 486 260 474 S340 462 360 468 V600 H0Z" fill="${hsl(h, s * 1.1, 8.5)}"/>`;
    let fx = sceneStars(rand, 8, 120, '#fff1d6');
    for (let k = 0; k < 16; k++) {
      fx += `<i class="fx-sand" style="${at(rand() * 360, 380 + rand() * 170)};--d:${(5 + rand() * 6).toFixed(1)}s;--delay:-${(rand() * 8).toFixed(1)}s"></i>`;
    }
    return { art, fx };
  },

  // 5. Frost Peak: snowy mountains, pine trees, the northern lights and snow.
  (h, s, rand) => {
    let art = sceneSky(hsl(h + 20, s * 1.1, 8), hsl(h, s * 1.3, 13), hsl(h, s, 7));
    art += `<path d="M0 420 L40 318 L70 366 L112 280 L150 330 L180 226 L214 314 L232 296 L262 252 L300 340 L330 300 L360 350 V600 H0Z" fill="${hsl(h, s * 0.8, 15)}"/>`;
    art += `<path d="M40 318 L53 348 L46 343 L36 352 L29 342 Z M112 280 L128 310 L118 304 L108 316 L99 306 Z M180 226 L196 262 L186 255 L177 266 L168 256 Z M262 252 L280 288 L268 281 L258 292 L248 283 Z M330 300 L342 320 L334 316 L325 324 L319 316 Z" fill="#e8f6f7" opacity=".72"/>`;
    art += `<path d="M0 452 C80 430 160 448 240 440 S330 428 360 436 V600 H0Z" fill="${hsl(h, s * 0.9, 11)}"/>`;
    for (const [x, y, size] of [[22, 470, 58], [52, 476, 44], [306, 468, 56], [338, 474, 46], [278, 480, 36]]) art += pine(x, y, size, hsl(h, s, 7.5));
    art += `<path d="M0 476 C80 462 170 482 260 472 S340 464 360 468 V600 H0Z" fill="${hsl(h, s * 0.5, 17)}"/>`;
    let fx = sceneStars(rand, 10, 140, '#eaffff');
    fx += '<i class="fx-aurora" style="top:6%;--d:14s"></i><i class="fx-aurora two" style="top:13%;--d:19s"></i>';
    for (let k = 0; k < 22; k++) {
      fx += `<i class="fx-snow" style="left:${(rand() * 100).toFixed(1)}%;--size:${(2 + rand() * 2.5).toFixed(1)}px;--dx:${(rand() * 40 - 20).toFixed(0)}px;--d:${(7 + rand() * 7).toFixed(1)}s;--delay:-${(rand() * 14).toFixed(1)}s"></i>`;
    }
    return { art, fx };
  },

  // 6. Ember Isle: a volcano glowing on the left, embers rising.
  (h, s, rand) => {
    let art = sceneSky(hsl(h, s * 1.2, 8), hsl(h + 8, s * 1.5, 13), hsl(h, s, 7));
    art += `<ellipse cx="270" cy="150" rx="90" ry="22" fill="${hsl(h, s * 0.5, 13)}" opacity=".7"/><ellipse cx="90" cy="96" rx="70" ry="16" fill="${hsl(h, s * 0.5, 12)}" opacity=".6"/>`;
    art += `<path d="M-30 470 L36 300 C44 292 72 292 80 300 L170 470 Z" fill="${hsl(h, s * 0.9, 11)}"/>`;
    art += `<path d="M40 298 C48 306 68 306 76 298" stroke="#ff8a3d" stroke-width="5" fill="none" stroke-linecap="round" opacity=".9"/>
      <path d="M54 304 C52 340 64 360 56 390 C50 414 58 440 52 466" stroke="#ff6b2a" stroke-width="3" fill="none" opacity=".75" stroke-linecap="round"/>
      <path d="M66 304 C76 330 70 352 84 380" stroke="#ff8a3d" stroke-width="2" fill="none" opacity=".6" stroke-linecap="round"/>`;
    art += `<path d="M200 470 C220 440 260 430 300 438 C330 444 350 432 360 436 V600 H200 Z" fill="${hsl(h, s, 9)}"/>`;
    art += `<path d="M0 472 C90 456 180 478 270 468 S340 458 360 462 V600 H0Z" fill="${hsl(h, s, 7.5)}"/>`;
    for (let k = 0; k < 10; k++) {
      art += `<circle cx="${(rand() * 360).toFixed(1)}" cy="${(482 + rand() * 60).toFixed(1)}" r="${(0.8 + rand() * 1.2).toFixed(1)}" fill="#ff8a3d" opacity=".5"/>`;
    }
    let fx = `<i class="fx-crater" style="${at(58, 298)}"></i>`;
    for (let k = 0; k < 16; k++) {
      fx += `<i class="fx-ember" style="${at(44 + rand() * 30, 298)};--dx:${(rand() * 120 - 30).toFixed(0)}px;--d:${(3.5 + rand() * 3).toFixed(1)}s;--delay:-${(rand() * 6).toFixed(1)}s"></i>`;
    }
    return { art, fx };
  },

  // 7. Moon Base: grey craters, a dome base with a blinking mast, a planet.
  (h, s, rand) => {
    let art = sceneSky(hsl(h, s * 1.4, 6), hsl(h, s * 1.6, 10), hsl(h, s, 7));
    art += `<circle cx="292" cy="98" r="32" fill="#5d8fd6" opacity=".9"/><path d="M270 86 C284 80 300 84 318 78 M266 104 C284 98 304 104 322 98" stroke="#d8ecff" stroke-width="4" fill="none" opacity=".5" stroke-linecap="round"/>
      <path d="M292 66 A32 32 0 0 1 292 130 A24 32 0 0 0 292 66 Z" fill="${hsl(h, s, 6)}" opacity=".55"/>`;
    art += `<path d="M0 448 C80 436 170 452 250 444 S330 436 360 440 V600 H0Z" fill="${hsl(h, s * 0.7, 17)}"/>`;
    for (const [x, y, rx] of [[40, 470, 22], [140, 492, 14], [230, 470, 18], [320, 500, 26], [90, 530, 30], [260, 540, 20]]) {
      art += `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${rx * 0.28}" fill="${hsl(h, s * 0.6, 12)}"/><ellipse cx="${x}" cy="${y - 2}" rx="${rx * 0.8}" ry="${rx * 0.18}" fill="${hsl(h, s * 0.6, 14)}"/>`;
    }
    art += `<path d="M262 446 a26 24 0 0 1 52 0 Z" fill="${hsl(h, s * 0.6, 24)}"/><path d="M308 446 a16 15 0 0 1 32 0 Z" fill="${hsl(h, s * 0.6, 21)}"/>
      <rect x="283" y="436" width="8" height="6" fill="#ffe7a3" opacity=".8"/><rect x="318" y="438" width="5" height="4" fill="#ffe7a3" opacity=".7"/>
      <path d="M346 446 V392 M346 396 l-10 -8 M346 404 l9 -7" stroke="${hsl(h, s * 0.5, 30)}" stroke-width="2.5" fill="none"/>`;
    let fx = sceneStars(rand, 26, 330, '#f2f5ff');
    fx += `<i class="fx-blink" style="${at(346, 390)}"></i>`;
    fx += `<i class="fx-satellite" style="top:24%;--d:80s;--delay:-30s"><svg viewBox="0 0 30 14"><rect x="11" y="4" width="8" height="6" fill="#cfd6e4"/><rect x="0" y="5" width="10" height="4" fill="#6f8fc7"/><rect x="20" y="5" width="10" height="4" fill="#6f8fc7"/></svg></i>`;
    return { art, fx };
  },

  // 8. Star Sea: nebula clouds, a ringed planet, and the Baron's ship.
  (h, s, rand) => {
    let art = sceneSky(hsl(h, s * 1.2, 7), hsl(h + 10, s * 1.4, 12), hsl(h, s, 7));
    art += `<defs><radialGradient id="scn-neb1"><stop offset="0" stop-color="#d36ad6" stop-opacity=".28"/><stop offset="1" stop-color="#d36ad6" stop-opacity="0"/></radialGradient>
      <radialGradient id="scn-neb2"><stop offset="0" stop-color="#4fd1c5" stop-opacity=".2"/><stop offset="1" stop-color="#4fd1c5" stop-opacity="0"/></radialGradient>
      <linearGradient id="scn-starsea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${hsl(h + 10, s * 1.3, 20)}"/><stop offset="1" stop-color="${hsl(h, s, 6)}"/></linearGradient></defs>`;
    art += `<ellipse cx="110" cy="190" rx="150" ry="90" fill="url(#scn-neb1)"/><ellipse cx="270" cy="300" rx="140" ry="80" fill="url(#scn-neb2)"/>`;
    art += `<circle cx="70" cy="112" r="20" fill="#e3a65c" opacity=".9"/><ellipse cx="70" cy="114" rx="36" ry="8" fill="none" stroke="#f3d7a8" stroke-width="2.5" opacity=".75" transform="rotate(-14 70 114)"/>`;
    art += `<rect y="448" width="360" height="152" fill="url(#scn-starsea)"/>`;
    for (let k = 0; k < 18; k++) {
      const y = 456 + rand() * 90;
      art += `<rect x="${(rand() * 360).toFixed(1)}" y="${y.toFixed(1)}" width="${(4 + rand() * 10).toFixed(1)}" height="1.2" fill="#f4e8ff" opacity="${(0.15 + rand() * 0.35).toFixed(2)}"/>`;
    }
    art += `<g fill="${hsl(h, s, 5)}"><path d="M276 446 h64 l-8 12 h-48 Z"/><rect x="306" y="398" width="2.5" height="48"/><path d="M309 402 L332 438 H309 Z" fill="${hsl(h, s * 0.6, 18)}"/><path d="M305 400 L296 430 H305 Z" fill="${hsl(h, s * 0.6, 15)}"/><rect x="300" y="388" width="14" height="8" rx="1"/><rect x="297" y="395" width="20" height="3"/></g>`;
    let fx = sceneStars(rand, 30, 400, '#fbf3ff');
    fx += '<i class="fx-shoot" style="top:12%;left:30%;--d:9s;--delay:-2s"></i><i class="fx-shoot" style="top:28%;left:62%;--d:13s;--delay:-8s"></i>';
    return { art, fx };
  },

  // 9. The Deep Cave: stalactites, glowing crystals, glowworms on the roof and drips.
  (h, s, rand) => {
    let art = sceneSky(hsl(h, s * 1.2, 4), hsl(h, s * 1.5, 9), hsl(h, s, 7));
    art += `<defs><radialGradient id="scn-crystal"><stop offset="0" stop-color="#7fe0ff" stop-opacity=".34"/><stop offset="1" stop-color="#7fe0ff" stop-opacity="0"/></radialGradient>
      <radialGradient id="scn-amethyst"><stop offset="0" stop-color="#c49aff" stop-opacity=".3"/><stop offset="1" stop-color="#c49aff" stop-opacity="0"/></radialGradient></defs>`;
    // The roof, with stalactites hanging from it. Short ones above the coin.
    const tips = [];
    let d = '';
    for (let x = 30; x < 336; x += 16 + rand() * 24) {
      const w = 8 + rand() * 14;
      const len = 26 + rand() * (x > 110 && x < 250 ? 50 : 140);
      d += `M${x.toFixed(1)} 0 L${(x + w / 2).toFixed(1)} ${len.toFixed(1)} L${(x + w).toFixed(1)} 0 Z `;
      tips.push([x + w / 2, len]);
    }
    art += `<path d="M0 0 H360 V22 C300 34 240 18 180 28 S60 34 0 22 Z" fill="${hsl(h, s, 5)}"/><path d="${d}" fill="${hsl(h, s, 5)}"/>`;
    // The cave walls
    const wall = hsl(h, s * 0.9, 3.5);
    art += `<path d="M0 0 H50 C36 70 58 140 34 210 C20 260 44 320 26 380 C16 420 34 470 20 520 L0 540 Z" fill="${wall}"/>`;
    art += `<path d="M360 0 H308 C326 60 302 130 328 200 C344 250 320 310 338 370 C348 410 330 470 342 520 L360 540 Z" fill="${wall}"/>`;
    // The floor, a still pool and stalagmites
    art += `<path d="M0 476 C70 458 140 474 210 464 S320 452 360 466 V600 H0Z" fill="${hsl(h, s, 8)}"/>`;
    art += `<ellipse cx="190" cy="520" rx="120" ry="14" fill="${hsl(h, s * 1.6, 13)}" opacity=".7"/><path d="M110 518 h40 M176 524 h56 M240 516 h22" stroke="${hsl(h, s * 1.4, 26)}" stroke-width="1.5" opacity=".5"/>`;
    art += `<path d="M14 478 L28 400 L40 476 Z M44 474 L54 430 L64 472 Z M296 470 L308 418 L320 468 Z M322 472 L338 384 L352 470 Z" fill="${hsl(h, s, 5.5)}"/>`;
    // Glowing crystals in the walls
    const crystals = (cx, cy, color, glow) => `<circle cx="${cx}" cy="${cy}" r="46" fill="url(#${glow})"/>
      <path d="M${cx - 14} ${cy + 16} L${cx - 10} ${cy - 18} L${cx - 4} ${cy + 16} Z M${cx - 4} ${cy + 16} L${cx + 2} ${cy - 30} L${cx + 9} ${cy + 16} Z M${cx + 8} ${cy + 16} L${cx + 16} ${cy - 10} L${cx + 19} ${cy + 16} Z" fill="${color}" opacity=".8"/>
      <path d="M${cx + 1} ${cy - 22} L${cx + 3} ${cy + 4}" stroke="#ffffff" stroke-width="1.5" opacity=".6"/>`;
    art += crystals(42, 400, '#7fd8f2', 'scn-crystal') + crystals(320, 350, '#b996f2', 'scn-amethyst') + crystals(330, 120, '#7fd8f2', 'scn-crystal');
    // Glowworms on the roof, drips from the stalactites, a glint and a bat
    let fx = sceneStars(rand, 30, 120, '#a8f4ff');
    tips.filter((_, k) => k % 2).slice(0, 6).forEach(([x, y], k) => {
      fx += `<i class="fx-drip" style="${at(x, y)};--d:${(2.6 + rand() * 2.6).toFixed(1)}s;--delay:-${(rand() * 5).toFixed(1)}s;--fall:${Math.round(200 + k * 30)}px"></i>`;
    });
    fx += `<i class="fx-glint" style="${at(44, 384)};--d:3.4s"></i><i class="fx-glint" style="${at(322, 326)};--d:4.6s;--delay:-2s"></i>`;
    fx += `<i class="fx-bat" style="top:16%;--d:24s;--delay:-6s"><svg viewBox="0 0 30 14"><path d="M15 6 C13 2 9 1 6 2 C7 4 4 5 1 4 C3 8 7 10 11 9 L15 13 L19 9 C23 10 27 8 29 4 C26 5 23 4 24 2 C21 1 17 2 15 6 Z" fill="${hsl(h, s * 0.6, 20)}"/></svg></i>`;
    return { art, fx };
  },

  // 10. The Mountain: crags at dusk, a rope bridge high up, a sea of clouds, an eagle.
  (h, s, rand) => {
    let art = sceneSky(hsl(h, s * 2.2, 9), hsl(h + 180, s * 3, 16), hsl(h, s, 7));
    art += `<defs><radialGradient id="scn-dusk"><stop offset="0" stop-color="#ffcf8a" stop-opacity=".45"/><stop offset="1" stop-color="#ffcf8a" stop-opacity="0"/></radialGradient></defs>`;
    art += `<circle cx="214" cy="330" r="120" fill="url(#scn-dusk)"/>`;
    // Far peaks with a little snow
    art += `<path d="M0 372 L34 336 L62 352 L100 286 L132 330 L164 300 L198 336 L234 262 L266 314 L294 292 L326 334 L360 300 V600 H0Z" fill="${hsl(h, s * 0.8, 15)}"/>`;
    art += `<path d="M100 286 L112 306 L104 302 L96 310 L90 302 Z M234 262 L248 286 L238 281 L230 290 L222 280 Z M294 292 L304 306 L297 303 L290 309 L286 302 Z" fill="#eef2f6" opacity=".55"/>`;
    // A sea of clouds below the peaks
    art += `<ellipse cx="190" cy="420" rx="230" ry="38" fill="${hsl(h + 180, s * 2, 30)}" opacity=".18"/><ellipse cx="120" cy="446" rx="160" ry="22" fill="${hsl(h, s, 40)}" opacity=".12"/>`;
    // The crags on both sides, with a few pines
    const crag = hsl(h, s, 9);
    art += `<path d="M0 600 V246 L18 220 L34 244 L52 204 L72 258 L90 300 L104 380 L112 600 Z" fill="${crag}"/>`;
    art += `<path d="M360 600 V234 L344 212 L326 246 L310 228 L292 290 L280 360 L272 600 Z" fill="${crag}"/>`;
    for (const [x, y, size] of [[20, 232, 26], [40, 254, 20], [338, 226, 24], [318, 252, 18]]) art += pine(x, y, size, hsl(h, s, 6.5));
    // A rope bridge between the crags, well above the coin
    const curve = (t, a, b, c) => (1 - t) * (1 - t) * a + 2 * (1 - t) * t * b + t * t * c;
    art += `<path d="M50 214 Q180 256 318 220" stroke="${hsl(h, s, 6)}" stroke-width="2" fill="none"/><path d="M50 226 Q180 268 318 232" stroke="${hsl(h, s, 6)}" stroke-width="3" fill="none"/>`;
    let planks = '';
    for (let t = 0.04; t < 0.97; t += 0.034) {
      const x = curve(t, 50, 180, 318);
      planks += `M${x.toFixed(1)} ${curve(t, 214, 256, 220).toFixed(1)} V${curve(t, 226, 268, 232).toFixed(1)} `;
    }
    art += `<path d="${planks}" stroke="${hsl(h, s, 6)}" stroke-width="2.4"/>`;
    let fx = sceneStars(rand, 12, 130, '#fff3e0');
    fx += `<i class="fx-cloud" style="top:12%;--d:80s;--delay:-30s"></i><i class="fx-cloud small" style="top:30%;--d:110s;--delay:-60s"></i>`;
    fx += `<i class="fx-eagle" style="${at(250, 140)};--d:16s"><svg viewBox="0 0 30 12"><path d="M15 7 C11 2 6 1 1 3 C6 4 9 6 12 9 L15 8 L18 9 C21 6 24 4 29 3 C24 1 19 2 15 7 Z" fill="${hsl(h, s, 5)}"/></svg></i>`;
    for (let k = 0; k < 7; k++) {
      fx += `<i class="fx-wind" style="${at(rand() * 300, 300 + rand() * 200)};--d:${(2.4 + rand() * 2.2).toFixed(1)}s;--delay:-${(rand() * 4).toFixed(1)}s"></i>`;
    }
    return { art, fx };
  },

  // 11. The Tunnel: an old mine with timber frames, rails into the dark and lanterns.
  (h, s, rand) => {
    let art = sceneSky(hsl(h, s, 5), hsl(h, s * 1.1, 8), hsl(h, s, 6));
    art += `<defs><radialGradient id="scn-lantern"><stop offset="0" stop-color="#ffc56b" stop-opacity=".5"/><stop offset="1" stop-color="#ffc56b" stop-opacity="0"/></radialGradient></defs>`;
    // Roof, walls and floor run into the dark far end
    art += `<path d="M0 0 H360 L250 190 H110 Z" fill="${hsl(h, s, 6.5)}"/>`;
    art += `<path d="M0 0 L110 190 V440 L0 560 Z" fill="${hsl(h, s, 8.5)}"/><path d="M360 0 L250 190 V440 L360 560 Z" fill="${hsl(h, s, 7.5)}"/>`;
    art += `<path d="M0 560 L110 440 H250 L360 560 V600 H0 Z" fill="${hsl(h, s, 10)}"/><rect x="110" y="190" width="140" height="250" fill="${hsl(h, s, 3)}"/>`;
    for (let k = 0; k < 9; k++) {
      art += `<circle cx="${(rand() < 0.5 ? 6 + rand() * 90 : 264 + rand() * 90).toFixed(1)}" cy="${(120 + rand() * 360).toFixed(1)}" r="${(1.5 + rand() * 2.5).toFixed(1)}" fill="${hsl(h, s, 13)}"/>`;
    }
    // Rails and sleepers
    let sleepers = '';
    for (let k = 0; k < 8; k++) {
      const y = 440 + Math.pow(k / 7, 1.7) * 160;
      const spread = ((y - 440) / 160) * 102;
      sleepers += `M${(150 - spread).toFixed(1)} ${y.toFixed(1)} H${(210 + spread).toFixed(1)} `;
    }
    art += `<path d="${sleepers}" stroke="${hsl(h, s, 5)}" stroke-width="5"/>`;
    art += `<path d="M162 440 L60 600 M198 440 L300 600" stroke="${hsl(h, s * 0.4, 30)}" stroke-width="3"/>`;
    // Timber frames, near and far
    const wood = hsl(h, s * 1.3, 13);
    const ink = hsl(h, s, 4);
    const frame = (x0, x1, top, bottom, w) => `<rect x="${x0}" y="${top}" width="${w}" height="${bottom - top}" fill="${wood}" stroke="${ink}" stroke-width="2"/><rect x="${x1 - w}" y="${top}" width="${w}" height="${bottom - top}" fill="${wood}" stroke="${ink}" stroke-width="2"/><rect x="${x0 - 4}" y="${top - w}" width="${x1 - x0 + 8}" height="${w}" fill="${wood}" stroke="${ink}" stroke-width="2"/>`;
    art += frame(112, 248, 196, 440, 6) + frame(72, 288, 128, 494, 10) + frame(18, 342, 48, 600, 16);
    // Two lanterns on the middle frame, a minecart and a pickaxe
    for (const x of [100, 260]) {
      art += `<circle cx="${x}" cy="160" r="46" fill="url(#scn-lantern)"/><path d="M${x} 128 V146" stroke="${ink}" stroke-width="2"/>
        <rect x="${x - 6}" y="146" width="12" height="15" rx="2" fill="#ffd27a" stroke="${ink}" stroke-width="2"/><path d="M${x - 7} 146 L${x} 140 L${x + 7} 146 Z" fill="${ink}"/>`;
    }
    art += `<path d="M286 540 L340 540 L334 566 L292 566 Z" fill="${hsl(h, s, 7)}" stroke="${ink}" stroke-width="2"/><circle cx="300" cy="570" r="6" fill="${ink}"/><circle cx="326" cy="570" r="6" fill="${ink}"/>`;
    art += `<path d="M54 470 L40 560" stroke="${hsl(h, s, 16)}" stroke-width="4" stroke-linecap="round"/><path d="M38 474 C46 462 62 462 70 474 C62 470 46 470 38 474 Z" fill="${hsl(h, s * 0.3, 32)}"/>`;
    let fx = `<i class="fx-flicker" style="${at(100, 154)}"></i><i class="fx-flicker" style="${at(260, 154)};animation-delay:-.8s"></i>`;
    for (let k = 0; k < 12; k++) {
      fx += `<i class="fx-dust" style="${at(40 + rand() * 280, 160 + rand() * 300)};--dx:${(rand() * 40 - 20).toFixed(0)}px;--dy:${(rand() * 30 - 10).toFixed(0)}px;--d:${(6 + rand() * 6).toFixed(1)}s;--delay:-${(rand() * 6).toFixed(1)}s"></i>`;
    }
    return { art, fx };
  },

  // 12. The Swamp: twisted trees with moss, reeds, lily pads, mist and fireflies.
  (h, s, rand) => {
    let art = sceneSky(hsl(h + 40, s * 0.9, 8), hsl(h, s * 1.2, 13), hsl(h, s, 7));
    art += `<defs><radialGradient id="scn-swampmoon"><stop offset="0" stop-color="#eef6c8" stop-opacity=".3"/><stop offset="1" stop-color="#eef6c8" stop-opacity="0"/></radialGradient>
      <linearGradient id="scn-bog" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${hsl(h, s * 1.1, 12)}"/><stop offset="1" stop-color="${hsl(h, s, 5)}"/></linearGradient></defs>`;
    art += `<circle cx="252" cy="96" r="62" fill="url(#scn-swampmoon)"/><circle cx="252" cy="96" r="22" fill="#e8f0c8" opacity=".75"/>`;
    // A far treeline, then the water
    let line = 'M0 440 ';
    for (let x = 0; x <= 360; x += 18) line += `Q${x + 9} ${(404 + rand() * 18).toFixed(1)} ${x + 18} ${(424 + rand() * 12).toFixed(1)} `;
    art += `<path d="${line} V600 H0 Z" fill="${hsl(h, s, 10)}"/>`;
    art += `<rect y="456" width="360" height="144" fill="url(#scn-bog)"/><rect y="455" width="360" height="2" fill="${hsl(h, s, 20)}" opacity=".5"/>`;
    for (let k = 0; k < 12; k++) {
      art += `<rect x="${(rand() * 340).toFixed(1)}" y="${(466 + rand() * 90).toFixed(1)}" width="${(6 + rand() * 16).toFixed(1)}" height="1.2" fill="#e8f0c8" opacity="${(0.08 + rand() * 0.18).toFixed(2)}"/>`;
    }
    // Twisted trees with hanging moss
    const bark = hsl(h, s, 5);
    const moss = hsl(h, s * 1.3, 11);
    art += `<path d="M6 600 C14 540 2 490 20 440 C28 410 18 380 30 350 L42 352 C34 384 44 410 36 440 C24 490 34 540 30 600 Z" fill="${bark}"/>
      <path d="M32 362 C50 340 74 334 100 340 M28 400 C16 386 8 382 -4 384" stroke="${bark}" stroke-width="7" fill="none" stroke-linecap="round"/>
      <path d="M52 346 c-2 10 2 18 -1 30 M64 340 c2 12 -2 20 1 36 M78 338 c-2 8 2 16 -1 24 M92 339 c1 10 -2 14 0 22 M8 384 c-2 10 2 16 0 26" stroke="${moss}" stroke-width="3" fill="none" stroke-linecap="round"/>`;
    art += `<path d="M354 600 C346 540 358 490 340 440 C332 410 342 380 330 350 L318 352 C326 384 316 410 324 440 C336 490 326 540 330 600 Z" fill="${bark}"/>
      <path d="M328 362 C310 340 286 334 260 340 M332 404 C344 390 352 386 364 388" stroke="${bark}" stroke-width="7" fill="none" stroke-linecap="round"/>
      <path d="M308 346 c2 10 -2 18 1 30 M296 340 c-2 12 2 20 -1 36 M282 338 c2 8 -2 16 1 24 M268 339 c-1 10 2 14 0 22 M352 388 c2 10 -2 16 0 26" stroke="${moss}" stroke-width="3" fill="none" stroke-linecap="round"/>`;
    // Reeds and cattails
    let reeds = '';
    let heads = '';
    for (const [from, to] of [[40, 110], [250, 322]]) {
      for (let x = from; x < to; x += 6 + rand() * 6) {
        const top = 418 + rand() * 30;
        reeds += `M${x.toFixed(1)} 470 Q${(x + rand() * 6 - 3).toFixed(1)} ${(top + 20).toFixed(1)} ${(x + rand() * 8 - 4).toFixed(1)} ${top.toFixed(1)} `;
        if (rand() < 0.35) heads += `<ellipse cx="${x.toFixed(1)}" cy="${(top + 10).toFixed(1)}" rx="2.6" ry="7" fill="${hsl(25, 40, 16)}"/>`;
      }
    }
    art += `<path d="${reeds}" stroke="${hsl(h, s, 8)}" stroke-width="2" fill="none"/>${heads}`;
    // Lily pads, one with a flower
    for (const [x, y, r] of [[128, 500, 14], [222, 534, 18], [86, 560, 16], [292, 508, 12]]) {
      art += `<path d="M${x} ${y} L${x + r} ${y - r * 0.12} A${r} ${r * 0.36} 0 1 1 ${x + r * 0.9} ${y + r * 0.2} Z" fill="${hsl(h, s * 1.4, 15)}"/>`;
    }
    art += `<circle cx="222" cy="528" r="4.5" fill="#f2a6c8" opacity=".85"/><circle cx="222" cy="528" r="1.6" fill="#f6e48a"/>`;
    let fx = sceneStars(rand, 10, 150, '#eef6d8');
    for (let k = 0; k < 3; k++) fx += `<i class="fx-mist" style="top:${66 + k * 7}%;--d:${34 + k * 11}s;--delay:-${k * 9}s"></i>`;
    for (let k = 0; k < 10; k++) {
      fx += `<i class="fx-firefly" style="${at(rand() * 360, 340 + rand() * 170)};--dx:${(rand() * 60 - 30).toFixed(0)}px;--dy:${(rand() * 40 - 20).toFixed(0)}px;--d:${(5 + rand() * 5).toFixed(1)}s;--delay:-${(rand() * 6).toFixed(1)}s"></i>`;
    }
    for (let k = 0; k < 6; k++) {
      fx += `<i class="fx-bubble" style="${at(40 + rand() * 280, 470 + rand() * 80)};--d:${(3 + rand() * 3).toFixed(1)}s;--delay:-${(rand() * 5).toFixed(1)}s"></i>`;
    }
    return { art, fx };
  },

  // 13. The City Gate: a grey city wall at dusk, two towers, a gatehouse
  // with its portcullis half down, grey flags, torches and pigeons.
  (h, s, rand) => {
    let art = sceneSky(hsl(h + 200, s * 2, 10), hsl(h, s * 3.4, 22), hsl(h, s, 8));
    art += `<defs><radialGradient id="scn-haze"><stop offset="0" stop-color="#ffd9a8" stop-opacity=".26"/><stop offset="1" stop-color="#ffd9a8" stop-opacity="0"/></radialGradient></defs>`;
    art += `<circle cx="270" cy="150" r="120" fill="url(#scn-haze)"/><circle cx="270" cy="150" r="22" fill="#f6e2c2" opacity=".6"/>`;
    // The city behind the wall: towers and spires
    const far = hsl(h, s * 1.2, 15);
    art += `<path d="M14 220 V150 h18 V120 l10 -14 l10 14 V150 h14 V220 Z M84 220 V128 l16 -26 l16 26 V220 Z M236 220 V140 h22 V112 l12 -16 l12 16 V140 h18 V220 Z M300 220 V122 l14 -22 l14 22 V220 Z" fill="${far}"/>`;
    art += `<rect x="96" y="150" width="4" height="7" fill="#ffd27a" opacity=".55"/><rect x="246" y="150" width="4" height="7" fill="#ffd27a" opacity=".45"/><rect x="310" y="140" width="4" height="7" fill="#ffd27a" opacity=".5"/>`;
    // The wall with its battlements
    const wall = hsl(h, s * 0.9, 19);
    const dark = hsl(h, s * 0.9, 11);
    let teeth = '';
    for (let x = 0; x < 360; x += 24) teeth += `M${x} 236 h14 v-14 h-14 Z `;
    art += `<path d="${teeth}" fill="${wall}"/><rect x="0" y="236" width="360" height="210" fill="${wall}"/>`;
    let stones = '';
    for (let row = 0; row < 9; row++) {
      const y = 250 + row * 22;
      for (let x = (row % 2) * 18 - 18; x < 360; x += 36) stones += `M${x} ${y} h30 `;
    }
    art += `<path d="${stones}" stroke="${dark}" stroke-width="2" opacity=".6"/>`;
    // The gatehouse, taller than the wall, with a grey banner
    const house = hsl(h, s * 0.9, 22);
    let crown = '';
    for (let x = 100; x < 256; x += 20) crown += `M${x} 176 h12 v-14 h-12 Z `;
    art += `<path d="${crown}" fill="${house}"/><rect x="100" y="176" width="160" height="270" fill="${house}"/>`;
    art += `<path d="M100 176 H260" stroke="${dark}" stroke-width="3"/>`;
    art += `<path d="M156 186 H204 V232 L180 222 L156 232 Z" fill="${hsl(h, s * 0.4, 46)}"/><path d="M164 196 H196" stroke="${hsl(h, s * 0.4, 30)}" stroke-width="2"/>`;
    art += `<text x="180" y="214" text-anchor="middle" font-family="Space Grotesk, sans-serif" font-size="13" font-weight="700" fill="${hsl(h, s * 0.4, 26)}">B.T.</text>`;
    // The gate: a dark arch with the portcullis half way down
    art += `<path d="M122 446 V286 C122 236 238 236 238 286 V446 Z" fill="${hsl(h, s * 0.7, 28)}"/>`;
    art += `<path d="M134 446 V290 C134 252 226 252 226 290 V446 Z" fill="${hsl(h, s, 5)}"/>`;
    let bars = '';
    for (let x = 144; x <= 218; x += 13) bars += `M${x} 262 V362 `;
    for (let y = 280; y <= 350; y += 23) bars += `M135 ${y} H225 `;
    art += `<path d="${bars}" stroke="${hsl(h, s * 0.5, 36)}" stroke-width="4"/>`;
    for (let x = 144; x <= 218; x += 13) art += `<path d="M${x - 3} 362 L${x} 373 L${x + 3} 362 Z" fill="${hsl(h, s * 0.5, 36)}"/>`;
    // Two round towers with pointed roofs
    const tower = (cx, top) => `<rect x="${cx - 34}" y="${top}" width="68" height="${446 - top}" fill="${hsl(h, s * 0.9, 21)}"/>
      <path d="M${cx - 40} ${top + 2} L${cx} ${top - 70} L${cx + 40} ${top + 2} Z" fill="${hsl(h + 180, s * 0.8, 26)}"/>
      <path d="M${cx - 40} ${top + 2} H${cx + 40}" stroke="${dark}" stroke-width="3"/>
      <rect x="${cx - 6}" y="${top + 40}" width="12" height="22" rx="6" fill="${dark}"/><rect x="${cx - 4}" y="${top + 44}" width="8" height="16" rx="4" fill="#ffd27a" opacity=".65"/>
      <rect x="${cx - 6}" y="${top + 110}" width="12" height="22" rx="6" fill="${dark}"/>
      <path d="M${cx} ${top - 70} V${top - 96}" stroke="${dark}" stroke-width="2.5"/>`;
    art += tower(42, 200) + tower(318, 190);
    // Torches on the towers
    art += `<path d="M42 300 V280 M318 290 V270" stroke="#8a5a2a" stroke-width="4" stroke-linecap="round"/>`;
    // The road to the gate, made of cobbles
    art += `<path d="M0 446 H360 V600 H0 Z" fill="${hsl(h, s, 10)}"/>`;
    art += `<path d="M110 600 L148 446 H212 L250 600 Z" fill="${hsl(h, s, 14)}"/>`;
    let cobbles = '';
    for (let row = 0; row < 7; row++) {
      const y = 456 + row * 22;
      const half = 32 + row * 6;
      for (let x = 180 - half; x < 180 + half; x += 16 + row) cobbles += `<ellipse cx="${x + 6}" cy="${y}" rx="${5 + row * 0.6}" ry="${2.6 + row * 0.3}" fill="${hsl(h, s, 18)}"/>`;
    }
    art += cobbles;
    // Grey flags flap on the towers; torches burn; grey pigeons fly over; a grey haze drifts by.
    let fx = '';
    [[42, 104], [318, 94]].forEach(([x, y], k) => {
      fx += `<i class="fx-flag" style="${at(x + 1, y)};--d:${(1.6 + k * 0.4).toFixed(1)}s"><svg viewBox="0 0 30 18"><path d="M0 1 C10 -2 18 5 30 2 V16 C18 19 10 12 0 15 Z" fill="${hsl(h, s * 0.5, 52)}"/></svg></i>`;
    });
    [[42, 276], [318, 266]].forEach(([x, y], k) => {
      fx += `<i class="fx-flicker" style="${at(x, y)};--d:${(1.5 + k * 0.4).toFixed(1)}s"></i>`;
    });
    const pigeon = `<svg viewBox="0 0 30 14"><path d="M15 7 C12 2 7 0 2 2 C6 4 9 6 11 8 C8 9 6 11 6 13 C10 12 13 10 15 9 C17 10 20 12 24 13 C24 11 22 9 19 8 C21 6 24 4 28 2 C23 0 18 2 15 7 Z" fill="${hsl(h, s * 0.4, 58)}"/></svg>`;
    fx += `<i class="fx-bat" style="top:12%;--d:26s;--delay:-4s">${pigeon}</i><i class="fx-bat" style="top:22%;--d:31s;--delay:-17s">${pigeon}</i>`;
    for (let k = 0; k < 3; k++) {
      fx += `<i class="fx-mist" style="top:${(64 + k * 8).toFixed(0)}%;--d:${(14 + k * 5).toFixed(0)}s;--delay:-${(k * 4).toFixed(0)}s"></i>`;
    }
    return { art, fx };
  },

  // 14. City Square: tall houses all round, a bell tower, lanterns on strings
  // over the square and a fountain in the middle.
  (h, s, rand) => {
    let art = sceneSky(hsl(h + 200, s * 1.6, 9), hsl(h, s * 1.8, 16), hsl(h, s, 8));
    // The bell tower on the right, with its bell
    const tower = hsl(h, s * 0.7, 14);
    art += `<path d="M270 600 V120 L300 70 L330 120 V600 Z" fill="${tower}"/>`;
    art += `<path d="M280 140 H320 V196 H280 Z" fill="${hsl(h, s, 6)}"/><path d="M280 140 C280 124 320 124 320 140" fill="${hsl(h, s, 6)}"/>`;
    art += `<path d="M288 182 C288 160 296 150 300 150 C304 150 312 160 312 182 Z" fill="#d9a73a"/><circle cx="300" cy="186" r="4" fill="#a87a1a"/><path d="M300 150 V142" stroke="#a87a1a" stroke-width="3"/>`;
    art += `<circle cx="300" cy="236" r="16" fill="#f4ecd2" opacity=".85"/><path d="M300 236 V226 M300 236 L307 240" stroke="${tower}" stroke-width="2.5" stroke-linecap="round"/>`;
    // Houses with steep roofs and warm windows
    const houses = [[-10, 300, 50], [36, 270, 46], [78, 312, 40], [116, 290, 36], [148, 318, 34], [178, 296, 40], [214, 284, 44], [252, 330, 30], [330, 280, 44]];
    const windows = [];
    houses.forEach(([x, y, w], k) => {
      const shade = hsl(h + (k % 3) * 12, s * 1.1, k % 2 ? 13 : 11);
      art += `<path d="M${x} 600 V${y} L${x + w / 2} ${y - w * 0.8} L${x + w} ${y} V600 Z" fill="${shade}"/>`;
      art += `<path d="M${x + w / 2} ${y - w * 0.8} V${y - w * 0.8 - 6}" stroke="${shade}" stroke-width="3"/>`;
      for (let row = 0; row < 4; row++) {
        for (let col = 0; col < 2; col++) {
          if (rand() < 0.5) {
            const wx = x + w * (col ? 0.62 : 0.2);
            const wy = y + 14 + row * 30;
            windows.push([wx, wy]);
            art += `<rect x="${wx.toFixed(1)}" y="${wy}" width="8" height="11" rx="1.5" fill="#ffd27a" opacity=".78"/>`;
          }
        }
      }
    });
    // Strings of lanterns across the square
    const strings = [[0, 150, 360, 170, 70], [0, 210, 270, 196, 60]];
    const lanterns = [];
    strings.forEach(([x1, y1, x2, y2, sag]) => {
      art += `<path d="M${x1} ${y1} Q${(x1 + x2) / 2} ${(y1 + y2) / 2 + sag} ${x2} ${y2}" stroke="${hsl(h, s, 30)}" stroke-width="1.5" fill="none"/>`;
      for (let k = 1; k < 8; k++) {
        const t = k / 8;
        const x = x1 + (x2 - x1) * t;
        const y = (1 - t) * (1 - t) * y1 + 2 * (1 - t) * t * ((y1 + y2) / 2 + sag) + t * t * y2;
        const color = ['#ffcf6a', '#ff8a8a', '#9ad8ff', '#b8f08a'][k % 4];
        lanterns.push([x, y + 6, color]);
        art += `<ellipse class="sl" data-spot="string" cx="${x.toFixed(1)}" cy="${(y + 6).toFixed(1)}" rx="4.5" ry="6" fill="${color}" opacity=".9"/>`;
      }
    });
    // The square and its fountain
    art += `<path d="M0 470 C80 460 280 460 360 470 V600 H0 Z" fill="${hsl(h, s * 0.6, 10)}"/>`;
    let stones = '';
    for (let row = 0; row < 5; row++) {
      const y = 486 + row * 24;
      for (let x = (row % 2) * 14 - 14; x < 360; x += 28) stones += `<ellipse cx="${x}" cy="${y}" rx="11" ry="4.5" fill="${hsl(h, s * 0.6, 13)}"/>`;
    }
    art += stones;
    art += `<ellipse cx="180" cy="548" rx="96" ry="18" fill="${hsl(h, s * 0.5, 22)}"/><ellipse cx="180" cy="544" rx="84" ry="12" fill="${hsl(200, 40, 30)}"/>`;
    art += `<path d="M168 544 V516 H192 V544 Z" fill="${hsl(h, s * 0.5, 24)}"/><ellipse cx="180" cy="516" rx="22" ry="6" fill="${hsl(h, s * 0.5, 26)}"/>`;
    art += `<path d="M180 512 C176 498 168 494 160 500 M180 512 C184 498 192 494 200 500 M180 512 V494" stroke="#bfe6ff" stroke-width="2.5" fill="none" opacity=".75" stroke-linecap="round"/>`;
    let fx = sceneStars(rand, 18, 110, '#ffe8f4');
    lanterns.forEach(([x, y, color], k) => {
      if (k % 2 === 0) fx += `<i class="fx-flicker" style="${at(x, y)};width:30px;height:30px;margin:-15px 0 0 -15px;background:radial-gradient(closest-side, ${color}66, ${color}00)"></i>`;
    });
    windows.slice(0, 5).forEach(([wx, wy], k) => {
      fx += `<i class="fx-window" style="${at(wx + 4, wy + 5)};--d:${(3 + k * 1.1).toFixed(1)}s"></i>`;
    });
    fx += `<i class="fx-glint" style="${at(160, 500)};--d:2.8s"></i><i class="fx-glint" style="${at(200, 502)};--d:3.4s;--delay:-1.5s"></i><i class="fx-glint" style="${at(180, 494)};--d:4s;--delay:-2.5s"></i>`;
    return { art, fx };
  },

  // 15. The Castle: a big moon, the castle on its hill with flags on every
  // tower, torches on the walls and a moat with a drawbridge.
  (h, s, rand) => {
    let art = sceneSky(hsl(h, s * 1.4, 8), hsl(h + 15, s * 1.6, 15), hsl(h, s, 7));
    art += `<defs><radialGradient id="scn-moon"><stop offset="0" stop-color="#eef2ff" stop-opacity=".32"/><stop offset="1" stop-color="#eef2ff" stop-opacity="0"/></radialGradient></defs>`;
    art += `<circle cx="84" cy="100" r="80" fill="url(#scn-moon)"/><circle cx="84" cy="100" r="30" fill="#eef1fb" opacity=".9"/><circle cx="74" cy="92" r="6" fill="#d8ddf0" opacity=".8"/><circle cx="94" cy="110" r="4" fill="#d8ddf0" opacity=".8"/>`;
    // The hill
    art += `<path d="M0 330 C80 300 280 296 360 326 V600 H0 Z" fill="${hsl(h, s * 0.8, 10)}"/>`;
    // The castle: walls, towers and the keep in the middle
    const stone = hsl(h, s * 0.6, 16);
    const dark = hsl(h, s * 0.6, 9);
    const battlement = (x, y, w) => {
      let d = '';
      for (let k = x; k < x + w - 4; k += 12) d += `M${k} ${y} h7 v-8 h-7 Z `;
      return d;
    };
    art += `<rect x="40" y="250" width="280" height="90" fill="${stone}"/><path d="${battlement(40, 250, 280)}" fill="${stone}"/>`;
    art += `<rect x="130" y="150" width="100" height="190" fill="${hsl(h, s * 0.6, 18)}"/><path d="${battlement(130, 150, 100)}" fill="${hsl(h, s * 0.6, 18)}"/>`;
    const tower = (x, y, w) => `<rect x="${x}" y="${y}" width="${w}" height="${340 - y}" fill="${hsl(h, s * 0.6, 17)}"/>
      <path d="M${x - 4} ${y + 1} L${x + w / 2} ${y - w * 1.2} L${x + w + 4} ${y + 1} Z" fill="${hsl(h + 120, s, 20)}"/>
      <path d="M${x + w / 2} ${y - w * 1.2} V${y - w * 1.2 - 16}" stroke="${dark}" stroke-width="2"/>`;
    art += tower(26, 200, 36) + tower(298, 196, 36) + tower(110, 130, 30) + tower(220, 126, 30);
    const windows = [[44, 236], [316, 232], [125, 176], [235, 172], [170, 196], [190, 196], [180, 250]];
    windows.forEach(([x, y]) => {
      art += `<rect x="${x - 4}" y="${y - 7}" width="8" height="14" rx="4" fill="${dark}"/><rect x="${x - 2.5}" y="${y - 5}" width="5" height="11" rx="2.5" fill="#ffd27a" opacity=".7"/>`;
    });
    // The moat and the drawbridge
    art += `<path d="M0 420 C100 410 260 410 360 420 V470 C260 462 100 462 0 470 Z" fill="${hsl(210, 40, 16)}"/>`;
    art += `<path d="M20 432 h40 M120 444 h60 M240 436 h56 M300 452 h40" stroke="${hsl(210, 50, 34)}" stroke-width="1.5" opacity=".6"/>`;
    art += `<path d="M150 470 L156 404 H204 L210 470 Z" fill="${hsl(28, 30, 18)}"/>`;
    let planks = '';
    for (let y = 412; y < 470; y += 9) planks += `M${150 + (470 - y) * 0.09} ${y} H${210 - (470 - y) * 0.09} `;
    art += `<path d="${planks}" stroke="${hsl(28, 30, 11)}" stroke-width="1.5"/>`;
    art += `<path d="M156 404 L140 330 M204 404 L220 330" stroke="${hsl(h, s * 0.3, 30)}" stroke-width="2" stroke-dasharray="3 2"/>`;
    art += `<path d="M0 470 C100 462 260 462 360 470 V600 H0 Z" fill="${hsl(h, s * 0.8, 9)}"/>`;
    art += grassTufts(rand, 474, hsl(h, s * 0.8, 9));
    // Flags on the towers, torches on the walls, stars and a bat
    let fx = sceneStars(rand, 24, 140, '#e8ecff');
    [[44, 141], [316, 136], [125, 78], [235, 74]].forEach(([x, y], k) => {
      fx += `<i class="fx-flag" style="${at(x + 1, y)};--d:${(1.5 + k * 0.3).toFixed(1)}s"><svg viewBox="0 0 30 18"><path d="M0 1 C10 -2 18 5 30 2 V16 C18 19 10 12 0 15 Z" fill="${hsl(h + 120, s * 1.4, 34)}"/></svg></i>`;
    });
    [[60, 280], [300, 280], [150, 296], [210, 296]].forEach(([x, y], k) => {
      fx += `<i class="fx-flicker" style="${at(x, y)};--d:${(1.6 + k * 0.3).toFixed(1)}s"></i>`;
    });
    fx += `<i class="fx-bat" style="top:22%;--d:22s;--delay:-9s"><svg viewBox="0 0 30 14"><path d="M15 6 C13 2 9 1 6 2 C7 4 4 5 1 4 C3 8 7 10 11 9 L15 13 L19 9 C23 10 27 8 29 4 C26 5 23 4 24 2 C21 1 17 2 15 6 Z" fill="${hsl(h, s * 0.6, 22)}"/></svg></i>`;
    return { art, fx };
  },

  // 16. The King's Hall: pillars, tall windows with beams of light, red
  // banners with crowns, a red carpet up to the throne and candles.
  (h, s, rand) => {
    let art = sceneSky(hsl(h, s * 0.5, 9), hsl(h, s * 0.7, 13), hsl(h, s * 0.6, 8));
    art += `<defs><linearGradient id="scn-beam" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff2c8" stop-opacity=".22"/><stop offset="1" stop-color="#fff2c8" stop-opacity="0"/></linearGradient>
      <radialGradient id="scn-throne"><stop offset="0" stop-color="#ffd77a" stop-opacity=".3"/><stop offset="1" stop-color="#ffd77a" stop-opacity="0"/></radialGradient></defs>`;
    // The back wall with three tall windows
    art += `<rect x="0" y="0" width="360" height="430" fill="${hsl(h, s * 0.4, 11)}"/>`;
    [[110, 60], [180, 40], [250, 60]].forEach(([cx, top]) => {
      art += `<path d="M${cx - 22} 250 V${top + 22} C${cx - 22} ${top - 6} ${cx + 22} ${top - 6} ${cx + 22} ${top + 22} V250 Z" fill="${hsl(220, 30, 24)}"/>`;
      art += `<path d="M${cx} ${top + 4} V250 M${cx - 22} ${top + 70} H${cx + 22} M${cx - 22} ${top + 140} H${cx + 22}" stroke="${hsl(h, s * 0.4, 11)}" stroke-width="3"/>`;
      art += `<path d="M${cx - 22} 250 L${cx - 70} 520 H${cx + 30} L${cx + 22} 250 Z" fill="url(#scn-beam)"/>`;
    });
    // The throne at the far end, glowing
    art += `<circle cx="180" cy="236" r="90" fill="url(#scn-throne)"/>`;
    art += `<path d="M150 300 V200 C150 176 162 168 180 156 C198 168 210 176 210 200 V300 Z" fill="#8a1a2a"/>`;
    art += `<path d="M150 300 V200 C150 176 162 168 180 156 C198 168 210 176 210 200 V300" stroke="#e3b23c" stroke-width="4" fill="none"/>`;
    art += `<path d="M170 150 L172 140 L176 146 L180 136 L184 146 L188 140 L190 150 Z" fill="#e3b23c"/>`;
    art += `<rect x="140" y="290" width="80" height="16" rx="3" fill="${hsl(h, s * 0.5, 22)}"/>`;
    // Pillars on both sides
    const pillar = x => `<rect x="${x}" y="0" width="44" height="470" fill="${hsl(h, s * 0.3, 18)}"/>
      <path d="M${x + 10} 0 V470 M${x + 22} 0 V470 M${x + 34} 0 V470" stroke="${hsl(h, s * 0.3, 14)}" stroke-width="3"/>
      <rect x="${x - 6}" y="440" width="56" height="30" fill="${hsl(h, s * 0.3, 20)}"/>`;
    art += pillar(6) + pillar(310);
    // Banners with a crown
    const banner = x => `<path d="M${x} 0 V150 L${x + 22} 136 L${x + 44} 150 V0 Z" fill="#9a1a2a"/>
      <path d="M${x + 4} 0 V142" stroke="#e3b23c" stroke-width="2"/><path d="M${x + 40} 0 V142" stroke="#e3b23c" stroke-width="2"/>
      <path d="M${x + 12} 74 L${x + 14} 60 L${x + 18} 68 L${x + 22} 56 L${x + 26} 68 L${x + 30} 60 L${x + 32} 74 Z" fill="#e3b23c"/>`;
    art += banner(56) + banner(260);
    // The floor and the red carpet
    art += `<path d="M0 430 H360 V600 H0 Z" fill="${hsl(h, s * 0.3, 13)}"/>`;
    let tiles = '';
    for (let y = 446; y < 600; y += 26) tiles += `M0 ${y} H360 `;
    for (let x = -40; x < 400; x += 40) tiles += `M${x} 430 L${180 + (x - 180) * 1.8} 600 `;
    art += `<path d="${tiles}" stroke="${hsl(h, s * 0.3, 10)}" stroke-width="2"/>`;
    art += `<path d="M156 306 H204 L270 600 H90 Z" fill="#a01a2e"/><path d="M156 306 L90 600 M204 306 L270 600" stroke="#e3b23c" stroke-width="3"/>`;
    // Candles on stands at the sides, light beams full of dust, gold that glints
    let fx = '';
    [[78, 330], [282, 330], [64, 236], [296, 236]].forEach(([x, y], k) => {
      art += `<path d="M${x} ${y + 60} V${y + 10}" stroke="#c9a050" stroke-width="3"/><rect x="${x - 3}" y="${y}" width="6" height="12" fill="#f4ecd2"/>`;
      fx += `<i class="fx-flicker" style="${at(x, y - 4)};width:44px;height:44px;margin:-22px 0 0 -22px;--d:${(1.4 + k * 0.25).toFixed(2)}s"></i>`;
    });
    for (let k = 0; k < 10; k++) {
      fx += `<i class="fx-dust" style="${at(70 + rand() * 220, 260 + rand() * 200)};--dx:${(rand() * 30 - 15).toFixed(0)}px;--dy:${(rand() * 30 - 15).toFixed(0)}px;--d:${(5 + rand() * 4).toFixed(1)}s;--delay:-${(rand() * 6).toFixed(1)}s"></i>`;
    }
    fx += `<i class="fx-glint" style="${at(180, 140)};--d:3.6s"></i><i class="fx-glint" style="${at(77, 66)};--d:4.4s;--delay:-1.8s"></i><i class="fx-glint" style="${at(281, 66)};--d:5s;--delay:-3s"></i>`;
    return { art, fx };
  }
];

/* --- World secrets (3.20) --- */
// Every world scene hides a few things that react when you tap them, and one
// secret. Five kinds of secret cover all sixteen worlds:
//   pass:   something goes by now and then; tap it before it is gone
//   steps:  tap the same thing three times; it changes every time
//   timing: tap while it glows at its brightest
//   memory: things light up in order; tap them in the same order
//   all:    get every one of them into the same state at once
// A solved secret pays about SECRET.seconds of income, once per SECRET.rest in
// each world. The first time in a world also gives diamonds, and three worlds
// hide a coloured key for the locked chest in the settings.
const SECRET = {
  rest: 10 * 60e3, seconds: 90, taps: 20, diamonds: 5,
  pass: [20, 38], memory: [24, 36], answer: 12,
  obsidian: { scenes: [0], every: [60, 150], life: 16, diamonds: 1, perDay: 5 }
};
// The key in the Harbor's bottle, the one on the Tunnel's gold and the one in
// the King's Hall confetti. Someone who is already past one of those worlds
// finds its key in the next secret they solve instead.
const SECRET_KEYS = [
  { id: 'red', scene: 1, color: '#e5483d' },
  { id: 'blue', scene: 10, color: '#4b8ff2' },
  { id: 'green', scene: 15, color: '#48c672' }
];
const KEY_ICON = '<svg class="item-svg" viewBox="0 0 24 24" aria-hidden="true"><circle cx="7" cy="12" r="4.2" fill="none" stroke="currentColor" stroke-width="2.6"/><path d="M11.2 12 H21 M18 12 V16 M21 12 V15" stroke="currentColor" stroke-width="2.6" fill="none" stroke-linecap="round"/></svg>';
const SEC_NS = 'http://www.w3.org/2000/svg';
let sec = null;

const sceneIndex = (world = state.world) => (world - 1) % SCENES.length;
const secretReady = (idx = sceneIndex()) => Date.now() - (state.secrets.at[idx] || 0) >= SECRET.rest;
const secRoot = () => document.querySelector('#world-scene .sec-root');
const secEl = sel => secRoot()?.querySelector(sel) || null;
const secAll = sel => [...(secRoot()?.querySelectorAll(sel) || [])];
const secTl = (x, y) => `transform:translate(${x}px,${y}px)`;
const lifted = y => y - (sec?.lift || 0);
const secHit = (r = 22) => `<circle class="sec-hit" r="${r}"/>`;
const sparkPath = r => `M0 ${-r} Q${r * 0.15} ${-r * 0.15} ${r} 0 Q${r * 0.15} ${r * 0.15} 0 ${r} Q${-r * 0.15} ${r * 0.15} ${-r} 0 Q${-r * 0.15} ${-r * 0.15} 0 ${-r} Z`;
const secCoin = (r = 7) => `<circle class="coin-face" r="${r}"/><path class="coin-star" d="${sparkPath(r * 0.62)}"/>`;
const secKey = () => '<g class="sec-key"><circle cx="-5.5" r="4.2"/><path d="M-1.3 0 H9 M6 0 V4.2 M9 0 V3.4"/></g>';
const keyLine = id => id === 'red' ? tr('A red key! I wonder what it opens.')
  : id === 'blue' ? tr('A blue key! Keys like this open something special.') : tr('A green key! Keep it safe.');

function secLater(fn, ms) {
  const timers = sec ? sec.timers : null;
  const id = setTimeout(() => {
    if (timers) timers.delete(id);
    fn();
  }, ms);
  if (timers) timers.add(id);
  return id;
}

function secReplay(el, cls) {
  if (!el) return;
  el.classList.remove(cls);
  el.getBoundingClientRect();
  el.classList.add(cls);
}

function secPlace(el, x, y) {
  if (el) el.style.transform = `translate(${x}px,${y}px)`;
}

// Something added to the scene for a moment: a number, a word, a burst, a key.
function secAdd(html, x, y, cls, ms) {
  const root = secRoot();
  if (!root) return null;
  const g = document.createElementNS(SEC_NS, 'g');
  g.setAttribute('class', cls);
  g.style.transform = `translate(${x.toFixed(1)}px,${y.toFixed(1)}px)`;
  g.innerHTML = html;
  root.appendChild(g);
  setTimeout(() => g.remove(), ms);
  return g;
}

function sceneFloat(x, y, text, kind = '') {
  const safe = String(text).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]);
  return secAdd(`<text class="sec-float ${kind}">${safe}</text>`, Math.max(34, Math.min(326, x)), y, 'sec-floater', kind === 'say' ? 3000 : 1800);
}

function secBurst(x, y, color, n = 8, spread = 24, cls = '') {
  if (calmMotion()) return;
  const lift = cls === 'up' ? -spread : cls === 'fall' ? spread : 0;
  let html = '';
  for (let k = 0; k < n; k++) {
    const a = (k / n) * Math.PI * 2 + Math.random() * 0.7;
    const d = spread * (0.55 + Math.random() * 0.6);
    html += `<circle r="${(1.3 + Math.random() * 1.7).toFixed(1)}" fill="${color}" style="--dx:${(Math.cos(a) * d).toFixed(1)}px;--dy:${(Math.sin(a) * d * 0.8 + lift).toFixed(1)}px"/>`;
  }
  secAdd(html, x, y, `sec-burst ${cls}`, 1300);
}

function secKeyPop(x, y, key) {
  const g = secAdd(secKey(), x, y, 'sec-keypop', 3300);
  if (g) g.style.setProperty('--key', key.color);
}

function secConfetti(key) {
  const colors = ['#e5483d', '#f7b931', '#4b8ff2', '#48c672', '#c8a2ff', '#ff8a4c'];
  let html = '';
  for (let k = 0; k < (calmMotion() ? 0 : 28); k++) {
    html += `<rect x="${(16 + Math.random() * 328).toFixed(0)}" y="-12" width="5" height="8" rx="1" fill="${colors[k % colors.length]}" style="--dy:${(390 + Math.random() * 80).toFixed(0)}px;--r:${(Math.random() * 720 - 360).toFixed(0)}deg;animation-delay:${(Math.random() * 0.8).toFixed(2)}s"/>`;
  }
  if (key) html += `<g class="fall-key" style="--key:${key.color}"><g style="${secTl(300, -14)}">${secKey()}</g></g>`;
  secAdd(html, 0, 0, 'sec-confetti', 5600);
}

// The key a solved secret gives, if any: this world's own key first, then a
// key from a world the player has already passed.
function secretKeyFor(idx) {
  const have = state.secrets.keys;
  const reached = Math.max(state.world, state.stats.bestWorld || 0);
  return SECRET_KEYS.find(k => !have.includes(k.id) && k.scene === idx)
    || SECRET_KEYS.find(k => !have.includes(k.id) && reached > k.scene + 1) || null;
}

// Pays for a solved secret. The state changes at once; `delay` holds back the
// numbers and sounds until the scene's own little show reaches its end.
function secretSolve(pt, shownKey = false, delay = 0) {
  if (!sec || !secretReady(sec.idx)) return null;
  const idx = sec.idx;
  const store = state.secrets;
  const first = !store.found.includes(idx);
  const key = secretKeyFor(idx);
  const coins = Math.max(clickPower() * SECRET.taps, baseIncome() * SECRET.seconds);
  store.at[idx] = Date.now();
  state.stats.secrets++;
  sec.ready = false;
  earn(coins);
  if (first) {
    store.found.push(idx);
    state.diamonds += SECRET.diamonds;
  }
  if (key) store.keys.push(key.id);
  const y = pt.y > 380 ? lifted(pt.y) : pt.y;
  secLater(() => {
    sceneFloat(pt.x, y - 10, `+${format(coins)}`);
    if (first) secLater(() => sceneFloat(pt.x, y - 30, `+${SECRET.diamonds} 💎`, 'gem'), 450);
    if (key && !shownKey) secKeyPop(pt.x, y - 24, key);
    sfx('lucky');
    buzz(40);
  }, delay);
  const line = key ? (store.keys.length === SECRET_KEYS.length ? tr('That makes all three keys! Look in the settings.') : keyLine(key.id))
    : first ? tr('You found a secret in this world!') : '';
  if (line) secLater(() => pipSay(line, 'happy', 3800, true), delay + 900);
  secRoot()?.classList.add('resting');
  save();
  refresh();
  return { coins, first, key };
}

// Obsidian flies: now and then one of the Meadow's fireflies glows purple.
// Each one caught is a diamond, up to SECRET.obsidian.perDay a day.
function obsidianLeft() {
  const o = state.secrets.obsidian;
  return o.day === today() ? SECRET.obsidian.perDay - o.n : SECRET.obsidian.perDay;
}

function obsidianTick(now) {
  if (!SECRET.obsidian.scenes.includes(sec.idx)) return;
  const shown = secEl('.sec-fly.obsidian');
  if (sec.obsUntil && (now >= sec.obsUntil || !shown)) {
    if (shown) shown.classList.remove('obsidian');
    sec.obsUntil = 0;
    sec.obsAt = now + between(SECRET.obsidian.every) * 1000;
  }
  if (!sec.obsAt) sec.obsAt = now + between(SECRET.obsidian.every) * 1000;
  if (sec.obsUntil || now < sec.obsAt || obsidianLeft() <= 0) return;
  const flies = secAll('.sec-fly:not(.gone)');
  if (!flies.length) return;
  flies[Math.floor(Math.random() * flies.length)].classList.add('obsidian');
  sec.obsUntil = now + SECRET.obsidian.life * 1000;
}

function obsidianCatch(pt) {
  if (obsidianLeft() <= 0) return;
  const o = state.secrets.obsidian;
  if (o.day !== today()) {
    o.day = today();
    o.n = 0;
  }
  o.n++;
  state.diamonds += SECRET.obsidian.diamonds;
  sceneFloat(pt.x, pt.y - 26, `+${SECRET.obsidian.diamonds} 💎`, 'gem');
  sfx('lucky');
  save();
  refresh();
}

// pass: one thing crosses the scene along a straight line (or, in still
// mode, fades in and out at one spot) every SECRET.pass seconds.
function passStart(def) {
  const el = secEl('.sec-pass');
  if (!el) return;
  const set = (name, value) => el.style.setProperty(name, value);
  set('--fx', `${def.from[0]}px`);
  const lift = def.low ? sec.lift || 0 : 0;
  set('--fy', `${def.from[1] - lift}px`);
  set('--tx', `${def.to[0]}px`);
  set('--ty', `${def.to[1] - lift}px`);
  set('--mx', `${def.still[0]}px`);
  set('--my', `${def.still[1] - lift}px`);
  set('--pd', `${def.secs}s`);
  el.classList.remove('caught', 'keyed');
  el.classList.toggle('still', calmMotion());
  secReplay(el, 'go');
  sec.passing = true;
  sec.caught = false;
  sec.passEnd = Date.now() + def.secs * 1000;
}

function passStop() {
  secEl('.sec-pass')?.classList.remove('go', 'caught', 'keyed');
  sec.passing = false;
  sec.caught = false;
  sec.next = Date.now() + between(SECRET.pass) * 1000;
}

function passTick(now, def) {
  if (sec.passing && !sec.caught && now >= sec.passEnd) passStop();
  else if (!sec.passing && sec.ready && now >= sec.next) passStart(def);
}

function passCatch(el, pt) {
  if (!sec.passing || sec.caught || !sec.ready) return null;
  sec.caught = true;
  const key = secretKeyFor(sec.idx);
  const own = !!key && key.scene === sec.idx;
  if (own) {
    el.classList.add('keyed');
    el.style.setProperty('--key', key.color);
  }
  el.classList.add('caught');
  secLater(passStop, 2600);
  return secretSolve(pt, own);
}

// memory: the items play a short tune of four now and then; tapping them back
// in the same order within SECRET.answer seconds solves it.
function memoryTick(now, def) {
  if (!sec.ready || sec.playing) return;
  if (sec.input !== null && now > sec.until) sec.input = null;
  if (sec.input === null && now >= sec.next) memoryPlay(def);
}

function memoryPlay(def) {
  const n = def.items.length;
  sec.seq = [];
  while (sec.seq.length < 4) {
    const v = Math.floor(Math.random() * n);
    if (v !== sec.seq[sec.seq.length - 1]) sec.seq.push(v);
  }
  sec.playing = true;
  sec.input = null;
  sec.seq.forEach((v, k) => secLater(() => memoryLight(def, v), 500 + k * 700));
  secLater(() => {
    sec.playing = false;
    sec.input = 0;
    sec.until = Date.now() + SECRET.answer * 1000;
  }, 500 + sec.seq.length * 700);
  sec.next = Date.now() + between(SECRET.memory) * 1000;
}

function memoryLight(def, k) {
  secReplay(secAll('[data-spot="item"]')[k], 'lit');
  sfx(def.notes[k]);
}

function memoryTap(def, el, pt) {
  const k = +el.dataset.k;
  memoryLight(def, k);
  if (!sec.ready || sec.playing || sec.input === null) return;
  if (sec.seq[sec.input] !== k) {
    sec.input = null;
    sec.next = Date.now() + 3500;
    secLater(() => sfx('miss'), 250);
    return;
  }
  sec.input++;
  if (sec.input < sec.seq.length) return;
  sec.input = null;
  def.solved(pt);
}

// The sixteen scenes, in world order. Coordinates are in the scene's
// 360 × 600 drawing; everything sits clear of the coin and the texts.
const SECRETS = [
  { // 1. The Meadow: catch five fireflies and they make a glowing coin.
    // Now and then one of them is an obsidian fly, worth a diamond.
    homes: [[44, 300], [318, 296], [308, 124], [46, 112], [62, 440], [300, 442]],
    art() {
      return this.homes.map(([x, y], k) => `<g${y > 390 ? ' class="low"' : ''} style="${secTl(x, y)}"><g class="sec-fly" data-spot="fly" style="--d:${(3.6 + k * 0.6).toFixed(1)}s;--delay:-${(k * 1.1).toFixed(1)}s">${secHit(20)}<circle class="fly-glow" r="9"/><circle class="fly-core" r="2.4"/></g></g>`).join('')
        + `<g class="sec-flycoin"><g class="pop">${secCoin(11)}</g></g>`;
    },
    start() {
      sec.count = 0;
    },
    tap(el, pt) {
      if (el.classList.contains('gone')) return;
      if (el.classList.contains('obsidian')) {
        el.classList.remove('obsidian');
        obsidianCatch(pt);
      }
      el.classList.add('gone');
      sfx('catch');
      secLater(() => el.classList.remove('gone'), 5000 + Math.random() * 3000);
      if (!sec.ready) return;
      sec.count = (sec.count || 0) + 1;
      if (sec.count < 5) {
        sceneFloat(pt.x, pt.y - 14, `${sec.count}/5`, 'soft');
        return;
      }
      sec.count = 0;
      const coin = secEl('.sec-flycoin');
      secPlace(coin, pt.x, pt.y);
      secReplay(coin, 'show');
      secBurst(pt.x, pt.y, '#f6e48a', 10, 26);
      secretSolve(pt);
    }
  },
  { // 2. The Harbor: tap the lighthouse and it flashes. Now and then a message
    // in a bottle drifts by: fish it out. The first one holds the red key.
    from: [352, 454], to: [4, 450], still: [300, 452], secs: 18, low: true,
    art() {
      return `<g style="${secTl(308, 333)}"><g class="sec-light" data-spot="light">${secHit(22)}<circle class="flash" r="15"/></g></g>
        <g class="sec-pass bottle-pass" data-spot="pass">${secHit(22)}<g class="bob"><g class="bottle"><path class="glass" d="M-12 -4 H3 L7 -2 H11 V2 H7 L3 4 H-12 Z"/><rect class="cork" x="11" y="-2" width="3" height="4" rx="1"/><rect class="note" x="-9" y="-2.2" width="10" height="4.4" rx="1"/></g></g>
        <g class="out"><path class="scroll" d="M-7 -6 H7 V5 H-7 Z"/><path class="lines" d="M-4 -3 H4 M-4 0 H4 M-4 3 H2"/><g class="key-at"><g style="${secTl(0, -16)}">${secKey()}</g></g></g></g>`;
    },
    start() {
      sec.next = Date.now() + between([6, 14]) * 1000;
    },
    tick(now) {
      passTick(now, this);
    },
    tap(el, pt, spot) {
      if (spot === 'light') {
        secReplay(el, 'flash-on');
        sfx('dong');
        return;
      }
      if (passCatch(el, pt)) sfx('splash');
    }
  },
  { // 3. Old Town: tap a window and its light goes on or off. A cat hops over
    // the roofs: tap it three times and it knocks a coin off the clock tower.
    spots: [[296, 372], [56, 370], [83, 210]],
    art() {
      return `<g class="sec-cat" data-spot="cat" style="${secTl(296, 372)}">${secHit(22)}<g class="jumper"><g class="cat"><path class="fur" d="M-7 0 C-8 -6 -6 -10 -2 -11 L-3 -16 L0 -13 L3 -16 L3 -11 C6 -9 7 -5 6 0 Z"/><path class="tail" d="M6 -1 C12 -2 13 -8 10 -12"/><circle class="eye" cx="-1" cy="-12" r=".9"/><circle class="eye" cx="2" cy="-12" r=".9"/></g></g></g>
        <g class="sec-drop" style="${secTl(83, 214)};--fall:90px"><g class="pop">${secCoin(6)}</g></g>`;
    },
    go(k) {
      const [x, y] = this.spots[k];
      secPlace(secEl('.sec-cat'), x, y);
    },
    start() {
      sec.stage = 0;
      this.go(0);
    },
    rest() {
      sec.stage = 2;
      this.go(2);
    },
    tap(el) {
      sfx('meow');
      if (!sec.ready) {
        secReplay(el.querySelector('.jumper'), 'hop');
        return;
      }
      if (sec.stage < 2) {
        sec.stage++;
        this.go(sec.stage);
        secReplay(el.querySelector('.jumper'), 'leap');
        return;
      }
      secReplay(el.querySelector('.cat'), 'swipe');
      secReplay(secEl('.sec-drop'), 'fall');
      secretSolve({ x: 83, y: 236 });
    }
  },
  { // 4. Sunny Dunes: tap a cactus and it flowers. Now and then an X shows in
    // the sand: dig three times for a chest.
    art() {
      return [[40, 424, 397], [322, 424, 401]].map(([x, y, top]) => `<g style="${secTl(x, y)}"><g class="sec-cactus" data-spot="cactus">${secHit(24)}<g class="bloom" style="${secTl(0, top - y)}"><g class="petals"><circle r="4.2"/><circle class="mid" r="1.7"/></g></g></g></g>`).join('')
        + `<g class="sec-dig low" data-spot="dig" data-stage="0" style="${secTl(282, 458)}">${secHit(24)}<path class="xmark" d="M-7 -4 L7 4 M7 -4 L-7 4"/><ellipse class="hole" rx="11" ry="4"/><g class="chest"><g class="pop"><rect class="box" x="-9" y="-12" width="18" height="11" rx="1.5"/><path class="lid" d="M-9 -12 C-9 -18 9 -18 9 -12 Z"/><rect class="chest-lock" x="-1.6" y="-9.5" width="3.2" height="4"/></g></g></g>`;
    },
    start() {
      sec.stage = 0;
      secEl('.sec-dig').dataset.stage = '0';
    },
    rest() {
      secEl('.sec-dig').dataset.stage = 'rest';
    },
    tap(el, pt, spot) {
      if (spot === 'cactus') {
        secReplay(el, 'flower');
        sfx('pop');
        return;
      }
      if (!sec.ready || sec.stage >= 3) return;
      sec.stage++;
      el.dataset.stage = String(sec.stage);
      secBurst(282, lifted(456), '#e8c88a', 7, 18, 'up');
      sfx(sec.stage < 3 ? 'crack' : 'loot');
      if (sec.stage < 3) return;
      secretSolve({ x: 282, y: 440 });
      secLater(() => {
        if (!sec.ready) el.dataset.stage = 'rest';
      }, 3400);
    }
  },
  { // 5. Frost Peak: tap a pine and its snow falls off. Build a snowman with
    // three taps on the snow pile; he waves and gives you a coin.
    pines: [[22, 440], [52, 452], [306, 438], [338, 452]],
    art() {
      return this.pines.map(([x, y]) => `<g class="low" style="${secTl(x, y)}"><g class="sec-pine" data-spot="pine">${secHit(18)}</g></g>`).join('')
        + `<g class="sec-snowman low" data-spot="snowman" data-stage="0" style="${secTl(96, 452)}">${secHit(24)}<ellipse class="mound" cy="1" rx="15" ry="5"/><circle class="b1" cy="-10" r="12"/><circle class="b2" cy="-28" r="9"/><g class="b3"><circle class="snow" cy="-42" r="7"/><path class="hat" d="M-6.5 -47 H6.5 V-49 H4 V-57 H-4 V-49 H-6.5 Z"/><circle class="coal" cx="-2.5" cy="-43.5" r="1"/><circle class="coal" cx="2.5" cy="-43.5" r="1"/><path class="nose" d="M0 -41.5 L6 -40.5 L0 -39.5 Z"/></g><path class="arms" d="M-8 -30 L-19 -37 M8 -30 L19 -38"/></g>`;
    },
    start() {
      sec.stage = 0;
      secEl('.sec-snowman').dataset.stage = '0';
    },
    rest() {
      secEl('.sec-snowman').dataset.stage = '3';
    },
    tap(el, pt, spot) {
      if (spot === 'pine') {
        secBurst(pt.x, pt.y - 22, '#eef6ff', 9, 20, 'fall');
        sfx('gust');
        return;
      }
      if (!sec.ready || sec.stage >= 3) {
        secReplay(el, 'wave');
        return;
      }
      sec.stage++;
      el.dataset.stage = String(sec.stage);
      sfx('build');
      if (sec.stage < 3) return;
      secReplay(el, 'wave');
      secretSolve({ x: 96, y: 396 });
    }
  },
  { // 6. Ember Isle: the volcano glows brighter and dimmer. Tap it at its
    // brightest and it erupts with coins.
    art() {
      return `<defs><radialGradient id="sec-lava"><stop offset="0" stop-color="#fff2a8"/><stop offset=".45" stop-color="#ff9a3c" stop-opacity=".75"/><stop offset="1" stop-color="#ff5a1f" stop-opacity="0"/></radialGradient></defs>
        <g style="${secTl(58, 296)}"><g class="sec-volcano" data-spot="volcano">${secHit(30)}<circle class="glow" r="22" fill="url(#sec-lava)"/></g></g>`;
    },
    start() {
      secReplay(secEl('.sec-volcano'), 'pulse');
      sec.t0 = Date.now();
    },
    rest() {
      secEl('.sec-volcano')?.classList.remove('pulse');
    },
    tap(el) {
      const phase = ((Date.now() - (sec.t0 || 0)) % 3200) / 3200;
      if (!sec.ready || Math.abs(phase - 0.5) > 0.15) {
        secBurst(58, 290, '#9a948c', 6, 16, 'up');
        sfx('poof');
        return;
      }
      el.classList.remove('pulse');
      secReplay(el, 'erupt');
      secBurst(58, 286, '#ffb347', 14, 40, 'up');
      sfx('rumble');
      secretSolve({ x: 58, y: 262 });
    }
  },
  { // 7. Moon Base: the mast sends a signal when you tap it. A little
    // astronaut hops in slow motion; on the third hop he plants a flag.
    art() {
      return `<g style="${secTl(346, 398)}"><g class="sec-mast" data-spot="mast">${secHit(20)}</g></g>
        <g class="sec-astro low" data-spot="astro" data-stage="0" style="${secTl(246, 434)}">${secHit(22)}<g class="flag"><path class="pole" d="M-15 0 V-30"/><path class="cloth" d="M-15 -30 H-2 V-21 H-15 Z"/><circle class="emblem" cx="-8.5" cy="-25.5" r="2.4"/></g><g class="jumper"><rect class="pack" x="-7.5" y="-15" width="4" height="9" rx="1"/><rect class="suit" x="-5" y="-16" width="10" height="12" rx="3"/><circle class="helmet" cy="-21" r="6"/><path class="visor" d="M-3.6 -22 H3.6 A3.6 3 0 0 1 -3.6 -22 Z"/><rect class="leg" x="-4" y="-5" width="3" height="5"/><rect class="leg" x="1" y="-5" width="3" height="5"/></g></g>`;
    },
    start() {
      sec.stage = 0;
      secEl('.sec-astro').dataset.stage = '0';
    },
    rest() {
      secEl('.sec-astro').dataset.stage = '3';
    },
    tap(el, pt, spot) {
      if (spot === 'mast') {
        secAdd('<circle r="6"/><circle r="6" class="late"/>', 346, 390, 'sec-rings', 1800);
        sfx('pop');
        return;
      }
      secReplay(el.querySelector('.jumper'), 'float');
      sfx('pop');
      if (!sec.ready || sec.stage >= 3) return;
      sec.stage++;
      if (sec.stage < 3) return;
      secLater(() => {
        el.dataset.stage = '3';
        sfx('claim');
      }, 900);
      secretSolve({ x: 232, y: 396 }, false, 900);
    }
  },
  { // 8. Star Sea: tap the ringed planet and a little moon circles it. Now and
    // then a falling star goes by: tap it and make a wish.
    from: [352, 20], to: [232, 140], still: [300, 70], secs: 3.8,
    art() {
      return `<g style="${secTl(73, 118)}"><g class="sec-planet" data-spot="planet">${secHit(28)}<g class="orbit"><circle class="moonlet" cx="34" r="3.5"/></g></g></g>
        <g class="sec-pass star-pass" data-spot="pass">${secHit(26)}<g class="star"><path class="tail" d="M0 0 L30 -26"/><path class="head" d="${sparkPath(7)}"/></g></g>`;
    },
    start() {
      sec.next = Date.now() + between([5, 12]) * 1000;
    },
    tick(now) {
      passTick(now, this);
    },
    tap(el, pt, spot) {
      if (spot === 'planet') {
        secReplay(el, 'spin');
        sfx('wisp');
        return;
      }
      if (!passCatch(el, pt)) return;
      sfx('wish');
      secBurst(pt.x, pt.y, '#fff2b0', 12, 30);
      sceneFloat(pt.x, pt.y + 28, tr('Make a wish!'), 'soft');
    }
  },
  { // 9. The Deep Cave: each crystal sings a note. Now and then they play a
    // little tune by themselves: play it back in the same order.
    items: [[42, 398], [320, 346], [326, 124], [40, 270]],
    colors: ['#7fd8f2', '#b996f2', '#f2a6d8', '#8ff0b0'],
    notes: ['note0', 'note1', 'note2', 'note3'],
    art() {
      return this.items.map(([x, y], k) => `<g${y > 390 ? ' class="low"' : ''} style="${secTl(x, y)}"><g class="sec-crystal" data-spot="item" data-k="${k}" style="--c:${this.colors[k]}">${secHit(24)}<circle class="halo" r="22"/><path class="shards" d="M-9 6 L-6 -8 L-2 6 Z M-3 6 L1 -15 L5 6 Z M3 6 L8 -5 L11 6 Z"/></g></g>`).join('');
    },
    start() {
      sec.next = Date.now() + 5000;
      sec.input = null;
    },
    tick(now) {
      memoryTick(now, this);
    },
    tap(el, pt) {
      memoryTap(this, el, pt);
    },
    solved(pt) {
      secAll('.sec-crystal').forEach((c, k) => secLater(() => secReplay(c, 'lit'), k * 120));
      secretSolve(pt);
    }
  },
  { // 10. The Mountain: shout at the crags and they answer. An eagle circles
    // high up: tap it and it dives into the clouds for a coin.
    art() {
      return `<g style="${secTl(34, 282)}"><g class="sec-crag" data-spot="echo">${secHit(26)}</g></g>
        <g style="${secTl(300, 112)}"><g class="sec-orbit"><g style="${secTl(34, 0)}"><g class="counter"><g class="sec-eagle" data-spot="eagle">${secHit(22)}<g class="dive"><g class="bird"><path class="wings" d="M0 0 C-6 -6 -14 -7 -20 -3 C-13 -3 -8 0 -3 3 L0 2 L3 3 C8 0 13 -3 20 -3 C14 -7 6 -6 0 0 Z"/><g class="talon" style="${secTl(0, 6)}">${secCoin(4)}</g></g></g></g></g></g></g></g>`;
    },
    tap(el, pt, spot) {
      if (spot === 'echo') {
        [0, 1, 2].forEach(k => secLater(() => sceneFloat(72 + k * 36, 266 - k * 10, tr('Hello!'), `echo e${k}`), k * 520));
        sfx('echo');
        return;
      }
      if (sec.diving) return;
      sfx('flap');
      if (!sec.ready) {
        secReplay(el.querySelector('.bird'), 'flutter');
        return;
      }
      sec.diving = true;
      const orbit = secEl('.sec-orbit');
      orbit.classList.add('hold');
      secReplay(el.querySelector('.dive'), 'go');
      secLater(() => {
        sec.diving = false;
        orbit.classList.remove('hold');
        el.querySelector('.dive').classList.remove('go');
      }, 2500);
      secretSolve({ x: pt.x, y: pt.y + 20 }, false, 2000);
    }
  },
  { // 11. The Tunnel: light every lantern and a minecart full of gold rolls
    // out of the dark. The first one has the blue key on top of the gold.
    lamps: [[100, 153], [260, 153], [310, 296]],
    art() {
      const old = ([x, y]) => `<g style="${secTl(x, y)}"><g class="sec-lantern old" data-spot="lantern">${secHit(22)}<circle class="dim" r="40"/><rect class="body" x="-6" y="-7" width="12" height="15" rx="2"/><circle class="flare" r="16"/></g></g>`;
      const [x, y] = this.lamps[2];
      return old(this.lamps[0]) + old(this.lamps[1])
        + `<g style="${secTl(x, y)}"><path class="sec-hook" d="M0 -30 V-14"/><g class="sec-lantern new" data-spot="lantern">${secHit(22)}<circle class="halo" r="30"/><path class="roof" d="M-7 -8 L0 -14 L7 -8 Z"/><rect class="body" x="-6" y="-8" width="12" height="15" rx="2"/><circle class="flare" r="16"/></g></g>`
        + `<g class="sec-cart low" style="${secTl(180, 440)}"><g class="ride"><path class="tub" d="M-20 -14 H20 L16 2 H-16 Z"/><circle class="wheel" cx="-10" cy="5" r="4.5"/><circle class="wheel" cx="10" cy="5" r="4.5"/><path class="gold" d="M-18 -14 C-14 -26 14 -26 18 -14 Z"/><circle class="nug" cx="-8" cy="-18" r="2.4"/><circle class="nug" cx="4" cy="-21" r="2.4"/><circle class="nug" cx="11" cy="-16" r="2.2"/><g class="cart-key" style="${secTl(0, -27)}"><g style="transform:rotate(-24deg)">${secKey()}</g></g></g></g>`;
    },
    start() {
      const lamps = secAll('.sec-lantern');
      const lit = Math.floor(Math.random() * lamps.length);
      lamps.forEach((l, k) => l.classList.toggle('dark', k !== lit));
      secEl('.sec-cart').classList.remove('roll', 'parked', 'keyed');
    },
    rest() {
      secAll('.sec-lantern').forEach(l => l.classList.remove('dark'));
      secEl('.sec-cart').classList.add('parked');
    },
    tap(el) {
      if (!el.classList.contains('dark')) {
        secReplay(el, 'flicker');
        sfx('pop');
        return;
      }
      el.classList.remove('dark');
      sfx('spell');
      if (!sec.ready || secAll('.sec-lantern.dark').length) return;
      const cart = secEl('.sec-cart');
      const key = secretKeyFor(sec.idx);
      const own = !!key && key.scene === sec.idx;
      cart.classList.toggle('keyed', own);
      if (own) cart.style.setProperty('--key', key.color);
      secLater(() => {
        secReplay(cart, 'roll');
        sfx('rails');
      }, 500);
      secretSolve({ x: 70, y: 412 }, own, 2100);
    }
  },
  { // 12. The Swamp: tap a lily pad and it bobs. Tap the frog three times: it
    // hops from pad to pad and turns into a little prince with a golden ball.
    pads: [[52, 452], [138, 462], [306, 448]],
    art() {
      return this.pads.map(([x, y]) => `<g class="low" style="${secTl(x, y)}"><g class="sec-pad" data-spot="pad">${secHit(18)}<path class="leaf" d="M0 0 L14 -1.6 A14 5 0 1 1 13 1.6 Z"/></g></g>`).join('')
        + `<g class="sec-frog low" data-spot="frog" style="${secTl(52, 449)}">${secHit(20)}<g class="jumper"><g class="frog"><ellipse class="fb" cy="-5" rx="8" ry="6"/><circle class="fe" cx="-4" cy="-10" r="2.6"/><circle class="fe" cx="4" cy="-10" r="2.6"/><circle class="fp" cx="-4" cy="-10.5" r="1.1"/><circle class="fp" cx="4" cy="-10.5" r="1.1"/><path class="fm" d="M-3 -4 Q0 -2 3 -4"/></g><g class="prince"><rect class="pb" x="-4" y="-12" width="8" height="11" rx="2"/><circle class="ph" cy="-16" r="4.5"/><path class="crown" d="M-4.5 -19 L-4.5 -24 L-2 -21.5 L0 -25 L2 -21.5 L4.5 -24 L4.5 -19 Z"/><circle class="ball" cx="8" cy="-5" r="3.2"/></g></g></g>`;
    },
    go(k) {
      const [x, y] = this.pads[k];
      secPlace(secEl('.sec-frog'), x, y - 3);
    },
    start() {
      sec.stage = 0;
      this.go(0);
    },
    rest() {
      sec.stage = 2;
      this.go(2);
    },
    tap(el, pt, spot) {
      if (spot === 'pad') {
        secReplay(el, 'bob');
        sfx('splash');
        return;
      }
      sfx('croak');
      const jumper = el.querySelector('.jumper');
      if (!sec.ready || el.classList.contains('royal')) {
        secReplay(jumper, 'hop');
        return;
      }
      if (sec.stage < 2) {
        sec.stage++;
        this.go(sec.stage);
        secReplay(jumper, 'leap');
        return;
      }
      el.classList.add('royal');
      secBurst(306, lifted(436), '#f6e48a', 10, 22);
      sfx('spell');
      secLater(() => el.classList.remove('royal'), 4200);
      secretSolve({ x: 306, y: 420 }, false, 600);
    }
  },
  { // 13. The City Gate: tap a flag and it flaps. Knock three times on the
    // little door: a guard opens the hatch, there's no toll today, and a coin.
    art() {
      return [[60, 140], [330, 128]].map(([x, y]) => `<g style="${secTl(x, y)}"><g class="sec-flag" data-spot="flag">${secHit(22)}</g></g>`).join('')
        + `<g class="low" style="${secTl(42, 446)}"><g class="sec-door" data-spot="door">${secHit(22)}<g class="shake"><path class="door" d="M-12 0 V-27 C-12 -36 12 -36 12 -27 V0 Z"/><path class="planks" d="M-4 0 V-33 M4 0 V-33"/><circle class="ring" cx="7" cy="-12" r="2"/><rect class="hole" x="-5" y="-27" width="10" height="8" rx="1.5"/><g class="guard"><circle class="face" cy="-21.5" r="3.4"/><path class="helm" d="M-4 -22.5 C-4 -28 4 -28 4 -22.5 Z"/></g><rect class="lid" x="-5" y="-27" width="10" height="8" rx="1.5"/></g></g></g>
        <g class="sec-drop low" style="${secTl(42, 420)};--fall:24px"><g class="pop">${secCoin(6)}</g></g>`;
    },
    start() {
      sec.stage = 0;
    },
    tap(el, pt, spot) {
      if (spot === 'flag') {
        const fx = document.querySelector('#world-scene .scene-fx');
        if (fx) {
          fx.classList.add('flutter');
          clearTimeout(sec.flutter);
          sec.flutter = secLater(() => fx.classList.remove('flutter'), 2500);
        }
        sfx('gust');
        return;
      }
      secReplay(el.querySelector('.shake'), 'knock');
      sfx('knock');
      if (!sec.ready || el.classList.contains('open')) return;
      sec.stage++;
      if (sec.stage < 3) return;
      sec.stage = 0;
      secLater(() => {
        el.classList.add('open');
        sceneFloat(150, 382, tr('No toll today!'), 'say');
        secReplay(secEl('.sec-drop'), 'fall');
        sfx('gate');
      }, 500);
      secLater(() => el.classList.remove('open'), 3800);
      secretSolve({ x: 42, y: 392 }, false, 800);
    }
  },
  { // 14. City Square: tap a lantern and it sways. Pigeons peck at the
    // stones: get all four up in the air at once and one leaves a coin behind.
    birds: [[34, 462, 1], [76, 466, -1], [284, 466, 1], [326, 462, -1]],
    art() {
      return this.birds.map(([x, y, dir]) => `<g class="low" style="${secTl(x, y)}"><g class="sec-pigeon" data-spot="pigeon">${secHit(18)}<g class="fly"><g style="transform:scaleX(${dir})"><g class="peck"><ellipse class="pbody" rx="7" ry="4.5"/><circle class="phead" cx="-6" cy="-4" r="3"/><path class="pbeak" d="M-8.8 -4.2 L-11 -3.5 L-8.8 -2.8 Z"/><path class="ptail" d="M6 -1 L11 -3 L11 1 Z"/></g></g></g></g></g>`).join('')
        + `<g class="sec-drop low" style="${secTl(56, 452)};--fall:8px"><g class="pop">${secCoin(6)}</g></g>`;
    },
    start() {
      sec.up = [0, 0, 0, 0];
    },
    tap(el) {
      const k = secAll('.sec-pigeon').indexOf(el);
      const now = Date.now();
      sec.up = sec.up || [0, 0, 0, 0];
      if (sec.up[k] > now) return;
      sec.up[k] = now + 3600;
      secReplay(el, 'up');
      sfx('flap');
      if (!sec.ready || sec.up.some(t => t <= now)) return;
      secLater(() => secReplay(secEl('.sec-drop'), 'show'), 600);
      secretSolve({ x: 56, y: 430 }, false, 600);
    }
  },
  { // 15. The Castle: tap a tower window and a light comes on. Now and then a
    // dragon flies past the moon: tap it and it drops a golden scale.
    from: [-34, 78], to: [394, 30], still: [84, 64], secs: 9,
    art() {
      return [[44, 236], [316, 232]].map(([x, y]) => `<g style="${secTl(x, y)}"><g class="sec-cwin" data-spot="cwin">${secHit(18)}<rect class="glow" x="-4" y="-6" width="8" height="12" rx="1.5"/><path class="who" d="M-2 6 V1 C-2 -3 2 -3 2 1 V6 Z"/></g></g>`).join('')
        + `<g class="sec-pass dragon-pass" data-spot="pass">${secHit(26)}<g class="dragon"><path class="dtail" d="M-15 0 C-21 -2 -25 3 -31 0"/><path class="dbody" d="M-16 0 C-8 -4 6 -4 13 -1 L19 -4 L17 0 L22 2 L13 2 C6 4 -8 4 -16 0 Z"/><g class="dwing"><path d="M-3 -1 L3 -17 L10 -11 L7 -1 Z"/></g></g></g>`;
    },
    start() {
      sec.next = Date.now() + between([8, 16]) * 1000;
    },
    tick(now) {
      passTick(now, this);
    },
    tap(el, pt, spot) {
      if (spot === 'cwin') {
        secReplay(el, 'on');
        sfx('pop');
        return;
      }
      if (!passCatch(el, pt)) return;
      sfx('golden');
      secAdd('<path class="scale" d="M0 -6 C5 -2 5 4 0 7 C-5 4 -5 -2 0 -6 Z"/>', pt.x, pt.y + 6, 'sec-scale', 2300);
    }
  },
  { // 16. The King's Hall: the windows light up in a tune of their own. Tap
    // them back in the same order for a fanfare and confetti, with the green
    // key falling among it the first time.
    items: [[110, 160], [180, 120], [250, 160]],
    tops: [60, 40, 60],
    notes: ['note1', 'note2', 'note3'],
    art() {
      return this.items.map(([x, y], k) => {
        const cx = [110, 180, 250][k];
        const top = this.tops[k];
        return `<g class="sec-window" data-spot="item" data-k="${k}"><path class="glass" d="M${cx - 22} 250 V${top + 22} C${cx - 22} ${top - 6} ${cx + 22} ${top - 6} ${cx + 22} ${top + 22} V250 Z"/><path class="ray" d="M${cx - 22} 250 L${cx - 70} 520 H${cx + 30} L${cx + 22} 250 Z"/><circle class="sec-hit" cx="${x}" cy="${y}" r="24"/></g>`;
      }).join('');
    },
    start() {
      sec.next = Date.now() + 5000;
      sec.input = null;
    },
    tick(now) {
      memoryTick(now, this);
    },
    tap(el, pt) {
      memoryTap(this, el, pt);
    },
    solved() {
      sfx('fanfare');
      const key = secretKeyFor(sec.idx);
      const own = !!key && key.scene === sec.idx;
      secConfetti(own ? key : null);
      secretSolve({ x: 300, y: 430 }, own, 1700);
    }
  }
];

function secretInit() {
  if (sec) sec.timers.forEach(clearTimeout);
  const root = secRoot();
  if (!root) {
    sec = null;
    return;
  }
  const idx = +root.dataset.scene;
  sec = { idx, def: SECRETS[idx], timers: new Set(), stage: 0, next: Date.now() + 6000, input: null, seq: [], ready: secretReady(idx) };
  root.classList.toggle('resting', !sec.ready);
  $('world-scene')?.classList.toggle('calm', calmMotion());
  if (sec.ready) sec.def.start?.();
  else sec.def.rest?.();
  secretFit();
}

// On a short screen the cards under the coin hide the bottom of the world.
// The things that live down there move up a little (at most 40) to stay in view.
function secretFit() {
  const root = secRoot();
  const svg = root?.ownerSVGElement;
  const edge = document.querySelector('#screen-coin .coin-instruction');
  const m = svg?.getScreenCTM?.();
  if (!sec || !root || !edge || !m || !m.d) return;
  const y = (edge.getBoundingClientRect().top - m.f) / m.d;
  sec.lift = Math.round(Math.max(0, Math.min(40, 468 - y)));
  root.style.setProperty('--lift', `${sec.lift}px`);
}

function secretTick(now) {
  const root = secRoot();
  if (!sec || !root) return;
  root.classList.toggle('paused', !!(boss || fight));
  $('world-scene')?.classList.toggle('calm', calmMotion());
  if (boss || fight || isModalOpen() || !$('screen-coin')?.classList.contains('active')) return;
  const ready = secretReady(sec.idx);
  if (ready && !sec.ready) {
    root.classList.remove('resting');
    sec.ready = true;
    sec.def.start?.();
  }
  sec.ready = ready;
  if (!(now < sec.fitAt)) {
    sec.fitAt = now + 2000;
    secretFit();
  }
  sec.def.tick?.(now);
  obsidianTick(now);
}

function secretTap(el, pt) {
  const root = secRoot();
  if (!sec || !root || root.classList.contains('paused')) return;
  const spot = el.dataset.spot;
  if (spot === 'win') {
    el.classList.toggle('off');
    sfx('clack');
    return;
  }
  if (spot === 'string') {
    secReplay(el, 'sway');
    sfx('pop');
    return;
  }
  sec.def.tap?.(el, pt, spot);
}

// Where a tap lands in the scene's own 360 × 600 drawing.
function scenePoint(event) {
  const svg = document.querySelector('#world-scene .scene-play');
  const m = svg?.getScreenCTM?.();
  if (!m) return { x: 180, y: 300 };
  const p = new DOMPoint(event.clientX, event.clientY).matrixTransform(m.inverse());
  return { x: p.x, y: p.y };
}

function worldSceneHtml(number, info) {
  const index = (number - 1) % SCENES.length;
  const rand = seeded(1000 + index * 97);
  const { art, fx: own } = SCENES[index](info.hue, info.sat, rand);
  const fx = own + worldParticles(number);
  return `<svg class="scene-art" viewBox="0 0 360 600" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${art}</svg><div class="scene-fx">${fx}</div><svg class="scene-play" viewBox="0 0 360 600" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><g class="sec-root" data-scene="${index}">${SECRETS[index].art()}</g></svg>`;
}

// The world sets the colours around you; the coin level sets the coin's metal.
function applyTheme() {
  const info = world();
  const root = document.documentElement;
  root.dataset.effects = state.settings.effects;
  // 3.35: the world's skin sets every colour and material (185-world-skins.js).
  applySkin();
  const scene = $('world-scene');
  if (scene && scene.dataset.world !== String(state.world)) {
    scene.innerHTML = worldSceneHtml(state.world, info);
    scene.dataset.world = String(state.world);
    secretInit();
  }
  applyCoinLook();
  applyFun();
  const pip = $('stage-pip');
  if (pip && !pip.querySelector(`.pip-${outfitOf('pip')}`)) setHtml('stage-pip', pipSvg());
  updateBuddy();
  applyWorldEdge();
  root.style.setProperty('--world-texture', worldTexture(state.world));
  Ambience.sync();
}

function applyCoinLook() {
  const look = material(state.coinLevel);
  [$('coin-stage'), $('coin-card')].forEach(el => {
    if (!el) return;
    el.style.setProperty('--color-coin-light', look.light);
    el.style.setProperty('--color-coin-mid', look.mid);
    el.style.setProperty('--color-coin-dark', look.dark);
  });
  setText('level-badge', `LV ${format(state.coinLevel)}`);
}

function audioContext() {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return null;
    const fresh = !audio;
    audio = audio || new AudioCtx();
    if (fresh) setTimeout(() => Ambience.sync(), 50);
    if (audio.state === 'suspended' && !document.hidden && !appPaused) audio.resume();
    return audio;
  } catch (error) {
    return null;
  }
}

