function sfx(kind) {
  if (!state.settings.sound || !SOUNDS[kind]) return;
  if (DUCK_SOUNDS[kind] && funOn('funDuck')) {
    quack(DUCK_SOUNDS[kind]);
    return;
  }
  const ctx = audioContext();
  if (!ctx) return;
  try {
    let time = ctx.currentTime;
    for (const [frequency, duration, volume, type] of SOUNDS[kind]()) {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = type || 'triangle';
      osc.frequency.value = frequency;
      gain.gain.setValueAtTime(volume * SFX_GAIN * volume_('soundVol'), time);
      gain.gain.exponentialRampToValueAtTime(0.0001, time + duration);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(time);
      osc.stop(time + duration + 0.02);
      time += duration * 0.85;
    }
  } catch (error) {
    // Sound is a nice extra; the game works without it.
  }
}

/* --- Talking: letter by letter, in a voice --- */
// Motion kept low: Effects off, or the phone asks for less motion.
const calmMotion = () => state.settings.effects === 'off' || !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

// One blip of a voice: a short tone that drops a touch, like a syllable.
const BLIP_VOLUME = { square: 0.018, triangle: 0.034, sawtooth: 0.014, sine: 0.04 };
function talkBlip([pitch, wave]) {
  if (!state.settings.voices) return;
  const ctx = audioContext();
  if (!ctx) return;
  try {
    const now = ctx.currentTime;
    const f = pitch * (1 + (Math.random() - 0.5) * 0.12);
    const osc = ctx.createOscillator();
    const filter = ctx.createBiquadFilter();
    const gain = ctx.createGain();
    osc.type = wave;
    osc.frequency.setValueAtTime(f, now);
    osc.frequency.exponentialRampToValueAtTime(f * 0.88, now + 0.055);
    filter.type = 'lowpass';
    filter.frequency.value = pitch * 3;
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, (BLIP_VOLUME[wave] || 0.03) * SFX_GAIN * volume('voiceVol')), now + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.06);
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.07);
  } catch (error) {
    // Talking is a nice extra; the game works without it.
  }
}

// Writes a line into el, letter by letter, with a blip of the voice every
// few letters. The whole line is in the page from the start, so screen
// readers hear it once and nothing jumps about; the letters just show up
// one by one. Returns a handle: finish() shows the rest at once, stop()
// stops typing, done says whether it is all there.
function typeLine(el, text, voice, onDone, instant = false) {
  const esc = ch => (ch === '<' ? '&lt;' : ch === '>' ? '&gt;' : ch === '&' ? '&amp;' : ch);
  el.innerHTML = [...text].map(ch => (ch === ' ' ? ' ' : `<span class="ch">${esc(ch)}</span>`)).join('');
  el.classList.add('typing');
  el.classList.remove('typed');
  const letters = el.querySelectorAll('.ch');
  let i = 0;
  let timer = 0;
  let lastBlip = 0;
  const handle = { done: false };
  handle.stop = () => clearTimeout(timer);
  handle.finish = () => {
    clearTimeout(timer);
    el.classList.add('typed');
    if (handle.done) return;
    handle.done = true;
    if (onDone) onDone();
  };
  if (instant || calmMotion() || !letters.length) {
    if (voice) talkBlip(voice);
    handle.finish();
    return handle;
  }
  const step = () => {
    if (!el.isConnected) return;
    const letter = letters[i++];
    letter.classList.add('on');
    const ch = letter.textContent;
    const now = performance.now();
    if (voice && /[\p{L}\p{N}]/u.test(ch) && now - lastBlip > 58) {
      talkBlip(voice);
      lastBlip = now;
    }
    if (i >= letters.length) {
      handle.finish();
      return;
    }
    timer = setTimeout(step, /[.!?…]/.test(ch) ? 210 : /[,;:]/.test(ch) ? 110 : 30);
  };
  timer = setTimeout(step, 40);
  return handle;
}

// A helicopter made of filtered noise that thumps 15 times a second.
function chopper(seconds, loud) {
  if (!state.settings.sound) return null;
  const volume = Math.max(0.0002, loud * volume_('soundVol'));
  const ctx = audioContext();
  if (!ctx) return null;
  try {
    const rate = ctx.sampleRate;
    const length = Math.floor(rate * seconds);
    const buffer = ctx.createBuffer(1, length, rate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) {
      const t = i / rate;
      const thump = Math.exp(-((t * 15) % 1) * 7);
      data[i] = ((Math.random() * 2 - 1) * 0.8 + Math.sin(2 * Math.PI * 62 * t) * 0.6) * thump;
    }
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 700;
    const gain = ctx.createGain();
    const start = ctx.currentTime;
    const fade = Math.min(1.2, seconds / 3);
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(volume, start + fade);
    gain.gain.setValueAtTime(volume, start + seconds - fade);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + seconds);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(ctx.destination);
    source.start(start);
    source.stop(start + seconds + 0.05);
    return source;
  } catch (error) {
    return null;
  }
}

// Looping background music. Browsers only allow sound after the first
// touch, so it starts then. It stops while the app is in the background.
// Every world has a tune of its own, Coinbury has one for the day and one
// for the night, and fights have their own. A world's tune carries on where
// it was when you come back to it; fight music starts from the top.
const WORLD_MUSIC = ['meadow', 'harbor', 'oldtown', 'dunes', 'frost', 'ember', 'moon', 'starsea',
  'cave', 'mountain', 'tunnel', 'swamp', 'gate', 'square', 'castle', 'kingshall'];
const FIGHT_MUSIC = ['boss', 'ruler', 'final', 'critter'];
// Decoded music takes a lot of memory (about 10 MB a minute), so only the
// last few tunes are kept.
const MUSIC_KEEP = 3;

/* --- The chest's surprises (3.24) --- */
// What the three keys open: a jukebox and five silly extras, in the chest's window.
const funUnlocked = () => state.secrets.keys.length === SECRET_KEYS.length;
const funOn = key => !!state.settings[key] && funUnlocked();
const FUN_SWITCHES = [
  ['funEyes', tr('Googly eyes'), tr('Two wobbly eyes on the coin.')],
  ['funRainbow', tr('Rainbow coin'), tr('The coin glows in every color.')],
  ['funConfetti', tr('Confetti taps'), tr('Every tap throws confetti.')],
  ['funDuck', tr('Duck mode'), tr('Every tap quacks.')],
  ['funSnow', tr('Snow everywhere'), tr('Snow falls on every screen.')]
];

// The jukebox: any tune of the game, instead of the one that fits where you
// are. Fights keep their own music.
const JUKEBOX = [
  ...WORLD_MUSIC.map((id, k) => ({ id, group: 'worlds', name: () => (WORLDS[k] ? WORLDS[k].name : id) })),
  { id: 'cityday', group: 'city', name: () => T`${CITY.name} by day` },
  { id: 'citynight', group: 'city', name: () => T`${CITY.name} by night` },
  { id: 'critter', group: 'fights', name: () => tr('Critter fights') },
  { id: 'boss', group: 'fights', name: () => tr('Guard fights') },
  { id: 'ruler', group: 'fights', name: () => tr('Ruler fights') },
  { id: 'final', group: 'fights', name: () => tr('The last fight') }
];
const JUKEBOX_WAIT = 350;
let jukeboxTimer = 0;
let jukeboxBefore = '';
const jukeboxTune = () => (funUnlocked() && JUKEBOX.find(tune => tune.id === state.settings.jukebox)) || null;
// The tune the jukebox plays: while a pick settles, the one from before.
const jukeboxPlays = () => (jukeboxTimer ? jukeboxBefore : jukeboxTune() ? jukeboxTune().id : '');
const jukeboxName = () => (jukeboxTune() ? jukeboxTune().name() : tr('Automatic'));

function jukeboxHtml() {
  const pick = jukeboxTune() ? jukeboxTune().id : 'auto';
  const option = (id, name, wide = false) => `<button class="jukebox-option${pick === id ? ' active' : ''}${wide ? ' wide' : ''}" data-action="set-jukebox" data-id="${id}" role="radio" aria-checked="${pick === id}">${pick === id ? '<i aria-hidden="true">♪</i>' : ''}<span>${name}</span></button>`;
  const groups = [['worlds', tr('Worlds')], ['city', CITY.name], ['fights', tr('Fights')]];
  return `<div class="modal-icon gold">♪</div>
    <div class="eyebrow">${tr('THE CHEST')}</div>
    <h2 id="modal-title">${tr('Jukebox')}<span>${LANG && ['ja', 'zh'].includes(LANG.code) ? '。' : '.'}</span></h2>
    <p class="modal-copy">${tr('Pick a tune, and it plays instead of the usual music. Fights keep their own.')}</p>
    <div class="jukebox-list" role="radiogroup" aria-label="${tr('Jukebox')}">
      ${option('auto', `${tr('Automatic')}<small>${tr('The music follows where you are.')}</small>`, true)}
      ${groups.map(([group, title]) => `<h3 class="jukebox-head">${title}</h3>${JUKEBOX.filter(tune => tune.group === group).map(tune => option(tune.id, tune.name())).join('')}`).join('')}
    </div>
    ${state.settings.musicVol > 0 ? '' : `<p class="note">${tr('The music is turned off. Turn it up in Settings to hear the jukebox.')}</p>`}
    <div class="modal-actions"><button class="modal-action soft" data-action="open-chest">${tr('Back to the chest')}</button></div>`;
}

// The chest's window: the jukebox and the five extras, switched like the settings.
function onOffRow(key, label, note = '') {
  return `<div class="setting-row onoff-row"><span>${label}${note ? `<small>${note}</small>` : ''}</span>
      <div class="onoff" role="group" aria-label="${label}">
        <button data-action="set-option" data-key="${key}" data-value="1" class="${state.settings[key] ? 'active' : ''}" aria-pressed="${!!state.settings[key]}">${tr('ON')}</button>
        <button data-action="set-option" data-key="${key}" data-value="0" class="${state.settings[key] ? '' : 'active'}" aria-pressed="${!state.settings[key]}">${tr('OFF')}</button>
      </div></div>`;
}

function chestWindowHtml() {
  return `<div class="modal-icon gold chest-icon">${CHEST_ICON}</div>
    <div class="eyebrow">${tr('SETTINGS')}</div>
    <h2 id="modal-title">${tr('The chest')}<span>${LANG && ['ja', 'zh'].includes(LANG.code) ? '。' : '.'}</span></h2>
    <p class="modal-copy">${tr('All three keys fit! Inside: a jukebox and five silly surprises.')}</p>
    <div class="setting-row jukebox-row"><span>${tr('Jukebox')}</span><button class="setting-pick" data-action="open-jukebox">${jukeboxName()}<span aria-hidden="true">›</span></button></div>
    ${FUN_SWITCHES.map(([key, label, note]) => onOffRow(key, label, note)).join('')}
    <p class="note">${tr('Confetti, snow and the wobbly eyes follow your Effects setting.')}</p>
    <div class="modal-actions">${tr('<button class="modal-action soft" data-action="back-to-settings">Back to settings</button>')}</div>`;
}

// The music is muffled away from the coin and the city and while Pip talks,
// but not while you pick a tune in the jukebox.
function musicMuffleNow() {
  Music.muffle(modalType !== 'jukebox' && ((currentScreen !== 'coin' && currentScreen !== 'city') || !!inDialogue));
}

// Switches the extras on and off to match the settings.
function applyFun() {
  const root = document.documentElement;
  root.classList.toggle('fun-rainbow', funOn('funRainbow'));
  root.classList.toggle('fun-eyes', funOn('funEyes'));
  Googly.toggle(funOn('funEyes'));
  Snow.toggle(funOn('funSnow') && !calmMotion() ? (effectsAll() ? 28 : 14) : 0);
}

// Googly eyes on the coin. The pupils roll about loose: they fall to the
// bottom, and every tap sends them bouncing around.
const Googly = {
  eyes: [],
  raf: 0,
  last: 0,
  toggle(on) {
    const face = document.querySelector('#coin-button .coin-inner');
    const have = face ? face.querySelector('.googly') : null;
    if (!face || on === !!have) return;
    cancelAnimationFrame(this.raf);
    this.raf = 0;
    this.eyes = [];
    if (!on) {
      have.remove();
      return;
    }
    const el = document.createElement('span');
    el.className = 'googly';
    el.setAttribute('aria-hidden', 'true');
    el.innerHTML = '<i><b></b></i><i><b></b></i>';
    face.appendChild(el);
    // At rest, the stylesheet keeps the pupils at the bottom.
    this.eyes = [...el.querySelectorAll('b')].map(pupil => ({ pupil, x: 0, y: 0, vx: 0, vy: 0, room: 0, still: true }));
  },
  // How far a pupil can roll from the middle: the eye's radius less its own.
  measure(eye) {
    eye.room = Math.max(2, (eye.pupil.parentElement.clientWidth - eye.pupil.offsetWidth) / 2);
    if (eye.still) {
      eye.x = 0;
      eye.y = eye.room;
    }
  },
  shake(power = 1) {
    if (!this.eyes.length || calmMotion()) return;
    for (const eye of this.eyes) {
      this.measure(eye);
      eye.still = false;
      const angle = Math.random() * Math.PI * 2;
      const kick = eye.room * (24 + Math.random() * 26) * power;
      eye.vx += Math.cos(angle) * kick;
      eye.vy += Math.sin(angle) * kick - eye.room * 14 * power;
    }
    if (!this.raf) {
      this.last = performance.now();
      this.raf = requestAnimationFrame(now => this.step(now));
    }
  },
  step(now) {
    const dt = Math.min(0.034, Math.max(0.001, (now - this.last) / 1000));
    this.last = now;
    let moving = false;
    for (const eye of this.eyes) {
      const room = eye.room;
      eye.vy += room * 150 * dt;
      eye.x += eye.vx * dt;
      eye.y += eye.vy * dt;
      const d = Math.hypot(eye.x, eye.y);
      if (d > room) {
        // The rim: a hard knock bounces back, a soft one just rolls along it.
        const nx = eye.x / d;
        const ny = eye.y / d;
        eye.x = nx * room;
        eye.y = ny * room;
        const out = eye.vx * nx + eye.vy * ny;
        if (out > 0) {
          const back = out > room * 4 ? 1.55 : 1;
          eye.vx -= back * out * nx;
          eye.vy -= back * out * ny;
        }
        eye.vx *= 0.95;
        eye.vy *= 0.95;
      }
      if (Math.hypot(eye.vx, eye.vy) > room * 0.5 || eye.y < room * 0.98) moving = true;
      else eye.still = true;
      eye.pupil.style.transform = `translate(${eye.x.toFixed(1)}px, ${eye.y.toFixed(1)}px)`;
    }
    this.raf = moving && this.eyes.length ? requestAnimationFrame(next => this.step(next)) : 0;
  }
};

// Snow over every screen: flakes in a layer of their own that taps go through.
const Snow = {
  count: 0,
  toggle(count) {
    if (count === this.count && !!count === !!$('snow-layer')) return;
    this.count = count;
    const old = $('snow-layer');
    if (old) old.remove();
    if (!count) return;
    const rand = seeded(324);
    const layer = document.createElement('div');
    layer.className = 'snow-layer';
    layer.id = 'snow-layer';
    layer.setAttribute('aria-hidden', 'true');
    let html = '';
    for (let k = 0; k < count; k++) {
      const fall = 8 + rand() * 9;
      const size = (2.5 + rand() * 4.5).toFixed(1);
      html += `<i style="left: ${(rand() * 100).toFixed(1)}%; --fall: ${fall.toFixed(1)}s; --late: -${(rand() * fall).toFixed(1)}s; --sway: ${Math.round(6 + rand() * 16)}px; --swing: ${(2 + rand() * 2.5).toFixed(1)}s"><b style="width: ${size}px; height: ${size}px; opacity: ${(0.5 + rand() * 0.45).toFixed(2)}"></b></i>`;
    }
    layer.innerHTML = html;
    document.body.appendChild(layer);
  }
};

// Confetti from every tap, in a layer of its own so it never crowds out the numbers.
const CONFETTI = ['#ff5d5d', '#ffb02e', '#ffe45c', '#45c66b', '#3fa2ff', '#a874ff', '#ff79c6'];
function spawnConfetti(x, y) {
  if (!funOn('funConfetti') || calmMotion()) return;
  const stage = $('coin-stage');
  if (!stage) return;
  let layer = $('confetti-layer');
  if (!layer) {
    layer = document.createElement('div');
    layer.className = 'confetti-layer';
    layer.id = 'confetti-layer';
    layer.setAttribute('aria-hidden', 'true');
    stage.appendChild(layer);
  }
  const count = effectsAll() ? 7 : 3;
  for (let k = 0; k < count && layer.childElementCount < 50; k++) {
    const bit = document.createElement('i');
    bit.className = `confetti${Math.random() < 0.3 ? ' round' : ''}`;
    bit.style.left = `${x}px`;
    bit.style.top = `${y}px`;
    bit.style.background = CONFETTI[Math.floor(Math.random() * CONFETTI.length)];
    bit.style.setProperty('--dx', `${Math.round(Math.random() * 170 - 85)}px`);
    bit.style.setProperty('--up', `${Math.round(-35 - Math.random() * 75)}px`);
    bit.style.setProperty('--down', `${Math.round(50 + Math.random() * 90)}px`);
    bit.style.setProperty('--spin', `${Math.round(Math.random() * 900 - 450)}deg`);
    layer.appendChild(bit);
    setTimeout(() => bit.remove(), 1100);
  }
}

// Duck mode: taps and hits quack, lucky ones twice. A quack is a buzzy tone
// that drops in pitch, shaped by two filters like a beak.
const DUCK_SOUNDS = { tap: 1, hit: 1, squish: 1, lucky: 2 };
function quack(times = 1) {
  const ctx = audioContext();
  if (!ctx) return;
  try {
    for (let k = 0; k < times; k++) {
      const start = ctx.currentTime + k * 0.12;
      const pitch = (k ? 620 : 520) * (1 + (Math.random() - 0.5) * 0.14);
      const osc = ctx.createOscillator();
      const low = ctx.createBiquadFilter();
      const high = ctx.createBiquadFilter();
      const gain = ctx.createGain();
      const level = Math.max(0.0002, 0.055 * SFX_GAIN * volume_('soundVol'));
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(pitch, start);
      osc.frequency.linearRampToValueAtTime(pitch * 1.1, start + 0.03);
      osc.frequency.exponentialRampToValueAtTime(pitch * 0.7, start + 0.15);
      low.type = 'bandpass';
      low.frequency.value = 1100;
      low.Q.value = 3;
      high.type = 'bandpass';
      high.frequency.value = 2500;
      high.Q.value = 5;
      gain.gain.setValueAtTime(0.0001, start);
      gain.gain.exponentialRampToValueAtTime(level, start + 0.015);
      gain.gain.setValueAtTime(level, start + 0.08);
      gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.16);
      osc.connect(low);
      osc.connect(high);
      low.connect(gain);
      high.connect(gain);
      gain.connect(ctx.destination);
      osc.start(start);
      osc.stop(start + 0.18);
    }
  } catch (error) {
    // Quacking is a nice extra; the game works without it.
  }
}

// A tap with the extras on: confetti, a jiggle for the eyes, and a quack on a lucky one.
/* --- The lock on the chest (3.24) --- */
// A rounded triangle in three parts, one keyhole for each key. The parts are
// the same shape turned a third of a turn each: drawn here is the bottom one,
// its hole pointing down. A turn of the lock that brings a key's hole to the
// bottom (counterclockwise is negative, the way the lock turns):
const LOCK_KEYS = ['red', 'blue', 'green'];
const LOCK_HOLE = { red: 120, blue: 240, green: 0 };
const LOCK_TURN = { red: -120, blue: -240, green: 0 };
const LOCK_SECTOR = 'M0 0 L38.1 22 A76.2 76.2 0 0 1 -38.1 22 Z';
const LOCK_KEYHOLE = 'M-2.6 18.4 L-3.8 28 H3.8 L2.6 18.4 A6 6 0 1 0 -2.6 18.4 Z';
const LOCK_FX = { start: 450, turn: 520, fly: 460, twist: 240, pause: 160 };
let lockBusy = null;

// The keys go in with motion only where the phone can show it.
const lockMotion = () => !calmMotion() && typeof requestAnimationFrame === 'function'
  && typeof Element !== 'undefined' && typeof Element.prototype.animate === 'function';
const lockWait = ms => new Promise(done => setTimeout(done, ms));
// The lock's turn at rest: the next empty hole at the bottom.
const lockAngle = slots => LOCK_TURN[LOCK_KEYS.find(id => !slots.includes(id)) || 'green'];
// From `from`, the nearest turn counterclockwise that brings `id`'s hole down.
const lockTowards = (from, id) => from - ((((from - LOCK_TURN[id]) % 360) + 360) % 360);

function lockKeyHtml(id, turned) {
  const key = SECRET_KEYS.find(k => k.id === id);
  const pose = turned ? 'transform="rotate(90 0 13)"' : 'transform="translate(0 13) scale(3.4) translate(0 -13)" opacity="0"';
  return `<g class="lock-key" style="--key:${key.color}" ${pose}><ellipse class="bow" cx="0" cy="13" rx="4.8" ry="8.6"/><ellipse class="shine" cx="-1.7" cy="9.6" rx="1.2" ry="2.6"/><circle class="eye" cx="0" cy="7.6" r="1.4"/></g>`;
}

function lockHtml() {
  const store = state.secrets;
  const open = store.opened && funUnlocked();
  const parts = LOCK_KEYS.map(id => `<g class="lock-part" data-key="${id}" transform="rotate(${LOCK_HOLE[id]})"><g class="lock-slide">`
    + `<path class="lock-sector" d="${LOCK_SECTOR}"/><path class="lock-hole" d="${LOCK_KEYHOLE}"/>`
    + `<circle class="lock-dot" cx="11.5" cy="24" r="2.8" fill="${SECRET_KEYS.find(k => k.id === id).color}"/>`
    + `${store.slots.includes(id) ? lockKeyHtml(id, true) : ''}</g></g>`).join('');
  return `<button class="lock${open ? ' open' : ''}" data-action="lock" aria-label="${open ? tr('The chest') : tr('Locked chest')}">`
    + `<svg class="lock-art" viewBox="-50 -56 100 100" aria-hidden="true"><defs>`
    + '<linearGradient id="lock-metal" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f8da7c"/><stop offset="0.55" stop-color="#dca843"/><stop offset="1" stop-color="#a7741d"/></linearGradient>'
    + '<radialGradient id="lock-shine"><stop offset="0" stop-color="#fffbe0"/><stop offset="0.45" stop-color="#ffd768" stop-opacity="0.9"/><stop offset="1" stop-color="#ffb02e" stop-opacity="0"/></radialGradient>'
    + `</defs><circle class="lock-glow" r="19"/><g class="lock-turn" transform="rotate(${lockAngle(store.slots)})">${parts}</g></svg></button>`;
}

// Opening Settings: the keys found since last time go in, one by one.
function lockPlay() {
  const store = state.secrets;
  const fresh = LOCK_KEYS.filter(id => store.keys.includes(id) && !store.slots.includes(id));
  if (!fresh.length && (store.opened || !funUnlocked())) return;
  if (!lockMotion()) {
    lockSettle();
    return;
  }
  const button = document.querySelector('#modal-content .lock');
  if (!button || lockBusy === button) return;
  lockBusy = button;
  lockRun(button, fresh).finally(() => {
    if (lockBusy === button) lockBusy = null;
  });
}

// Without motion: every key in its hole at once, and the lock open if all are.
function lockSettle() {
  const store = state.secrets;
  store.slots = LOCK_KEYS.filter(id => store.keys.includes(id));
  if (funUnlocked()) store.opened = true;
  save();
  const button = document.querySelector('#modal-content .lock');
  if (button) button.outerHTML = lockHtml();
}

function lockTween(ms, step) {
  return new Promise(done => {
    const t0 = performance.now();
    const frame = now => {
      const k = Math.min(1, (now - t0) / ms);
      step(k);
      if (k < 1) requestAnimationFrame(frame);
      else done();
    };
    requestAnimationFrame(frame);
  });
}

function lockTurnTo(turn, from, to) {
  return lockTween(LOCK_FX.turn, k => {
    const e = k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
    turn.setAttribute('transform', `rotate(${(from + (to - from) * e).toFixed(2)})`);
  });
}

async function lockRun(button, fresh) {
  const store = state.secrets;
  const alive = () => button.isConnected && modalType === 'settings';
  const turn = button.querySelector('.lock-turn');
  let angle = lockAngle(store.slots);
  await lockWait(LOCK_FX.start);
  for (const id of fresh) {
    if (!alive()) return;
    const target = lockTowards(angle, id);
    if (target !== angle) {
      await lockTurnTo(turn, angle, target);
      angle = target;
      if (!alive()) return;
      lockThud(0.3);
    }
    // The key comes in from our side of the screen: big and faint, then small and solid in its hole…
    const slide = button.querySelector(`.lock-part[data-key="${id}"] .lock-slide`);
    slide.insertAdjacentHTML('beforeend', lockKeyHtml(id, false));
    const key = slide.lastElementChild;
    await lockTween(LOCK_FX.fly, k => {
      key.setAttribute('transform', `translate(0 13) scale(${(1 + 2.4 * (1 - k) * (1 - k)).toFixed(3)}) translate(0 -13)`);
      key.style.opacity = String(Math.min(1, k * 1.6));
    });
    if (!alive()) return;
    // …and turns, with a click.
    sfx('clack');
    await lockTween(LOCK_FX.twist, k => key.setAttribute('transform', `rotate(${(90 * (1 - (1 - k) * (1 - k))).toFixed(1)} 0 13)`));
    if (!alive()) return;
    sfx('clack');
    buzz(12, 'tap');
    if (!store.slots.includes(id)) store.slots.push(id);
    save();
    await lockWait(LOCK_FX.pause);
  }
  if (!alive()) return;
  if (funUnlocked()) {
    lockOpen(button);
    return;
  }
  const next = LOCK_KEYS.find(id => !store.slots.includes(id));
  const target = lockTowards(angle, next);
  if (target === angle) return;
  await lockTurnTo(turn, angle, target);
  if (alive()) lockThud(0.3);
}

// All three in: the parts slide apart and it shines from inside.
function lockOpen(button) {
  state.secrets.opened = true;
  save();
  button.classList.add('open');
  button.setAttribute('aria-label', tr('The chest'));
  lockThud(0.8);
  setTimeout(() => sfx('loot'), 140);
  buzz([20, 40, 30]);
  for (let k = 0; k < 8; k++) {
    const spark = document.createElement('i');
    spark.className = 'lock-spark';
    spark.textContent = k % 2 ? '✦' : '✧';
    spark.style.setProperty('--a', `${k * 45 + 20}deg`);
    button.appendChild(spark);
    setTimeout(() => spark.remove(), 1000);
  }
}

// A tap on the lock before it is open: a heavy wooden knock, and it shakes.
function lockKnock() {
  lockThud(1);
  buzz(30);
  const button = document.querySelector('#modal-content .lock');
  if (!button || calmMotion()) return;
  button.classList.remove('knock');
  void button.offsetWidth;
  button.classList.add('knock');
}

// A heavy, wooden knock: a low thump and a short burst of noise through a woody band.
function lockThud(power = 1) {
  if (!state.settings.sound) return;
  const ctx = audioContext();
  if (!ctx) return;
  try {
    const now = ctx.currentTime;
    const level = Math.max(0.0002, 0.1 * power * SFX_GAIN * volume_('soundVol'));
    const osc = ctx.createOscillator();
    const body = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(190, now);
    osc.frequency.exponentialRampToValueAtTime(85, now + 0.18);
    body.gain.setValueAtTime(0.0001, now);
    body.gain.exponentialRampToValueAtTime(level, now + 0.006);
    body.gain.exponentialRampToValueAtTime(0.0001, now + 0.3);
    osc.connect(body);
    body.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.32);
    const length = Math.floor(ctx.sampleRate * 0.09);
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (length / 6));
    const noise = ctx.createBufferSource();
    const band = ctx.createBiquadFilter();
    const knock = ctx.createGain();
    noise.buffer = buffer;
    band.type = 'bandpass';
    band.frequency.value = 480;
    band.Q.value = 1.6;
    knock.gain.value = level * 1.5;
    noise.connect(band);
    band.connect(knock);
    knock.connect(ctx.destination);
    noise.start(now);
  } catch (error) {
    // The knock is a nice extra; the game works without it.
  }
}

function funTap(x, y, lucky) {
  if (!funUnlocked()) return;
  spawnConfetti(x, y);
  if (!boss && funOn('funEyes')) Googly.shake(lucky ? 1.5 : 1);
  if (lucky && funOn('funDuck')) spawnWord(x, y - 34, tr('Quack!'), 'quack');
}


// The tune for what is on the screen right now.
function musicFor() {
  if (boss) {
    if (boss.rank < 2) return 'boss';
    return homeWorld(boss.number) === WORLDS.length ? 'final' : 'ruler';
  }
  if (fight) return 'critter';
  if (jukeboxPlays()) return jukeboxPlays();
  if (currentScreen === 'city') return isNight() ? 'citynight' : 'cityday';
  return WORLD_MUSIC[homeWorld() - 1] || WORLD_MUSIC[0];
}

const Music = {
  volume: { boss: 0.3, ruler: 0.3, final: 0.3, critter: 0.29 },
  filter: null,
  bus: null,
  muffled: false,
  // All the tunes go out through one filter and one volume.
  out(ctx) {
    if (!this.filter) {
      this.filter = ctx.createBiquadFilter();
      this.filter.type = 'lowpass';
      this.filter.Q.value = 0.7;
      this.bus = ctx.createGain();
      this.filter.connect(this.bus);
      this.bus.connect(ctx.destination);
      this.muffle(this.muffled, true);
    }
    return this.filter;
  },
  muffle(on, now = false) {
    this.muffled = on;
    if (!this.filter) return;
    const t = this.filter.context.currentTime;
    const k = now ? 0.001 : 0.15;
    this.filter.frequency.setTargetAtTime(on ? 800 : 20000, t, k);
    this.bus.gain.setTargetAtTime(on ? 0.7 : 1, t, k);
  },
  buffers: {},
  loading: {},
  used: {},
  spots: {},
  source: null,
  gain: null,
  playing: '',
  wanted: '',
  started: false,
  startedAt: 0,
  offset: 0,

  file(name) {
    return `music/${name}.${this.extension()}`;
  },

  level(name) {
    return (this.volume[name] || 0.28) * volume('musicVol');
  },

  // The music slider moved: the tune that plays follows at once.
  setLevel() {
    this.refresh();
    if (!this.gain || !audio || !this.playing) return;
    try {
      this.gain.gain.cancelScheduledValues(audio.currentTime);
      this.gain.gain.setTargetAtTime(Math.max(0.0001, this.level(this.playing)), audio.currentTime, 0.05);
    } catch (error) {
      // It catches up with the next tune.
    }
  },

  extension() {
    try {
      return document.createElement('audio').canPlayType('audio/ogg; codecs="vorbis"') ? 'ogg' : 'mp3';
    } catch (error) {
      return 'mp3';
    }
  },

  allowed() {
    return this.started && state.settings.music && !document.hidden && !appPaused;
  },

  start() {
    if (this.started) return;
    this.started = true;
    this.wanted = musicFor();
    this.refresh();
  },

  play(name) {
    this.wanted = name;
    this.used[name] = Date.now();
    this.refresh();
  },

  // Switches to the tune that fits, if it is not the one already wanted.
  follow() {
    const name = musicFor();
    if (name !== this.wanted) this.play(name);
  },

  // Lets go of the tunes not heard for a while.
  forget() {
    Object.keys(this.buffers)
      .sort((a, b) => (this.used[b] || 0) - (this.used[a] || 0))
      .slice(MUSIC_KEEP)
      .forEach(name => {
        if (name === this.playing || name === this.wanted) return;
        delete this.buffers[name];
        this.loading[name] = null;
      });
  },

  load(name) {
    if (this.buffers[name]) return Promise.resolve(this.buffers[name]);
    if (!this.loading[name]) {
      const ctx = audioContext();
      if (!ctx || typeof fetch !== 'function') return Promise.resolve(null);
      this.loading[name] = fetch(this.file(name))
        .then(response => {
          if (!response.ok) throw new Error(`HTTP ${response.status}`);
          return response.arrayBuffer();
        })
        .then(data => new Promise((resolve, reject) => ctx.decodeAudioData(data, resolve, reject)))
        .then(buffer => {
          this.buffers[name] = buffer;
          this.forget();
          return buffer;
        })
        .catch(error => {
          console.warn('Music could not load.', error);
          this.loading[name] = null;
          return null;
        });
    }
    return this.loading[name];
  },

  async refresh() {
    if (!this.allowed()) {
      this.stop(true);
      return;
    }
    const name = this.wanted;
    if (this.playing === name && this.source) return;
    const buffer = await this.load(name);
    if (!buffer || name !== this.wanted || !this.allowed() || (this.playing === name && this.source)) return;
    this.stop(true);
    const ctx = audioContext();
    if (!ctx) return;
    try {
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.loop = true;
      const gain = ctx.createGain();
      gain.gain.setValueAtTime(0.0001, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(this.level(name), ctx.currentTime + 1.5);
      source.connect(gain);
      gain.connect(this.out(ctx));
      const offset = FIGHT_MUSIC.includes(name) ? 0 : (this.spots[name] || 0) % buffer.duration;
      source.start(0, offset);
      this.source = source;
      this.gain = gain;
      this.playing = name;
      this.startedAt = ctx.currentTime;
      this.offset = offset;
      this.used[name] = Date.now();
    } catch (error) {
      console.warn('Music could not play.', error);
    }
  },

  stop(fade) {
    if (!this.source) return;
    // Remember where the tune was, to carry on from there next time.
    try {
      const length = this.source.buffer && this.source.buffer.duration;
      if (length && audio) this.spots[this.playing] = (this.offset + audio.currentTime - this.startedAt) % length;
    } catch (error) {
      // It starts from the top next time.
    }
    const { source, gain } = this;
    this.source = null;
    this.gain = null;
    this.playing = '';
    try {
      if (fade && audio) {
        const now = audio.currentTime;
        gain.gain.cancelScheduledValues(now);
        gain.gain.setValueAtTime(Math.max(0.0001, gain.gain.value), now);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.6);
        source.stop(now + 0.65);
      } else {
        source.stop();
      }
    } catch (error) {
      // Already stopped.
    }
  },

  // The app went to the background: freeze all sound where it is.
  suspend() {
    try {
      if (audio && audio.state === 'running') audio.suspend();
    } catch (error) {
      // Nothing to pause.
    }
  },

  // Back again: carry on from the same spot.
  wake() {
    if (document.hidden || appPaused) return;
    try {
      if (audio && audio.state === 'suspended') audio.resume();
    } catch (error) {
      // Sound stays off.
    }
    this.refresh();
  }
};

// The "helicopter helicopter" voice. It loads after the first touch,
// so it plays right away when you catch the helicopter.
const Voice = {
  buffer: null,
  loading: null,

  file() {
    const name = APP_CONFIG.helicopterVoice;
    if (!name) return '';
    return /\.[a-z0-9]+$/i.test(name) ? name : `${name}.${Music.extension()}`;
  },

  load() {
    if (this.buffer) return Promise.resolve(this.buffer);
    const file = this.file();
    const ctx = audioContext();
    if (!file || !ctx || typeof fetch !== 'function') return Promise.resolve(null);
    if (!this.loading) {
      this.loading = fetch(file)
        .then(response => {
          if (!response.ok) throw new Error(`HTTP ${response.status}`);
          return response.arrayBuffer();
        })
        .then(data => new Promise((resolve, reject) => ctx.decodeAudioData(data, resolve, reject)))
        .then(buffer => {
          this.buffer = buffer;
          return buffer;
        })
        .catch(error => {
          console.warn('The helicopter voice could not load.', error);
          this.loading = null;
          return null;
        });
    }
    return this.loading;
  },

  // Resolves to true when the voice played.
  async play() {
    if (!state.settings.sound || !this.file()) return false;
    const buffer = await this.load();
    const ctx = audioContext();
    if (!buffer || !ctx) return false;
    try {
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      const gain = ctx.createGain();
      gain.gain.value = 0.9 * volume('soundVol');
      source.connect(gain);
      gain.connect(ctx.destination);
      source.start();
      return true;
    } catch (error) {
      return false;
    }
  }
};

function buzz(ms, kind = '') {
  if (!state.settings.vibrate || (kind === 'tap' && !state.settings.tapBuzz) || typeof navigator.vibrate !== 'function') return;
  try {
    navigator.vibrate(ms);
  } catch (error) {
    // Vibration is optional.
  }
}

function playDemoAd() {
  return new Promise(resolve => {
    const overlay = $('ad-overlay');
    const total = 3000;
    const started = Date.now();
    overlay.classList.remove('hidden');
    const timer = setInterval(() => {
      const elapsed = Date.now() - started;
      $('ad-count').textContent = String(Math.max(1, Math.ceil((total - elapsed) / 1000)));
      $('ad-bar').style.width = `${Math.min(100, (elapsed / total) * 100)}%`;
      if (elapsed >= total) {
        clearInterval(timer);
        overlay.classList.add('hidden');
        $('ad-bar').style.width = '0';
        resolve(true);
      }
    }, 100);
  });
}

/* -----------------------------------------------------------------
   9. SURPRISES
   ----------------------------------------------------------------- */

/* --- Golden coins --- */
function nextGoldenDelay() {
  const speed = (1 + 0.1 * state.upgradeLevels[U.MAGNET]) * (1 + itemBonus('golden'));
  return ((90 + Math.random() * 120) * 1000) / speed;
}

function spawnGolden(now) {
  const el = document.createElement('button');
  el.className = 'golden-coin';
  el.textContent = '✦';
  el.setAttribute('aria-label', tr('Golden coin! Tap it for a bonus'));
  el.style.left = `${14 + Math.random() * 72}%`;
  el.style.top = `${16 + Math.random() * 56}%`;
  el.addEventListener('pointerdown', event => {
    event.preventDefault();
    event.stopPropagation();
    catchGolden();
  });
  el.addEventListener('click', event => {
    if (event.detail === 0) catchGolden();
  });
  $('golden-layer').appendChild(el);
  golden = { el, until: now + GOLDEN_LIFETIME };
}

function removeGolden() {
  if (golden) {
    const el = golden.el;
    golden = null;
    el.classList.add('leaving');
    setTimeout(() => el.remove(), 400);
  }
  goldenAt = Date.now() + nextGoldenDelay();
}

// Some bonuses only make sense at the right moment.
function goldenBonusOk(id) {
  if (id === 'mania') return baseIncome() > 0;
  if (id === 'shower') return !rain && !boss && currentScreen === 'coin';
  if (id === 'monster') return !monster && !fight && !boss && currentScreen === 'coin';
  return true;
}

/* --- Helping hands (3.21) --- */
// While Helping Hands lasts, four white gloves ring the coin and tap along.
// They fly in from the golden coin that brought them and fly off when it ends.
const HAND_SPOTS = [-135, -45, 45, 135];
let handsOn = false;

const handSvg = () => `<svg viewBox="0 0 40 46" aria-hidden="true"><path d="M10 40 C5 33 5 25 8 21 L8 13 C8 9.5 13 9.5 13 13 L13 19 L14 8 C14 4.5 19 4.5 19 8 L19 18 L20 6 C20 2.5 25 2.5 25 6 L25 18 L26 10 C26 6.5 31 6.5 31 10 L31 28 C31 35 27 40 21 40 Z" fill="#fff" stroke="#2b2236" stroke-width="2.4" stroke-linejoin="round"/><rect x="9" y="39" width="20" height="6" rx="2.5" fill="#fff" stroke="#2b2236" stroke-width="2.4"/><path d="M13 19 V25 M19 18 V24 M25 18 V24" stroke="#2b2236" stroke-width="1.6" stroke-linecap="round" opacity=".45"/></svg>`;

function handsLayer() {
  let layer = $('hands-layer');
  const stage = $('coin-stage');
  if (!layer && stage) {
    layer = document.createElement('div');
    layer.id = 'hands-layer';
    layer.className = 'hands-layer';
    layer.setAttribute('aria-hidden', 'true');
    stage.appendChild(layer);
  }
  return layer;
}

// `from`: where on the screen the golden coin was, or null to just appear.
function handsShow(from) {
  const layer = handsLayer();
  const coin = $('coin-button');
  if (!layer || !coin) return;
  const s = $('coin-stage').getBoundingClientRect();
  const c = coin.getBoundingClientRect();
  const cx = c.left - s.left + c.width / 2;
  const cy = c.top - s.top + c.height / 2;
  const r = c.width / 2 + 14;
  layer.innerHTML = '';
  HAND_SPOTS.forEach((deg, k) => {
    const a = (deg * Math.PI) / 180;
    const hand = document.createElement('div');
    hand.className = `hand${from ? ' fly' : ''}`;
    hand.style.setProperty('--x', `${(cx + Math.cos(a) * r).toFixed(1)}px`);
    hand.style.setProperty('--y', `${(cy + Math.sin(a) * r).toFixed(1)}px`);
    hand.style.setProperty('--r', `${deg - 90}deg`);
    hand.style.setProperty('--d', `${(k * 0.11).toFixed(2)}s`);
    if (from) {
      hand.style.setProperty('--fx', `${(from.x - s.left).toFixed(1)}px`);
      hand.style.setProperty('--fy', `${(from.y - s.top).toFixed(1)}px`);
    }
    hand.innerHTML = `<i>${handSvg()}</i>`;
    layer.appendChild(hand);
  });
  handsOn = true;
  if (from) {
    layer.getBoundingClientRect();
    layer.querySelectorAll('.hand').forEach(hand => hand.classList.remove('fly'));
  }
}

// Off they go, each straight away from the coin.
function handsGo() {
  const layer = $('hands-layer');
  handsOn = false;
  if (!layer) return;
  layer.querySelectorAll('.hand').forEach((hand, k) => {
    const a = (HAND_SPOTS[k % HAND_SPOTS.length] * Math.PI) / 180;
    const x = parseFloat(hand.style.getPropertyValue('--x')) + Math.cos(a) * 520;
    const y = parseFloat(hand.style.getPropertyValue('--y')) + Math.sin(a) * 520;
    hand.style.setProperty('--x', `${x.toFixed(1)}px`);
    hand.style.setProperty('--y', `${y.toFixed(1)}px`);
    hand.classList.add('leave');
  });
  setTimeout(() => {
    if (!handsOn && layer) layer.innerHTML = '';
  }, 1100);
}

function handsTick(now) {
  const on = state.handsUntil > now;
  if (on && !handsOn) handsShow(null);
  else if (!on && handsOn) handsGo();
}

/* --- The ShameSauce logo at the start (3.21) --- */
// It fades in, "Shame" shakes and "Sauce" drips, then it fades out into the
// game; a tap skips it. Browsers driven by tests skip it at once.
const SPLASH = { ms: 2100, calm: 1100, fade: 500 };
let splashDone = Promise.resolve();

function splashRun() {
  const el = $('splash');
  if (!el) return;
  if (navigator.webdriver) {
    el.remove();
    return;
  }
  const calm = calmMotion();
  el.classList.toggle('calm', calm);
  splashDone = new Promise(resolve => {
    let gone = false;
    const leave = () => {
      if (gone) return;
      gone = true;
      el.classList.add('out');
      setTimeout(() => {
        el.remove();
        resolve();
      }, SPLASH.fade);
    };
    el.addEventListener('pointerdown', leave);
    setTimeout(leave, calm ? SPLASH.calm : SPLASH.ms);
  });
}

function catchGolden() {
  if (!golden) return;
  const spot = golden.el.getBoundingClientRect();
  removeGolden();
  state.stats.golden++;
  questProgress('golden');
  const bonus = weightedPick(GOLDEN_BONUSES.filter(option => goldenBonusOk(option.id)), option => option.weight);
  if (!state.goldenKinds.includes(bonus.id)) state.goldenKinds.push(bonus.id);
  const now = Date.now();
  let line;
  if (bonus.id === 'diamonds') {
    state.diamonds += 3;
    line = '+3 ◆';
  } else if (bonus.id === 'frenzy') {
    state.frenzyUntil = now + frenzySeconds() * 1000;
    line = T`${FRENZY.power}× tap power for ${frenzySeconds()} seconds`;
  } else if (bonus.id === 'surge') {
    state.surgeUntil = now + bonusSeconds(SURGE.seconds) * 1000;
    line = T`${SURGE.power}× tap power for ${bonusSeconds(SURGE.seconds)} seconds`;
  } else if (bonus.id === 'hands') {
    state.handsUntil = now + bonusSeconds(HANDS.seconds) * 1000;
    handsShow({ x: spot.left + spot.width / 2, y: spot.top + spot.height / 2 });
    line = T`${HANDS.taps} free taps a second for ${bonusSeconds(HANDS.seconds)} seconds`;
  } else if (bonus.id === 'mania') {
    state.maniaUntil = now + bonusSeconds(MANIA.seconds) * 1000;
    line = T`${MANIA.power}× machine income for ${bonusSeconds(MANIA.seconds)} seconds`;
  } else if (bonus.id === 'shower') {
    startRain(now, true);
    line = tr('Catch the falling coins!');
  } else if (bonus.id === 'monster') {
    spawnMonster(0.25);
    line = tr('A critter is coming. Catch it!');
  } else {
    const amount = Math.max(clickPower() * 40, baseIncome() * 300);
    earn(amount);
    line = T`+${format(amount)} coins`;
  }
  if (frenzyRemaining() > 0 && surgeRemaining() > 0) unlock('double');
  showBonusBanner(tr('GOLDEN COIN'), bonus.name, line, 'gold');
  pipAct('cheer', true);
  sfx('golden');
  buzz(30);
  save();
  refresh();
}

function goldenTick(now) {
  if (golden) {
    if (now > golden.until) removeGolden();
    return;
  }
  if (now >= goldenAt && !isModalOpen() && !boss) spawnGolden(now);
}

/* --- Coin rain (World 3 and later) --- */
function rainTick(now) {
  if (rain) {
    if (now > rain.until) {
      if (rain.caught) notify(T`The rain stopped. You caught ${rain.caught} of ${RAIN.drops} coins!`);
      stopRain();
    }
    return;
  }
  if (state.world < FEATURE_WORLD.rain || boss) return;
  if (!rainAt) {
    rainAt = now + between(RAIN.delay) * 1000;
    return;
  }
  if (now >= rainAt && !isModalOpen() && currentScreen === 'coin') startRain(now);
}

function startRain(now, shower = false) {
  const layer = $('rain-layer');
  const value = Math.max(clickPower() * 20, baseIncome() * 25) * (1 + itemBonus('rain'));
  rain = { until: now + RAIN.seconds * 1000, value, caught: 0 };
  const symbol = world().symbol;
  for (let k = 0; k < RAIN.drops; k++) {
    const drop = document.createElement('button');
    drop.className = 'rain-coin';
    drop.textContent = symbol;
    drop.setAttribute('aria-label', tr('Falling coin, tap to catch'));
    drop.style.left = `${6 + Math.random() * 82}%`;
    drop.style.animationDelay = `${(Math.random() * (RAIN.seconds - 4.5)).toFixed(2)}s`;
    drop.style.animationDuration = `${(3 + Math.random() * 1.5).toFixed(2)}s`;
    drop.addEventListener('pointerdown', event => {
      event.preventDefault();
      event.stopPropagation();
      catchRain(drop);
    });
    drop.addEventListener('click', event => {
      if (event.detail === 0) catchRain(drop);
    });
    layer.appendChild(drop);
  }
  sfx('rain');
  if (!shower) notify(tr('Coin rain! Catch the falling coins.'));
}

function catchRain(drop) {
  if (!rain || drop.classList.contains('caught')) return;
  // Freeze the coin where it was caught, then let it pop.
  const placed = getComputedStyle(drop).transform;
  drop.style.animation = 'none';
  drop.style.transform = placed && placed !== 'none' ? placed : '';
  drop.classList.add('caught');
  drop.style.animation = 'rain-pop .5s ease-out forwards';
  drop.textContent = `+${format(rain.value)}`;
  earn(rain.value);
  rain.caught++;
  questProgress('rain');
  if (rain.caught >= RAIN.drops) unlock('rain');
  sfx('lucky');
  buzz(12, 'tap');
  updateHud();
  setTimeout(() => drop.remove(), 500);
}

function stopRain() {
  const layer = $('rain-layer');
  if (layer) layer.innerHTML = '';
  if (rain) rainAt = Date.now() + between(RAIN.delay) * 1000;
  rain = null;
}

/* --- The helicopter: very rare, and a little silly --- */
function heliSvg() {
  return `<svg class="heli-svg" viewBox="0 0 220 130" aria-hidden="true">
    <rect class="rotor" x="18" y="6" width="156" height="7" rx="3.5" fill="#b9bab0" stroke="#3a3b35" stroke-width="1.5"/>
    <rect x="91" y="12" width="9" height="18" fill="#8d8e85" stroke="#3a3b35" stroke-width="1.5"/>
    <path d="M148 58 L204 47 L207 57 L150 76 Z" fill="#e0a21f" stroke="#6b4006" stroke-width="3.5" stroke-linejoin="round"/>
    <rect class="tail-rotor" x="199" y="30" width="8" height="38" rx="4" fill="#b9bab0" stroke="#3a3b35" stroke-width="1.5"/>
    <ellipse cx="100" cy="65" rx="58" ry="37" fill="#f7b931" stroke="#6b4006" stroke-width="4"/>
    <path d="M60 58 C60 40 74 32 95 32 L99 64 L58 64 Z" fill="#bfe8ff" stroke="#6b4006" stroke-width="3.5" stroke-linejoin="round"/>
    <rect x="66" y="45" width="13" height="8" rx="2.5" fill="#1b1b1b"/>
    <rect x="83" y="45" width="13" height="8" rx="2.5" fill="#1b1b1b"/>
    <path d="M79 48 L83 48" stroke="#1b1b1b" stroke-width="2.5"/>
    <path d="M71 57 Q80 64 91 56" stroke="#1b1b1b" stroke-width="3" fill="none" stroke-linecap="round"/>
    <circle cx="123" cy="69" r="12" fill="#ffe99b" stroke="#a7620a" stroke-width="3.5"/>
    <path d="M123 61 L125.2 66.8 L131 69 L125.2 71.2 L123 77 L120.8 71.2 L115 69 L120.8 66.8 Z" fill="#a7620a"/>
    <path d="M78 98 L73 108 M128 98 L133 108" stroke="#8d8e85" stroke-width="5" stroke-linecap="round"/>
    <path d="M56 108 L152 108" stroke="#b9bab0" stroke-width="6" stroke-linecap="round"/>
  </svg>`;
}

let heliSound = null;

function heliTick(now) {
  if (heli) return;
  if (!heliAt) {
    heliAt = now + (between(HELI.first) * 1000) / (1 + itemBonus('heli'));
    return;
  }
  if (now >= heliAt && !isModalOpen() && !boss) spawnHeli();
}

function spawnHeli() {
  if (heli) return;
  const layer = $('heli-layer');
  const el = document.createElement('button');
  el.className = `heli ${Math.random() < 0.5 ? 'from-left' : 'from-right'}`;
  el.innerHTML = heliSvg();
  el.style.top = `${16 + Math.random() * 38}%`;
  el.style.animationDuration = `${HELI.flight}s`;
  el.setAttribute('aria-label', tr('A helicopter! Tap it'));
  el.addEventListener('pointerdown', event => {
    event.preventDefault();
    event.stopPropagation();
    catchHeli();
  });
  el.addEventListener('click', event => {
    if (event.detail === 0) catchHeli();
  });
  el.addEventListener('animationend', event => {
    if (event.animationName === 'heli-fly') missHeli();
  });
  layer.appendChild(el);
  heli = { el };
  heliSound = chopper(HELI.flight, 0.05);
  updateBadges();
}

function clearHeli() {
  if (heli) heli.el.remove();
  heli = null;
  if (heliSound) {
    try {
      heliSound.stop();
    } catch (error) {
      // Already quiet.
    }
  }
  heliSound = null;
  heliAt = Date.now() + (between(HELI.next) * 1000) / (1 + itemBonus('heli'));
}

function missHeli() {
  clearHeli();
  updateBadges();
}

function catchHeli() {
  if (!heli) return;
  clearHeli();
  const coins = Math.max(clickPower() * 60, baseIncome() * 180);
  const diamonds = 5;
  earn(coins);
  state.diamonds += diamonds;
  state.stats.helicopters++;
  lastHeli = { coins, diamonds };
  // "Helicopter helicopter!" If the voice can't play, a rotor and a jingle.
  Voice.play().then(played => {
    if (played) return;
    chopper(1.8, 0.2);
    setTimeout(() => sfx('travel'), 400);
  });
  buzz(60);
  openModal('heli');
  save();
  refresh();
}

/* --- Faces, critters, bosses and Pip --- */
/* --- Faces that change with the mood --- */
// Every critter, boss and Pip draws its face from a few numbers, so the
// same face can look calm, hurt, angry, scared, happy or knocked out.
//   eyes:  [[x, y, r, look], …]   look: which way the pupil leans (1, 0, -1)
//   mouth: [x, y, width] or null   base: the usual mouth (smile, frown, flat,
//          grin, fangs, wavy, small, none)
//   brows: 'angry' for critters that always frown
//   style: 'eye' (white eye and pupil), 'slit' (glowing cat eye), 'led' (robot
//          light), 'shades' (dark glasses: only the brows move)
//   ink, mouthInk, white, pupil: colours
const MOODS = ['idle', 'hurt', 'angry', 'scared', 'happy', 'ko', 'sleep'];

function faceSvg(face, mood = 'idle') {
  const ink = face.ink || '#1d140c';
  const mouthInk = face.mouthInk || ink;
  const white = face.white || '#ffffff';
  const pupil = face.pupil || '#17130f';
  const style = face.style || 'eye';
  const line = r => Math.max(2, r * 0.38).toFixed(1);
  let eyes = '';
  let brows = '';
  for (const [x, y, r, look = 1, dir] of face.eyes) {
    const side = dir || (x < 50 ? 1 : -1);
    const w = line(r);
    if (style === 'shades') {
      // Dark glasses: no eyes to change, the brows do the talking.
    } else if (mood === 'hurt') {
      const d = side;
      eyes += `<path d="M${x - d * r * 0.7} ${y - r * 0.65} L${x + d * r * 0.55} ${y} L${x - d * r * 0.7} ${y + r * 0.65}" stroke="${style === 'led' ? white : ink}" stroke-width="${w}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`;
    } else if (mood === 'happy') {
      eyes += `<path d="M${x - r * 0.8} ${y + r * 0.35} Q${x} ${y - r * 0.95} ${x + r * 0.8} ${y + r * 0.35}" stroke="${style === 'led' ? white : ink}" stroke-width="${w}" fill="none" stroke-linecap="round"/>`;
    } else if (mood === 'sleep') {
      eyes += `<path d="M${x - r * 0.8} ${y + r * 0.1} Q${x} ${y + r * 0.7} ${x + r * 0.8} ${y + r * 0.1}" stroke="${style === 'led' ? white : ink}" stroke-width="${w}" fill="none" stroke-linecap="round"/>`;
    } else if (mood === 'ko') {
      const k = r * 0.6;
      eyes += `<path d="M${x - k} ${y - k} L${x + k} ${y + k} M${x + k} ${y - k} L${x - k} ${y + k}" stroke="${style === 'led' ? white : ink}" stroke-width="${w}" stroke-linecap="round"/>`;
    } else if (style === 'led') {
      const s = mood === 'scared' ? 0.6 : 1;
      eyes += `<circle cx="${x}" cy="${y}" r="${(r * s).toFixed(1)}" fill="${white}"/>`;
    } else if (style === 'slit') {
      eyes += `<g class="eye"><circle cx="${x}" cy="${y}" r="${r}" fill="${white}"/><path d="M${x} ${y - r * (mood === 'scared' ? 0.3 : 0.65)} V${y + r * (mood === 'scared' ? 0.3 : 0.65)}" stroke="${pupil}" stroke-width="${(r * (mood === 'angry' ? 0.3 : 0.38)).toFixed(1)}" stroke-linecap="round"/></g>`;
    } else {
      const big = mood === 'scared' ? 1.15 : 1;
      const p = mood === 'scared' ? 0.28 : mood === 'angry' ? 0.42 : 0.5;
      const lean = mood === 'scared' ? 0 : look;
      eyes += `<g class="eye"><circle cx="${x}" cy="${y}" r="${(r * big).toFixed(1)}" fill="${white}"/><circle cx="${(x + lean * r * 0.25).toFixed(1)}" cy="${(y + r * 0.15).toFixed(1)}" r="${(r * p).toFixed(1)}" fill="${pupil}"/><circle cx="${(x + lean * r * 0.25 - r * 0.18).toFixed(1)}" cy="${(y - r * 0.1).toFixed(1)}" r="${(r * 0.15).toFixed(1)}" fill="#ffffff"/></g>`;
    }
    // Brows: angry slopes down to the middle, scared slopes up.
    const d = side;
    const by = style === 'shades' ? y - r * 1.15 : y - r * 1.35;
    const browInk = face.browInk || ink;
    if (mood === 'angry' || (face.brows === 'angry' && (mood === 'idle' || mood === 'hurt'))) {
      brows += `<path d="M${x - d * r * 1.05} ${by - r * 0.3} L${x + d * r * 0.65} ${by + r * 0.3}" stroke="${browInk}" stroke-width="${line(r)}" stroke-linecap="round"/>`;
    } else if (mood === 'scared') {
      brows += `<path d="M${x - d * r * 1.05} ${by + r * 0.2} L${x + d * r * 0.65} ${by - r * 0.35}" stroke="${browInk}" stroke-width="${line(r)}" stroke-linecap="round"/>`;
    } else if (style === 'shades') {
      const lift = mood === 'happy' ? -r * 0.35 : 0;
      brows += `<path d="M${x - r} ${by + lift} Q${x} ${by - r * 0.35 + lift} ${x + r} ${by + lift}" stroke="${browInk}" stroke-width="${line(r)}" fill="none" stroke-linecap="round"/>`;
    }
  }
  let mouth = '';
  // Most faces have one mouth; a duo has one each (mouths).
  for (const [mx, my, mw] of face.mouths || (face.mouth ? [face.mouth] : [])) {
    const sw = Math.max(2.2, mw * 0.18).toFixed(1);
    const h = mw / 2;
    const shapes = {
      smile: `<path d="M${mx - h} ${my} Q${mx} ${my + mw * 0.42} ${mx + h} ${my}" stroke="${mouthInk}" stroke-width="${sw}" fill="none" stroke-linecap="round"/>`,
      small: `<path d="M${mx - h * 0.6} ${my} Q${mx} ${my + mw * 0.3} ${mx + h * 0.6} ${my}" stroke="${mouthInk}" stroke-width="${sw}" fill="none" stroke-linecap="round"/>`,
      frown: `<path d="M${mx - h} ${my + mw * 0.22} Q${mx} ${my - mw * 0.22} ${mx + h} ${my + mw * 0.22}" stroke="${mouthInk}" stroke-width="${sw}" fill="none" stroke-linecap="round"/>`,
      flat: `<path d="M${mx - h} ${my} H${mx + h}" stroke="${mouthInk}" stroke-width="${sw}" stroke-linecap="round"/>`,
      wavy: `<path d="M${mx - h} ${my} q${h / 2} ${-mw * 0.18} ${h} 0 t${h} 0" stroke="${mouthInk}" stroke-width="${sw}" fill="none" stroke-linecap="round"/>`,
      grin: `<path d="M${mx - h} ${my - mw * 0.05} Q${mx} ${my + mw * 0.55} ${mx + h} ${my - mw * 0.05} Z" fill="#3a1f12" stroke="${mouthInk}" stroke-width="${(sw * 0.8).toFixed(1)}" stroke-linejoin="round"/><path d="M${mx - h * 0.7} ${my + mw * 0.02} H${mx + h * 0.7}" stroke="#ffffff" stroke-width="${(mw * 0.12).toFixed(1)}" stroke-linecap="round"/>`,
      fangs: `<path d="M${mx - h} ${my} Q${mx} ${my + mw * 0.45} ${mx + h} ${my}" stroke="${mouthInk}" stroke-width="${sw}" fill="none" stroke-linecap="round"/><path d="M${mx - h * 0.45} ${my + mw * 0.08} l${mw * 0.06} ${mw * 0.16} l${mw * 0.06} ${-mw * 0.15} Z M${mx + h * 0.2} ${my + mw * 0.12} l${mw * 0.06} ${mw * 0.15} l${mw * 0.06} ${-mw * 0.16} Z" fill="#ffffff"/>`,
      open: `<ellipse cx="${mx}" cy="${my + mw * 0.12}" rx="${(mw * 0.22).toFixed(1)}" ry="${(mw * 0.28).toFixed(1)}" fill="#3a1f12" stroke="${mouthInk}" stroke-width="${(sw * 0.7).toFixed(1)}"/>`,
      happy: `<path d="M${mx - h} ${my - mw * 0.05} Q${mx} ${my + mw * 0.7} ${mx + h} ${my - mw * 0.05} Z" fill="#3a1f12" stroke="${mouthInk}" stroke-width="${(sw * 0.8).toFixed(1)}" stroke-linejoin="round"/><ellipse cx="${mx}" cy="${my + mw * 0.32}" rx="${(mw * 0.2).toFixed(1)}" ry="${(mw * 0.1).toFixed(1)}" fill="#e46a6a"/>`,
      none: ''
    };
    const pick = {
      idle: face.base || 'smile',
      hurt: 'open',
      angry: face.base === 'fangs' || face.base === 'grin' ? face.base : 'frown',
      scared: 'wavy',
      happy: 'happy',
      ko: 'wavy',
      sleep: 'small'
    }[mood] || face.base || 'smile';
    mouth += shapes[pick] || '';
    if (mood === 'ko' && face.base !== 'none') mouth += `<path d="M${mx + h * 0.2} ${my + mw * 0.05} q${mw * 0.12} ${mw * 0.3} ${mw * 0.24} 0" fill="#e46a6a"/>`;
  }
  return `<g class="face mood-${mood}">${brows}${eyes}${mouth}</g>`;
}

// A soft, bumpy outline: a circle with little round bumps all the way round.
function fluffPath(cx, cy, rx, ry, bumps, depth) {
  const point = (angle, grow) => [
    cx + Math.cos(angle) * (rx + grow),
    cy + Math.sin(angle) * (ry + grow)
  ];
  const step = (Math.PI * 2) / bumps;
  let d = '';
  for (let k = 0; k < bumps; k++) {
    const a0 = k * step - Math.PI / 2;
    const [x0, y0] = point(a0, 0);
    const [cxp, cyp] = point(a0 + step / 2, depth * 2);
    const [x1, y1] = point(a0 + step, 0);
    if (k === 0) d += `M${x0.toFixed(1)} ${y0.toFixed(1)} `;
    d += `Q${cxp.toFixed(1)} ${cyp.toFixed(1)} ${x1.toFixed(1)} ${y1.toFixed(1)} `;
  }
  return `${d}Z`;
}

const SHADOW_SVG = '<ellipse cx="50" cy="93" rx="27" ry="4.5" fill="#000000" opacity=".28"/>';
const FLOAT_SHADOW_SVG = '<ellipse cx="50" cy="95" rx="18" ry="3.5" fill="#000000" opacity=".2"/>';
const BOSS_GROUND_SVG = '<ellipse cx="50" cy="95" rx="32" ry="4.5" fill="#000000" opacity=".3"/>';

// A horse seen from the front, for the Bäckahäst and Sleipnir.
//   legs: x of the front legs, back: x of the legs behind them
function horseSvg({ coat, shade, mane, ink, hoof, legs, back = [] }) {
  const leg = (x, behind) => `<rect x="${x - 4}" y="68" width="8" height="19" rx="3.5" fill="${behind ? shade : coat}" stroke="${ink}" stroke-width="2.5"/><rect x="${x - 4.5}" y="85" width="9" height="5" rx="2" fill="${hoof}" stroke="${ink}" stroke-width="1.5"/>`;
  return `${SHADOW_SVG}
    ${back.map(x => leg(x, true)).join('')}
    ${legs.map(x => leg(x, false)).join('')}
    <ellipse cx="50" cy="67" rx="23" ry="11" fill="${coat}" stroke="${ink}" stroke-width="3"/>
    <path d="M31 30 C25 44 27 60 33 68 C35 56 37 44 41 34 Z M69 30 C75 44 73 60 67 68 C65 56 63 44 59 34 Z" fill="${mane}" stroke="${ink}" stroke-width="2.5" stroke-linejoin="round"/>
    <path d="M37 22 L34 8 L45 18 Z M63 22 L66 8 L55 18 Z" fill="${coat}" stroke="${ink}" stroke-width="2.5" stroke-linejoin="round"/>
    <path d="M35 26 C35 15 65 15 65 26 C65 38 62 50 60 60 C59 69 41 69 40 60 C38 50 35 38 35 26 Z" fill="${coat}" stroke="${ink}" stroke-width="3.5"/>
    <ellipse cx="50" cy="61" rx="10" ry="7" fill="${shade}"/>
    <ellipse cx="46" cy="61" rx="1.6" ry="2.4" fill="${ink}"/><ellipse cx="54" cy="61" rx="1.6" ry="2.4" fill="${ink}"/>
    <path d="M42 17 C46 25 44 31 40 33 C48 31 52 25 50 17 Z M50 17 C54 25 58 27 60 31 C58 23 56 19 50 17 Z" fill="${mane}" stroke="${ink}" stroke-width="2" stroke-linejoin="round"/>`;
}

