// Pip's friends are coinfolk too: a coin with arms, feet and a face, each in
// a metal of its own, with something that is only theirs.
function coinfolkBody({ light, mid, dark, cheek = '#f08a5d' }) {
  return `<path d="M21 60 Q11 62 10 52" stroke="${dark}" stroke-width="4" fill="none" stroke-linecap="round"/>
    <path d="M79 60 Q89 62 90 52" stroke="${dark}" stroke-width="4" fill="none" stroke-linecap="round"/>
    <ellipse cx="40" cy="91" rx="7" ry="4" fill="${dark}"/><ellipse cx="60" cy="91" rx="7" ry="4" fill="${dark}"/>
    <circle cx="50" cy="56" r="33" fill="${mid}" stroke="${dark}" stroke-width="4"/>
    <circle cx="50" cy="56" r="25" fill="none" stroke="${light}" stroke-width="2.5" opacity=".8"/>
    <circle cx="31" cy="64" r="4.5" fill="${cheek}" opacity=".55"/><circle cx="69" cy="64" r="4.5" fill="${cheek}" opacity=".55"/>`;
}
const friendFace = (ink, extra = {}) => ({ eyes: [[40, 52, 6.5], [60, 52, 6.5]], mouth: [50, 66, 16], base: 'smile', ink, ...extra });

