  s += `<path d="M262 113h10v-6l-5 -4l-5 4Z" fill="#f2ead8" stroke="#a89a84" stroke-width=".8"/><path d="M261 107l6 -5.2l6 5.2Z" fill="#c8836f"/>`;
  s += cityWindmill(146, 126);
  s += `<path d="M0 146C64 132 126 146 196 138C258 132 318 142 360 134V${back}H0Z" fill="${P.near}"/>`;
  s += `<g class="trees"${sky.id === 'wind' ? '' : capped}>`;
  [[22, 150, 8, 0], [92, 147, 7, 1], [128, 150, 6, 2], [238, 145, 7, 1], [328, 146, 8, 2]].forEach(([x, y, r, k]) => { s += cityTree(x, y, r, k); });
  s += cityPoplar(208, 168, 32) + cityPoplar(292, 166, 26) + cityTree(354, 170, 9, 0) + cityTree(64, 166, 6, 2);
  s += '</g>';
