  if (!snowy) s += flowerBed(cityPen(5), 2, back + 3, 24) + flowerBed(cityPen(6), 140, back + 3, 12) + flowerBed(cityPen(7), 204, back + 3, 10);
  else [5, 6, 7].forEach(k => cityPen(k));
