// A body with its face in a slot of its own, so the mood can change
// without drawing the whole creature again.
function creatureSvg(look, mood, className) {
  return `<svg class="${className}" viewBox="0 0 100 100" aria-hidden="true">${look.body}<g class="face-slot" data-mood="${mood}">${faceSvg(look.face, mood)}</g>${look.over || ''}</svg>`;
}
const monsterSvg = (id, mood = 'idle') => creatureSvg(LOOKS[id] || LOOKS.rustling, mood, 'monster-svg');
const bossSvg = (id, mood = 'idle') => creatureSvg(BOSS_LOOKS[id] || BOSS_LOOKS.baron, mood, 'boss-svg');
const pipSvg = (mood = 'idle', number = state.world) => pipWorldSvg(mood, number);

// Changes the face inside a drawing made by creatureSvg.
function setFace(container, look, mood) {
  const slot = container && container.querySelector('.face-slot');
  if (!slot || !look || slot.getAttribute('data-mood') === mood) return;
  slot.innerHTML = faceSvg(look.face, mood);
  slot.setAttribute('data-mood', mood);
}

/* --- Monsters: Baron Tarnish's grimy critters --- */
function monsterTick(now) {
  if (monster) {
    // In case the walk animation never reports that it ended.
    if (now > monster.until) missMonster();
    return;
  }
  if (!monsterAt) {
    monsterAt = now + between(MONSTER.first) * 1000;
    return;
  }
  if (now >= monsterAt && !isModalOpen() && !boss && !fight && !rain) spawnMonster();
}

// Picks one of a list, where weight(item) says how likely each one is.
function weightedPick(list, weight) {
  let roll = Math.random() * list.reduce((sum, item) => sum + weight(item), 0);
  for (const item of list) {
    roll -= weight(item);
    if (roll < 0) return item;
  }
  return list[list.length - 1];
}

// Mostly the critters of this world, sometimes one from a world before.
// Rare critters come by less often.
function pickMonster() {
  const home = homeWorld();
  const reachable = MONSTERS.filter(kind => kind.world <= state.world);
  const local = reachable.filter(kind => kind.world === home);
  const pool = local.length && Math.random() < MONSTER.local ? local : reachable;
  return weightedPick(pool, kind => RARITIES[kind.rarity].spawn);
}

function rollVariant(shiny = MONSTER.shiny) {
  const roll = Math.random();
  if (roll < shiny) return 'shiny';
  if (roll < shiny + MONSTER.big) return 'big';
  return '';
}

const variantName = (name, variant) => (variant ? T`${VARIANTS[variant].label} ${name}` : name);
const rarityOf = kind => RARITIES[kind.rarity] || RARITIES[0];
const rarityPill = rarity => `<span class="pill rarity ${rarity.id}">${rarity.name.toUpperCase()}</span>`;

function spawnMonster(shiny = MONSTER.shiny) {
  if (monster) return;
  const layer = $('monster-layer');
  if (!layer) return;
  if (!state.story.critters && state.story.prologue && currentScreen === 'coin' && !inDialogue) {
    state.story.critters = true;
    pipSay(tr('Critters run by now and then. Tap them before they get away!'), 'idle', 3800, true);
  }
  const kind = pickMonster();
  const variant = rollVariant(shiny * (1 + itemBonus('shiny')));
  const rarity = rarityOf(kind);
  const fromLeft = Math.random() < 0.5;
  // The rarest critters are in a bit more of a hurry. If you are on another
  // screen, it takes its time, so you can hurry back.
  const away = currentScreen !== 'coin';
  const walk = MONSTER.walk * (MONSTER.pace[kind.move] || 1) * (kind.rarity >= R.VERY_RARE ? 0.88 : 1) * (away ? MONSTER.away : 1);
  const el = document.createElement('button');
  const side = LOOKS[kind.id] && LOOKS[kind.id].side ? ' sideways' : '';
  el.className = `monster ${fromLeft ? 'from-left' : 'from-right'} ${kind.move} r-${rarity.id}${variant ? ` ${variant}` : ''}${side}`;
  el.innerHTML = monsterSvg(kind.id);
  el.style.setProperty('--walk', `${walk.toFixed(1)}s`);
  el.style.setProperty('--blink', `${(-Math.random() * 4).toFixed(2)}s`);
  el.setAttribute('aria-label', T`A ${rarity.name} ${variantName(kind.name, variant)}! Tap it to fight`);
  el.addEventListener('pointerdown', event => {
    event.preventDefault();
    event.stopPropagation();
    startFight();
  });
  el.addEventListener('click', event => {
    if (event.detail === 0) startFight();
  });
  el.addEventListener('animationend', event => {
    if (event.animationName.startsWith('monster-walk')) missMonster();
  });
  layer.appendChild(el);
  const born = Date.now();
  monster = { el, kind: kind.id, variant, born, until: born + walk * 1000 + 500 };
  const name = variantName(kind.name, variant);
  const special = kind.rarity >= R.VERY_RARE || variant === 'shiny';
  if (special) {
    sfx(kind.rarity >= R.MYTHICAL ? 'legendary' : 'golden');
    buzz([20, 40, 20]);
  } else {
    sfx('monster');
  }
  if (away) {
    notify(T`A ${kind.rarity >= R.RARE ? T`${rarity.name} ${name}` : name} is at your coin! Hurry back to catch it.`);
    updateBadges();
  } else if (special) {
    notify(T`A ${kind.rarity >= R.RARE ? T`${rarity.name} ${name}` : name}! Catch it before it gets away!`);
    pipSay(T`Look! A ${rarity.name} ${name}! Quick!`, 'scared', 2600, true);
  } else {
    pipWake();
    // The first few times, say what to do.
    if (state.stats.monsters < 3) notify(T`A ${name} is sneaking past! Tap it to fight.`);
    else if (kind.rarity === R.RARE) notify(T`A Rare ${name} is sneaking past!`);
  }
}

// A critter that came by while you were on another screen kept walking,
// so it shows up where it would be by now.
function syncMonsterWalk() {
  if (!monster) return;
  const elapsed = (Date.now() - monster.born) / 1000;
  monster.el.style.animationDelay = `${(-elapsed).toFixed(2)}s, 0s`;
}

// Takes the walking monster off the screen. The next one comes later.
function clearMonster(delay = between(MONSTER.delay) / monsterRate()) {
  if (monster) monster.el.remove();
  monster = null;
  monsterAt = Date.now() + delay * 1000;
}

function missMonster() {
  if (!monster) return;
  clearMonster();
}

function fightTime() {
  return fight ? Math.max(0, (fight.until - Date.now()) / 1000) : 0;
}

function startFight() {
  if (!monster || boss || fight || isModalOpen()) return;
  const kind = MONSTERS.find(m => m.id === monster.kind) || MONSTERS[0];
  const variant = monster.variant || '';
  const extra = VARIANTS[variant] || { hp: 1, luck: 0 };
  const rarity = rarityOf(kind);
  clearMonster();
  // Health is counted in taps, without short bonuses like Frenzy.
  const perTap = (tapBase() + baseIncome() * echoShare()) * boostMult();
  const hp = Math.max(1, between(MONSTER.hp) * kind.tough * extra.hp * rarity.hp * perTap);
  fight = {
    kind: kind.id, variant, rarity: kind.rarity, name: variantName(kind.name, variant),
    luck: kind.luck + extra.luck + rarity.luck, hp, max: hp,
    until: Date.now() + (MONSTER.fight + rarity.time) * (1 + itemBonus('fighttime')) * 1000, mood: 'idle', moodUntil: 0
  };
  sfx('monster');
  buzz(30);
  Music.follow();
  openModal('fight', true);
}

function renderFight(content) {
  if (!fight) {
    closeModal();
    return;
  }
  const rarity = RARITIES[fight.rarity];
  const tags = [
    fight.rarity > R.COMMON ? rarityPill(rarity) : '',
    fight.variant ? `<span class="pill ${fight.variant === 'shiny' ? 'gold' : 'purple'}">${VARIANTS[fight.variant].label.toUpperCase()}</span>` : ''
  ].join(' ');
  content.innerHTML = T`<div class="fight-head"><div class="eyebrow">MONSTER FIGHT ${tags}</div><b id="fight-time">${Math.ceil(fightTime())}s</b></div>
    <h2 id="modal-title">${fight.name}<span>!</span></h2>
    <div class="fight-bar"><span id="fight-bar"></span></div>
    <div class="fight-hp" id="fight-hp"></div>
    <div class="fight-arena r-${rarity.id}" id="fight-arena">
      <button class="fight-monster${fight.variant ? ` ${fight.variant}` : ''}" id="fight-monster" aria-label="Hit the ${fight.name}">${monsterSvg(fight.kind, fight.mood)}</button>
      <div class="fx-layer" id="fight-fx" aria-hidden="true"></div>
    </div>
    <p class="note center">Tap it as fast as you can before it runs off! Tap × to run away.</p>`;
  const target = $('fight-monster');
  target.addEventListener('pointerdown', event => {
    if (event.pointerType === 'mouse' && event.button !== 0) return;
    event.preventDefault();
    const rect = $('fight-arena').getBoundingClientRect();
    hitMonster(event.clientX - rect.left, event.clientY - rect.top);
  });
  target.addEventListener('click', event => {
    if (event.detail !== 0) return;
    const rect = $('fight-arena').getBoundingClientRect();
    hitMonster(rect.width / 2, rect.height / 2);
  });
  updateFightHud();
}

// The critter's face follows the fight: cross when it's hurt, scared when
// it's nearly beaten, smug when it is about to get away.
function fightMood() {
  const share = fight.hp / fight.max;
  if (share <= 0.3) return 'scared';
  if (fightTime() < 3 && share > 0.4) return 'happy';
  if (share <= 0.65) return 'angry';
  return 'idle';
}

function setFightMood(mood) {
  if (!fight || fight.mood === mood) return;
  fight.mood = mood;
  setFace($('fight-monster'), LOOKS[fight.kind], mood);
}

function updateFightHud() {
  if (!fight || modalType !== 'fight') return;
  setText('fight-time', `${Math.ceil(fightTime())}s`);
  setText('fight-hp', `${format(fight.hp)} / ${format(fight.max)} HP`);
  const bar = $('fight-bar');
  if (bar) bar.style.width = `${(fight.hp / fight.max) * 100}%`;
  if (Date.now() >= fight.moodUntil) setFightMood(fightMood());
}

let hitTimer;

function hitMonster(x, y) {
  if (!fight) return;
  registerCombo();
  state.stats.taps++;
  const lucky = Math.random() < critChance();
  const damage = tapValue(lucky) * damageMult();
  fight.hp = Math.max(0, fight.hp - damage);
  spawnFloat(x, y, damage, lucky, true, 'fight-fx');
  const target = $('fight-monster');
  if (target) {
    target.classList.add('hit');
    clearTimeout(hitTimer);
    hitTimer = setTimeout(() => target.classList.remove('hit'), 110);
  }
  fight.moodUntil = Date.now() + 150;
  setFightMood('hurt');
  sfx(lucky ? 'lucky' : 'squish');
  buzz(lucky ? 25 : 10, 'tap');
  if (fight.hp <= 0) winFight();
  else updateFightHud();
}

// Picks a treasure: the rarity first, then one of that rarity that isn't at
// its max level yet. A critter's favourite comes up more often. When every
// treasure of that rarity is at its max, the nearest rarity with room; when
// all of them are, nothing (and you get diamonds instead).
function rollItem(extraLuck = 0, favorite = '') {
  const luck = 1 + itemBonus('loot') + extraLuck;
  const weights = RARITIES.map((rarity, i) => (i === 0 ? rarity.weight : rarity.weight * luck));
  let roll = Math.random() * weights.reduce((sum, w) => sum + w, 0);
  let rarity = 0;
  while (rarity < weights.length - 1 && roll >= weights[rarity]) {
    roll -= weights[rarity];
    rarity++;
  }
  const order = RARITIES.map((_, r) => r).sort((a, b) => Math.abs(a - rarity) - Math.abs(b - rarity) || a - b);
  for (const r of order) {
    const pool = ITEM_TYPES.filter(type => type.rarity === r && itemLevel(type.id) < type.max);
    if (!pool.length) continue;
    const liked = pool.find(type => type.id === favorite);
    const type = liked && Math.random() < FAVORITE_DROP ? liked : pool[Math.floor(Math.random() * pool.length)];
    return { type: type.id, rarity: r };
  }
  return null;
}

// A treasure you found: new, or one level up.
function grantItem(item) {
  if (!item || !ITEM_BY_ID[item.type]) {
    state.diamonds += MAXED_TREASURE_DIAMONDS;
    return { type: '', rarity: 0, level: 0, before: 0, diamonds: MAXED_TREASURE_DIAMONDS };
  }
  const type = ITEM_BY_ID[item.type];
  const before = itemLevel(type.id);
  const level = Math.min(type.max, before + 1);
  state.itemLevels[type.id] = level;
  state.items[type.id] = itemValue(type, level);
  state.itemCounts[type.id]++;
  state.rarities[type.rarity]++;
  state.stats.items++;
  return { type: type.id, rarity: type.rarity, level, before };
}

// Knocked out! A short look at the dizzy critter, then the loot.
function winFight() {
  const won = fight;
  fight = null;
  const kind = MONSTERS.find(m => m.id === won.kind) || MONSTERS[0];
  state.stats.monsters++;
  state.bestiary[won.kind] = (state.bestiary[won.kind] || 0) + 1;
  let coins = Math.max(tapBase() * boostMult() * 30, baseIncome() * 60) * (VARIANTS[won.variant]?.coins || 1) * rarityOf(kind).coins * streakLoot()
    * (1 + itemBonus('chalice'));
  const greedy = Math.random() < itemBonus('greed');
  if (greedy) coins *= GREED;
  earn(coins);
  if (won.variant === 'shiny') unlock('shiny-monster');
  if (won.kind === 'kolobok') unlock('clever-fox');
  if (won.variant === 'big') unlock('big-monster');
  const item = grantItem(rollItem(won.luck, kind.drop));
  const twin = Math.random() < itemBonus('mirror') ? grantItem(rollItem(won.luck, kind.drop)) : null;
  // The Diamond Pouch: a chance of a diamond on top.
  const gem = Math.random() < itemBonus('gem') ? 1 : 0;
  state.diamonds += gem;
  const bricks = addBricks(critterBricks(kind, won.variant));
  // The first time you beat a critter from the folk tales, Pip tells its tale.
  const tale = state.bestiary[won.kind] === 1 ? kind.tale || '' : '';
  lastLoot = { ...item, coins, gem, bricks, greedy, twin, monster: won.name, rarityOfMonster: won.rarity, luck: won.luck, drop: kind.drop, extra: null, tale };
  pipAct('cheer', true);
  addStreak();
  questProgress('monsters');
  if (won.place) setTimeout(() => placeFightWon(won.place), 700);
  const target = $('fight-monster');
  if (target) {
    setFace(target, LOOKS[won.kind], 'ko');
    target.classList.add('ko');
  }
  sfx('squish');
  buzz(item.rarity >= R.VERY_RARE ? 90 : 50);
  save();
  setTimeout(() => {
    sfx(item.rarity >= R.VERY_RARE ? 'legendary' : 'loot');
    openModal('loot', true);
    refresh();
  }, 450);
}

// It got away, looking very pleased with itself.
function loseFight() {
  const lost = fight;
  fight = null;
  const streak = breakStreak();
  const target = $('fight-monster');
  if (target && modalType === 'fight') {
    setFace(target, LOOKS[lost.kind], 'happy');
    target.classList.add('escaping');
  }
  sfx('escape');
  notify(T`The ${lost.name} got away! Tap faster next time. Combo helps.${streak >= 3 ? T` Your streak of ${streak} is over.` : ''}`);
  setTimeout(() => {
    if (modalType === 'fight' && !fight) closeModal();
  }, 650);
}

function fleeFight() {
  const fled = fight;
  fight = null;
  if (!fled) return;
  const streak = breakStreak();
  notify(T`You ran away from the ${fled.name}.${streak >= 3 ? T` Your streak of ${streak} is over.` : ''}`);
}

/* -----------------------------------------------------------------
  10. ACHIEVEMENTS
   ----------------------------------------------------------------- */
const hasAchievement = id => state.achievements.includes(id);
const achievementReward = ach => (ach.secret ? ACH.secretDiamonds : ACH.diamonds);
const bannerQueue = [];
let bannerBusy = false;

function unlock(id) {
  const ach = ACHIEVEMENTS.find(a => a.id === id);
  if (!ach || hasAchievement(id)) return false;
  state.achievements.push(id);
  state.achievementTimes[id] = Date.now();
  const reward = achievementReward(ach);
  state.diamonds += reward;
  showBanner({ icon: ach.icon, title: ach.name, sub: T`${ach.secret ? tr('Secret found') : tr('Achievement')} · +${reward} ◆ · +1% taps and income`, secret: ach.secret });
  updateHud();
  save();
  return true;
}

// Checks the achievements that come from numbers, a few times a second.
function checkAchievements() {
  const fresh = ACHIEVEMENTS.filter(ach => !ach.secret && !hasAchievement(ach.id) && achDone(ach));
  if (!fresh.length) return;
  if (fresh.length <= 2) {
    fresh.forEach(ach => unlock(ach.id));
    return;
  }
  // Many at once, for example right after an update: one banner for all.
  let diamonds = 0;
  const now = Date.now();
  for (const ach of fresh) {
    state.achievements.push(ach.id);
    state.achievementTimes[ach.id] = now;
    diamonds += achievementReward(ach);
  }
  state.diamonds += diamonds;
  showBanner({ icon: '★', title: T`${fresh.length} achievements unlocked`, sub: T`+${diamonds} ◆ · +${fresh.length}% taps and income` });
  updateHud();
  save();
}

// How many kinds of monster you have beaten.
const kindsBeaten = () => MONSTERS.filter(kind => state.bestiary[kind.id] > 0).length;

// Achievements found since you last opened the list.
const newAchievements = () => state.achievements.slice(state.achievementsSeen);
let achNewIds = [];
let achShown = '';

function showBanner(banner) {
  bannerQueue.push(banner);
  if (!bannerBusy) nextBanner();
}

function nextBanner() {
  const el = $('ach-banner');
  if (inDialogue && bannerQueue.length) {
    bannerBusy = true;
    setTimeout(nextBanner, 500);
    return;
  }
  const banner = bannerQueue.shift();
  if (!banner || !el) {
    bannerBusy = false;
    return;
  }
  bannerBusy = true;
  el.innerHTML = `<b>${banner.icon}</b><span><strong>${banner.title}</strong><small>${banner.sub}</small></span>`;
  el.classList.toggle('secret', Boolean(banner.secret));
  el.classList.add('show');
  sfx('achieve');
  setTimeout(() => {
    el.classList.remove('show');
    setTimeout(nextBanner, 350);
  }, 2800);
}

/* -----------------------------------------------------------------
  11. GAME LOOP AND START-UP
   ----------------------------------------------------------------- */
function checkDay() {
  const now = today();
  if (now === dayKey) return;
  dayKey = now;
  syncAdDay();
  ensureQuests();
  refresh();
  if (!isFresh()) afterTalk(() => openModal('daily'));
}

function autoTap(seconds) {
  const auto = autoTapsPerSecond();
  if (auto <= 0) return;
  autoCarry += auto * seconds;
  const taps = Math.floor(autoCarry);
  if (taps <= 0) return;
  autoCarry -= taps;
  const each = tapBase() * boostMult() * frenzyMult() * surgeMult() * streakMult() * (1 + critChance() * (luckyPower() - 1)) * (1 + itemBonus('auto'));
  if (boss) {
    if (!canHitBoss() || bossHidden()) return;
    boss.hp = Math.max(0, boss.hp - (each + income() * echoShare()) * damageMult() * bossFactor() * taps);
    afterBossDamage();
  } else if (fight) {
    fight.hp = Math.max(0, fight.hp - (each + income() * echoShare()) * damageMult() * taps);
    if (fight.hp <= 0) winFight();
    else updateFightHud();
  } else {
    earn(each * taps);
  }
}

// Time spent away from the game (in the background, or with the phone
// locked) doesn't count against a boss or monster fight.
function shiftTimers(ms) {
  if (!(ms > 0)) return;
  if (boss && !boss.paused) shiftBoss(ms);
  if (fight) fight.until += ms;
}

function tick() {
  const now = Date.now();
  if (document.hidden) {
    lastTick = now;
    return;
  }
  let seconds = (now - lastTick) / 1000;
  lastTick = now;
  decayCombo(now, Math.min(seconds, 10));
  // A gap means the app was asleep in the background. Fights wait,
  // and a long gap counts as offline time so the offline cap applies.
  if (seconds > 1) shiftTimers((seconds - 0.25) * 1000);
  if (seconds > 10) {
    handleAway(seconds);
    seconds = 0;
  }
  if (seconds > 0) {
    earn(income() * seconds);
    autoTap(seconds);
    state.stats.playSeconds += seconds;
    questProgress('minutes', seconds / 60);
  }
  if (boss && !boss.done && !boss.paused) {
    if (boss.intro && now >= boss.intro + BOSS_FX.wait) beginBossFight(now);
    else if (boss.until && now >= boss.until && !phoenixSave(now)) endBoss(false);
  }
  bossTick(now);
  restTick(now);
  if (fight && now >= fight.until) loseFight();
  else updateFightHud();
  goldenTick(now);
  rainTick(now);
  heliTick(now);
  secretTick(now);
  handsTick(now);
  if (now >= handbookAt) {
    handbookAt = now + HANDBOOK_EVERY;
    handbookTick();
  }
  monsterTick(now);
  pipTick(now);
  checkAchievements();
  checkDay();
  firstSteps();
  cityClock(now);
  // Fights end, worlds change and night falls: the music follows.
  Music.follow();
  updateHud();
  updateScreen();
  updateBadges();
}

// Holding a buy button keeps buying, a little faster the longer you hold.
const HOLD = { delay: 420, gap: 120, fastest: 55, speedup: 0.9, actions: ['buy-upgrade', 'buy-machine', 'level-up'] };
let hold = null;
let skipClick = false;

/* --- 3.19: Building like in a Lego game --- */
const LEGO = { base: 1300, perLevel: 300, calm: 600, tap: 260 };
let lego = null;
const legoActive = () => !!(lego && lego.holding);

// The picture to build in: the window's big one, or the card's little one.
function legoArt(button) {
  return button.closest('#modal-content') ? document.querySelector('#modal-content .building-hero') : button.closest('.city-card')?.querySelector('.city-thumb');
}

// Over the building as it is now, the next level, in layers: a layer that
// is placed drops in and clicks into place.
function legoSetup(button, id) {
  const art = legoArt(button);
  const svg = art && art.querySelector('svg.city-art');
  if (!svg || !svg.viewBox || !svg.viewBox.baseVal) return null;
  const box = svg.getBoundingClientRect();
  const frame = art.getBoundingClientRect();
  const vb = svg.viewBox.baseVal;
  const scale = Math.min(box.width / vb.width, box.height / vb.height);
  const w = vb.width * scale;
  const h = vb.height * scale;
  const level = cityLevel(id);
  const layer = document.createElement('div');
  layer.className = 'lego';
  layer.style.cssText = `left:${(box.left - frame.left + (box.width - w) / 2).toFixed(1)}px;top:${(box.top - frame.top + box.height - h).toFixed(1)}px;width:${w.toFixed(1)}px;height:${h.toFixed(1)}px`;
  const next = buildingSvg(id, level + 1);
  layer.innerHTML = `<div class="lego-new">${next}</div><div class="lego-band">${next}</div>`;
  art.classList.add('lego-art');
  art.appendChild(layer);
  const bands = 6 + Math.min(4, level);
  return { id, button, art, layer, bands, placed: 0, progress: 0, need: calmMotion() ? LEGO.calm : LEGO.base + LEGO.perLevel * level, holding: false, pressed: 0, last: 0, frame: 0, done: false };
}

function legoStart(button, event) {
  const id = button.dataset.id;
  if (!canBuild(BUILDING_BY_ID[id])) return;
  if (!lego || lego.id !== id || lego.button !== button || !lego.layer.isConnected) {
    legoClear();
    lego = legoSetup(button, id);
    if (!lego) return;
  }
  if (lego.done) return;
  lego.holding = true;
  lego.pressed = performance.now();
  lego.last = lego.pressed;
  lego.pointer = event.pointerId;
  lego.x = event.clientX;
  lego.y = event.clientY;
  button.classList.add('holding');
  button.classList.remove('hint');
  lego.frame = requestAnimationFrame(legoStep);
}

function legoStep(now) {
  if (!lego || !lego.holding || lego.done) return;
  lego.progress = Math.min(1, lego.progress + (now - lego.last) / lego.need);
  lego.last = now;
  lego.button.style.setProperty('--lego', `${(lego.progress * 100).toFixed(1)}%`);
  const target = Math.floor(lego.progress * lego.bands + 1e-9);
  while (lego.placed < target) legoPlace(lego.placed++);
  if (lego.progress >= 1) {
    lego.done = true;
    lego.holding = false;
    const { id } = lego;
    // The last layer lands, then the building is done.
    setTimeout(() => {
      legoClear();
      skipClick = false;
      handleAction('city-build', { id });
    }, calmMotion() ? 80 : 300);
    return;
  }
  lego.frame = requestAnimationFrame(legoStep);
}

// One layer: bricks fly over, it drops in and clicks into place.
function legoPlace(k) {
  const { layer, bands } = lego;
  const top = (1 - (k + 1) / bands) * 100;
  const bottom = (k / bands) * 100;
  const band = layer.querySelector('.lego-band');
  band.style.clipPath = `inset(${top.toFixed(2)}% 0 ${bottom.toFixed(2)}% 0)`;
  band.classList.remove('drop');
  void band.offsetWidth;
  band.classList.add('drop');
  layer.querySelector('.lego-new').style.clipPath = `inset(${(100 - bottom).toFixed(2)}% 0 0 0)`;
  setTimeout(() => {
    if (layer.isConnected) layer.querySelector('.lego-new').style.clipPath = `inset(${top.toFixed(2)}% 0 0 0)`;
  }, 200);
  sfx('clack');
  buzz(8, 'tap');
  if (calmMotion() || typeof Element.prototype.animate !== 'function') return;
  // Two bricks hop from the button to the layer.
  const from = lego.button.getBoundingClientRect();
  const to = layer.getBoundingClientRect();
  for (let n = 0; n < 2; n++) {
    const brick = document.createElement('i');
    brick.className = 'lego-brick';
    document.body.appendChild(brick);
    const x0 = from.left + from.width * (0.35 + n * 0.3);
    const y0 = from.top + from.height / 2;
    const x1 = to.left + to.width * (0.3 + Math.random() * 0.4);
    const y1 = to.top + to.height * (1 - (k + 0.5) / bands);
    brick.style.left = `${x0}px`;
    brick.style.top = `${y0}px`;
    const lift = Math.min(y0, y1) - y0 - 40;
    brick.animate([
      { transform: 'translate(-50%, -50%) rotate(0deg) scale(.8)', opacity: 1 },
      { transform: `translate(calc(-50% + ${(x1 - x0) / 2}px), calc(-50% + ${lift}px)) rotate(${n ? -160 : 160}deg) scale(1.1)`, opacity: 1, offset: 0.55 },
      { transform: `translate(calc(-50% + ${x1 - x0}px), calc(-50% + ${y1 - y0}px)) rotate(${n ? -320 : 320}deg) scale(.5)`, opacity: 0 }
    ], { duration: 320 + n * 60, easing: 'ease-in' }).onfinish = () => brick.remove();
  }
}

// Let go: it waits where it is. A quick tap only says "hold me".
function legoStop() {
  if (!lego || !lego.holding) return;
  lego.holding = false;
  cancelAnimationFrame(lego.frame);
  lego.button.classList.remove('holding');
  skipClick = true;
  if (performance.now() - lego.pressed < LEGO.tap && lego.progress < 0.3) {
    const button = lego.button;
    button.classList.remove('hint');
    void button.offsetWidth;
    button.classList.add('hint');
    sfx('miss');
  }
}

function legoClear() {
  if (!lego) return;
  cancelAnimationFrame(lego.frame);
  if (lego.layer.isConnected) lego.layer.remove();
  lego.art.classList.remove('lego-art');
  lego.button.classList.remove('holding');
  lego.button.style.removeProperty('--lego');
  lego = null;
}

function startHold(button, event) {
  stopHold();
  hold = { action: button.dataset.action, index: button.dataset.index, pointer: event.pointerId, x: event.clientX, y: event.clientY, count: 0, gap: HOLD.gap };
  hold.timer = setTimeout(holdStep, HOLD.delay);
}

function holdStep() {
  if (!hold) return;
  const selector = `#screen-${currentScreen} [data-action="${hold.action}"]${hold.index === undefined ? '' : `[data-index="${hold.index}"]`}`;
  const button = document.querySelector(selector);
  if (!button || isModalOpen()) {
    stopHold();
    return;
  }
  if (!button.disabled) {
    handleAction(hold.action, button.dataset);
    hold.count++;
    if (hold.count >= 25) unlock('spree');
  }
  hold.gap = Math.max(HOLD.fastest, hold.gap * HOLD.speedup);
  hold.timer = setTimeout(holdStep, hold.gap);
}

// Letting go ends it; the click that follows a long hold buys nothing more.
function stopHold() {
  if (!hold) return;
  clearTimeout(hold.timer);
  if (hold.count > 0) skipClick = true;
  hold = null;
}

function setupInput() {
  const coinButton = $('coin-button');
  coinButton.addEventListener('pointerdown', event => {
    if (event.pointerType === 'mouse' && event.button !== 0) return;
    event.preventDefault();
    const rect = $('coin-stage').getBoundingClientRect();
    tap(event.clientX - rect.left, event.clientY - rect.top);
  });
  // Taps that reach the world behind the coin: its secrets and the things that react.
  $('world-scene').addEventListener('pointerdown', event => {
    const spot = event.target.closest('[data-spot]');
    if (!spot || (event.pointerType === 'mouse' && event.button !== 0)) return;
    event.preventDefault();
    secretTap(spot, scenePoint(event));
  });
  // Keyboard taps (Enter/Space) arrive as clicks without a pointer.
  coinButton.addEventListener('click', event => {
    if (event.detail !== 0) return;
    const rect = $('coin-stage').getBoundingClientRect();
    tap(rect.width / 2, rect.height / 2);
  });

  // Music and the helicopter voice may only start after the first touch.
  const wakeSound = () => {
    Music.start();
    Voice.load();
  };
  document.addEventListener('pointerdown', wakeSound, { capture: true });
  document.addEventListener('keydown', wakeSound, { capture: true });

  document.addEventListener('input', event => volumeInput(event, false));
  document.addEventListener('change', event => volumeInput(event, true));
  document.addEventListener('pointerdown', event => {
    skipClick = false;
    pipWake();
    if (event.pointerType === 'mouse' && event.button !== 0) return;
    const button = event.target.closest('[data-action]');
    if (button && !button.disabled && HOLD.actions.includes(button.dataset.action)) startHold(button, event);
    if (button && !button.disabled && button.dataset.action === 'city-build') legoStart(button, event);
  });
  document.addEventListener('pointermove', event => {
    if (hold && event.pointerId === hold.pointer && Math.hypot(event.clientX - hold.x, event.clientY - hold.y) > 14) stopHold();
    if (legoActive() && event.pointerId === lego.pointer && Math.hypot(event.clientX - lego.x, event.clientY - lego.y) > 18) legoStop();
  });
  ['pointerup', 'pointercancel'].forEach(type => document.addEventListener(type, () => {
    stopHold();
    legoStop();
  }));
  window.addEventListener('blur', () => {
    stopHold();
    legoStop();
  });
  // A long press shouldn't open the browser's menu on a buy button.
  document.addEventListener('contextmenu', event => {
    if (event.target.closest('.buy-button, .lego-button')) event.preventDefault();
  });

  document.addEventListener('click', event => {
    const nav = event.target.closest('[data-go]');
    const inModal = !!event.target.closest('#modal-backdrop');
    if (nav) {
      if (inModal && modalGuarded()) return;
      // A little secret: poke the diamonds ten times.
      if (nav.classList.contains('diamond-pill') && quickTaps('diamonds', 10)) unlock('shiny');
      const again = nav.classList.contains('nav-item') && nav.dataset.go === currentScreen;
      if (modalType) {
        closeModal();
        if (again) return;
      }
      // Tapping the tab you're on jumps to the next part of the page.
      if (again) jumpOnScreen();
      else go(nav.dataset.go);
      return;
    }
    const button = event.target.closest('[data-action]');
    const skip = skipClick;
    skipClick = false;
    if (!button || button.disabled) return;
    if (skip && (HOLD.actions.includes(button.dataset.action) || button.dataset.action === 'city-build')) return;
    if (inModal && modalGuarded()) return;
    handleAction(button.dataset.action, button.dataset);
  });

  // A little secret: tap the logo seven times quickly.
  $('brand').addEventListener('click', () => {
    if (!quickTaps('logo', 7)) return;
    unlock('logo');
    if (!heli && !boss && !isModalOpen()) spawnHeli();
  });

  $('modal-close').addEventListener('click', () => {
    if (!modalGuarded()) closeModal();
  });
  // A tap next to the window closes it, but only if the finger also went
  // down there: the tap that opened a window must not close it again.
  // A tap next to a monster shouldn't end the fight, so only × closes that.
  const backdrop = $('modal-backdrop');
  backdrop.addEventListener('pointerdown', event => {
    backdropPressed = event.target === backdrop;
  });
  backdrop.addEventListener('click', event => {
    const pressed = backdropPressed;
    backdropPressed = false;
    if (event.target === backdrop && pressed && modalType !== 'fight' && !modalGuarded()) closeModal();
  });
  window.addEventListener('resize', fitCoinScreen);
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') closeModal();
  });

  document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
      stopHold();
      hiddenAt = Date.now();
      save();
      Music.suspend();
      Reminders.plan();
      return;
    }
    Music.wake();
    Reminders.clear();
    const away = hiddenAt ? (Date.now() - hiddenAt) / 1000 : 0;
    hiddenAt = 0;
    lastTick = Date.now();
    shiftTimers(away * 1000);
    if (away > 10) handleAway(away);
    else if (away > 0) earn(income() * away);
    refresh();
  });
  window.addEventListener('pagehide', save);
}

function start() {
  translatePage();
  syncAdDay();
  ensureQuests();
  applyTheme();
  setHtml('stage-pip', pipSvg());
  goldenAt = Date.now() + nextGoldenDelay();
  splashRun();
  setupInput();
  fitCoinScreen();
  go('coin');
  checkWhatsNew();
  openCity();
  updateCityTab();
  handbookTick(true);
  const away = (Date.now() - state.savedAt) / 1000;
  if (away > 10) handleAway(away);
  // Pip says hello once, in his own words, then the daily gift.
  const consentDone = isNativeApp() ? splashDone.then(() => new Promise(done => {
    NativeAds.asked = done;
    NativeAds.init().finally(done);
  })) : splashDone;
  if (!state.story.prologue) {
    consentDone.then(() => startWelcome());
  }
  else if (!isFresh() || state.story.diary) openModal('daily');
  if (migrationMessage) setTimeout(() => notify(migrationMessage), 700);
  save();
  setInterval(tick, 250);
  setInterval(save, 5000);
  if (isNativeApp()) {
    NativeApp.init();
    if (window.CdvPurchase) NativeStore.init();
    else document.addEventListener('deviceready', () => NativeStore.init(), { once: true });
  }
}

/* --- Fewer tabs, a clearer coin screen (3.26) --- */
// Machines and upgrades share one tab: the title, the machines, then the
// power-ups.
function renderWorkshop() {
  setHtml('upgrades-head', screenTitle(tr('POWER UP YOUR PROFITS'), tr('Upgrades'), tr('Machines earn coins for you, even while you are away. Power-ups make your taps and machines stronger.')));
  setHtml('work-tabs', workTabsHtml());
  // The tab strip stays right under the top bar while the page scrolls.
  const hud = document.querySelector('.hud');
  if (hud && hud.offsetHeight) document.documentElement.style.setProperty('--hud-h', `${hud.offsetHeight}px`);
  renderMachines();
  renderUpgrades();
  $('screen-machines').classList.toggle('work-off', workTab !== 'machines');
  $('upgrades-part').classList.toggle('work-off', workTab !== 'power');
  updateWorkDots();
}

// A tab each for the machines and the power-ups (3.26.1), so nobody has to
// scroll past all the machines to reach the power-ups.
// 3.35: Power-ups first and open by default; a hint about machines still opens Machines.
let workTab = 'power';
const BOLT_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13.6 1.8 L4.4 13.7 H11 L9.7 22.2 L19.6 9.7 H12.8 Z" fill="currentColor"/></svg>';

function workTabsHtml() {
  const tab = (id, icon, label) => `<button class="coll-tab work-tab${workTab === id ? ' active' : ''}" data-action="work-tab" data-id="${id}" role="tab" aria-selected="${workTab === id}">${icon}<span>${label}</span><i class="coll-dot work-dot" id="work-dot-${id}"></i></button>`;
  return tab('power', BOLT_SVG, tr('Power-ups')) + tab('machines', '<b class="work-glyph" aria-hidden="true">⚙</b>', tr('Machines'));
}

// A dot on the other tab when there is something to buy there: a new kind of
// machine, or any power-up.
function updateWorkDots() {
  const top = highestOwned();
  const machine = top + 1 < unlockedMachines() && state.balance >= machineCost(top + 1, 1);
  const power = upgrades.some((_, i) => upgradeUnlocked(i) && !upgradeMaxed(i) && state.balance >= upgradeCost(i));
  const m = $('work-dot-machines');
  if (m) m.classList.toggle('on', machine && workTab !== 'machines');
  const p = $('work-dot-power');
  if (p) p.classList.toggle('on', power && workTab !== 'power');
}

function workTabGo(tab) {
  workTab = tab === 'power' ? 'power' : 'machines';
  renderWorkshop();
  updatePrices();
  // Scrolled down the other list? Start this one at its top, under the strip.
  const head = $('upgrades-head');
  const hud = document.querySelector('.hud');
  if (!head) return;
  const top = head.getBoundingClientRect().bottom + window.scrollY - (hud ? hud.offsetHeight : 0);
  if (window.scrollY > top) window.scrollTo(0, Math.max(0, top));
}

// Goals open from the star at the top, with a dot when a reward waits.
function goalsWaiting() {
  return goalGroups.some(group => goalState(group).ready) || questsWaiting();
}

// Treasures and achievements share one window, a tab for each. It opens
// where something is new, or else where you were last.
let collTab = 'treasures';

function collectionTab() {
  if (treasureKinds() > state.treasuresSeen) return 'treasures';
  if (newAchievements().length) return 'achievements';
  return collTab;
}

function openCollection(tab) {
  collTab = ['achievements', 'wardrobe'].includes(tab) ? tab : 'treasures';
  if (collTab === 'achievements') {
    if (modalType !== 'ach') achNewIds = newAchievements();
    state.achievementsSeen = state.achievements.length;
  } else {
    state.treasuresSeen = treasureKinds();
  }
  openModal(collTab, true);
  updateHud();
  save();
}

function collectionTabs(tab) {
  const fresh = { treasures: treasureKinds() > state.treasuresSeen, achievements: newAchievements().length > 0, wardrobe: wardrobeNew() };
  const button = (id, icon, label) => `<button class="coll-tab${tab === id ? ' active' : ''}" data-action="open-${id}" role="tab" aria-selected="${tab === id}">${icon}<span>${label}</span>${fresh[id] && tab !== id ? '<i class="coll-dot"></i>' : ''}</button>`;
  return `<h2 id="modal-title">${tr('Collection')}<span>.</span></h2>
    <div class="coll-tabs" role="tablist">${button('treasures', CHEST_SVG, tr('Treasures'))}${button('achievements', TROPHY_SVG, tr('Achievements'))}${button('wardrobe', HANGER_SVG, tr('Wardrobe'))}</div>`;
}

// The bonus chips in the corner of the coin stage: a tap on them shows all
// of them for a few seconds.
const EFFECT_CHIPS = { max: 3, open: 6000 };
let effectsOpen = 0;

function effectsToggle() {
  effectsOpen = effectsOpen > Date.now() ? 0 : Date.now() + EFFECT_CHIPS.open;
  setHtml('effects-row', effectsHtml());
}

// Pip's next step: one line under the coin that points at the next thing to
// do, a tap away. The coin screen's own cards (levels, bosses, the portal)
// speak for themselves, so it points elsewhere. Spending coins and visiting
// the city only come up after a while away from them.
const NEXT_STEP = { spend: 60, city: 120 };
const stepSeen = { upgrades: Date.now(), city: Date.now() };
let nextStepNow = null;
let nextStepKey = '';

function stepSeenAt(...screens) {
  for (const screen of screens) {
    if (screen in stepSeen) stepSeen[screen] = Date.now();
  }
}

// The best thing to buy right now: a power-up, or more of your best machine.
function spendable() {
  const up = upgrades.findIndex((_, i) => upgradeUnlocked(i) && !upgradeMaxed(i) && state.balance >= upgradeCost(i));
  if (up >= 0) return `#upgrades-part [data-upgrade="${up}"]`;
  const top = highestOwned();
  return top >= 0 && state.balance >= machineCost(top, 1) ? `#screen-machines [data-machine="${top}"]` : '';
}

function nextStep() {
  if (boss || inDialogue) return null;
  const away = screen => (Date.now() - stepSeen[screen]) / 1000;
  const top = highestOwned();
  if (top < 0 && state.balance >= machineCost(0, 1)) return { id: 'first', text: tr('Buy your first machine'), go: 'upgrades', mark: '#screen-machines [data-machine="0"]' };
  if (top >= 0 && top + 1 < unlockedMachines() && state.balance >= machineCost(top + 1, 1)) {
    return { id: `machine${top + 1}`, text: T`New machine: ${machines[top + 1].name}`, go: 'upgrades', mark: `#screen-machines [data-machine="${top + 1}"]` };
  }
  // A new player is pointed at the coin and the machines; goals and the gift come after the first guard.
  if (goalsWaiting() && !isFresh()) return { id: 'goals', text: tr('Claim your diamonds'), go: 'goals', mark: '#screen-goals [data-action^="claim"]:not([disabled])' };
  if (!dailyInfo().claimed && !isFresh()) return { id: 'gift', text: tr('Open today\'s gift'), go: 'shop', mark: '#screen-shop [data-action="claim-daily"]' };
  if (cityNews()) return { id: 'city-new', text: T`Something new in ${CITY.name}`, go: 'city' };
  if (cityWaiting() && away('city') > NEXT_STEP.city) return { id: 'city', text: T`Visit ${CITY.name}`, go: 'city' };
  const buy = away('upgrades') > NEXT_STEP.spend && spendable();
  if (buy) return { id: 'spend', text: tr('Spend your coins'), go: 'upgrades', mark: buy };
  return null;
}

// Runs with the coin screen, four times a second; the line only changes
// when the step does, so it never moves under a finger.
function updateNextStep() {
  const box = $('coin-instruction');
  const button = $('next-step');
  if (!box || !button) return;
  const step = nextStep();
  nextStepNow = step;
  const key = step ? `${step.id}|${step.text}` : '';
  if (key === nextStepKey) return;
  nextStepKey = key;
  box.classList.toggle('stepping', !!step);
  if (!step) return;
  button.innerHTML = `<span class="next-pip">${pipSvg('happy')}</span><span class="next-text">${step.text}</span><span class="next-go" aria-hidden="true">›</span>`;
  fitLine(button.querySelector('.next-text'), 9.5);
  button.classList.remove('fresh');
  void button.offsetWidth;
  button.classList.add('fresh');
}

function nextStepGo() {
  const step = nextStepNow;
  if (!step) return;
  if (step.go === 'upgrades' && step.mark) workTab = step.mark.startsWith('#upgrades-part') ? 'power' : 'machines';
  go(step.go);
  if (step.mark) setTimeout(() => flashMark(step.mark), 80);
}

// Lights up a card for a moment and brings it into view.
function flashMark(sel) {
  const el = sel && document.querySelector(sel);
  const card = el && (el.closest('.card') || el);
  if (!card) return;
  if (card.scrollIntoView) card.scrollIntoView({ block: 'center', behavior: 'smooth' });
  card.classList.remove('hint-flash');
  void card.offsetWidth;
  card.classList.add('hint-flash');
  setTimeout(() => card.classList.remove('hint-flash'), 2600);
}

/* --- Weather in Coinbury (3.27) --- */
// The sky over the city can change every quarter of an hour: the same for
// everyone at the same time, by what the world you are in tends to bring.
// After rain or a storm comes a rainbow, for a few minutes, by day.
const WEATHER = {
  slot: 15 * 60 * 1000,
  clear: 0.42,
  rainbow: 6 * 60 * 1000,
  // The pot of gold at the end of the rainbow: this many minutes of income.
  pot: 15,
  // Lightning every few seconds in a storm; the strikes can leave bricks (at most boltMax a storm).
  bolt: [7000, 16000], boltMax: 3, boltBricks: [1, 3], boltChance: 0.6,
  // On a windy day a twister crosses the street now and then.
  twister: [14000, 26000], twisterMs: 9000, twisterW: 9, flight: 2400,
  // In a chat, each line shows this long.
  sayStep: 1300
};
// What each world's sky tends to bring (the weight of each kind).
const WEATHER_WORLDS = [
  { rain: 3, storm: 1, fog: 1, wind: 1 },
  { rain: 3, storm: 2, fog: 2, wind: 2 },
  { rain: 2, fog: 3, storm: 1, wind: 1 },
  { sand: 3, heat: 3, wind: 2 },
  { snow: 4, aurora: 3, fog: 1, wind: 1 },
  { heat: 3, storm: 2, sand: 1 },
  { aurora: 3, snow: 2, fog: 1 },
  { aurora: 3, rain: 1, wind: 1 },
  { fog: 3, rain: 2 },
  { snow: 3, wind: 2, fog: 1, storm: 1 },
  { fog: 2, sand: 2, wind: 1 },
  { fog: 3, rain: 3, storm: 1 },
  { rain: 2, wind: 2, fog: 1, storm: 1 },
  { rain: 2, heat: 2, storm: 1, wind: 1 },
  { storm: 3, fog: 2, rain: 1 },
  { aurora: 2, snow: 1, rain: 1, heat: 1 }
];
// How each kind looks in the label, and how it changes the townsfolk's pace.
const WEATHER_INFO = {
  clear: { icon: '☀️', name: tr('Sunny') },
  night: { icon: '🌙', name: tr('Clear night') },
  rain: { icon: '🌧️', name: tr('Rain'), pace: 1.3 },
  storm: { icon: '⛈️', name: tr('Thunderstorm'), pace: 1.6 },
  snow: { icon: '❄️', name: tr('Snow'), pace: 0.75 },
  fog: { icon: '🌫️', name: tr('Fog'), pace: 0.75 },
  wind: { icon: '💨', name: tr('Windy') },
  sand: { icon: '🏜️', name: tr('Sandstorm'), pace: 0.7 },
  heat: { icon: '🌡️', name: tr('Heat wave'), pace: 0.8 },
  aurora: { icon: '🌌', name: tr('Northern lights') },
  rainbow: { icon: '🌈', name: tr('Rainbow') }
};
const WEATHER_IDS = ['clear', 'rain', 'storm', 'snow', 'fog', 'wind', 'sand', 'heat', 'aurora', 'rainbow'];
const UMBRELLA_COLORS = ['#e2574c', '#3f8fe0', '#f2b134', '#5fbf6a', '#a774e0', '#ef7fb0'];
// Automated test browsers keep a clear sky unless a test asks for weather,
// so the older tests of the city see the same city as before.
let weatherForce = typeof navigator !== 'undefined' && navigator.webdriver ? 'clear' : '';
let weatherShown = '';
let weatherKey = '';
let weatherSlot = 0;
let weatherBoltAt = 0;
let twister = null;
let twisterAt = 0;
let cityPanes = [];
let boltSerial = 0;

// The kind of weather of the quarter hour around `time`.
function weatherKind(time, world = homeWorld()) {
  const slot = Math.floor(time / WEATHER.slot);
  const rand = seeded(slot * 7919 + world * 131);
  if (rand() < WEATHER.clear) return 'clear';
  const night = isNight(new Date(time));
  const options = Object.entries(WEATHER_WORLDS[world - 1] || WEATHER_WORLDS[0]).filter(([id]) => (id !== 'aurora' || night) && (id !== 'heat' || !night));
  let roll = rand() * options.reduce((sum, [, w]) => sum + w, 0);
  for (const [id, w] of options) {
    roll -= w;
    if (roll <= 0) return id;
  }
  return 'clear';
}

// The weather right now, with the rainbow that follows rain.
function weatherNow(now = Date.now(), world = homeWorld()) {
  const slot = Math.floor(now / WEATHER.slot);
  if (weatherForce) return { id: weatherForce, slot };
  let id = weatherKind(now, world);
  if (id === 'clear' && !isNight(new Date(now)) && now - slot * WEATHER.slot < WEATHER.rainbow && ['rain', 'storm'].includes(weatherKind(now - WEATHER.slot, world))) id = 'rainbow';
  return { id, slot };
}

const weatherInfo = id => (id === 'clear' && isNight() ? WEATHER_INFO.night : WEATHER_INFO[id] || WEATHER_INFO.clear);
const weatherPace = () => (WEATHER_INFO[weatherShown] && WEATHER_INFO[weatherShown].pace) || 1;
// Drops and flakes: half as many with fewer effects, none with calm motion or effects off.
const weatherCount = n => (calmMotion() || state.settings.effects === 'off' ? 0 : state.settings.effects === 'all' ? n : Math.round(n / 2));
const weatherFlashes = () => state.settings.effects === 'all' && !calmMotion();

// Four times a second with the city: a new sky when the weather changes,
// lightning in a storm and twisters on a windy day.
function weatherTick(now) {
  const view = document.querySelector('#screen-city .city-view');
  if (!view) return;
  const w = skyState(now);
  if (skyKeyOf(w) !== weatherKey) weatherSync(view, w, now);
  if (w.id === 'storm' && now >= weatherBoltAt) {
    weatherBolt(now);
    weatherBoltAt = now + WEATHER.bolt[0] + Math.random() * (WEATHER.bolt[1] - WEATHER.bolt[0]);
  }
  if (w.id === 'wind') twisterTick(now);
}

function weatherSync(view, w, now) {
  // The picture itself changes with the sky.
  const scene = view.querySelector('.city-svg');
  if (scene && skyKeyOf(w) !== sceneKey) scene.outerHTML = citySceneSvg();
  weatherShown = w.id;
  weatherKey = skyKeyOf(w);
  weatherSlot = w.slot;
  WEATHER_IDS.forEach(id => view.classList.toggle(`sky-${id}`, id === w.id));
  setHtml('city-ground', weatherGroundHtml(w));
  setHtml('city-weather', weatherFrontHtml(w));
  // What belongs in the sky goes into the picture, behind the hills and the houses.
  const svg = view.querySelector('.city-svg');
  if (svg) {
    svg.querySelectorAll('.w-skyart').forEach(el => el.remove());
    const sky = svg.querySelector('rect');
    const art = weatherSkySvg(w);
    if (sky && art) sky.insertAdjacentHTML('afterend', art);
  }
  weatherBoltAt = now + 2500;
  if (twister) twister.el.remove();
  twister = null;
  twisterAt = now + 3000;
  // A storm: everyone in the street runs for cover right away.
  if (w.id === 'storm') {
    cityPeople.forEach(p => {
      if (p.held || p.lighter || p.lifted || p.townie.classList.contains('inside')) return;
      p.steps = [];
      p.busyUntil = Math.min(p.busyUntil, now);
      p.townie.classList.remove('chat');
      p.say = null;
      sayShow(p, '');
    });
  }
}

// The label in the corner, and what falls or drifts in front of everything.
function weatherFrontHtml(w) {
  const info = weatherInfo(w.id);
  const rand = seeded(w.slot * 13 + 7);
  let html = `<span class="weather-pill"><i>${info.icon}</i>${info.name}</span>`;
  if (['rain', 'storm', 'snow', 'fog', 'sand', 'heat'].includes(w.id)) html += '<i class="w-tint"></i>';
  if (w.id === 'rain') html += weatherBits('drop', weatherCount(34), rand);
  if (w.id === 'storm') html += weatherBits('drop', weatherCount(46), rand) + '<i class="w-flash"></i>';
  if (w.id === 'snow') html += weatherBits('flake', weatherCount(30), rand);
  if (w.id === 'sand') html += weatherBits('grain', weatherCount(20), rand);
  if (w.id === 'wind') html += weatherBits('leaf', weatherCount(9), rand);
  if (w.id === 'fog') html += '<i class="w-mist m1"></i><i class="w-mist m2"></i><i class="w-mist m3"></i>';
  if (w.id === 'heat' && weatherCount(1)) html += '<i class="w-shimmer"></i>';
  // The pot of gold sits in front of the townsfolk and the pigeons, so a tap always finds it.
  if (w.id === 'rainbow' && state.city.sky.pot !== w.slot) {
    html += `<button class="w-pot" data-action="rainbow-pot" style="${cityAt(282, 244)}" aria-label="${tr('A pot of gold')}">${POT_SVG}</button>`;
  }
  return html;
}

function weatherBits(kind, n, rand) {
  let html = '';
  for (let k = 0; k < n; k++) {
    const d = { drop: 0.5 + rand() * 0.35, flake: 6 + rand() * 6, grain: 0.9 + rand() * 0.8, leaf: 3.2 + rand() * 2.6 }[kind];
    const y = kind === 'leaf' ? 42 + rand() * 50 : rand() * 96;
    html += `<i class="w-${kind}" style="--x:${r1(rand() * 104 - 2)}%;--y:${r1(y)}%;--d:${d.toFixed(2)}s;--delay:-${(rand() * d * 3).toFixed(2)}s;--s:${(0.7 + rand() * 0.6).toFixed(2)}"></i>`;
  }
  return html;
}

// On the ground: puddles, eyes at the windows, snow and a snowman.
function weatherGroundHtml(w) {
  const rand = seeded(w.slot * 17 + 3);
  let html = '';
  if (w.id === 'rain' || w.id === 'storm') {
    for (const pd of cityPuddles) html += `<i class="w-ring" style="${cityAt(pd.x + (rand() - 0.5) * pd.r, pd.y)};--delay:-${(rand() * 2).toFixed(2)}s"></i>`;
  }
  if (w.id === 'storm') {
    const panes = cityPanes.map(pane => ({ pane, r: rand() })).sort((a, b) => a.r - b.r).slice(0, 6).map(x => x.pane);
    for (const pane of panes) html += `<i class="w-eyes" style="${cityAt(pane.x, pane.y)};--w:${r1((pane.w / CITY_VIEW.w) * 100)}%;--delay:-${(rand() * 3).toFixed(2)}s"><b></b><b></b></i>`;
  }
  const s = w.stage === undefined ? skyState() : w;
  if (s.id === 'sand' && weatherCount(2)) {
    html += `<i class="w-tumble" style="--y:${r1(88 + rand() * 6)}%;--delay:-${(rand() * 5).toFixed(2)}s"><b><svg viewBox="0 0 20 20" aria-hidden="true"><g fill="none" stroke-linecap="round"><circle cx="10" cy="10" r="8.4" stroke="#8a6034" stroke-width="1.2"/><path d="M2.6 8.4q7.4 -6.2 14.6 .8M3.2 13.2q6.4 4.4 13.6 -2M6 3.2q-2.4 8.4 3.2 13.6M14.2 3.2q3.2 7.2 -2.2 13.8M2.2 10.8q8.2 -2.2 15.6 1.2M10.2 1.6q-4.2 8.2 1 16.8" stroke="#b08048" stroke-width="1"/><path d="M5 6.4q5 -2 9.6 1.4M5.4 14.8q4.6 1.2 8.8 -1.8" stroke="#d2a86c" stroke-width=".8"/></g></svg></b></i>`;
  }
  if (s.id === 'snow' || s.after === 'snow') {
    const step = s.id === 'snow' ? s.stage : 3 + s.afterStage;
    html += `<i class="w-snowman${step > 3 ? ' melting' : ''}" style="${cityAt(SNOWMAN_X, 247)}">${snowmanSvg(Math.min(step, 3))}</i>`;
  }
  return html;
}

// In the sky, behind everything else: clouds, the rainbow, the northern
// lights, the heat's big sun, a dusty sky.
function weatherSkySvg(w) {
  if (w.id === 'storm' || w.id === 'rain' || w.id === 'snow') {
    const fill = { storm: '#4c5468', rain: '#9aa4b4', snow: '#e2e7ef' }[w.id];
    let s = '<g class="w-skyart w-clouds">';
    [[-8, 32, 2.6], [56, 18, 2.2], [120, 36, 2.8], [190, 16, 2.4], [254, 34, 2.7], [322, 20, 2.3]].forEach(([x, y, k], i) => {
      s += `<g transform="translate(${x} ${y}) scale(${k})"><g class="w-cloud" style="--d:${28 + i * 6}s"><path d="M-14 3a14 7 0 0 1 4 -10a11 8 0 0 1 20 -2a12 6.5 0 0 1 26 9Z" fill="${fill}"/></g></g>`;
    });
    return `${s}</g>`;
  }
  if (w.id === 'rainbow') {
    const colors = ['#ff5f5f', '#ffa24a', '#ffe15a', '#6ed36e', '#56a8ff', '#a274ff'];
    return `<g class="w-skyart w-rainbow" fill="none" stroke-width="5.4">${colors.map((c, k) => {
      const r = 118 - k * 5.2;
      return `<path d="M${r1(250 - r)} 184A${r1(r)} ${r1(r)} 0 0 1 ${r1(250 + r)} 184" stroke="${c}"/>`;
    }).join('')}</g>`;
  }
  if (w.id === 'aurora') return AURORA_SVG;
  if (w.id === 'heat' && !isNight()) {
    const sun = skySpot();
    return `<g class="w-skyart"><circle class="w-heatglow" cx="${sun.x}" cy="${sun.y}" r="130" fill="url(#city-sun)"/></g>`;
  }
  if (w.id === 'sand') return `<g class="w-skyart"><rect width="${CITY_VIEW.w}" height="${CITY_VIEW.back}" fill="#d9a35c" opacity=".38"/></g>`;
  return '';
}

const AURORA_SVG = `<g class="w-skyart w-aurora"><defs><linearGradient id="w-aur" x1="0" x2="1"><stop offset="0" stop-color="#5dffb0" stop-opacity="0"/><stop offset=".22" stop-color="#5dffb0"/><stop offset=".55" stop-color="#5ad8ff"/><stop offset=".82" stop-color="#c29aff"/><stop offset="1" stop-color="#c29aff" stop-opacity="0"/></linearGradient>
  <filter id="w-aur-blur" x="-10%" y="-60%" width="120%" height="220%"><feGaussianBlur stdDeviation="2.4"/></filter></defs>
  <path class="w-band b1" d="M-10 56C40 26 92 64 150 36S262 10 372 42" stroke="url(#w-aur)" stroke-width="18" fill="none" filter="url(#w-aur-blur)"/>
  <path class="w-band b2" d="M-10 30C52 6 112 44 176 20S280 2 372 24" stroke="url(#w-aur)" stroke-width="11" fill="none" filter="url(#w-aur-blur)"/>
  <path class="w-band b3" d="M-10 76C60 50 130 88 200 58S300 42 372 64" stroke="url(#w-aur)" stroke-width="9" fill="none" filter="url(#w-aur-blur)"/></g>`;
const BOLT_SVG_PATH = '<svg viewBox="0 0 20 100" preserveAspectRatio="none" aria-hidden="true"><path d="M11 0L7 26L12.5 28L6 52L11.5 54L5 78L10.5 80L7.5 100" fill="none" stroke="#fffbe6" stroke-width="2.6" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></svg>';

// A storm: off to the nearest door (or out of the picture), and in again
// once it has passed.
function stormPlan(p, now) {
  const here = folkNow(p, now).x;
  const doors = ['works', 'bakery', 'gym'].filter(id => cityLevel(id) > 0).map(id => pct(FOLK_PLACES[id].door) - p.w / 2);
  const shelter = now2 => {
    if (weatherShown === 'storm' && p.lane.isConnected) {
      p.busyUntil = now2 + 1200;
      p.steps.unshift(shelter);
    }
  };
  const steps = [() => { delete p.townie.dataset.carry; }];
  if (doors.length) {
    const x = doors.reduce((best, d) => (Math.abs(d - here) < Math.abs(best - here) ? d : best));
    steps.push(now2 => folkGo(p, x, p.laneY, now2, 1.4), now2 => folkGo(p, x, FOLK.doorY, now2, 0.6), now2 => {
      p.townie.classList.add('inside');
      p.busyUntil = now2 + 800;
    }, shelter, now2 => {
      p.townie.classList.remove('inside');
      p.busyUntil = now2 + 300 + Math.random() * 1800;
    }, now2 => folkGo(p, x, p.laneY, now2, 0.5));
  } else {
    const edge = here < 45 ? -9 : 97;
    steps.push(now2 => folkGo(p, edge, p.laneY, now2, 1.4), shelter, now2 => folkGo(p, 8 + Math.random() * 78, p.laneY, now2));
  }
  p.steps = steps;
}

// A flash, a bolt and thunder a moment later; now and then a brick is left
// in the street, warm and glowing.
function weatherBolt(now) {
  const ground = $('city-ground');
  const front = $('city-weather');
  if (!ground || !front) return;
  const x = 14 + Math.random() * 332;
  const bolt = document.createElement('i');
  bolt.className = 'w-bolt';
  bolt.style.left = `${((x / CITY_VIEW.w) * 100).toFixed(2)}%`;
  bolt.innerHTML = BOLT_SVG_PATH;
  front.appendChild(bolt);
  setTimeout(() => bolt.remove(), 700);
  if (weatherFlashes()) {
    const flash = front.querySelector('.w-flash');
    if (flash) {
      flash.classList.remove('on');
      void flash.offsetWidth;
      flash.classList.add('on');
    }
    ground.querySelectorAll('.w-eyes').forEach(eyes => {
      eyes.classList.add('scared');
      setTimeout(() => eyes.classList.remove('scared'), 1600);
    });
  }
  cityPeople.forEach(q => {
    if (!q.townie.classList.contains('inside')) q.scaredUntil = now + 1600;
  });
  thunder(0.25 + Math.random() * 0.6);
  const sky = state.city.sky;
  const used = (sky.boltSlot === weatherSlot ? sky.bolts : 0) + front.querySelectorAll('.w-brick').length;
  if (used < WEATHER.boltMax && Math.random() < WEATHER.boltChance) {
    const n = WEATHER.boltBricks[0] + Math.floor(Math.random() * (WEATHER.boltBricks[1] - WEATHER.boltBricks[0] + 1));
    front.insertAdjacentHTML('beforeend', `<button class="w-brick" data-action="bolt-brick" data-id="${++boltSerial}" data-n="${n}" style="${cityAt(x, 241)}" aria-label="${tr('A brick from the lightning')}">${BRICK_ICON}</button>`);
  }
}

function boltClaim(el) {
  if (!el) return;
  const n = Math.max(1, Math.min(WEATHER.boltBricks[1], Number(el.dataset.n) || 1));
  const sky = state.city.sky;
  if (sky.boltSlot !== weatherSlot) {
    sky.boltSlot = weatherSlot;
    sky.bolts = 0;
  }
  sky.bolts++;
  addBricks(n);
  floatBricks(n, el);
  el.remove();
  sfx('bricks');
  buzz(20);
  notify(T`Bricks from the lightning: +${n}`);
  save();
}

// The pot of gold at the end of the rainbow: once for each rainbow.
function potClaim(el) {
  const w = weatherNow();
  if (el) el.remove();
  if (w.id !== 'rainbow' || state.city.sky.pot === w.slot) return;
  state.city.sky.pot = w.slot;
  const coins = giftCoins(WEATHER.pot);
  earn(coins);
  sfx('golden');
  buzz(30);
  notify(T`A pot of gold at the end of the rainbow! +✦ ${format(coins)}`);
  updateHud();
  save();
}

// Thunder: a low rumble of noise that rolls away.
function thunder(delay = 0) {
  if (!state.settings.sound || currentScreen !== 'city') return;
  const ctx = audioContext();
  if (!ctx) return;
  try {
    const now = ctx.currentTime + delay;
    const level = Math.max(0.0002, 0.16 * SFX_GAIN * volume_('soundVol'));
    const length = Math.floor(ctx.sampleRate * 2.4);
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      last = last * 0.97 + (Math.random() * 2 - 1) * 0.03;
      data[i] = last * 7;
    }
    const noise = ctx.createBufferSource();
    const low = ctx.createBiquadFilter();
    const gain = ctx.createGain();
    noise.buffer = buffer;
    low.type = 'lowpass';
    low.frequency.setValueAtTime(520, now);
    low.frequency.exponentialRampToValueAtTime(110, now + 2.2);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(level, now + 0.06);
    gain.gain.exponentialRampToValueAtTime(level * 0.45, now + 0.6);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 2.3);
    noise.connect(low);
    low.connect(gain);
    gain.connect(ctx.destination);
    noise.start(now);
  } catch (error) {
    // Thunder is a nice extra; the game works without it.
  }
}

// A twister on a windy day: it crosses the street, and whoever it meets goes
// up and around and lands in the fountain (or a bit further down the street).
function twisterTick(now) {
  const layer = $('city-weather');
  if (!layer || folkStill()) return;
  if (!twister) {
    if (now < twisterAt) return;
    const dir = Math.random() < 0.5 ? 1 : -1;
    const from = dir > 0 ? -WEATHER.twisterW - 2 : 102;
    const to = dir > 0 ? 102 : -WEATHER.twisterW - 2;
    const el = document.createElement('i');
    el.className = 'w-twister';
    el.innerHTML = '<b></b><b></b><b></b><b></b><b></b><b></b>';
    el.style.left = `${from}%`;
    layer.appendChild(el);
    void el.offsetWidth;
    el.style.transition = `left ${WEATHER.twisterMs}ms linear`;
    el.style.left = `${to}%`;
    twister = { el, from, to, dir, start: now, who: null };
    sfx('gust');
    return;
  }
  const t = (now - twister.start) / WEATHER.twisterMs;
  if (t >= 1) {
    twister.el.remove();
    twister = null;
    twisterAt = now + WEATHER.twister[0] + Math.random() * (WEATHER.twister[1] - WEATHER.twister[0]);
    return;
  }
  if (twister.who) return;
  const x = twister.from + (twister.to - twister.from) * t + WEATHER.twisterW / 2;
  for (const p of cityPeople) {
    if (p.held || p.lighter || p.lifted || p.townie.classList.contains('inside')) continue;
    const here = folkNow(p, now);
    if (Math.abs(here.y - p.laneY) > 0.6 || Math.abs(here.x + p.w / 2 - x) > 2.4) continue;
    twisterLift(p, here);
    break;
  }
}

function twisterLift(p, here) {
  twister.who = p;
  p.held = true;
  p.lifted = true;
  p.say = null;
  sayShow(p, '');
  p.townie.classList.remove('chat');
  p.townie.style.pointerEvents = 'none';
  delete p.townie.dataset.carry;
  const fountain = cityLevel('fountain') > 0;
  const x = fountain ? pct(179) - p.w / 2 : Math.max(2, Math.min(90, here.x + twister.dir * 16));
  const y = fountain ? 76 : p.laneY;
  const ms = WEATHER.flight;
  p.lane.style.transition = `transform ${ms}ms ease-in-out, top ${ms}ms ease-in-out`;
  p.lane.style.transform = `translateX(${x.toFixed(2)}%)`;
  p.lane.style.top = `${y.toFixed(2)}%`;
  p.lane.classList.remove('walking');
  p.townie.classList.add('lifted');
  p.from = p.x = x;
  p.fromY = p.y = y;
  p.dur = 0;
  setTimeout(() => twisterLand(p, fountain), ms);
}

function twisterLand(p, fountain) {
  p.townie.classList.remove('lifted');
  p.townie.style.pointerEvents = '';
  p.lifted = false;
  p.held = false;
  if (!p.lane.isConnected) return;
  const now = Date.now();
  if (fountain) {
    const ground = $('city-ground');
    if (ground) {
      ground.insertAdjacentHTML('beforeend', `<i class="w-splash" style="${cityAt(179, 212)}">${'<i></i>'.repeat(6)}</i>`);
      const splash = ground.lastElementChild;
      setTimeout(() => splash.remove(), 1000);
    }
    sfx('splash');
  } else {
    sfx('poof');
  }
  // A word about it, and back to the street.
  p.townie.classList.add('chat');
  p.say = { lines: [fountain ? '💦' : '😵'], start: now, role: 0 };
  p.busyUntil = now + 1700;
  p.steps = [() => {
    p.townie.classList.remove('chat');
    p.say = null;
    sayShow(p, '');
  }, now2 => folkGo(p, p.x, p.laneY, now2, 0.6)];
}

// What the townsfolk say to each other: emoji and little words, about the
// weather, the city, or nothing much.
const CHAT_LINES = {
  any: [['👋', '👋'], ['😄', '😂'], ['🎵', '💃'], ['❓', '🤷'], ['💰', '🤑'], ['🐦', '😊'], ['🧱', '💪'], [tr('Hi!'), tr('Hi!')]],
  pip: [[tr('Pip!'), '❤️'], ['✦', '😍']],
  rain: [['☔', '😩'], ['💧', '💧💧'], ['🌧️', '🌈?']],
  snow: [['❄️', '⛄!'], [tr('Brr!'), '🥶'], ['🥶', '☕']],
  fog: [['👀?', '🌫️'], ['👻?', '😱']],
  wind: [['💨', '🎩!'], ['🌪️', '😵']],
  sand: [['😖', '🏜️'], ['💨', '😵']],
  heat: [['🥵', '🍦'], ['☀️', '😎'], [tr('Phew!'), '🥵']],
  aurora: [['✨', '😮'], ['🌌', '💚'], [tr('Wow!'), '✨']],
  rainbow: [['🌈!', '✨'], ['🌈', '💰?'], [tr('Wow!'), '🌈']],
  night: [['🌙', '😴'], ['⭐', '✨']],
  bakery: [['🍞', '😋'], [tr('Yum!'), '🥐']],
  gym: [['💪', '🏋️']],
  market: [['🛒', '💰']],
  fountain: [['⛲', '🪙']],
  clock: [['⏰', '🏃']]
};

function chatLines() {
  const pools = [];
  const sky = CHAT_LINES[weatherShown];
  if (sky) pools.push(sky, sky);
  if (weatherShown === 'clear' && isNight()) pools.push(CHAT_LINES.night);
  ['bakery', 'gym', 'market', 'fountain', 'clock'].forEach(id => {
    if (cityLevel(id)) pools.push(CHAT_LINES[id]);
  });
  pools.push(CHAT_LINES.any, CHAT_LINES.any, CHAT_LINES.pip);
  const pool = pools[Math.floor(Math.random() * pools.length)];
  const lines = [...pool[Math.floor(Math.random() * pool.length)]];
  // Now and then the first one has the last word.
  if (Math.random() < 0.3) lines.push(['😄', '👍', '😂', '!'][Math.floor(Math.random() * 4)]);
  return lines;
}

// Whose turn it is in a chat: a line each, then a little pause.
function sayTick(p, now) {
  const k = Math.floor((now - p.say.start) / WEATHER.sayStep);
  sayShow(p, k < p.say.lines.length && k % 2 === p.say.role ? p.say.lines[k] : '');
}

function sayShow(p, line) {
  const bubble = p.townie.querySelector('.folk-say');
  if (!bubble || (bubble.dataset.line || '') === line) return;
  bubble.dataset.line = line;
  bubble.textContent = line;
  bubble.classList.toggle('text', !!line);
}

/* --- The townsfolk, drawn again (3.28) --- */
// Coins as before, with faces that live. The face sits in a slot of its own
// (data-mood), so a new mood only redraws the face. Arms, hands, clothes and
// what they hold are all in the drawing; the page shows what fits (the pose
// in data-al and data-ar, what is held in data-held, the weather on the city).
const FOLK_INK = '#3b2a1f';
const FOLK_MOUTH = '#5a1f22';
const FOLK_TONGUE = '#ff7d8e';
const FOLK_CLOTHS = ['#cf6f43', '#3f6fb0', '#c99a2e', '#2f8f83', '#9a4f8f', '#d5544a', '#5f8a3a'];
const FOLK_MITTENS = ['#e2524a', '#3f8fe0', '#f2b134', '#5fbf6a', '#a774e0', '#ef7fb0', '#f08a3a'];
const FOLK_UMBRELLAS = [['#e2574c', '#a8372f'], ['#3f8fe0', '#285f9e'], ['#f2b134', '#b07c12'], ['#5fbf6a', '#3b8a45'], ['#a774e0', '#7146a8'], ['#ef7fb0', '#b44a7a'], ['#2fb5b0', '#1e7d7a']];
const folkMetal = k => (folkLook(k).lighter ? MATERIALS[4] : MATERIALS[FOLK_METALS[(Number(k) || 0) % FOLK_METALS.length]]);
// Arms (behind the coin) and hands (in front): [class, arm, hand x, hand y].
const FOLK_ARMS = [
  ['al-down', 'M7.6 32Q4.6 35 5.2 38.6', 5.2, 39.2],
  ['al-carry', 'M7.6 31Q3.8 31.4 3.2 27.4', 3.2, 26.8],
  ['al-up', 'M7.8 27Q3.4 24 3.4 18.6', 3.4, 17.6],
  ['al-hug', 'M7.6 31Q10 35 14 34.6', 14.6, 34.4],
  ['ar-down', 'M32.4 32Q35.4 35 34.8 38.6', 34.8, 39.2],
  ['ar-wave', 'M32.2 27Q36.4 23.6 37.4 17.4', 37.6, 16.4],
  ['ar-up', 'M32.2 27Q36.6 24 36.6 18.6', 36.6, 17.6],
  ['ar-hug', 'M32.4 31Q30 35 26 34.6', 25.4, 34.4],
  ['ar-umbrella', 'M32.4 31Q36.4 29.4 35.6 24.6', 35.6, 23.8],
  ['ar-hold', 'M32.4 31Q36 29.6 35.2 25', 35.2, 24.2],
  ['ar-pole', 'M32.4 31Q36 31.4 37 28.6', 37.4, 28],
  ['ar-cane', 'M32.4 32Q35 32.6 35.2 30.4', 35.4, 30]
];

// The face for a mood: neutral, happy, talk, laugh, wow, scared, grumpy,
// sleepy, cold, squint (sand) and hot.
function folkFaceSvg(k, mood) {
  const look = folkLook(k);
  const m = folkMetal(k);
  const ink = FOLK_INK;
  const whiteBrows = look.extra === 'mustache';
  const eyesOpen = (rx = 2.95, ry = 3.55, pupil = 1.85, dy = 0.5) => {
    let whites = '';
    let pupils = '';
    let lids = '';
    for (const cx of [15.4, 24.6]) {
      whites += `<ellipse cx="${cx}" cy="25.8" rx="${rx}" ry="${ry}" fill="#fff" stroke="${m.dark}" stroke-width=".9"/>`;
      pupils += `<circle cx="${r1(cx + 0.3)}" cy="${r1(25.8 + dy)}" r="${pupil}" fill="#2a1c16"/><circle cx="${r1(cx - 0.45)}" cy="${r1(24.85 + dy)}" r="${r1(pupil * 0.38)}" fill="#fff"/>`;
      lids += `<ellipse class="lid" cx="${cx}" cy="25.8" rx="${r1(rx + 0.35)}" ry="${r1(ry + 0.35)}" fill="${m.mid}" stroke="${m.dark}" stroke-width=".9"/>`;
    }
    return `${whites}<g class="pupils">${pupils}</g>${lids}`;
  };
  const halfLids = drop => [15.4, 24.6].map(cx => `<path d="M${r1(cx - 3.25)} ${r1(25.8 + drop)}Q${cx} ${r1(21.2 + drop)} ${r1(cx + 3.25)} ${r1(25.8 + drop)}Z" fill="${m.mid}" stroke="${m.dark}" stroke-width=".9" stroke-linejoin="round"/>`).join('');
  const arcs = (d1, d2, w = 1.5) => `<path d="${d1}" stroke="${ink}" stroke-width="${w}" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="${d2}" stroke="${ink}" stroke-width="${w}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`;
  let eyes;
  if (mood === 'laugh') eyes = arcs('M12.8 26.6Q15.4 23.2 18 26.6', 'M22 26.6Q24.6 23.2 27.2 26.6');
  else if (mood === 'cold') eyes = arcs('M13 24.2L17.6 25.9L13 27.6', 'M27 24.2L22.4 25.9L27 27.6');
  else if (mood === 'squint') eyes = arcs('M12.7 26.2Q15.4 24.8 18.1 26.2', 'M21.9 26.2Q24.6 24.8 27.3 26.2', 1.6);
  else if (mood === 'scared') eyes = eyesOpen(3.3, 4.2, 1.15, 0);
  else if (mood === 'wow') eyes = eyesOpen(3.2, 3.9, 1.9, -0.4);
  else if (mood === 'sleepy') eyes = eyesOpen() + halfLids(1.2);
  else if (mood === 'hot') eyes = eyesOpen() + halfLids(0.3);
  else eyes = eyesOpen();
  const brow = d => `<path d="${d}" stroke="${whiteBrows ? '#f4f1ea' : ink}" stroke-width="${whiteBrows ? 1.9 : 1.2}" fill="none" stroke-linecap="round"/>`;
  const BROWS = {
    scared: ['M12.4 20.4Q14.6 18.4 17.2 19.6', 'M22.8 19.6Q25.4 18.4 27.6 20.4'],
    wow: ['M12.6 19.8Q15 18 17.4 19.4', 'M22.6 19.4Q25 18 27.4 19.8'],
    talk: ['M12.8 20.6Q15.2 18.8 17.6 20.2', 'M22.4 20.2Q24.8 18.8 27.2 20.6'],
    laugh: ['M12.8 20.6Q15.2 18.8 17.6 20.2', 'M22.4 20.2Q24.8 18.8 27.2 20.6'],
    squint: ['M12.6 20.4Q15.2 21 17.8 22', 'M22.2 22Q24.8 21 27.4 20.4'],
    grumpy: ['M12.6 20.4Q15.2 21 17.8 22', 'M22.2 22Q24.8 21 27.4 20.4'],
    cold: ['M12.8 21.6Q15 20 17.4 20.6', 'M22.6 20.6Q25 20 27.2 21.6'],
    sleepy: ['M12.8 21.8Q15.2 21 17.6 21.8', 'M22.4 21.8Q24.8 21 27.2 21.8'],
    hot: ['M12.8 21.8Q15.2 21 17.6 21.8', 'M22.4 21.8Q24.8 21 27.2 21.8'],
    neutral: ['M12.9 21.4Q15.2 20.8 17.5 21.3', 'M22.5 21.3Q24.8 20.8 27.1 21.4'],
    happy: ['M12.8 21.2Q15.2 19.8 17.6 20.9', 'M22.4 20.9Q24.8 19.8 27.2 21.2']
  };
  const [b1, b2] = BROWS[mood] || BROWS.happy;
  const smile = `<path d="M16.4 30.8Q20 35 23.6 30.8" stroke="${ink}" stroke-width="1.5" fill="none" stroke-linecap="round"/>`;
  const open = `<path d="M17.2 31Q20 30.4 22.8 31Q22.6 34.6 20 34.6Q17.4 34.6 17.2 31Z" fill="${FOLK_MOUTH}" stroke="${ink}" stroke-width="1"/><path d="M18.4 33.6Q20 32.4 21.6 33.6Q20 34.4 18.4 33.6Z" fill="${FOLK_TONGUE}"/>`;
  const MOUTHS = {
    talk: `<g class="m-a">${open}</g><g class="m-b"><path d="M17.4 31.8Q20 33.4 22.6 31.8" stroke="${ink}" stroke-width="1.5" fill="none" stroke-linecap="round"/></g>`,
    laugh: `<path d="M15.4 30.4H24.6Q24.4 36.2 20 36.2Q15.6 36.2 15.4 30.4Z" fill="${FOLK_MOUTH}" stroke="${ink}" stroke-width="1.1" stroke-linejoin="round"/><path d="M17.4 34.8Q20 32.6 22.6 34.8Q20 36.2 17.4 34.8Z" fill="${FOLK_TONGUE}"/><path d="M16.4 30.9H23.6" stroke="#fff" stroke-width="1" opacity=".9"/>`,
    scared: `<ellipse cx="20" cy="32.8" rx="1.6" ry="2" fill="${FOLK_MOUTH}" stroke="${ink}" stroke-width="1"/>`,
    wow: `<path d="M18 31.2Q20 30.6 22 31.2Q22 35 20 35Q18 35 18 31.2Z" fill="${FOLK_MOUTH}" stroke="${ink}" stroke-width="1"/>`,
    cold: `<path d="M16 31.8l1.33 -1.1l1.33 1.1l1.33 -1.1l1.33 1.1l1.33 -1.1l1.33 1.1" stroke="${ink}" stroke-width="1.2" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`,
    hot: `<path d="M17 31Q20 30.2 23 31Q22.8 34.4 20 34.4Q17.2 34.4 17 31Z" fill="${FOLK_MOUTH}" stroke="${ink}" stroke-width="1"/><path d="M18.5 33Q18.6 37.6 20 37.6Q21.4 37.6 21.5 33Z" fill="${FOLK_TONGUE}" stroke="#c84a5c" stroke-width=".6"/>`,
    sleepy: `<ellipse cx="20.6" cy="32.4" rx="1.2" ry="1.5" fill="${FOLK_MOUTH}"/>`,
    grumpy: `<path d="M17 32.8Q20 31.2 23 32.8" stroke="${ink}" stroke-width="1.4" fill="none" stroke-linecap="round"/>`,
    neutral: `<path d="M17.6 32.2Q20 33 22.4 32.2" stroke="${ink}" stroke-width="1.4" fill="none" stroke-linecap="round"/>`,
    squint: `<path d="M17.4 32.6Q20 31.8 22.6 32.6" stroke="${ink}" stroke-width="1.4" fill="none" stroke-linecap="round"/>`
  };
  const cheek = mood === 'neutral' || mood === 'grumpy' || mood === 'squint' ? 0.22 : ['cold', 'laugh', 'hot'].includes(mood) ? 0.62 : 0.42;
  const tint = mood === 'cold' || mood === 'hot' ? '#ff5f5f' : '#ff8f8f';
  return `<ellipse cx="11.3" cy="30.6" rx="2.3" ry="1.3" fill="${tint}" opacity="${cheek}"/><ellipse cx="28.7" cy="30.6" rx="2.3" ry="1.3" fill="${tint}" opacity="${cheek}"/>`
    + eyes + brow(b1) + brow(b2) + (MOUTHS[mood] || smile);
}

// A new mood redraws only the face.
function setFolkMood(container, mood) {
  const face = container && container.querySelector('.face');
  if (!face || face.getAttribute('data-mood') === mood) return;
  face.innerHTML = folkFaceSvg(face.getAttribute('data-k'), mood);
  face.setAttribute('data-mood', mood);
}

// Clothes for the weather; the page shows the ones that fit the sky.
const FOLK_WEAR = `<g class="wear wear-rain"><path d="M9.6 16.8Q20 5 30.4 16.8Z" fill="#ffd23f" stroke="${FOLK_INK}" stroke-width="1.3" stroke-linejoin="round"/><path d="M6 17.2Q20 13.4 33.6 15.6Q37 17.6 35.4 20.6Q30.8 17.8 20 17.6Q10 17.8 6 17.2Z" fill="#f6c21c" stroke="${FOLK_INK}" stroke-width="1.2" stroke-linejoin="round"/><path d="M13.4 12.2Q20 8.4 26.6 12.2" stroke="#fff6c8" stroke-width="1" fill="none" opacity=".8"/></g>
  <g class="wear wear-snow"><path d="M8.6 36.2Q20 41.8 31.4 36.2L31 39.8Q20 45.2 9 39.8Z" style="fill:var(--mitten)" stroke="${FOLK_INK}" stroke-width="1.2"/><path d="M12 38.4l1.4 2.4M16 39.6l1 2.4M20 40l.4 2.4M24 39.6l-.2 2.4M28 38.4l-.8 2.4" stroke="#000" stroke-opacity=".22" stroke-width=".9"/><path d="M25.6 40.6l1.6 6.4l3.2 -.8l-1.8 -6.6" style="fill:var(--mitten)" stroke="${FOLK_INK}" stroke-width="1.1" stroke-linejoin="round"/>
    <path d="M10.2 17.6C10.4 6.6 29.6 6.6 29.8 17.6Z" style="fill:var(--mitten)" stroke="${FOLK_INK}" stroke-width="1.3"/><path d="M10.4 17.2H29.6" stroke="#eef2f8" stroke-width="3" stroke-linecap="round"/><path d="M14 12.2v3M17 10.4v4.4M20 9.8v4.8M23 10.4v4.4M26 12.2v3" stroke="#000" stroke-opacity=".2" stroke-width="1" stroke-linecap="round"/><circle cx="20" cy="6.8" r="3" fill="#f2f5fb" stroke="${FOLK_INK}" stroke-width="1.1"/>
    <g class="breath"><circle cx="27.4" cy="33.4" r="1.5" fill="#fff"/><circle cx="30" cy="32" r="2.1" fill="#fff"/><circle cx="33" cy="31.2" r="1.5" fill="#fff"/></g></g>
  <g class="wear wear-sand"><path d="M7.6 26Q6.8 9.4 20 9Q33.2 9.4 32.4 26Q30.6 17.6 20 17.4Q9.4 17.6 7.6 26Z" fill="#d9a46a" stroke="${FOLK_INK}" stroke-width="1.2" stroke-linejoin="round"/>
    <path d="M8.8 28.6Q20 26.4 31.2 28.6L29.6 35.2Q20 41.2 10.4 35.2Z" style="fill:var(--cloth)" stroke="${FOLK_INK}" stroke-width="1.2" stroke-linejoin="round"/><path d="M12 31.4Q20 33.6 28 31.4M13.4 34.2Q20 36.6 26.6 34.2" stroke="#000" stroke-opacity=".24" stroke-width=".9" fill="none"/><g fill="#f6d6a8"><circle cx="15.4" cy="30.6" r=".7"/><circle cx="20" cy="31.6" r=".7"/><circle cx="24.6" cy="30.6" r=".7"/></g><path class="cloth-tail" d="M31 29.2l4.6 -.6l-.8 2.2l3.6 1.6l-3.8 .8l-3.4 -1.6Z" style="fill:var(--cloth)" stroke="${FOLK_INK}" stroke-width="1" stroke-linejoin="round"/>
    <path d="M5.4 24.4H34.6" stroke="#5a3a22" stroke-width="2.2" stroke-linecap="round"/><circle cx="15.2" cy="24.8" r="4.1" fill="#ffcf6b" fill-opacity=".55" stroke="${FOLK_INK}" stroke-width="1.5"/><circle cx="24.8" cy="24.8" r="4.1" fill="#ffcf6b" fill-opacity=".55" stroke="${FOLK_INK}" stroke-width="1.5"/><path d="M12.8 23.2q1.4 -1.6 3 -1.2M22.4 23.2q1.4 -1.6 3 -1.2" stroke="#fff" stroke-width=".9" fill="none" opacity=".9"/></g>
  <g class="wear wear-heat"><path d="M13.4 13.4C13.6 6.4 26.4 6.4 26.6 13.4Z" fill="#f2d27a" stroke="${FOLK_INK}" stroke-width="1.2"/><path d="M13.6 11.6H26.4" stroke="#e2524a" stroke-width="1.9"/><path d="M4.6 15.2Q20 10.6 35.4 15.2Q20 18.4 4.6 15.2Z" fill="#f2d27a" stroke="${FOLK_INK}" stroke-width="1.2" stroke-linejoin="round"/><path d="M8.6 14.8l1.6 .8M13 13.6l1.4 .9M27 13.6l-1.4 .9M31.4 14.8l-1.6 .8" stroke="#c9a24a" stroke-width=".8"/>
    <path class="sweat" d="M30.8 18.2q1.7 2.8 0 3.6q-1.7 -.8 0 -3.6Z" fill="#9fd6ff" stroke="#3b7fb8" stroke-width=".6"/><path class="sweat s2" d="M8.8 21.2q1.3 2.1 0 2.8q-1.3 -.7 0 -2.8Z" fill="#9fd6ff" stroke="#3b7fb8" stroke-width=".6"/></g>`;

// What they hold in the right hand: an umbrella, a lantern, an ice cream, a
// shovel or a broom.
function folkHeld([color, dark]) {
  const [hx, hy] = [35.6, 23.8];
  const top = [hx - 9.4, -4.6];
  const ang = r1(Math.atan2(top[1] - hy, top[0] - hx) * 180 / Math.PI + 90);
  return `<g class="held held-umbrella"><path d="M${hx} ${r1(hy + 3.6)}q0 2.6 -2.4 2.4" stroke="${FOLK_INK}" stroke-width="1.3" fill="none" stroke-linecap="round"/><path d="M${hx} ${r1(hy + 3.6)}L${r1(top[0])} ${top[1]}" stroke="${FOLK_INK}" stroke-width="1.1"/>
    <g transform="translate(${r1(top[0])} ${top[1]}) rotate(${ang})"><g class="canopy"><path d="M-15 6Q-14 -6 0 -7Q14 -6 15 6Q12.5 4 10 6Q7.5 4 5 6Q2.5 4 0 6Q-2.5 4 -5 6Q-7.5 4 -10 6Q-12.5 4 -15 6Z" fill="${color}" stroke="${FOLK_INK}" stroke-width="1.1" stroke-linejoin="round"/>
      <path d="M0 -7Q-4.6 -1 -5 6M0 -7Q4.6 -1 5 6M0 -7Q-10.6 -2 -10 6M0 -7Q10.6 -2 10 6" stroke="${dark}" stroke-width=".8" fill="none"/><path d="M-11.6 -1.4Q-6 -6 0 -6.2" stroke="#fff" stroke-width="1" fill="none" opacity=".55" stroke-linecap="round"/><path d="M0 -7v-2.6" stroke="${FOLK_INK}" stroke-width="1.2" stroke-linecap="round"/></g></g></g>
    <g class="held held-lantern"><circle class="lantern-glow" cx="35.6" cy="30.6" r="7.6" fill="#ffd36b" opacity=".4"/><path d="M35.2 24.4v2" stroke="${FOLK_INK}" stroke-width="1"/><path d="M33 26.4h4.6l.8 1.4h-6.2Z" fill="#5a4636" stroke="${FOLK_INK}" stroke-width=".8" stroke-linejoin="round"/><path d="M33.1 27.8h5.4l-.6 5.8h-4.2Z" fill="#ffe08a" stroke="${FOLK_INK}" stroke-width="1" stroke-linejoin="round"/><path d="M35.8 32.4q-1.4 -1.5 0 -3.4q1.4 1.9 0 3.4Z" fill="#ff9a3c"/><path d="M33.4 33.7h4.6" stroke="${FOLK_INK}" stroke-width="1.4" stroke-linecap="round"/></g>
    <g class="held held-icecream"><path d="M35.2 31.6l-2.2 -6.4h4.4Z" fill="#e8b46a" stroke="${FOLK_INK}" stroke-width="1" stroke-linejoin="round"/><path d="M33.8 26.6l2.4 2.6M34.4 28.6l1.4 -1.6" stroke="#b9853f" stroke-width=".6"/><circle cx="35.2" cy="23.2" r="3" fill="#ff9fc0" stroke="${FOLK_INK}" stroke-width="1"/><path d="M33 23.6q1 1.6 2.2 0q1.2 1.6 2.2 0" stroke="#e8709a" stroke-width=".7" fill="none"/></g>
    <g class="held held-shovel"><path d="M35.2 24.2L38.4 42" stroke="#8a5a32" stroke-width="1.6" stroke-linecap="round"/><path d="M36 41.6l5 -.9l.9 4.6q-2.4 2.4 -5 .9Z" fill="#9aa4ae" stroke="${FOLK_INK}" stroke-width="1" stroke-linejoin="round"/><path d="M33.8 24.4h2.8" stroke="${FOLK_INK}" stroke-width="1.4" stroke-linecap="round"/></g>
    <g class="held held-broom"><path d="M35.2 24.2L37.6 41" stroke="#a87444" stroke-width="1.5" stroke-linecap="round"/><path d="M35.2 40.8l4.8 -.6l2 6.2l-7.4 .8Z" fill="#e3c36a" stroke="${FOLK_INK}" stroke-width="1" stroke-linejoin="round"/><path d="M36.4 42l.4 4.2M38 41.8l.8 4.2M39.4 41.4l1.2 4.2" stroke="#b5933e" stroke-width=".6"/></g>`;
}

/* --- The weather in the city itself (3.28) --- */
// The sky right now: the weather, how far it has come (0, 1, 2: it builds up
// over the quarter hour), and what is left of the one before (snow and sand
// stay a while, puddles dry up). Tests can set the stage and what came before.
const SKY = { after: 10, stages: [3, 8] };
let weatherStageForce = null;
let weatherAfterForce = '';
let citySky = { id: 'clear', slot: 0, stage: 0, after: '', afterStage: 0 };
let sceneKey = '';
let scenePaint = null;
let cityPuddles = [];
const SNOWMAN_X = 16;

function skyState(now = Date.now()) {
  const w = weatherNow(now);
  const into = (now - w.slot * WEATHER.slot) / 60000;
  const stage = weatherStageForce !== null ? weatherStageForce : into < SKY.stages[0] ? 0 : into < SKY.stages[1] ? 1 : 2;
  let after = '';
  let afterStage = 0;
  if (!['snow', 'sand', 'rain', 'storm'].includes(w.id) && (weatherForce || into < SKY.after)) {
    const before = weatherForce ? weatherAfterForce : weatherKind(now - WEATHER.slot);
    if (['snow', 'sand', 'rain', 'storm'].includes(before)) {
      after = before === 'storm' ? 'rain' : before;
      afterStage = weatherStageForce !== null ? Math.min(1, weatherStageForce) : into < SKY.after / 2 ? 0 : 1;
    }
  }
  return { id: w.id, slot: w.slot, stage, after, afterStage };
}
const skyKeyOf = s => `${s.id}|${s.slot}|${s.stage}|${s.after}|${s.afterStage}|${isNight()}`;

// How the weather paints the city: the sky, the hills, the lawn and the street.
function skyPaint(sky) {
  const night = isNight();
  const p = {
    skyTop: night ? '#0d1438' : '#74bfee', skyLow: night ? '#33427c' : '#d8f1ff',
    far: '#bfe2c4', farLine: '#a6d2a8', near: '#a3d68f', lawn: '#7cc66f', tuft: 'rgba(47, 106, 42, .3)',
    walk: '#e9dcc0', slab: '#d3c3a1', street: '#d9c8a4', curb: '#bfab84', tones: ['#cdb990', '#c4ae84', '#d4c29b'], cobble: '#b49e74', leaf: '', leafMix: 0
  };
  const mix = (to, t) => {
    for (const [k, v] of Object.entries(to)) p[k] = Array.isArray(v) ? v.map((c, i) => mixHex(p[k][i], c, t)) : mixHex(p[k], v, t);
  };
  const grow = [0.55, 0.8, 1][sky.stage] || 1;
  const left = sky.afterStage ? 0.35 : 0.65;
  if (sky.id === 'snow' || sky.after === 'snow') mix({ far: '#eef3f8', farLine: '#d6e0ea', near: '#e6edf4', lawn: '#f1f5fa', walk: '#f4f7fb', slab: '#dde5ee' }, sky.id === 'snow' ? grow : left);
  if (sky.id === 'sand' || sky.after === 'sand') mix({ far: '#ecd3a0', farLine: '#d9b97e', near: '#e3c088', lawn: '#d8c088', walk: '#ead7ab', slab: '#d9be8a' }, sky.id === 'sand' ? grow : left);
  if (sky.id === 'heat') mix({ far: '#dfe5ad', farLine: '#cdd690', near: '#cfd581', lawn: '#b9c765' }, 0.8);
  if (sky.id === 'rain' || sky.id === 'storm') mix({ far: '#a7cdb0', near: '#8cc27c', lawn: '#69b25d', street: '#b4a37e', curb: '#9a8862', tones: ['#a99775', '#9e8b69', '#b2a07c'], cobble: '#8c7a56' }, 1);
  if (sky.after === 'rain') mix({ street: '#c8b892', tones: ['#bdab84', '#b4a17a', '#c6b48c'], cobble: '#a08d68' }, sky.afterStage ? 0.4 : 0.8);
  const SKIES = { rain: ['#8d9bb0', '#c9d3df', '#121a33', '#2a3352'], storm: ['#5b6478', '#9aa3b4', '#0a0f22', '#1c2440'], snow: ['#b9c7d8', '#eef3f9', '#1a2440', '#3c4a6e'],
    fog: ['#c9d2dc', '#eef1f4', '#1a2238', '#3a4258'], sand: ['#d9a865', '#f2d6a2', '#3a2a24', '#6a4a36'], heat: ['#8fc8ef', '#fff4d6', '#0d1438', '#33427c'] };
  const sk = SKIES[sky.id];
  if (sk) {
    p.skyTop = night ? sk[2] : sk[0];
    p.skyLow = night ? sk[3] : sk[1];
  }
  if (sky.id === 'sand' || sky.after === 'sand') Object.assign(p, { leaf: '#b9a46a', leafMix: sky.id === 'sand' ? 0.45 : 0.25 });
  if (sky.id === 'heat') Object.assign(p, { leaf: '#a9b64e', leafMix: 0.4 });
  return p;
}
const sceneLeaf = color => (scenePaint && scenePaint.leaf ? mixHex(color, scenePaint.leaf, scenePaint.leafMix) : color);

// Snow on every top edge: what lies on a roof, a chimney, a sill, a lamp or a
// branch. The edges are where the drawing has nothing just above it.
function snowCapFilter(sky) {
  const sand = sky.id === 'sand' || sky.after === 'sand';
  const depth = sand ? (sky.id === 'sand' ? [0.9, 1.5, 2.1][sky.stage] : [1.3, 0.8][sky.afterStage])
    : sky.id === 'snow' ? [1.3, 2.1, 2.9][sky.stage] : [1.7, 1][sky.afterStage];
  const [shade, top] = sand ? ['#b98a4a', '#efd49c'] : ['#9fb6d2', '#fbfdff'];
  return `<filter id="snow-cap" x="-6%" y="-14%" width="112%" height="124%" color-interpolation-filters="sRGB">
    <feOffset in="SourceAlpha" dy="${depth}" result="down"/>
    <feComposite in="SourceAlpha" in2="down" operator="out" result="top"/>
    <feMorphology in="top" operator="dilate" radius=".45" result="fat"/>
    <feGaussianBlur in="fat" stdDeviation=".35" result="soft"/>
    <feComponentTransfer in="soft" result="cap"><feFuncA type="table" tableValues="0 1 1 1"/></feComponentTransfer>
    <feFlood flood-color="${shade}" result="blue"/><feComposite in="blue" in2="cap" operator="in" result="shade"/><feOffset in="shade" dy=".8" result="under"/>
    <feFlood flood-color="${top}" result="white"/><feComposite in="white" in2="cap" operator="in" result="snow"/><feOffset in="snow" dy="-.5" result="lift"/>
    <feMerge><feMergeNode in="SourceGraphic"/><feMergeNode in="under"/><feMergeNode in="lift"/></feMerge></filter>`;
}

// Snow or sand piled up against a building: higher at the corners and by the
// door, a low ridge along the front.
function sceneDrift(x0, w, base, sky) {
  const snow = sky.id === 'snow' || sky.after === 'snow';
  const sand = sky.id === 'sand' || sky.after === 'sand';
  if (!snow && !sand) return '';
  const now = sky.id === 'snow' || sky.id === 'sand';
  const h = now ? (snow ? [1.6, 3, 4.4] : [2.6, 4.6, 6.6])[sky.stage] : (snow ? [3, 1.4] : [3.8, 2])[sky.afterStage];
  if (sand) {
    const x1 = x0 + w;
    return `<path d="M${r1(x0 - 7)} ${base}Q${r1(x0 - 2.4)} ${r1(base - h * 1.75)} ${r1(x0 + 5)} ${r1(base - h * 1.2)}Q${r1(x0 + w * 0.3)} ${r1(base - h * 0.42)} ${r1(x0 + w * 0.64)} ${r1(base - h * 0.2)}Q${r1(x1 - 3)} ${r1(base - h * 0.62)} ${r1(x1 + 3)} ${base}Z" fill="#e9cc8e" stroke="#c9a25e" stroke-width=".7" stroke-linejoin="round"/>`
      + strokes(`M${r1(x0 - 3.6)} ${r1(base - h * 1.3)}q2.8 -1.7 6.4 -.5`, '#f8e6bc', 0.8)
      + strokes(`M${r1(x0 + 1)} ${r1(base - h * 0.7)}q3 -1.1 6.4 -.1M${r1(x0 + w * 0.32)} ${r1(base - h * 0.24)}q4 -1 8 0M${r1(x1 - 6)} ${r1(base - h * 0.3)}q2.4 -.9 4.8 0`, '#d4ae6c', 0.6);
  }
  const [fill, edge] = snow ? ['#f6f9fd', '#c4d2e2'] : ['#e9cc8e', '#c9a25e'];
  const x1 = x0 + w;
  let s = `<path d="M${r1(x0 - 4)} ${base}Q${r1(x0 + 1)} ${r1(base - h * 1.1)} ${r1(x0 + 9)} ${r1(base - h * 0.4)}Q${r1(x0 + w / 2)} ${r1(base - h * 0.2)} ${r1(x1 - 9)} ${r1(base - h * 0.45)}Q${r1(x1 - 1)} ${r1(base - h * 1.15)} ${r1(x1 + 4)} ${base}Z" fill="${fill}" stroke="${edge}" stroke-width=".6"/>`;
  if (sand) s += strokes(`M${r1(x0 + 1)} ${r1(base - h * 0.5)}q3 -1 6 0M${r1(x1 - 8)} ${r1(base - h * 0.55)}q3 -1 6 0`, '#d4ae6c', 0.6);
  return s;
}

// The shutters close in a storm: two halves over each window, a crack between
// them for the eyes. The windows behind them stay dark.
function stormShutters(p) {
  let s = '';
  for (const l of p.lights) {
    if ((l.kind !== 'pane' && l.kind !== 'arch') || l.w < 4 || l.h < 4) continue;
    l.lit = false;
    const half = r1(l.w / 2 - 0.35);
    for (const x of [l.x - 0.5, l.x + l.w / 2 + 0.35]) {
      s += `<path d="M${r1(x)} ${r1(l.y - 0.6)}h${r1(half + 0.5)}v${r1(l.h + 1.2)}h${r1(-half - 0.5)}Z" fill="#8a6440" stroke="${CITY_INK}" stroke-width=".6"/>`;
      let slats = '';
      for (let y = l.y + 1.4; y < l.y + l.h; y += 1.8) slats += `M${r1(x + 0.6)} ${r1(y)}h${r1(half - 0.7)}`;
      s += strokes(slats, '#6a4a2e', 0.5);
    }
  }
  return s;
}

// The street with the weather on it: snow with tracks, sand with ripples,
// wet stones with puddles and the lamps shining in them.
function sceneStreet(sky, night) {
  const { w: W, h: H, front } = CITY_VIEW;
  let s = '';
  const snow = sky.id === 'snow' || sky.after === 'snow';
  const sand = sky.id === 'sand' || sky.after === 'sand';
  const rain = sky.id === 'rain' || sky.id === 'storm';
  cityPuddles = [];
  if (snow) {
    const cover = sky.id === 'snow' ? [0.55, 0.78, 0.93][sky.stage] : [0.6, 0.32][sky.afterStage];
    s += `<rect x="0" y="${front - 1}" width="${W}" height="${H - front + 1}" fill="#f5f8fc" opacity="${cover}"/>`;
    s += strokes(`M0 236Q60 233 120 236.6T240 235.4T360 236.2M0 241Q70 238.6 140 241.6T280 240.2T360 241`, '#c9d6e4', 1.1);
    if (sky.after === 'snow') s += `<rect x="0" y="${front + 6}" width="${W}" height="10" fill="#cbd7e3" opacity=".35"/>`;
  }
  if (sand) {
    const cover = sky.id === 'sand' ? [0.4, 0.64, 0.84][sky.stage] : [0.55, 0.3][sky.afterStage];
    s += `<rect x="0" y="${front - 1}" width="${W}" height="${H - front + 1}" fill="#e6c98e" opacity="${cover}"/>`;
    let ripples = '';
    for (let y = front + 6; y < H; y += 6.5) for (let x = (y * 7) % 23; x < W; x += 34) ripples += `M${x} ${y}q4 -1.6 8 0q4 1.6 8 0`;
    s += strokes(ripples, '#cfa966', 0.6).replace('<path', `<path opacity="${cover}"`);
  }
  if (sky.after === 'snow' || sky.after === 'sand') {
    const [fill, edge, lit] = sky.after === 'snow' ? ['#f7fafd', '#bfcddd', '#ffffff'] : ['#e9cc8e', '#c9a25e', '#f8e6bc'];
    const big = sky.afterStage ? 0.72 : 1;
    for (const [x, r] of [[64, 9], [152, 7], [262, 8.4], [338, 10]]) {
      const k = r * big;
      s += `<path d="M${r1(x - k)} ${front + 3}Q${r1(x - k * 0.7)} ${r1(front + 3 - k * 0.8)} ${r1(x)} ${r1(front + 3 - k * 0.78)}Q${r1(x + k * 0.8)} ${r1(front + 3 - k * 0.7)} ${r1(x + k)} ${front + 3}Z" fill="${fill}" stroke="${edge}" stroke-width=".7"/>`
        + strokes(`M${r1(x - k * 0.6)} ${r1(front + 3 - k * 0.5)}q${r1(k * 0.4)} ${r1(-k * 0.3)} ${r1(k * 0.8)} -.2`, lit, 0.8);
    }
  }
  if (rain || sky.after === 'rain') {
    // Puddles: where they form is the same all through one rain.
    const rand = seeded((sky.after ? sky.slot - 1 : sky.slot) * 31 + 5);
    const grow = rain ? [0.5, 0.8, 1][sky.stage] : [0.7, 0.4][sky.afterStage];
    for (let k = 0; k < 4; k++) {
      const pd = { x: r1(24 + k * 84 + rand() * 50), y: r1(231 + rand() * 13), r: r1(7 + rand() * 6) };
      cityPuddles.push(pd);
      const rx = r1(pd.r * grow);
      const ry = r1(rx * 0.24);
      s += `<ellipse cx="${pd.x}" cy="${pd.y}" rx="${rx}" ry="${ry}" fill="${night ? '#34406c' : '#93abc4'}" opacity=".92"/><ellipse cx="${r1(pd.x - rx * 0.18)}" cy="${r1(pd.y - ry * 0.2)}" rx="${r1(rx * 0.6)}" ry="${r1(ry * 0.5)}" fill="${night ? '#55649c' : '#c6dcef'}" opacity=".85"/>`
        + strokes(`M${r1(pd.x - rx * 0.55)} ${r1(pd.y - ry * 0.1)}q${r1(rx * 0.25)} ${r1(-ry * 0.5)} ${r1(rx * 0.5)} 0`, '#ffffff', 0.6);
    }
    if (rain) {
      s += `<rect x="0" y="${front}" width="${W}" height="${H - front}" fill="#1e2a44" opacity="${night ? 0.3 : 0.12}"/>`;
      // The lamps shine on the wet stones.
      for (const x of [76, 147, 211, 285]) s += `<rect x="${x - 3}" y="${front + 2}" width="6" height="${H - front - 2}" fill="url(#wet-glow)" opacity="${night ? 0.8 : 0.35}"/>`;
    }
  }
  return s;
}

// The snowman the children build: a ball, two, then a head with a hat and a
// carrot nose.
function snowmanSvg(step) {
  const ball = (cx, cy, r) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="#fbfdff" stroke="#bccadc" stroke-width="1"/><path d="M${cx - r * 0.6} ${cy + r * 0.45}q${r * 0.6} ${r * 0.35} ${r * 1.2} 0" stroke="#dbe5f0" stroke-width="1.2" fill="none"/>`;
  let s = '<svg viewBox="0 0 30 42" overflow="visible" aria-hidden="true"><ellipse cx="15" cy="40.5" rx="11" ry="1.6" fill="rgba(59,42,31,.18)"/>';
  s += ball(15, 30.5, 9.5);
  if (step >= 1) s += ball(15, 16, 6.6);
  if (step >= 2) s += `<path d="M6.4 26.6L1.6 22.4M23.6 26.6l4.8 -4.2M3.4 24l-1.2 -2.6M26.6 24l1.2 -2.6" stroke="#7a5638" stroke-width="1.1" stroke-linecap="round"/><circle cx="15" cy="27.4" r=".9" fill="#3b2a1f"/><circle cx="15" cy="31.2" r=".9" fill="#3b2a1f"/>`;
  if (step >= 2) s += `<circle cx="12.6" cy="14.8" r=".95" fill="#3b2a1f"/><circle cx="17.4" cy="14.8" r=".95" fill="#3b2a1f"/><path d="M15 16.6l5.4 1.2 -5.4 .9Z" fill="#f08a3a"/><path d="M12 19.2q3 1.6 6 0" stroke="#3b2a1f" stroke-width=".8" fill="none" stroke-linecap="round"/>`;
  if (step >= 3) s += `<path d="M8.2 9.6h13.6M10.6 9.6V3.2h8.8V9.6" fill="#3b2a1f" stroke="#3b2a1f" stroke-width="1.6" stroke-linejoin="round"/><path d="M10.4 7.6h9.2" stroke="#d94b4b" stroke-width="1.3"/><path d="M9.6 21.4q5.4 2.6 10.8 0" stroke="#d94b4b" stroke-width="2" fill="none" stroke-linecap="round"/>`;
  return `${s}</svg>`;
}

// The pot of gold at the end of the rainbow: an iron pot with the gold in it,
// in front of the back of the rim and behind the front, in rainbow light.
const POT_SVG = `<svg viewBox="0 0 64 58" overflow="visible" aria-hidden="true"><defs>
    <radialGradient id="pg-glow" cx=".5" cy=".55" r=".5"><stop offset="0" stop-color="#fff0b0" stop-opacity=".9"/><stop offset="1" stop-color="#fff0b0" stop-opacity="0"/></radialGradient>
    <linearGradient id="pg-iron" x1="0" x2="1"><stop offset="0" stop-color="#6a6476"/><stop offset=".28" stop-color="#3a3542"/><stop offset=".7" stop-color="#25212c"/><stop offset="1" stop-color="#17141c"/></linearGradient>
    <linearGradient id="pg-gold" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff6c4"/><stop offset=".45" stop-color="#ffd24d"/><stop offset="1" stop-color="#c8860f"/></linearGradient>
    <linearGradient id="pg-coin" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff8d0"/><stop offset=".5" stop-color="#ffc93a"/><stop offset="1" stop-color="#d18d12"/></linearGradient>
    <linearGradient id="pg-beam" x1="0" x2="1"><stop offset="0" stop-color="#ff5f5f"/><stop offset=".2" stop-color="#ffa24a"/><stop offset=".4" stop-color="#ffe15a"/><stop offset=".6" stop-color="#6ed36e"/><stop offset=".8" stop-color="#56a8ff"/><stop offset="1" stop-color="#a274ff"/></linearGradient>
    <linearGradient id="pg-beam-fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#fff" stop-opacity="1"/></linearGradient>
    <mask id="pg-beam-mask"><rect x="0" y="-30" width="64" height="60" fill="url(#pg-beam-fade)"/></mask></defs>
    <rect x="20" y="-30" width="24" height="52" fill="url(#pg-beam)" opacity=".38" mask="url(#pg-beam-mask)"/>
    <ellipse cx="32" cy="30" rx="31" ry="25" fill="url(#pg-glow)"/>
    <ellipse cx="32" cy="54.6" rx="21" ry="2.8" fill="#000" opacity=".25"/>
    <path d="M17.4 47.6l-2.6 6.2h5.4l1.8 -5ZM46.6 47.6l2.6 6.2h-5.4l-1.8 -5ZM30 50.6l-.6 4.4h5.2l-.6 -4.4Z" fill="#1d1a22" stroke="#0e0c12" stroke-width="1" stroke-linejoin="round"/>
    <ellipse cx="32" cy="24.6" rx="24" ry="5.6" fill="#141118"/>
    <path d="M8 24.6Q32 14.2 56 24.6" stroke="#3a3542" stroke-width="3.4" fill="none" stroke-linecap="round"/>
    <path d="M10.6 25.4Q11.6 12.4 32 11.4Q52.4 12.4 53.4 25.4Q32 32 10.6 25.4Z" fill="url(#pg-gold)" stroke="#9a6410" stroke-width="1.1"/>
    <g stroke="#a86e12" stroke-width=".9"><ellipse cx="21.6" cy="17.2" rx="5.4" ry="2.5" fill="url(#pg-coin)" transform="rotate(-12 21.6 17.2)"/><ellipse cx="42.2" cy="18" rx="5.2" ry="2.4" fill="url(#pg-coin)" transform="rotate(14 42.2 18)"/><ellipse cx="31.4" cy="13.8" rx="5.6" ry="2.6" fill="url(#pg-coin)"/><ellipse cx="36.6" cy="9.4" rx="3.2" ry="5.8" fill="url(#pg-coin)" transform="rotate(18 36.6 9.4)"/><ellipse cx="26.4" cy="22.2" rx="5" ry="2.3" fill="url(#pg-coin)" transform="rotate(6 26.4 22.2)"/><ellipse cx="37.8" cy="23" rx="4.6" ry="2.1" fill="url(#pg-coin)" transform="rotate(-8 37.8 23)"/></g>
    <g fill="#b07612"><path d="M31.4 12.2l.5 1.1l1.1 .5l-1.1 .5l-.5 1.1l-.5 -1.1l-1.1 -.5l1.1 -.5Z"/><path d="M21.6 15.6l.45 1l1 .45l-1 .45l-.45 1l-.45 -1l-1 -.45l1 -.45Z"/><path d="M42.2 16.4l.45 1l1 .45l-1 .45l-.45 1l-.45 -1l-1 -.45l1 -.45Z"/></g>
    <path d="M8 24.6Q32 34.8 56 24.6Q57.8 50 32 50Q6.2 50 8 24.6Z" fill="url(#pg-iron)" stroke="#0e0c12" stroke-width="1.6" stroke-linejoin="round"/>
    <path d="M13.4 31.4Q13.8 42.4 21.4 46.6" stroke="#9a94a6" stroke-width="2.2" fill="none" opacity=".55" stroke-linecap="round"/>
    <path d="M8.6 28.4q-4.6 .6 -4 5.4q.8 3.2 4.4 2.2M55.4 28.4q4.6 .6 4 5.4q-.8 3.2 -4.4 2.2" stroke="#0e0c12" stroke-width="2.4" fill="none" stroke-linecap="round"/>
    <path d="M7.6 24.6Q32 35.4 56.4 24.6" stroke="#4a4554" stroke-width="3.8" fill="none" stroke-linecap="round"/>
    <path d="M11.4 26.8Q32 34.4 52.6 26.8" stroke="#8d879a" stroke-width=".9" fill="none" opacity=".8"/>
    <g class="pot-sparks" fill="#fffbe0"><path d="M9 6l1 2.6l2.6 1l-2.6 1l-1 2.6l-1 -2.6l-2.6 -1l2.6 -1Z"/><path d="M53.4 2.6l.8 2l2 .8l-2 .8l-.8 2l-.8 -2l-2 -.8l2 -.8Z"/><path d="M48.4 15.8l.6 1.5l1.5 .6l-1.5 .6l-.6 1.5l-.6 -1.5l-1.5 -.6l1.5 -.6Z"/></g></svg>`;

/* --- The townsfolk live (3.28) --- */
// Each has a temper: some smile easily, some are calm, some a bit grumpy in
// the rain, some get sleepy late at night.
const FOLK_TEMPERS = ['cheery', 'calm', 'grumpy', 'cheery', 'calm', 'sleepy', 'calm', 'cheery', 'grumpy'];

// Their faces, arms and what they hold, by what is going on.
function folkLooks(now) {
  for (const p of cityPeople) {
    if (p.friend || p.townie.classList.contains('inside')) continue;
    const mood = folkMoodFor(p, now);
    setFolkMood(p.townie, mood);
    folkPose(p, mood, now);
    if (p.townie.classList.contains('talk')) {
      const face = $('talk-face');
      if (face) setFolkMood(face, mood);
    }
  }
}

function folkMoodFor(p, now) {
  if (p.lifted || p.scaredUntil > now) return 'scared';
  if (p.townie.classList.contains('talk')) return p.townie.classList.contains('typing') ? 'talk' : 'happy';
  if (p.greetUntil > now) return 'laugh';
  if (p.say) {
    const k = Math.floor((now - p.say.start) / WEATHER.sayStep);
    if (k < p.say.lines.length && k % 2 === p.say.role) return 'talk';
    return p.temper === 'grumpy' ? 'neutral' : p.temper === 'cheery' || p.kid ? 'laugh' : 'happy';
  }
  const walking = p.lane.classList.contains('walking');
  switch (weatherShown) {
    case 'storm': return 'scared';
    case 'sand': return 'squint';
    case 'heat': return 'hot';
    case 'snow': return p.kid ? 'happy' : walking ? 'neutral' : 'cold';
    case 'rain': return p.kid ? 'happy' : p.temper === 'grumpy' ? 'grumpy' : 'neutral';
    case 'aurora': case 'rainbow': return walking ? 'happy' : 'wow';
    default: break;
  }
  const hour = new Date().getHours();
  if ((hour >= 22 || hour < 6) && p.temper === 'sleepy' && !walking) return 'sleepy';
  return p.kid || p.temper === 'cheery' ? 'happy' : 'neutral';
}

// What they hold in the weather: a lantern in the fog, an ice cream in the
// heat, a shovel after the snow and a broom after the sand.
function folkHeldFor(p) {
  if (weatherShown === 'fog' && p.i % 2 === 0) return 'lantern';
  if (weatherShown === 'heat' && p.i % 3 !== 1) return 'icecream';
  if (citySky.after === 'snow' && !p.kid && p.i % 2 === 1) return 'shovel';
  if (citySky.after === 'sand' && !p.kid && p.i % 2 === 0) return 'broom';
  return '';
}

function folkPose(p, mood, now) {
  const t = p.townie;
  const carry = !!t.dataset.carry && t.dataset.carry !== 'pole';
  const walking = p.lane.classList.contains('walking');
  let al = carry ? 'carry' : 'down';
  let ar = p.lighter ? 'pole' : p.cane ? 'cane' : 'down';
  let held = '';
  if (mood === 'scared') {
    if (!carry) al = 'up';
    if (!p.lighter) ar = 'up';
  } else if (p.greetUntil > now) {
    if (!p.lighter) ar = 'wave';
  } else if ((weatherShown === 'rain' || weatherShown === 'storm') && !p.lighter) {
    ar = 'umbrella';
  } else if (weatherShown === 'snow' && !walking && !carry && !p.lighter && !p.kid) {
    al = 'hug';
    ar = 'hug';
  } else if (mood === 'wow' && !p.lighter) {
    ar = 'wave';
  } else if (!p.lighter) {
    held = folkHeldFor(p);
    if (held) ar = 'hold';
  }
  if (t.dataset.al !== al) t.dataset.al = al;
  if (t.dataset.ar !== ar) t.dataset.ar = ar;
  if ((t.dataset.held || '') !== held) t.dataset.held = held;
  const look = p.say ? 'side' : mood === 'wow' ? 'up' : '';
  if ((t.dataset.look || '') !== look) t.dataset.look = look;
}

// A splash where a child jumps into a puddle.
function puddleSplash(pd) {
  const ground = $('city-ground');
  if (!ground) return;
  ground.insertAdjacentHTML('beforeend', `<i class="w-splash" style="${cityAt(pd.x, pd.y)}">${'<i></i>'.repeat(6)}</i>`);
  const splash = ground.lastElementChild;
  setTimeout(() => splash.remove(), 1000);
}

/* --- The worlds as little planets (3.29) --- */
// Every world is a small round planet with its own landmarks on top, like a
// toy globe: drawn for the journey from one world to the next. The ground
// turns slowly under the landmarks, and the little things on it move.
const PLANET_R = 40;
const PL_INK = '#2a1c14';
let planetUid = 0;

// Something standing on the planet, at an angle from the top (negative is left).
const plOn = (angle, body, s = 1.4) => `<g transform="rotate(${angle}) translate(0 ${-PLANET_R + 0.8}) scale(${s})">${body}</g>`;
// A four-pointed sparkle.
const plSpark = (x, y, r, fill, cls = 'pl-twinkle', delay = 0) => `<path class="${cls}" style="animation-delay:-${delay}s" d="M${x} ${r1(y - r)}Q${r1(x + r * 0.18)} ${r1(y - r * 0.18)} ${r1(x + r)} ${y}Q${r1(x + r * 0.18)} ${r1(y + r * 0.18)} ${x} ${r1(y + r)}Q${r1(x - r * 0.18)} ${r1(y + r * 0.18)} ${r1(x - r)} ${y}Q${r1(x - r * 0.18)} ${r1(y - r * 0.18)} ${x} ${r1(y - r)}Z" fill="${fill}"/>`;
const plSmoke = (x, y, n = 3) => Array.from({ length: n }, (_, k) => `<circle class="pl-smoke" style="animation-delay:-${(k * 2.2 / n).toFixed(2)}s" cx="${x}" cy="${y}" r="2.2" fill="#e9e4dc"/>`).join('');
const plFlag = (h, color, w = 7) => `<path d="M0 0V${-h}" stroke="${PL_INK}" stroke-width="1" stroke-linecap="round"/><path class="pl-flag" d="M0.4 ${-h}h${w}l-2 2.4l2 2.4h${-w}Z" fill="${color}" stroke="${PL_INK}" stroke-width=".7" stroke-linejoin="round"/>`;
