// A planet, as an SVG. Each drawing gets its own ids, so many can share a page.
function planetSvg(number, cls = '') {
  const n = ((number - 1) % PLANETS.length + PLANETS.length) % PLANETS.length;
  const p = PLANETS[n];
  const id = `pl${++planetUid}`;
  const [light, mid, dark] = p.body;
  const R = PLANET_R;
  const ring = p.ring ? (front) => `<g transform="rotate(-14)"><path d="M${front ? '-56 0A56 11 0 0 0 56 0' : '56 0A56 11 0 0 0 -56 0'}" stroke="url(#${id}-r)" stroke-width="${front ? 6 : 5}" fill="none" opacity="${front ? 1 : 0.7}"/></g>` : () => '';
  return `<svg class="planet-svg ${cls}" viewBox="-64 -90 128 154" aria-hidden="true"><defs>
    <radialGradient id="${id}-b" cx="35%" cy="30%" r="80%"><stop offset="0" stop-color="${light}"/><stop offset=".55" stop-color="${mid}"/><stop offset="1" stop-color="${dark}"/></radialGradient>
    <radialGradient id="${id}-s" cx="34%" cy="28%" r="78%"><stop offset="0" stop-color="#ffffff" stop-opacity=".22"/><stop offset=".42" stop-color="#ffffff" stop-opacity="0"/><stop offset=".8" stop-color="#000000" stop-opacity=".22"/><stop offset="1" stop-color="#000000" stop-opacity=".5"/></radialGradient>
    <radialGradient id="${id}-g"><stop offset=".78" stop-color="${p.glow}" stop-opacity="0"/><stop offset=".86" stop-color="${p.glow}" stop-opacity=".5"/><stop offset="1" stop-color="${p.glow}" stop-opacity="0"/></radialGradient>
    ${p.ring ? `<linearGradient id="${id}-r" x1="0" x2="1"><stop offset="0" stop-color="${p.ring[2]}"/><stop offset=".5" stop-color="${p.ring[0]}"/><stop offset="1" stop-color="${p.ring[1]}"/></linearGradient>` : ''}
    <clipPath id="${id}-c"><circle r="${R}"/></clipPath></defs>
    <circle r="${R + 8}" fill="url(#${id}-g)"/>${p.sky || ''}${ring(false)}
    <g clip-path="url(#${id}-c)"><circle r="${R}" fill="url(#${id}-b)"/><g class="pl-ground"><g>${p.ground}</g><g transform="translate(${2 * R} 0)">${p.ground}</g></g><circle r="${R}" fill="url(#${id}-s)"/></g>
    <circle r="${R}" fill="none" stroke="${dark}" stroke-width="1.6"/><path d="M-33 -22A40 40 0 0 1 8 -39.2" stroke="#ffffff" stroke-opacity=".4" stroke-width="1.6" fill="none" stroke-linecap="round"/>
    ${ring(true)}${p.top}</svg>`;
}

/* --- Pip dresses for each world (3.29) --- */
// Pip wears something of the world he is in: a flower crown in the Meadow,
// a sailor's cap at the Harbor, a space helmet on the Moon, a crown in the
// King's Hall. Little things on him move: a butterfly, a lantern's flame, a
// blinking antenna, a frog on his lily-pad hat.
const PG_INK = '#3b2a1f';
// Pip's leaf again, moved, for when it pokes out of a hat.
const pipLeaf = (dx, dy, snow = false) => `<g transform="translate(${dx} ${dy})"><g class="pip-leaf"><path d="M50 22 C50 14 54 8 61 6 C62 13 58 19 50 22 Z" fill="#8fd16a" stroke="#3d6b22" stroke-width="2.5" stroke-linejoin="round"/><path d="M50 24 L50 18" stroke="#3d6b22" stroke-width="2.5" stroke-linecap="round"/>${snow ? '<path d="M53.4 13.6q2.6 -5.6 7.4 -6.6q.6 3 -1.4 5.4q-2.4 2.4 -6 1.2Z" fill="#ffffff"/>' : ''}</g></g>`;
const pgFlower = (x, y, petal, mid = '#ffd34d') => `<g transform="translate(${x} ${y})">${[0, 72, 144, 216, 288].map(a => `<circle transform="rotate(${a})" cy="-3.2" r="2.7" fill="${petal}" stroke="${PG_INK}" stroke-width=".9"/>`).join('')}<circle r="2.1" fill="${mid}" stroke="${PG_INK}" stroke-width=".8"/></g>`;
const pgSpark = (x, y, r, fill, delay = 0) => `<path class="pg-twinkle" style="animation-delay:-${delay}s" d="M${x} ${y - r}Q${x + r * 0.2} ${y - r * 0.2} ${x + r} ${y}Q${x + r * 0.2} ${y + r * 0.2} ${x} ${y + r}Q${x - r * 0.2} ${y + r * 0.2} ${x - r} ${y}Q${x - r * 0.2} ${y - r * 0.2} ${x} ${y - r}Z" fill="${fill}"/>`;

