const pipLooks = {};
// Pip's look: his body and face, with what he wears in that world.
function pipLook(number = state.world) {
  return pipLookFor(outfitOf('pip', number));
}

function pipWorldSvg(mood = 'idle', number = state.world) {
  const outfit = outfitOf('pip', number);
  return creatureSvg(pipLookFor(outfit), mood, `pip-svg pip-${outfit}`);
}

/* --- The journey to the next world (3.29) --- */
// Pip stands on the old planet, jumps into the portal, flies through the
// stars (his clothes change on the way, with a puff), and lands on the new
// planet, whose name comes up underneath. A tap skips it. With calm effects
// it is only the new planet and its name, shown for a moment.
const JOURNEY = { ms: 4800, calm: 1700, swap: 2300, land: 3550 };
let journeyForce = false;
let journeyEnd = null;
// Test browsers skip the journey, unless a test asks for it.
const journeyOn = () => journeyForce || !navigator.webdriver;

function journeyHtml(from, to) {
  const rand = seeded(to * 31 + 7);
  const hueOf = n => WORLDS[(n - 1) % WORLDS.length].hue;
  const [ha, hb] = [hueOf(from), hueOf(to)];
  let stars = '';
  for (let k = 0; k < 80; k++) {
    stars += `<circle cx="${r1(rand() * 360)}" cy="${r1(rand() * 720)}" r="${r1(0.4 + rand() * 1.2)}" fill="#ffffff" opacity="${(0.25 + rand() * 0.75).toFixed(2)}"${k % 6 ? '' : ' class="jr-tw"'} style="animation-delay:-${(rand() * 3).toFixed(1)}s"/>`;
  }
  let warp = '';
  for (let k = 0; k < 44; k++) {
    const len = r1(6 + rand() * 14);
    const color = k % 3 ? '#ffffff' : `hsl(${k % 2 ? ha : hb}, 90%, 78%)`;
    warp += `<g transform="rotate(${r1(rand() * 360)})"><path class="jr-streak" style="animation-delay:-${(rand() * 0.8).toFixed(2)}s" d="M0 -14V${-14 - len}" stroke="${color}" stroke-width="${r1(0.25 + rand() * 0.5)}" stroke-linecap="round"/></g>`;
  }
  const swirl = hue => `<svg viewBox="-50 -50 100 100" aria-hidden="true"><defs><radialGradient id="jr-p${hue}"><stop offset="0" stop-color="#ffffff"/><stop offset=".3" stop-color="hsl(${hue}, 95%, 80%)"/><stop offset=".7" stop-color="hsl(${hue}, 85%, 52%)" stop-opacity=".7"/><stop offset="1" stop-color="hsl(${hue}, 80%, 40%)" stop-opacity="0"/></radialGradient></defs>
    <circle r="49" fill="url(#jr-p${hue})"/><g class="jr-swirl" fill="none" stroke="#ffffff" stroke-linecap="round">${[0, 60, 120, 180, 240, 300].map(a => `<path transform="rotate(${a})" d="M4 0C10 -12 26 -16 38 -6" stroke-width="2.4" opacity=".75"/>`).join('')}</g>
    <circle class="jr-ring" r="40" fill="none" stroke="#ffffff" stroke-width="1.6" stroke-dasharray="3 7" opacity=".8"/></svg>`;
  const passing = [from - 1, to + 1].map(n => ((n - 1 + 32) % WORLDS.length) + 1);
  const info = worldInfo(to);
  return `<div class="jr-neb a" style="--h:${ha}"></div><div class="jr-neb b" style="--h:${hb}"></div>
    <svg class="jr-stars" viewBox="0 0 360 720" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${stars}</svg>
    <svg class="jr-warp" viewBox="-60 -60 120 120" aria-hidden="true">${warp}</svg>
    <div class="jr-pass p1">${planetSvg(passing[0])}</div><div class="jr-pass p2">${planetSvg(passing[1])}</div>
    <div class="jr-planet from">${planetSvg(from)}</div><div class="jr-planet to">${planetSvg(to)}</div>
    <div class="jr-portal">${swirl(ha)}</div>
    <div class="jr-pip"><div class="jr-pip-in"><div class="old">${pipSvg('happy', from)}</div><div class="new">${pipSvg('happy', to)}</div></div></div>
    <div class="jr-puff">${[0, 45, 90, 135, 180, 225, 270, 315].map((a, k) => `<i style="--a:${a}deg;--c:${k % 2 ? '#ffe28a' : '#ffffff'}"></i>`).join('')}</div>
    <div class="jr-dust">${[-1, -0.6, 0.6, 1].map(x => `<i style="--x:${x}"></i>`).join('')}</div>
    <div class="jr-flash"></div>
    <div class="jr-title"><small>${T`WORLD ${to}`}</small><b>${info.name}</b></div>`;
}

function journey(from, to) {
  return new Promise(done => {
    journeySkip();
    const calm = calmMotion();
    const el = document.createElement('div');
    el.id = 'journey';
    el.className = `journey${calm ? ' calm' : ''}`;
    el.setAttribute('aria-hidden', 'true');
    el.innerHTML = journeyHtml(from, to);
    document.body.appendChild(el);
    const timers = [];
    if (!calm) {
      [[0, 'warp'], [620, 'pip'], [JOURNEY.swap, 'poof'], [JOURNEY.land, 'pop'], [JOURNEY.land + 260, 'travel']]
        .forEach(([ms, kind]) => timers.push(setTimeout(() => sfx(kind), ms)));
      timers.push(setTimeout(() => buzz(30), JOURNEY.land));
    } else {
      sfx('travel');
    }
    let over = false;
    journeyEnd = (fast = false) => {
      if (over) return;
      over = true;
      journeyEnd = null;
      timers.forEach(clearTimeout);
      el.classList.add(fast ? 'skip' : 'out');
      setTimeout(() => {
        el.remove();
        done();
      }, fast ? 220 : 420);
    };
    el.addEventListener('pointerdown', () => journeyEnd && journeyEnd(true));
    timers.push(setTimeout(() => journeyEnd && journeyEnd(), (calm ? JOURNEY.calm : JOURNEY.ms) - 400));
  });
}

// Ends the journey at once (a tap, the back button, or a new journey).
function journeySkip() {
  if (journeyEnd) journeyEnd(true);
}

/* --- The world along the bottom bar (3.29) --- */
// The menu bar at the bottom wears the world you are in: grass and flowers
// with a ladybug in the Meadow, a pier with a crab at the Harbor, lava that
// glows on Ember Isle, a minecart in the Tunnel, torches at the Castle.
const EDGE = { w: 360, h: 18 };

function worldEdgeSvg(number) {
  const n = ((number - 1) % 16 + 16) % 16;
  const rand = seeded(4242 + n * 13);
  const { w: W, h: H } = EDGE;
  const ink = '#2a1c14';
  const many = (step, fn) => {
    let s = '';
    for (let x = 0, k = 0; x < W + step; x += step, k++) s += fn(x, k);
    return s;
  };
  const blades = (colors, lo, hi, step = 3.2) => many(step, x => {
    const h = lo + rand() * (hi - lo);
    const lean = (rand() - 0.5) * 3;
    return `<path d="M${r1(x - 1.4)} ${H}Q${r1(x + lean * 0.4)} ${r1(H - h * 0.6)} ${r1(x + lean)} ${r1(H - h)}Q${r1(x + 0.6)} ${r1(H - h * 0.5)} ${r1(x + 1.6)} ${H}Z" fill="${colors[Math.floor(rand() * colors.length)]}"/>`;
  });
  const spark = (x, y, r, fill, delay) => `<path class="we-twinkle" style="animation-delay:-${delay}s" d="M${x} ${y - r}Q${x + r * 0.2} ${y - r * 0.2} ${x + r} ${y}Q${x + r * 0.2} ${y + r * 0.2} ${x} ${y + r}Q${x - r * 0.2} ${y + r * 0.2} ${x - r} ${y}Q${x - r * 0.2} ${y - r * 0.2} ${x} ${y - r}Z" fill="${fill}"/>`;
  let s = '';
  switch (n + 1) {
    case 1: // The Meadow
      s += blades(['#3f8f3a', '#56a846', '#2f7a34'], 5, 13);
      s += [24, 70, 128, 182, 236, 300, 340].map((x, k) => `<g class="we-sway" style="animation-delay:-${k * 0.7}s"><path d="M${x} ${H}V${H - 10 - (k % 3) * 2}" stroke="#2f7a34" stroke-width="1"/><g transform="translate(${x} ${H - 11 - (k % 3) * 2})">${[0, 72, 144, 216, 288].map(a => `<circle transform="rotate(${a})" cy="-1.8" r="1.5" fill="${['#ffffff', '#ffb3d1', '#fff07a'][k % 3]}"/>`).join('')}<circle r="1.1" fill="${k % 3 === 2 ? '#e8902a' : '#ffd34d'}"/></g></g>`).join('');
      s += `<g class="we-walk slow"><g transform="translate(0 ${H - 3.4})"><ellipse rx="3" ry="2.4" fill="#e0403a" stroke="${ink}" stroke-width=".6"/><path d="M0 -2.4V2.4" stroke="${ink}" stroke-width=".5"/><circle cx="2.8" cy="-.4" r="1.3" fill="${ink}"/><g fill="${ink}"><circle cx="-1.2" cy="-1" r=".55"/><circle cx="1" cy="1" r=".55"/><circle cx="-1.4" cy="1.2" r=".5"/></g></g></g>`;
      break;
    case 2: // The Harbor
      s += `<rect y="${H - 5}" width="${W}" height="5" fill="#8a5a32"/>${many(18, x => `<path d="M${x} ${H - 5}v5" stroke="#5e3a1c" stroke-width=".8"/>`)}<path d="M0 ${H - 5}H${W}" stroke="#b07a44" stroke-width="1"/>`;
      s += many(60, x => `<rect x="${x - 2}" y="${H - 14}" width="4" height="10" rx="1" fill="#7a4a24" stroke="${ink}" stroke-width=".6"/><path d="M${x - 2} ${H - 12}h4" stroke="#c8a070" stroke-width=".8"/>`);
      s += many(60, x => `<path d="M${x + 2} ${H - 11}Q${x + 30} ${H - 4} ${x + 58} ${H - 11}" stroke="#e8d0a0" stroke-width="1.4" fill="none"/><path d="M${x + 2} ${H - 11}Q${x + 30} ${H - 4} ${x + 58} ${H - 11}" stroke="#a8855a" stroke-width="1.4" fill="none" stroke-dasharray="1.2 1.6"/>`);
      s += `<g class="we-walk"><g transform="translate(0 ${H - 7})"><ellipse rx="3.4" ry="2.2" fill="#e8603a" stroke="${ink}" stroke-width=".6"/><path d="M-3 -.6l-2 -2.2M3 -.6l2 -2.2M-2.4 1.4l-1.6 1.6M2.4 1.4l1.6 1.6" stroke="#e8603a" stroke-width=".9" stroke-linecap="round"/><circle cx="-1" cy="-2.4" r=".7" fill="${ink}"/><circle cx="1" cy="-2.4" r=".7" fill="${ink}"/></g></g>`;
      break;
    case 3: // Old Town
      s += many(9, (x, k) => `<rect x="${x + (k % 2) * 4.5 - 4.5}" y="${H - 4.6}" width="8" height="4.6" rx="1.6" fill="${k % 3 ? '#6a5a7a' : '#7a6a8a'}"/>`);
      s += [60, 180, 300].map((x, k) => `<path d="M${x} ${H - 3}V${H - 15}" stroke="#2a2438" stroke-width="1.2"/><path d="M${x - 2} ${H - 15}h4l-.6 -2.4h-2.8Z" fill="#2a2438"/><circle class="we-glow" style="animation-delay:-${k * 0.8}s" cx="${x}" cy="${H - 16}" r="4.4" fill="#ffd77a" opacity=".4"/><circle cx="${x}" cy="${H - 16}" r="1.2" fill="#fff4c0"/>`).join('');
      s += [118, 240].map(x => `<rect x="${x - 6}" y="${H - 8}" width="12" height="3.4" rx="1" fill="#8a5a32"/>${[-4, 0, 4].map((d, k) => `<circle cx="${x + d}" cy="${H - 9}" r="1.6" fill="${['#e0405a', '#ffd34d', '#ff8ab0'][k]}"/>`).join('')}`).join('');
      break;
    case 4: // Sunny Dunes
      s += `<path d="M0 ${H}V${H - 6}C40 ${H - 12} 80 ${H - 3} 120 ${H - 8}S200 ${H - 12} 240 ${H - 6}S320 ${H - 11} 360 ${H - 7}V${H}Z" fill="#e8b85a"/><path d="M0 ${H}V${H - 3}C50 ${H - 7} 90 ${H} 140 ${H - 4}S230 ${H - 7} 280 ${H - 3}S340 ${H - 5} 360 ${H - 4}V${H}Z" fill="#d49a3c"/>`;
      // 3.35: a saguaro with two arms and a flower (the one-armed kind read as a "4").
      s += [70, 250].map(x => {
        const d = `M${x} ${H - 4}V${H - 15}M${x} ${H - 8.6}h-3.4v-3.4M${x} ${H - 10.4}h3.2v-3`;
        return `<g fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="${d}" stroke="${ink}" stroke-width="4"/><path d="${d}" stroke="#4fae46" stroke-width="2.7"/><path d="M${x - 0.5} ${H - 14}V${H - 6}" stroke="#86d670" stroke-width=".7"/></g><circle cx="${x}" cy="${H - 15.8}" r="1.3" fill="#ff8fb0" stroke="${ink}" stroke-width=".4"/>`;
      }).join('');
      s += `<g class="we-roll"><g transform="translate(0 ${H - 8})"><g class="we-spin"><circle r="4" fill="none" stroke="#a87a44" stroke-width=".8"/><path d="M-3.6 -1q3.4 -3 7.2 .4M-3 2q3 2 6.4 -1M-1 -3.8q-2 4 1.6 7.6M1.6 -3.8q2 4 -1.6 7.6" stroke="#b08048" stroke-width=".7" fill="none"/></g></g></g>`;
      break;
    case 5: // Frost Peak
      s += `<path d="M0 ${H}V${H - 6}${many(24, x => `Q${x + 6} ${H - 12 - (x % 48 ? 0 : 3)} ${x + 12} ${H - 7}Q${x + 18} ${H - 10} ${x + 24} ${H - 6}`)}V${H}Z" fill="#f4f9ff"/><path d="M0 ${H - 2}H${W}" stroke="#cfe0ef" stroke-width="1.2"/>`;
      s += [40, 150, 270].map(x => `<path d="M${x} ${H - 5}l-4 0l4 -10l4 10Z" fill="#2f7a54"/><path d="M${x} ${H - 15}l-2 4.6q2 .8 4 0Z" fill="#ffffff"/>`).join('');
      s += [96, 210, 330, 18].map((x, k) => spark(x, H - 13 + (k % 2) * 3, 2.2, '#ffffff', k * 0.7)).join('');
      break;
    case 6: // Ember Isle
      s += `<path d="M0 ${H}V${H - 6}${many(20, x => `L${x + 7} ${H - 9 - rand() * 3}L${x + 14} ${H - 6}L${x + 20} ${H - 7}`)}V${H}Z" fill="#2a1410"/>`;
      s += `<path class="we-glow" d="M0 ${H - 2}${many(30, x => `L${x + 10} ${H - 4}L${x + 18} ${H - 1.6}L${x + 30} ${H - 3}`)}" stroke="#ff7a2a" stroke-width="1.2" fill="none"/>`;
      s += [50, 140, 220, 310].map((x, k) => `<circle class="we-rise" style="animation-delay:-${k * 0.9}s" cx="${x}" cy="${H - 8}" r="1" fill="#ffb03a"/>`).join('');
      break;
    case 7: // Moon Base
      s += `<rect y="${H - 6}" width="${W}" height="6" fill="#8a8e9a"/><path d="M0 ${H - 6}H${W}" stroke="#c8ccd6" stroke-width="1"/>${many(30, x => `<path d="M${x} ${H - 6}v6" stroke="#5e626e" stroke-width=".8"/><circle cx="${x + 3}" cy="${H - 3}" r=".8" fill="#c8ccd6"/><circle cx="${x + 27}" cy="${H - 3}" r=".8" fill="#c8ccd6"/>`)}`;
      s += [[150, 60]].map(([x, w]) => `<rect x="${x}" y="${H - 6}" width="${w}" height="6" fill="#ffd34d"/>${Array.from({ length: 8 }, (_, k) => `<path d="M${x + k * 8} ${H}l4 -6h4l-4 6Z" fill="#2a2a32"/>`).join('')}`).join('');
      s += [40, 110, 270, 330].map((x, k) => `<rect x="${x - 3}" y="${H - 11}" width="6" height="5" rx="1" fill="#c8ccd6" stroke="${ink}" stroke-width=".5"/><circle class="we-blink" style="animation-delay:-${k * 0.4}s" cx="${x}" cy="${H - 8.6}" r="1.2" fill="${k % 2 ? '#7fff9a' : '#ff5a5a'}"/>`).join('');
      break;
    case 8: // Star Sea
      s += `<path d="M0 ${H}V${H - 5}${many(40, x => `Q${x + 10} ${H - 10} ${x + 20} ${H - 5}T${x + 40} ${H - 5}`)}V${H}Z" fill="#4a34a8"/><path d="M0 ${H - 2}${many(40, x => `Q${x + 10} ${H - 5} ${x + 20} ${H - 2}T${x + 40} ${H - 2}`)}" stroke="#8a72e8" stroke-width="1" fill="none"/>`;
      s += Array.from({ length: 9 }, (_, k) => spark(r1(20 + k * 40 + rand() * 12), r1(H - 9 - rand() * 6), r1(1.4 + rand() * 1.4), k % 3 ? '#ffffff' : '#ffe680', r1(rand() * 3))).join('');
      break;
    case 9: // The Deep Cave
      s += `<path d="M0 ${H}V${H - 5}${many(16, x => `L${x + 8} ${H - 7 - rand() * 2}L${x + 16} ${H - 5}`)}V${H}Z" fill="#163a34"/>`;
      s += [[30, '#b48cf0'], [96, '#6fe0f0'], [168, '#ff9ad0'], [236, '#8ff4ff'], [312, '#c8a4ff']].map(([x, c], k) => `<g stroke="${ink}" stroke-width=".5" stroke-linejoin="round"><path d="M${x - 4} ${H - 4}l-1 -6l2 -2.4l2 2.4l-.4 6Z" fill="${c}"/><path d="M${x} ${H - 4}l.4 -9.6l2 -2.6l2 2.6l-.6 9.6Z" fill="${c}"/></g>${spark(x + 2.4, H - 13, 2, '#ffffff', k * 0.6).replace('we-twinkle', 'we-glint')}`).join('');
      break;
    case 10: // The Mountain
      s += `<path d="M0 ${H}V${H - 6}L20 ${H - 12}L34 ${H - 7}L58 ${H - 15}L80 ${H - 6}L104 ${H - 10}L130 ${H - 5}L160 ${H - 14}L186 ${H - 6}L212 ${H - 11}L240 ${H - 5}L270 ${H - 15}L296 ${H - 7}L320 ${H - 11}L360 ${H - 5}V${H}Z" fill="#6a7a92"/>`;
      s += [[58, 15], [160, 14], [270, 15]].map(([x, h]) => `<path d="M${x} ${H - h}l-4 4.6l2 .6l2 -1.6l2 1.4l2 -.6Z" fill="#ffffff"/>`).join('');
      s += [96, 226, 340].map(x => `<path d="M${x} ${H - 3}l-3 0l3 -8l3 8Z" fill="#2f6a48"/>`).join('');
      break;
    case 11: // The Tunnel
      s += `<rect y="${H - 7}" width="${W}" height="3" fill="#7a4a24"/><path d="M0 ${H - 7}H${W}" stroke="#a8743c" stroke-width=".8"/>${many(26, x => `<circle cx="${x + 4}" cy="${H - 5.5}" r=".6" fill="#3a2a1e"/>`)}`;
      s += `<path d="M0 ${H - 2}H${W}M0 ${H - .4}H${W}" stroke="#9aa0aa" stroke-width=".8"/>${many(8, x => `<path d="M${x} ${H - 2.4}v2.4" stroke="#5e3a20" stroke-width="1.6"/>`)}`;
      s += `<g class="we-walk slow"><g transform="translate(0 ${H - 3})"><path d="M-5 -1V-6h10V-1Z" fill="#8a5a32" stroke="${ink}" stroke-width=".6"/><g fill="#ffd34d"><circle cx="-2" cy="-6.4" r="1.4"/><circle cx="1.4" cy="-6.8" r="1.6"/></g><g fill="#2a2a32"><circle cx="-3" r="1"/><circle cx="3" r="1"/></g></g></g>`;
      break;
    case 12: // The Swamp
      s += blades(['#4a6a2a', '#5a7a32'], 3, 8, 4.6);
      s += [30, 120, 200, 290].map((x, k) => `<g class="we-sway" style="animation-delay:-${k * 0.6}s"><path d="M${x} ${H}V${H - 15}M${x + 3} ${H}V${H - 12}" stroke="#5a7a2a" stroke-width=".9"/><rect x="${x - 1}" y="${H - 15}" width="2" height="5" rx="1" fill="#7a4a24"/><rect x="${x + 2}" y="${H - 12}" width="2" height="4.4" rx="1" fill="#7a4a24"/></g>`).join('');
      s += [70, 160, 250, 340].map((x, k) => `<circle class="we-blink soft" style="animation-delay:-${k * 0.7}s" cx="${x}" cy="${H - 11 - (k % 2) * 3}" r="1.3" fill="#fff07a"/>`).join('');
      break;
    case 13: // The City Gate
      s += `<rect y="${H - 6}" width="${W}" height="6" fill="#a8916a"/>${many(14, x => `<rect x="${x}" y="${H - 10}" width="8" height="4.6" fill="#a8916a"/><path d="M${x} ${H - 6}h14" stroke="#8a7650" stroke-width=".6"/>`)}`;
      s += [80, 270].map((x, k) => `<g class="we-sway" style="animation-delay:-${k}s"><path d="M${x - 5} ${H - 10}h10v8l-5 -3l-5 3Z" fill="${k ? '#e0b13a' : '#3f78c8'}" stroke="${ink}" stroke-width=".5"/></g>`).join('');
      break;
    case 14: // City Square
      s += many(90, (x, k) => `<path d="M${x} ${H - 15}Q${x + 45} ${H - 5} ${x + 90} ${H - 15}" stroke="${ink}" stroke-width=".5" fill="none"/>${Array.from({ length: 7 }, (_, j) => {
        const t = (j + 0.5) / 7; const fx = x + 90 * t; const fy = H - 15 + 10 * 4 * t * (1 - t);
        return `<path class="we-sway" style="animation-delay:-${((k * 7 + j) * 0.31).toFixed(2)}s" d="M${r1(fx - 2.6)} ${r1(fy)}l2.6 5l2.6 -5Z" fill="${['#ffd34d', '#5fb8ff', '#ff6a6a', '#7fd36a', '#ff9ad0'][(k * 7 + j) % 5]}"/>`;
      }).join('')}`);
      break;
    case 15: // The Castle
      s += `<rect y="${H - 6}" width="${W}" height="6" fill="#8a90b0"/>${many(16, x => `<rect x="${x}" y="${H - 10}" width="9" height="4.6" fill="#8a90b0"/><path d="M${x} ${H - 3}h16" stroke="#6a7090" stroke-width=".6"/>`)}`;
      s += [60, 180, 300].map((x, k) => `<path d="M${x - 1} ${H - 6}l-1 -6h4l-1 6Z" fill="#5a3a24"/><path class="we-flame" style="animation-delay:-${k * 0.3}s" d="M${x} ${H - 12}q-3 -3 0 -7q3 4 0 7Z" fill="#ffb03a"/><circle class="we-glow" cx="${x}" cy="${H - 14}" r="5" fill="#ffb03a" opacity=".3"/>`).join('');
      break;
    case 16: // The King's Hall
      s += `<rect y="${H - 7}" width="${W}" height="7" fill="#a82830"/><path d="M0 ${H - 7}H${W}" stroke="#ffd34d" stroke-width="1.4"/><path d="M0 ${H - 1.4}H${W}" stroke="#e0a830" stroke-width=".8"/>${many(30, x => `<path d="M${x + 15} ${H - 6}l2 2l-2 2l-2 -2Z" fill="#ffd34d"/>`)}`;
      s += [45, 135, 225, 315].map((x, k) => `<path d="M${x - 5} ${H - 7}l-1 -6l3.4 2.4l2.6 -4l2.6 4l3.4 -2.4l-1 6Z" fill="#ffd34d" stroke="${ink}" stroke-width=".5" stroke-linejoin="round"/>${spark(x + 7, H - 13, 1.8, '#ffffff', k * 0.8)}`).join('');
      break;
    default:
      break;
  }
  return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMax slice" aria-hidden="true">${s}</svg>`;
}

// Puts the world's edge on the bottom bar (once per world).
function applyWorldEdge() {
  const nav = document.querySelector('.nav');
  if (!nav) return;
  let edge = nav.querySelector('.world-edge');
  if (!edge) {
    edge = document.createElement('div');
    edge.className = 'world-edge';
    edge.setAttribute('aria-hidden', 'true');
    nav.prepend(edge);
  }
  const n = String(((state.world - 1) % 16) + 1);
  if (edge.dataset.world === n) return;
  edge.dataset.world = n;
  edge.innerHTML = worldEdgeSvg(state.world);
}

/* --- A wallpaper for each world (3.29) --- */
// Behind the screens, a faint pattern of the world you are in: leaves,
// waves, bricks, ripples in the sand, snowflakes, cracks, craters, stars,
// crystals, peaks, wood grain, lily pads, stone, tiles and damask.
const WORLD_TEXTURES = [
  '<path d="M10 14q6 -8 12 0q-6 6 -12 0ZM34 36q6 -8 12 0q-6 6 -12 0Z" fill="#fff"/><circle cx="36" cy="10" r="1.6" fill="#fff"/><circle cx="12" cy="38" r="1.4" fill="#fff"/>',
  '<path d="M0 12q6 -6 12 0t12 0t12 0t12 0M0 36q6 -6 12 0t12 0t12 0t12 0" stroke="#fff" stroke-width="2" fill="none"/>',
  '<path d="M0 12h48M0 36h48M12 0v12M36 12v24M12 36v12" stroke="#fff" stroke-width="2" fill="none"/>',
  '<path d="M0 10q12 -6 24 0t24 0M0 26q12 -6 24 0t24 0M0 42q12 -6 24 0t24 0" stroke="#fff" stroke-width="1.6" fill="none"/>',
  '<g stroke="#fff" stroke-width="1.6" stroke-linecap="round"><path d="M14 6v14M8 9.5l12 7M8 16.5l12 -7M36 28v14M30 31.5l12 7M30 38.5l12 -7"/></g>',
  '<path d="M4 8l8 6l-2 8l10 6M30 2l6 8l-4 6l10 4M26 34l8 4l2 8" stroke="#fff" stroke-width="1.8" fill="none"/><circle cx="40" cy="30" r="1.6" fill="#fff"/>',
  '<circle cx="14" cy="14" r="7" fill="none" stroke="#fff" stroke-width="2"/><circle cx="36" cy="34" r="4" fill="none" stroke="#fff" stroke-width="2"/><circle cx="38" cy="10" r="1.6" fill="#fff"/>',
  '<path d="M12 4q1 6 6 7q-5 1 -6 7q-1 -6 -6 -7q5 -1 6 -7ZM36 28q.8 4.6 4.6 5.4q-3.8 .8 -4.6 5.4q-.8 -4.6 -4.6 -5.4q3.8 -.8 4.6 -5.4Z" fill="#fff"/><circle cx="38" cy="10" r="1.2" fill="#fff"/><circle cx="10" cy="38" r="1.2" fill="#fff"/>',
  '<path d="M12 2l10 6v12l-10 6l-10 -6V8ZM36 26l10 6v12l-10 6l-10 -6V32Z" stroke="#fff" stroke-width="1.8" fill="none"/>',
  '<path d="M0 20l12 -10l12 10l12 -10l12 10M0 44l12 -10l12 10l12 -10l12 10" stroke="#fff" stroke-width="2" fill="none"/>',
  '<path d="M0 8q12 3 24 0t24 0M0 20q12 -3 24 0t24 0M0 32q12 3 24 0t24 0M0 44q12 -3 24 0t24 0" stroke="#fff" stroke-width="1.4" fill="none"/><ellipse cx="30" cy="20" rx="3" ry="1.6" fill="none" stroke="#fff" stroke-width="1.2"/>',
  '<path d="M14 14m-7 0a7 7 0 1 0 7 -7l-1 7Z M36 36m-5 0a5 5 0 1 0 5 -5l-.8 5Z" fill="#fff"/>',
  '<path d="M0 16h48M0 32h48M16 0v16M40 16v16M24 32v16" stroke="#fff" stroke-width="2.4" fill="none"/>',
  '<path d="M24 0l24 24l-24 24l-24 -24Z" stroke="#fff" stroke-width="1.6" fill="none"/><circle cx="24" cy="24" r="2.4" fill="#fff"/>',
  '<path d="M0 24h48M24 0v24M12 24v24M36 24v24" stroke="#fff" stroke-width="2.4" fill="none"/><path d="M12 8l3 3l-3 3l-3 -3Z" fill="#fff"/>',
  '<path d="M24 4l8 12l-8 12l-8 -12ZM0 28l8 12l-8 12M48 28l-8 12l8 12" stroke="#fff" stroke-width="1.6" fill="none"/><circle cx="24" cy="16" r="2" fill="#fff"/><circle cx="0" cy="40" r="2" fill="#fff"/><circle cx="48" cy="40" r="2" fill="#fff"/>'
];

function worldTexture(number) {
  const art = WORLD_TEXTURES[((number - 1) % WORLD_TEXTURES.length + WORLD_TEXTURES.length) % WORLD_TEXTURES.length];
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48"><g opacity=".045">${art}</g></svg>`;
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
}

/* --- Little lives in the sky of each world (3.29) --- */
// Over each world's picture behind the coin, something of its own drifts by:
// petals, gulls, bats, sand, snow, embers, shooting stars, drips, mist, dust
// in the lamplight, bubbles, leaves, sky lanterns, a far-off dragon, gold.
const WORLD_PARTICLES = [['petal', 8], ['gull', 3], ['bat', 3], ['wisp', 8], ['flake', 16], ['ember', 12], ['shoot', 2], ['shoot', 3],
  ['drip', 6], ['mist', 3], ['dust', 10], ['bubble', 8], ['leaf', 7], ['lantern', 5], ['dragon', 1], ['gold', 12]];
const WP_SVG = {
  gull: '<svg viewBox="0 0 20 8"><path class="wp-flap" d="M1 6Q5 0 10 5Q15 0 19 6" stroke="#f4f6f8" stroke-width="1.6" fill="none" stroke-linecap="round"/></svg>',
  bat: '<svg viewBox="0 0 24 10"><path class="wp-flap" d="M12 5Q8 0 1 2Q4 4 3 7Q6 5 8 8Q10 6 12 7Q14 6 16 8Q18 5 21 7Q20 4 23 2Q16 0 12 5Z" fill="#1a1426"/><circle cx="11" cy="4.4" r=".5" fill="#ffd77a"/><circle cx="13" cy="4.4" r=".5" fill="#ffd77a"/></svg>',
  dragon: '<svg viewBox="0 0 60 26"><path d="M4 16q8 -2 14 2q6 3 12 0l8 -4q6 -2 10 0l6 -4l-2 6q4 2 6 0" stroke="#1a1838" stroke-width="3" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path class="wp-flap" d="M26 15Q24 2 36 0Q32 8 38 12Z" fill="#1a1838"/><circle cx="53" cy="12" r=".8" fill="#ff8a4a"/></svg>',
  lantern: '<svg viewBox="0 0 10 14"><path d="M1 3Q5 0 9 3V11Q5 13 1 11Z" fill="#ffb347"/><path d="M3 11h4v2h-4Z" fill="#8a4a20"/><ellipse cx="5" cy="8" rx="2" ry="3" fill="#fff4c8" opacity=".8"/></svg>'
};

function worldParticles(number) {
  const [kind, total] = WORLD_PARTICLES[(number - 1) % WORLD_PARTICLES.length];
  const count = weatherCount(total);
  const rand = seeded(number * 53 + 9);
  let html = '';
  for (let k = 0; k < count; k++) {
    const d = (kind === 'dragon' ? 38 : kind === 'shoot' ? 9 + rand() * 7 : kind === 'mist' ? 40 + rand() * 30 : 5 + rand() * 7).toFixed(1);
    const vars = `--d:${d}s;--delay:-${(rand() * Number(d)).toFixed(1)}s;--dx:${Math.round(rand() * 60 - 30)}px;--s:${(0.7 + rand() * 0.6).toFixed(2)}`;
    const left = `left:${(rand() * 96 + 2).toFixed(1)}%`;
    if (WP_SVG[kind] && kind !== 'lantern') html += `<i class="wp wp-${kind}" style="top:${(6 + rand() * (kind === 'dragon' ? 10 : 30)).toFixed(1)}%;${vars}"><b>${WP_SVG[kind]}</b></i>`;
    else if (['flake', 'ember', 'drip', 'bubble', 'lantern', 'petal', 'leaf'].includes(kind)) html += `<i class="wp wp-col wp-${kind}" style="${left};${vars}"><b>${kind === 'lantern' ? WP_SVG.lantern : ''}</b></i>`;
    else html += `<i class="wp wp-${kind}" style="${left};top:${(8 + rand() * 70).toFixed(1)}%;${vars}"><b></b></i>`;
  }
  return html;
}

/* --- The sound of each world (3.29) --- */
// Under the music, every world has a quiet sound of its own, made on the
// spot: a breeze and birdsong in the Meadow, waves and gulls at the Harbor,
// a church bell in Old Town, gusts in the Dunes, icy chimes on Frost Peak, a
// crackling volcano, the beeps of the Moon Base, drips in the cave, frogs and
// crickets in the Swamp, a fountain on City Square, torches at the Castle and
// a harp in the King's Hall. It has its own volume in Settings.
const AMBIENCE = {
  gain: 0.32,
  tick: 500,
  worlds: [
    ['breeze', [['bird', 4]]],
    ['waves', [['gull', 8]]],
    ['breeze', [['bell', 18], ['steps', 10]]],
    ['wind', [['gust', 7]]],
    ['wind', [['chime', 8]]],
    ['rumble', [['crackle', 1.2]]],
    ['hum', [['beep', 6]]],
    ['shimmer', [['chime', 5]]],
    ['cave', [['drip', 2.4]]],
    ['wind', [['eagle', 16], ['gust', 9]]],
    ['rumble', [['clink', 4]]],
    ['night', [['frog', 3], ['cricket', 2.2]]],
    ['breeze', [['hoof', 12], ['bird', 8]]],
    ['crowd', [['splash', 6], ['bird', 10]]],
    ['wind', [['crackle', 2], ['bell', 24]]],
    ['hall', [['harp', 8], ['crackle', 3]]]
  ]
};

const Ambience = {
  world: 0,
  // The planet open in the planet window, if any (3.33).
  planet: 0,
  out: null,
  bed: null,
  timer: 0,
  buffers: null,

  level() {
    return (state.settings.ambienceVol ?? 60) / 100;
  },

  // Starts, changes or stops the sound to fit the world and the settings.
  // It waits for the game's own sound to start (after the first tap).
  sync() {
    clearTimeout(this.timer);
    const ctx = audio;
    const want = ctx && this.level() > 0 ? (((this.planet || state.world) - 1) % AMBIENCE.worlds.length) + 1 : 0;
    try {
      if (ctx && this.out) this.out.gain.setTargetAtTime(this.level() * AMBIENCE.gain, ctx.currentTime, 0.3);
      if (want !== this.world) {
        this.fadeBed();
        this.world = want;
        if (want) this.startBed(ctx);
      }
    } catch (error) {
      this.world = 0;
      return;
    }
    if (want) this.timer = setTimeout(() => this.tick(), AMBIENCE.tick);
  },

  // Now and then, one of the world's little sounds.
  tick() {
    const ctx = audio;
    if (!ctx || !this.world) return;
    if (ctx.state === 'running' && !document.hidden && !appPaused) {
      for (const [kind, every] of AMBIENCE.worlds[this.world - 1][1]) {
        if (Math.random() < AMBIENCE.tick / 1000 / every) {
          try {
            this.play(kind, ctx);
          } catch (error) {
            // A sound that could not be made is left out.
          }
        }
      }
    }
    this.timer = setTimeout(() => this.tick(), AMBIENCE.tick);
  },

  // Pink and brown noise, made once, that loops without a click.
  noise(ctx) {
    if (this.buffers && this.buffers.rate === ctx.sampleRate) return this.buffers;
    const len = ctx.sampleRate * 4;
    const pink = ctx.createBuffer(1, len, ctx.sampleRate);
    const brown = ctx.createBuffer(1, len, ctx.sampleRate);
    const p = pink.getChannelData(0);
    const b = brown.getChannelData(0);
    let b0 = 0;
    let b1 = 0;
    let b2 = 0;
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      b0 = 0.99765 * b0 + white * 0.099046;
      b1 = 0.963 * b1 + white * 0.2965164;
      b2 = 0.57 * b2 + white * 1.0526913;
      p[i] = (b0 + b1 + b2 + white * 0.1848) * 0.16;
      last = (last + 0.02 * white) / 1.02;
      b[i] = last * 3.2;
    }
    const seam = Math.floor(ctx.sampleRate * 0.05);
    for (const data of [p, b]) {
      for (let k = 0; k < seam; k++) {
        const t = k / seam;
        data[len - seam + k] = data[len - seam + k] * (1 - t) + data[k] * t;
      }
    }
    this.buffers = { rate: ctx.sampleRate, pink, brown };
    return this.buffers;
  },

  // The world's steady sound, faded in.
  startBed(ctx) {
    const { pink, brown } = this.noise(ctx);
    if (!this.out) {
      this.out = ctx.createGain();
      this.out.gain.value = this.level() * AMBIENCE.gain;
      this.out.connect(ctx.destination);
    }
    const now = ctx.currentTime;
    const bed = { nodes: [], gain: ctx.createGain() };
    bed.gain.gain.setValueAtTime(0, now);
    bed.gain.gain.linearRampToValueAtTime(1, now + 2.5);
    bed.gain.connect(this.out);
    const src = buffer => {
      const s = ctx.createBufferSource();
      s.buffer = buffer;
      s.loop = true;
      s.start(now, Math.random() * 3);
      bed.nodes.push(s);
      return s;
    };
    const filter = (type, freq, q = 0.7) => {
      const f = ctx.createBiquadFilter();
      f.type = type;
      f.frequency.value = freq;
      f.Q.value = q;
      return f;
    };
    const amp = v => {
      const g = ctx.createGain();
      g.gain.value = v;
      return g;
    };
    const lfo = (rate, depth, target) => {
      const o = ctx.createOscillator();
      const g = amp(depth);
      o.frequency.value = rate;
      o.connect(g);
      g.connect(target);
      o.start(now);
      bed.nodes.push(o);
    };
    const tone = (freq, vol) => {
      const o = ctx.createOscillator();
      o.frequency.value = freq;
      o.start(now);
      bed.nodes.push(o);
      const g = amp(vol);
      o.connect(g);
      g.connect(bed.gain);
      return g;
    };
    const chain = (...nodes) => nodes.reduce((a, c) => (a.connect(c), c));
    const kind = AMBIENCE.worlds[this.world - 1][0];
    if (kind === 'breeze') {
      const f = filter('lowpass', 900);
      const g = amp(0.45);
      chain(src(pink), f, g, bed.gain);
      lfo(0.07, 0.25, g.gain);
      lfo(0.05, 300, f.frequency);
    } else if (kind === 'waves') {
      const f = filter('lowpass', 520);
      const g = amp(0.55);
      chain(src(brown), f, g, bed.gain);
      lfo(0.11, 0.45, g.gain);
      const foam = amp(0.05);
      chain(src(pink), filter('highpass', 2500), foam, bed.gain);
      lfo(0.11, 0.05, foam.gain);
    } else if (kind === 'wind') {
      const f = filter('bandpass', 600, 1.2);
      const g = amp(0.7);
      chain(src(pink), f, g, bed.gain);
      lfo(0.06, 350, f.frequency);
      lfo(0.09, 0.3, g.gain);
    } else if (kind === 'rumble') {
      chain(src(brown), filter('lowpass', 150), amp(0.9), bed.gain);
    } else if (kind === 'hum') {
      tone(55, 0.05);
      chain(src(brown), filter('lowpass', 400), amp(0.25), bed.gain);
    } else if (kind === 'shimmer') {
      [880, 1320, 1760].forEach((freq, k) => lfo(0.13 + k * 0.07, 0.03, tone(freq, 0.03).gain));
      chain(src(pink), filter('highpass', 4000), amp(0.03), bed.gain);
    } else if (kind === 'cave') {
      chain(src(brown), filter('lowpass', 260), amp(0.5), bed.gain);
    } else if (kind === 'night') {
      chain(src(pink), filter('bandpass', 1800, 0.6), amp(0.3), bed.gain);
    } else if (kind === 'crowd') {
      const g = amp(0.6);
      chain(src(pink), filter('bandpass', 700, 0.9), g, bed.gain);
      lfo(2.3, 0.12, g.gain);
      lfo(0.37, 0.1, g.gain);
    } else if (kind === 'hall') {
      chain(src(brown), filter('lowpass', 380), amp(0.35), bed.gain);
    }
    this.bed = bed;
  },

  fadeBed() {
    const bed = this.bed;
    this.bed = null;
    if (!bed || !audio) return;
    const now = audio.currentTime;
    bed.gain.gain.cancelScheduledValues(now);
    bed.gain.gain.setValueAtTime(bed.gain.gain.value, now);
    bed.gain.gain.linearRampToValueAtTime(0, now + 1.5);
    bed.nodes.forEach(node => {
      try {
        node.stop(now + 1.6);
      } catch (error) {
        // Already stopped.
      }
    });
    setTimeout(() => bed.gain.disconnect(), 1900);
  },

  // One little sound of the world.
  play(kind, ctx) {
    const t = ctx.currentTime + 0.05;
    const out = this.out;
    const r = Math.random;
    const tone = (freq, start, dur, vol, type = 'sine', glide = 0) => {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = type;
      o.frequency.setValueAtTime(freq, start);
      if (glide) o.frequency.exponentialRampToValueAtTime(glide, start + dur);
      g.gain.setValueAtTime(0.0001, start);
      g.gain.exponentialRampToValueAtTime(vol, start + Math.min(0.02, dur / 4));
      g.gain.exponentialRampToValueAtTime(0.0001, start + dur);
      o.connect(g);
      g.connect(out);
      o.start(start);
      o.stop(start + dur + 0.05);
    };
    const hiss = (start, dur, vol, type, freq, q = 1) => {
      const s = ctx.createBufferSource();
      s.buffer = this.noise(ctx).pink;
      const f = ctx.createBiquadFilter();
      f.type = type;
      f.frequency.value = freq;
      f.Q.value = q;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, start);
      g.gain.exponentialRampToValueAtTime(vol, start + dur * 0.3);
      g.gain.exponentialRampToValueAtTime(0.0001, start + dur);
      s.connect(f);
      f.connect(g);
      g.connect(out);
      s.start(start, r() * 3);
      s.stop(start + dur + 0.05);
    };
    if (kind === 'bird') {
      const base = 2600 + r() * 1400;
      for (let k = 0, n = 2 + Math.floor(r() * 3); k < n; k++) tone(base * (0.9 + r() * 0.3), t + k * 0.11, 0.08, 0.05, 'sine', base * (1.3 + r() * 0.4));
    } else if (kind === 'gull') {
      tone(1100, t, 0.35, 0.035, 'triangle', 650);
      tone(1200, t + 0.42, 0.3, 0.03, 'triangle', 700);
    } else if (kind === 'bell') {
      [1, 2.01, 2.42, 3.01].forEach((m, k) => tone(311 * m, t, 2.8 - k * 0.4, 0.035 / (k + 1)));
    } else if (kind === 'steps') {
      for (let k = 0, n = 2 + Math.floor(r() * 3); k < n; k++) hiss(t + k * 0.42, 0.09, 0.08, 'lowpass', 500);
    } else if (kind === 'gust') {
      hiss(t, 1.8, 0.12, 'bandpass', 900 + r() * 600, 0.8);
    } else if (kind === 'chime') {
      const f = [1568, 1760, 2093, 2349, 2637][Math.floor(r() * 5)];
      tone(f, t, 1.4, 0.03);
      tone(f * 2.76, t, 0.6, 0.01);
    } else if (kind === 'crackle') {
      for (let k = 0, n = 3 + Math.floor(r() * 6); k < n; k++) hiss(t + r() * 0.5, 0.025, 0.04 + r() * 0.1, 'highpass', 2000);
    } else if (kind === 'beep') {
      tone(880, t, 0.09, 0.025, 'square');
      tone(1320, t + 0.14, 0.09, 0.02, 'square');
    } else if (kind === 'drip') {
      const f = 900 + r() * 700;
      [[0, 0.06], [0.23, 0.02], [0.46, 0.008]].forEach(([d, v]) => tone(f, t + d, 0.06, v, 'sine', f * 2.1));
    } else if (kind === 'eagle') {
      tone(1900, t, 0.5, 0.02, 'sawtooth', 1300);
    } else if (kind === 'clink') {
      const f = 2100 + r() * 400;
      for (const d of r() < 0.5 ? [0, 0.6] : [0]) {
        tone(f, t + d, 0.25, 0.03);
        tone(f * 1.48, t + d, 0.18, 0.014);
      }
    } else if (kind === 'frog') {
      for (let k = 0, n = 2 + Math.floor(r() * 2); k < n; k++) tone(110 + r() * 30, t + k * 0.32, 0.18, 0.07, 'triangle', 85);
    } else if (kind === 'cricket') {
      const f = 4300 + r() * 600;
      for (let k = 0; k < 3; k++) tone(f, t + k * 0.07, 0.04, 0.016);
    } else if (kind === 'hoof') {
      [0, 0.18, 0.5, 0.68].forEach(d => hiss(t + d, 0.06, 0.1, 'lowpass', 320));
    } else if (kind === 'splash') {
      hiss(t, 0.5, 0.06, 'bandpass', 1800, 0.7);
    } else if (kind === 'harp') {
      const scale = [523, 587, 659, 784, 880, 1047];
      const k0 = Math.floor(r() * 3);
      for (let k = 0; k < 3; k++) tone(scale[k0 + k], t + k * 0.16, 1.4, 0.03, 'triangle');
    }
  }
};

