// Clouds and butterflies over a globe (HTML, so they move cheaply).
const GLOBE_CLOUD = '<svg viewBox="0 0 60 26"><path d="M8 24Q0 24 1 17Q2 11 9 12Q10 4 19 4Q26 3 29 9Q32 3 40 4Q48 5 48 12Q57 11 58 18Q58 24 50 24Z" fill="#ffffff"/><path d="M8 24Q3 24 3 20Q10 22 18 20Q28 23 38 20Q48 22 56 19Q57 24 50 24Z" fill="#d8e4f4"/></svg>';
const globeFly = (a, b) => `<svg viewBox="-6 -5 12 10"><g class="gs-wing l"><path d="M0 0Q-5 -6 -5.4 -1Q-5 2.6 0 0Z" fill="${a}" stroke="${PL_INK}" stroke-width=".6"/><path d="M0 .4Q-4 4.6 -2.2 4.4Q-.6 4 0 .4Z" fill="${b}" stroke="${PL_INK}" stroke-width=".6"/></g>
  <g class="gs-wing r"><path d="M0 0Q5 -6 5.4 -1Q5 2.6 0 0Z" fill="${a}" stroke="${PL_INK}" stroke-width=".6"/><path d="M0 .4Q4 4.6 2.2 4.4Q.6 4 0 .4Z" fill="${b}" stroke="${PL_INK}" stroke-width=".6"/></g>
  <path d="M0 -2.6v4.6" stroke="${PL_INK}" stroke-width="1.1" stroke-linecap="round"/></svg>`;

/* --- The planets to explore (3.31) --- */
// Every planet is a round world to walk around (3.33: in 2.5D). Ten places on
// it: people with a story, a critters' nest and a guard, a new friend, little
// games, treasure to dig up and things to gather. Swipe and the planet turns
// under Pip's feet; faraway mountains and hills turn slower, so it has depth.
// Any planet you have reached can be explored; the Meadow's places come first.
// Sizes are in units of a window 160 wide; the planet's radius is 125.
// top is where the planet's top stands in the window (160 wide, 144 high); S is how
// far each layer reaches from the planet's middle.
const GLOBE = { friction: 0.92, places: 10, R: 125, far: 139, mtn: 153, top: 88, S: { mtn: 185, far: 161, ground: 153 } };
const PLACE_WAIT = { nest: 2, guard: 8, game: 4, treasure: 8, gather: 3 };
const PLACE_ICONS = {
  story: '<path d="M4 5.5h16a1.5 1.5 0 0 1 1.5 1.5v8a1.5 1.5 0 0 1-1.5 1.5H10l-4.5 3.5V16.5H4A1.5 1.5 0 0 1 2.5 15V7A1.5 1.5 0 0 1 4 5.5Z" fill="currentColor"/>',
  fight: '<path d="M4 3l9.5 9.5M3.5 6.5l3-3M10.5 16.5l3-3M20 3l-9.5 9.5M20.5 6.5l-3-3M13.5 16.5l-3-3M6.5 17.5l-3 3M17.5 17.5l3 3" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/>',
  friend: '<path d="M12 20.5S3 15 3 9.2A4.7 4.7 0 0 1 12 7a4.7 4.7 0 0 1 9 2.2C21 15 12 20.5 12 20.5Z" fill="currentColor"/>',
  game: '<rect x="3" y="7" width="18" height="11" rx="5" fill="currentColor"/><path d="M8 10.5v4M6 12.5h4" stroke="#1b1d18" stroke-width="1.8" stroke-linecap="round"/><circle cx="15.5" cy="11.5" r="1.3" fill="#1b1d18"/><circle cx="17.5" cy="14" r="1.3" fill="#1b1d18"/>',
  treasure: '<path d="M6 4h12l4 5-10 11L2 9Z" fill="currentColor"/><path d="M2 9h20M9 4l3 16M15 4l-3 16" stroke="#1b1d18" stroke-width="1.2" opacity=".5"/>',
  gather: '<path d="M4 10h16l-1.6 9.5a2 2 0 0 1-2 1.5H7.6a2 2 0 0 1-2-1.5Z" fill="currentColor"/><path d="M7.5 10Q12 2 16.5 10" stroke="currentColor" stroke-width="2" fill="none"/>',
  home: '<path d="M3 11.6 12 4l9 7.6V20a1 1 0 0 1-1 1h-5.2v-6h-5.6v6H4a1 1 0 0 1-1-1Z" fill="currentColor"/>'
};
const PLACE_KIND_NAMES = { story: tr('Story'), fight: tr('Fight'), friend: tr('Friend'), game: tr('Minigame'), treasure: tr('Treasure'), gather: tr('Gather') };
const PLACE_GO = { story: tr('Talk'), fight: tr('Fight!'), friend: tr('Visit'), game: tr('Play'), treasure: tr('Dig'), gather: tr('Collect') };

// How a planet looks up close: its sky from space down to the horizon, its
// ground, the faraway mountains and hills, and what grows and lives on it. A
// planet without a look of its own is drawn from its colours.
const GLOBE_LOOKS = {
  1: {
    sky: ['#0c0b18', '#203a7a', '#79c4ee', '#d4f3ff'],
    ground: ['#b4ea7e', '#72c652', '#3f923b', '#235a26'],
    far: ['#a6da8c', '#77b671', '#86c278', '#5f9e62', '#c8edb2'],
    mtn: ['#a9cde6', '#86acc9', '#f6fbff'],
    trail: ['#8a6232', '#e9cf8e', '#f7e6b4'],
    flowers: ['#ff9ac4', '#fff3a0', '#ffffff', '#b9a4ff'],
    tuft: '#2f7a32',
    trees: true,
    deco: { tree: 10, blossom: 3, bush: 6, sheep: 3, rock: 4, hay: 3, fence: 3, mush: 4 },
    air: { clouds: 2, flies: [['#ffd34d', '#f2903a'], ['#cfe6ff', '#7aa8f0']] },
    seed: 7
  }
};

function globePalette(n) {
  const look = GLOBE_LOOKS[((n - 1) % WORLDS.length) + 1];
  if (look) return look;
  const [light, mid, dark] = PLANETS[(n - 1) % PLANETS.length].body;
  const g = PLANETS[(n - 1) % PLANETS.length].glow;
  return {
    sky: ['#0c0b18', mixHex('#1d1a3a', g, 0.3), mixHex(g, mid, 0.3), mixHex(g, '#ffffff', 0.5)],
    ground: [mixHex(light, '#ffffff', 0.15), light, mid, dark],
    far: [mixHex(light, g, 0.5), mixHex(mid, g, 0.45), mixHex(mid, g, 0.3), mixHex(dark, g, 0.35), mixHex(light, '#ffffff', 0.35)],
    mtn: [mixHex(g, '#8fa8d8', 0.55), mixHex(g, '#6a80b0', 0.6), '#f6fbff'],
    trail: [darker(mid, 0.4), mixHex(light, '#f1dfa8', 0.55), mixHex(light, '#ffffff', 0.6)],
    flowers: [mixHex(g, '#ffffff', 0.45), mixHex(light, '#ffffff', 0.55)],
    tuft: darker(mid, 0.3),
    trees: false,
    deco: { rock: 7 },
    air: null,
    seed: n * 13 + 5
  };
}

// The weather and the time of day on a planet: the same sky its world has
// right now (Coinbury's weather), and night by the clock (a test can set it).
let pvClock = null;
const pvNight = () => isNight(pvClock || new Date());
const planetWeather = n => weatherNow(Date.now(), homeWorld(n)).id;
const pvDim = (hex, t) => mixHex(hex, '#0b1238', t);
const PV_SKIES = {
  rain: ['#0c0b18', '#2a3a5a', '#7d8ea8', '#b9c4d2'],
  storm: ['#0c0b18', '#1c2438', '#4a5670', '#7b879c'],
  snow: ['#0c0b18', '#3a4f7a', '#aebfd8', '#e4ecf6'],
  fog: ['#0c0b18', '#3b4a6a', '#c2cbd6', '#e6eaee'],
  sand: ['#0c0b18', '#6a4a2a', '#d9a35c', '#f0d2a0'],
  heat: ['#0c0b18', '#6a3a1a', '#f2b36a', '#ffe0a8']
};
function pvLook(n, sky, night) {
  let L = { ...globePalette(n) };
  const to = (list, hex, t) => list.map(x => mixHex(x, hex, t));
  if (PV_SKIES[sky]) L.sky = PV_SKIES[sky];
  if (sky === 'rain' || sky === 'storm') {
    const t = sky === 'storm' ? 0.3 : 0.16;
    L = { ...L, ground: to(L.ground, '#3a4a5a', t), far: to(L.far, '#5a6a7a', t + 0.1), mtn: to(L.mtn, '#6a7890', t + 0.1) };
  }
  if (sky === 'snow') L = { ...L, ground: [mixHex(L.ground[0], '#ffffff', 0.7), ...L.ground.slice(1)], far: [mixHex(L.far[0], '#ffffff', 0.7), L.far[1], mixHex(L.far[2], '#ffffff', 0.45), L.far[3], '#ffffff'], mtn: to(L.mtn, '#ffffff', 0.3) };
  if (sky === 'fog') L = { ...L, far: to(L.far, '#e6eaee', 0.45), mtn: to(L.mtn, '#e6eaee', 0.6) };
  if (sky === 'sand') L = { ...L, far: to(L.far, '#d9a35c', 0.4), mtn: to(L.mtn, '#e0b070', 0.5) };
  if (!night) return L;
  return { ...L, night: true, sky: ['#04050d', pvDim(L.sky[1], 0.66), pvDim(L.sky[2], 0.62), pvDim(L.sky[3], 0.56)],
    ground: L.ground.map(x => pvDim(x, 0.46)), far: L.far.map(x => pvDim(x, 0.52)), mtn: L.mtn.map(x => pvDim(x, 0.5)),
    trail: L.trail.map(x => pvDim(x, 0.46)), flowers: L.flowers.map(x => pvDim(x, 0.3)), tuft: pvDim(L.tuft, 0.46) };
}

// In the sky behind the mountains: the sun or the moon, a rainbow after rain,
// the northern lights.
function pvSkyArt(sky, night) {
  let h = night ? '<i class="pv-moon"></i>' : `<i class="pv-sun${sky === 'heat' ? ' hot' : ''}${['rain', 'storm', 'snow', 'fog'].includes(sky) ? ' dim' : ''}"></i>`;
  if (sky === 'rainbow') {
    h += `<svg class="pv-rainbow" viewBox="0 0 160 144" preserveAspectRatio="none" aria-hidden="true"><g fill="none" stroke-width="2.6" opacity=".8">${['#ff5f5f', '#ffa24a', '#ffe15a', '#6ed36e', '#56a8ff', '#a274ff'].map((col, k) => {
      const r = 62 - k * 2.5;
      return `<path d="M${r1(96 - r)} 80A${r1(r)} ${r1(r)} 0 0 1 ${r1(96 + r)} 80" stroke="${col}"/>`;
    }).join('')}</g></svg>`;
  }
  if (sky === 'aurora') {
    h += `<svg class="pv-aurora" viewBox="0 0 160 144" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="pv-aur" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5dffb0" stop-opacity="0"/><stop offset=".45" stop-color="#5dffb0" stop-opacity=".55"/><stop offset=".8" stop-color="#5ad8ff" stop-opacity=".3"/><stop offset="1" stop-color="#c29aff" stop-opacity="0"/></linearGradient></defs>${[[0, 6, 1], [1, 20, 0.8], [2, 0, 0.6]].map(([k, y, o]) => `<path class="pv-curtain c${k}" d="M-10 ${y + 40}C20 ${y + 18} 46 ${y + 46} 80 ${y + 26}S136 ${y + 8} 170 ${y + 30}V${y + 64}C136 ${y + 44} 112 ${y + 70} 80 ${y + 58}S20 ${y + 52} -10 ${y + 72}Z" fill="url(#pv-aur)" opacity="${o}"/>`).join('')}</svg>`;
  }
  return h;
}

// Weather clouds hang in front of the mountains and behind the hills.
function pvCloudsHtml(sky, night) {
  const fill = { storm: '#4c5468', rain: '#9aa4b4', snow: '#e2e7ef', fog: '#dfe4ea', wind: '#ffffff' }[sky];
  if (!fill) return '';
  const col = night ? pvDim(fill, 0.55) : fill;
  return `<div class="pv-clouds${sky === 'wind' ? ' fast' : ''}" aria-hidden="true">${[[-6, 9, 1.15], [34, 3, 0.9], [70, 12, 1.25], [108, 5, 1], [140, 11, 1.1]].map(([x, y, k], i) => `<i style="left:${r1((x / 160) * 100)}%;top:${r1((y / 144) * 100)}%;--k:${k};--d:${26 + i * 7}s;--delay:-${i * 5}s"><svg viewBox="-16 -12 54 16" aria-hidden="true"><path d="M-14 3a14 7 0 0 1 4 -10a11 8 0 0 1 20 -2a12 6.5 0 0 1 26 9Z" fill="${col}"/><path d="M-14 3a20 5 0 0 1 40 -1Z" fill="${pvDim(col, 0.2)}" opacity=".45"/></svg></i>`).join('')}</div>`;
}

// In front of everything: the tint of the sky, rain, snow, sand or leaves, a
// storm's flashes, mist, the heat's shimmer, and fireflies on a Meadow night.
function pvAirHtml(sky, night, L) {
  const rand = seeded(Math.floor(Date.now() / WEATHER.slot) * 13 + 7);
  let h = '';
  if (['rain', 'storm', 'snow', 'fog', 'sand', 'heat'].includes(sky)) h += '<i class="pv-tint"></i>';
  if (sky === 'rain') h += weatherBits('drop', weatherCount(26), rand);
  if (sky === 'storm') h += weatherBits('drop', weatherCount(36), rand) + (weatherFlashes() ? '<i class="pv-flash"></i>' : '');
  if (sky === 'snow') h += weatherBits('flake', weatherCount(24), rand);
  if (sky === 'sand') h += weatherBits('grain', weatherCount(16), rand);
  if (sky === 'wind') h += weatherBits('leaf', weatherCount(7), rand);
  if (sky === 'fog') h += '<i class="w-mist m1"></i><i class="w-mist m2"></i>';
  if (sky === 'heat' && weatherCount(1)) h += '<i class="w-shimmer"></i>';
  if (night && L.trees && !['rain', 'storm', 'snow'].includes(sky)) {
    h += Array.from({ length: weatherCount(10) }, () => `<i class="pv-firefly" style="--x:${r1(6 + rand() * 88)}%;--y:${r1(54 + rand() * 30)}%;--d:${r1(4 + rand() * 4)}s;--delay:-${r1(rand() * 6)}s"></i>`).join('');
  }
  return h ? `<div class="pv-air sky-${sky}" aria-hidden="true">${h}</div>` : '';
}

const globeRand = seed => () => {
  seed = (seed * 16807) % 2147483647;
  return (seed - 1) / 2147483646;
};
// A point at an angle round the planet (0 is the top), r from its middle; a thing standing there.
const pvAt = (deg, r) => {
  const a = (deg * Math.PI) / 180;
  return [r1(r * Math.sin(a)), r1(-r * Math.cos(a))];
};
const pvStand = (deg, r, inner) => `<g transform="rotate(${r1(deg)}) translate(0 ${r1(-r)})">${inner}</g>`;
const pvGap = (a, b) => Math.abs(((((a - b) % 360) + 540) % 360) - 180);

// Faraway: a ring of blue mountains with snow on the tallest, in haze at their feet.
function pvMountains(L, rand) {
  const R = GLOBE.mtn;
  const peaks = [];
  for (let d = rand() * 10; d < 350; d += 15 + rand() * 13) peaks.push([d, 12 + rand() * 20, 6 + rand() * 4]);
  const hgt = d => Math.max(3, ...peaks.map(([p, h, w]) => h * Math.max(0, 1 - pvGap(d, p) / w)));
  const pt = (d, r) => pvAt(d, r).join(' ');
  let edge = '';
  for (let d = 0; d < 360; d += 1.5) edge += `${edge ? 'L' : 'M'}${pt(d, R + hgt(d))}`;
  let shade = '';
  let snow = '';
  for (const [p, h, w] of peaks) {
    shade += `M${pt(p, R + h)}L${pt(p - w, R)}L${pt(p, R - 4)}Z`;
    if (h > 21) {
      const k = 0.3;
      snow += `M${pt(p, R + h)}L${pt(p - w * k, R + h * (1 - k))}L${pt(p - w * k * 0.4, R + h * (1 - k * 0.7))}L${pt(p, R + h * (1 - k * 1.05))}L${pt(p + w * k * 0.5, R + h * (1 - k * 0.75))}L${pt(p + w * k, R + h * (1 - k))}Z`;
    }
  }
  return `<path d="${edge}Z" fill="${L.mtn[0]}"/><path d="${shade}" fill="${L.mtn[1]}" opacity=".55"/><path d="${snow}" fill="${L.mtn[2]}"/>
    <circle r="${GLOBE.far + 7}" fill="none" stroke="${L.sky[3]}" stroke-width="16" opacity=".5"/>`;
}

// Further back on the same world: soft hills, and little trees on the Meadow.
function pvFar(L, rand, uid) {
  const R = GLOBE.far;
  let hills = '';
  for (let p = rand() * 16; p < 350; p += 18 + rand() * 13) {
    const h = 5 + rand() * 6;
    const w = 7.5 + rand() * 5;
    let d0 = '';
    for (let d = p - w; d <= p + w + 0.01; d += 1.5) d0 += `${d0 ? 'L' : 'M'}${pvAt(d, R - 2 + h * Math.cos((((d - p) / w) * Math.PI) / 2) ** 2).join(' ')}`;
    hills += `${d0}Z`;
  }
  let s = `<defs><radialGradient id="${uid}-f"><stop offset=".86" stop-color="${L.far[1]}"/><stop offset="1" stop-color="${L.far[0]}"/></radialGradient></defs>
    <circle r="${R}" fill="url(#${uid}-f)"/><path d="${hills}" fill="${L.far[0]}"/><path d="${hills}" fill="none" stroke="${L.far[4]}" stroke-width=".8" opacity=".8"/>`;
  if (L.trees) for (let d = rand() * 4; d < 360; d += 3.3 + rand() * 4) s += pvStand(d, R - 1, `<g transform="scale(${r1(0.4 + rand() * 0.22)})">${plRoundTree(L.far[2], L.far[3], L.far[4], 1)}</g>`);
  else for (let d = rand() * 6; d < 360; d += 9 + rand() * 8) s += pvStand(d, R - 1, `<path d="M-3 .5Q-2.6 -${r1(3 + rand() * 4)} 0 -${r1(4 + rand() * 5)}Q2.6 -3 3 .5Z" fill="${L.far[1]}"/>`);
  return s;
}

// The ground under Pip's feet: lit at its edge, a sandy trail round it with
// pebbles, flowers and grass, and trees, sheep and the like standing in two rows.
function pvGround(L, rand, uid, list, home, sky) {
  const R = GLOBE.R;
  let s = `<defs><radialGradient id="${uid}-g"><stop offset=".5" stop-color="${L.ground[3]}"/><stop offset=".78" stop-color="${L.ground[2]}"/><stop offset=".93" stop-color="${L.ground[1]}"/><stop offset="1" stop-color="${L.ground[0]}"/></radialGradient></defs>
    <circle r="${R + 0.9}" fill="${PL_INK}"/><circle r="${R}" fill="url(#${uid}-g)"/>`;
  for (let k = 0; k < 20; k++) {
    const d = rand() * 360;
    const [x, y] = pvAt(d, R * (0.52 + rand() * 0.26));
    s += `<ellipse cx="${x}" cy="${y}" rx="${r1(8 + rand() * 8)}" ry="${r1(2.4 + rand() * 2)}" transform="rotate(${r1(d)} ${x} ${y})" fill="${k % 3 ? L.ground[3] : L.ground[0]}" opacity=".16"/>`;
  }
  s += `<circle class="gl-trail" r="${R - 14}" fill="none" stroke="${L.trail[0]}" stroke-width="7"/><circle class="gl-trail" r="${R - 14}" fill="none" stroke="${L.trail[1]}" stroke-width="5"/>
    <circle r="${R - 12.8}" fill="none" stroke="${L.trail[2]}" stroke-width="1" stroke-dasharray="5 7" opacity=".9"/>`;
  const dot = ([x, y], r) => `M${r1(x - r)} ${y}a${r} ${r} 0 1 0 ${r1(2 * r)} 0a${r} ${r} 0 1 0 ${r1(-2 * r)} 0`;
  let peb = '';
  for (let d = 0; d < 360; d += 2.4 + rand() * 3.2) peb += dot(pvAt(d, R - 16 + rand() * 4), r1(0.5 + rand() * 0.6));
  s += `<path d="${peb}" fill="${darker(L.trail[1], 0.25)}"/>`;
  for (const c of L.flowers) {
    let f = '';
    for (let k = 0; k < 32; k++) f += dot(pvAt(rand() * 360, rand() < 0.5 ? R - 10 + rand() * 7 : R * (0.62 + rand() * 0.18)), 0.8);
    s += `<path d="${f}" fill="${c}" stroke="${PL_INK}" stroke-width=".25"/>`;
  }
  let g = '';
  for (let d = 0; d < 360; d += 1.28) {
    const a = (d * Math.PI) / 180;
    const [ux, uy, tx, ty] = [Math.sin(a), -Math.cos(a), Math.cos(a), Math.sin(a)];
    const at = (lx, up) => `${r1((R - 0.4 + up) * ux + lx * tx)} ${r1((R - 0.4 + up) * uy + lx * ty)}`;
    g += `M${at(-1.2, 0)}L${at(-0.6, 2.2)}L${at(0, 0.2)}L${at(0.7, 2.6)}L${at(1.3, 0)}`;
  }
  s += `<path d="${g}" fill="none" stroke="${L.tuft}" stroke-width=".55" stroke-linejoin="round" stroke-linecap="round"/>`;
  if (sky === 'snow') s += `<circle r="${R - 1.4}" fill="none" stroke="#f2f7ff" stroke-width="3.2" opacity=".92"/><circle r="${R - 3.4}" fill="none" stroke="#f2f7ff" stroke-width="1.6" stroke-dasharray="3 5" opacity=".7"/>`;
  // Never in front of a place: the back row may stand behind one.
  const deg = u => (u / R) * 57.3;
  const taken = list.map(p => [p.lon, deg(16), deg(4.5)]);
  if (home) taken.push([0, deg(40), deg(40)]);
  const rows = [[], []];
  for (const [kind, count] of Object.entries(L.deco)) {
    for (let k = 0, tries = 0; k < count && tries < 300; tries++) {
      const d = rand() * 360;
      const back = rand() < 0.4;
      if (taken.some(([t, w, wb]) => pvGap(d, t) < (back ? (w > deg(8) ? wb : w) + deg(1.6) : w + deg(3.4)))) continue;
      taken.push([d, deg(back ? 1.6 : 3.4), deg(back ? 1.6 : 3.4)]);
      rows[back ? 0 : 1].push(pvStand(d, back ? R + 1.6 : R - 0.3, `<g class="gd" style="--d:-${r1(rand() * 3)}s" transform="scale(${back ? 2.2 : 2.9})"${back ? ' opacity=".9"' : ''}>${GLOBE_DECO[kind]}</g>`));
      k++;
    }
  }
  const deco = rows[0].join('') + rows[1].join('');
  return `${s}<g class="globe-deco">${deco}</g>${L.night ? `<g class="pv-dark" opacity=".42">${deco}</g>` : ''}`;
}

// Up close, at the bottom: big grass and flowers that slide by fastest.
function pvFront(L) {
  const dark = darker(L.ground[3], 0.25);
  const tuft = (x, k) => `<g transform="translate(${x} 22) scale(${k})"><path d="M-7 0Q-6 -9 -9 -16Q-3 -10 -2 -3Q-1 -12 1 -19Q2 -10 2 -2Q4 -10 9 -14Q5 -7 6 0Z" fill="${dark}"/><path d="M-1 -3Q-.4 -11 1 -17" stroke="${L.ground[2]}" stroke-width="1" fill="none" stroke-linecap="round"/></g>`;
  const daisy = (x, c) => `<g transform="translate(${x} 22) scale(.9)"><path d="M0 0Q1 -6 0 -11" stroke="${dark}" stroke-width="1.4" fill="none"/>${[0, 60, 120, 180, 240, 300].map(a => `<ellipse cy="-15" rx="1.9" ry="3.2" fill="${c}" stroke="${PL_INK}" stroke-width=".5" transform="rotate(${a} 0 -11.5)"/>`).join('')}<circle cy="-11.5" r="2.1" fill="#ffd34d" stroke="${PL_INK}" stroke-width=".5"/></g>`;
  let one = [[4, 1], [24, 0.8], [62, 1.1], [98, 0.85], [124, 1.15], [150, 0.9]].map(([x, k]) => tuft(x, k)).join('');
  if (L.trees) one += [[40, 0], [112, 1], [140, 2]].map(([x, k]) => daisy(x, L.flowers[k % L.flowers.length])).join('');
  return [0, 160, 320].map(x => `<g transform="translate(${x} 0)">${one}</g>`).join('');
}

// Coinbury, home on the Meadow: the houses built so far (the biggest in front,
// the others on a hill behind), and our coin in the square.
const PLACE_HOME = { id: 'home', n: 1, kind: 'home', lon: 0 };
const globePlace = id => (id === 'home' ? PLACE_HOME : PLACE_BY_ID[id]);
const GLOBE_HOME_COIN = `<g class="pv-coin"><path d="M-5 .6h10l-1.2 -3h-7.6Z" fill="#b3ab9c" stroke="${PL_INK}" stroke-width=".6"/>
  <circle cy="-10.6" r="7.6" fill="#b87414" stroke="${PL_INK}" stroke-width=".8"/><circle cy="-11" r="6.4" fill="#f7c64a"/><circle cy="-11" r="4.8" fill="none" stroke="#c98a1e" stroke-width=".7"/>
  <g fill="#a7620a"><circle cx="-1.35" cy="-11.6" r="1.45"/><circle cx="1.35" cy="-11.6" r="1.45"/><circle cy="-13.5" r="1.45"/></g><path d="M0 -11.2v3q0 .7 .7 1" stroke="#a7620a" stroke-width=".7" fill="none" stroke-linecap="round"/>
  <path d="M-4.6 -13.6a5.6 5.6 0 0 1 3 -3.2" stroke="#ffffff" stroke-width=".9" fill="none" stroke-linecap="round" opacity=".6"/></g>`;
function globeHomeSvg(night = false) {
  const R = GLOBE.R;
  const levels = state.city.levels || {};
  const built = BUILDINGS.filter(b => (levels[b.id] || 0) > 0).sort((a, b) => levels[b.id] - levels[a.id]).slice(0, 5);
  // The ground here curves away with the planet (ys), the hill rises out of it,
  // and every house stands on the ground under it, leaning with the curve.
  const ys = x => R - Math.sqrt(R * R - x * x);
  const hill = x => {
    const t = Math.min(1, Math.max(0, (Math.abs(x) - 25) / 13));
    return 13 * (1 - t * t * (3 - 2 * t));
  };
  const on = (x, lift, inner) => `<g transform="translate(${r1(x)} ${r1(ys(x) - lift)}) rotate(${r1((Math.asin(x / R) * 180) / Math.PI)})">${inner}</g>`;
  const place = (svg, w, cls) => svg.replace(/\sclass="[^"]*"/, cls).replace('<svg ', `<svg x="${-w / 2}" y="${r1(0.8 - w)}" width="${w}" height="${w}" overflow="visible" `);
  // The windows that are lit at night, from the same drawing the city uses.
  const lights = (b, w) => {
    const art = CITY_ART[b.id];
    const p = cityPen(art.seed, false);
    art.svg(p, Math.max(1, levels[b.id]));
    const top = art.flag ? 16 : 6;
    const rects = p.lights.filter(l => l.lit).map(l => `<rect x="${r1(l.x - 1.4)}" y="${r1(l.y - 1.4)}" width="${r1(l.w + 2.8)}" height="${r1(l.h + 2.8)}" rx="2.4" fill="#ffd87a" opacity=".3"/><rect x="${r1(l.x)}" y="${r1(l.y)}" width="${r1(l.w)}" height="${r1(l.h)}" rx="${l.kind === 'arch' ? r1(l.w / 2) : 0.6}" fill="#ffe08a"/>`).join('');
    return `<svg x="${-w / 2}" y="${r1(0.8 - w)}" width="${w}" height="${w}" viewBox="-8 ${-top} ${art.w + 16} ${art.h + top + 2}" preserveAspectRatio="xMidYMax meet" overflow="visible"><g class="pv-lit">${rects}</g></svg>`;
  };
  const house = (b, x, w, lift) => {
    const svg = buildingSvg(b.id, levels[b.id]);
    return on(x, lift, place(svg, w, '') + (night ? place(svg, w, ' class="pv-dark" opacity=".5"') + lights(b, w) : ''));
  };
  let top = '';
  for (let x = -38; x <= 38.01; x += 1) top += `${top ? 'L' : 'M'}${x} ${r1(ys(x) - hill(x))}`;
  let under = '';
  for (let x = 38; x >= -38.01; x -= 2) under += `L${x} ${r1(ys(x) + 1.4)}`;
  let ticks = '';
  for (let x = -36.5; x <= 36.5; x += 1.3) ticks += `M${r1(x - 0.9)} ${r1(ys(x) - hill(x) + 0.3)}l.45 -1.8.45 1.6.5 -2.1.45 2.1`;
  let square = '';
  for (let x = -12; x <= 12.01; x += 2) square += `${square ? 'L' : 'M'}${x} ${r1(ys(x) - 1.5)}`;
  for (let x = 12; x >= -12.01; x -= 2) square += `L${x} ${r1(ys(x) + 0.6)}`;
  const bush = x => on(x, -0.2, `<g transform="scale(2.5)">${GLOBE_DECO.bush}</g>`);
  return `<svg class="planet-svg" viewBox="-32 -37 64 38" aria-hidden="true"><defs><linearGradient id="pvh" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#a6e070"/><stop offset=".6" stop-color="#96d665"/><stop offset="1" stop-color="#b4ea7e"/></linearGradient><radialGradient id="pvcg"><stop offset="0" stop-color="#ffe9a0" stop-opacity=".75"/><stop offset="1" stop-color="#ffe9a0" stop-opacity="0"/></radialGradient></defs>
    <path d="${top}${under}Z" fill="url(#pvh)"/>${night ? `<path d="${top}${under}Z" fill="#0b1238" opacity=".46"/>` : ''}<path d="${top}" fill="none" stroke="${PL_INK}" stroke-width=".9" stroke-linejoin="round"/>
    <path d="${ticks}" fill="none" stroke="#2f7a32" stroke-width=".45" stroke-linejoin="round" stroke-linecap="round"/>
    ${built.slice(2).map((b, k) => house(b, [-16, 0, 16][k], 18, 13)).join('')}${bush(-34)}${bush(34)}
    <path d="${square}Z" fill="#d6c196" stroke="${PL_INK}" stroke-width=".5"/><path d="M-8 ${r1(ys(8) - 0.5)}h2M-2 -0.6h2.4M4 ${r1(ys(4) - 0.6)}h2" stroke="#b49a6a" stroke-width=".5" stroke-linecap="round"/>
    ${built.slice(0, 2).map((b, k) => house(b, [-19.5, 19.5][k], 24, 0)).join('')}${night ? '<circle cy="-11" r="14" fill="url(#pvcg)"/>' : ''}${GLOBE_HOME_COIN}</svg>`;
}

function globeSkyHtml(L) {
  if (!L || !L.air) return '';
  return `<div class="globe-sky" aria-hidden="true">${Array.from({ length: L.air.clouds }, (_, k) => `<i class="gs-cloud c${k + 1}"><b>${GLOBE_CLOUD}</b></i>`).join('')}${L.air.flies.map(([a, b], k) => `<i class="gs-fly f${k + 1}"><b>${globeFly(a, b)}</b></i>`).join('')}</div>`;
}
// The places. lon says where round the planet (Coinbury is at 0); reward is what the first
// time gives, again what a later time gives (coins in minutes of income).
const PLACES = [
  { id: 'm-mill', n: 1, kind: 'story', art: 'mill', lon: 34, name: tr('The Old Mill'), text: tr('Miller Mo grinds flour here. Something is wrong with the sails.'),
    who: 'miller', lines: [['miller', tr('Oh, hello! The Baron\'s critters ran off with the pin from my sails. Now the old mill just stands there.')], ['pip', tr('A pin? Like this shiny one in the grass?')], ['miller', tr('That\'s it! Bless you, little coin. Look, she turns again! Take this for the road.')]],
    reward: { diamonds: 2, minutes: 20 } },
  { id: 'm-cottage', n: 1, kind: 'story', art: 'cottage', lon: 66, name: tr('Granny\'s Cottage'), text: tr('Granny Pewter bakes pies and knows every old tale of the Meadow.'),
    who: 'granny', lines: [['granny', tr('Come in, come in! Pie? Of course you want pie.')], ['granny', tr('My granny said the fairy ring hides a gift for anyone who digs with kind hands.')], ['pip', tr('Kind hands! That\'s us. Thank you, Granny!')]],
    reward: { diamonds: 2, minutes: 20 } },
  { id: 'm-burrow', n: 1, kind: 'fight', art: 'burrow', lon: 99, name: tr('The Burrow'), text: tr('Critters have dug a nest under the hill. They come back now and then.'),
    critters: ['rustling', 'dustbunny', 'pebblet', 'gnomelet'], wait: 'nest', reward: { diamonds: 2, bricks: 3 }, again: { bricks: 2 } },
  { id: 'm-gate', n: 1, kind: 'fight', art: 'gate', lon: 131, name: tr('Thistle Gate'), text: tr('A big Drop Bear guards the gate. It is tougher than the rest.'),
    critters: ['dropbear'], variant: 'big', wait: 'guard', reward: { diamonds: 5, bricks: 5 }, again: { diamonds: 1, bricks: 3 } },
  { id: 'm-oak', n: 1, kind: 'friend', art: 'oak', lon: 164, name: tr('The Old Oak'), text: tr('Someone small is humming in the hollow of the oak.'),
    friend: 'pollen', needs: 5, lines: [['pollen', tr('Bzz! You helped the whole Meadow. The bees told me everything.')], ['pollen', tr('I\'m Pollen, and this is Hum. Can we come along? A touch of honey makes coins shine!')], ['pip', tr('Welcome aboard, Pollen! And Hum too.')]],
    reward: { diamonds: 3 } },
  { id: 'm-hive', n: 1, kind: 'game', art: 'hive', lon: 196, name: tr('Beehive Hill'), text: tr('Find the pairs, and the bees share their honey.'), game: 'memory', wait: 'game', reward: { diamonds: 2, minutes: 15 }, again: { minutes: 15 } },
  { id: 'm-scarecrow', n: 1, kind: 'game', art: 'scarecrow', lon: 228, name: tr('Scarecrow Field'), text: tr('Stack the hay bales high for the scarecrow.'), game: 'tower', wait: 'game', reward: { diamonds: 2, bricks: 3 }, again: { bricks: 3 } },
  { id: 'm-stump', n: 1, kind: 'treasure', art: 'stump', lon: 261, name: tr('The Hollow Stump'), text: tr('Something glints deep inside the old stump.'), wait: 'treasure', reward: { diamonds: 5 }, again: { minutes: 30 } },
  { id: 'm-ring', n: 1, kind: 'treasure', art: 'ring', lon: 293, name: tr('The Fairy Ring'), text: tr('A ring of mushrooms. They say it hides a gift.'), wait: 'treasure', reward: { diamonds: 4 }, again: { minutes: 30, diamonds: 1 } },
  { id: 'm-pond', n: 1, kind: 'gather', art: 'pond', lon: 326, name: tr('Mill Pond'), text: tr('Reeds, clover and smooth stones. They grow back.'), wait: 'gather', reward: { diamonds: 1, bricks: 4, minutes: 10 }, again: { bricks: 3, minutes: 10 } }
];
const PLACE_BY_ID = Object.fromEntries(PLACES.map(p => [p.id, p]));
const placesOf = n => PLACES.filter(p => p.n === ((n - 1) % WORLDS.length) + 1);

// A save's places, shape only (this runs while the game loads).
function placesSafe(raw) {
  const out = { done: {}, at: {}, full: [] };
  if (!raw || typeof raw !== 'object') return out;
  for (const key of ['done', 'at']) {
    const src = raw[key] && typeof raw[key] === 'object' ? raw[key] : {};
    for (const [id, value] of Object.entries(src)) {
      if (/^[a-z0-9-]{1,24}$/.test(id) && Number.isFinite(value) && value >= 0) out[key][id] = Math.floor(value);
    }
  }
  out.full = Array.isArray(raw.full) ? [...new Set(raw.full.filter(n => Number.isInteger(n) && n > 0 && n <= 64))] : [];
  return out;
}

const placeDone = p => (state.places.done[p.id] || 0) > 0;
const placeWait = p => (PLACE_WAIT[p.wait] || 0) * 3600 * 1000;
const placeReadyAt = p => (state.places.at[p.id] || 0) + placeWait(p);
const placeOnce = p => p.kind === 'story' || p.kind === 'friend';
const placeNeeds = p => (p.needs ? Math.max(0, p.needs - placesOf(p.n).filter(q => q !== p && placeDone(q)).length) : 0);
function placeReady(p, now = Date.now()) {
  if (placeOnce(p)) return !placeDone(p) && !placeNeeds(p);
  return !placeDone(p) || now >= placeReadyAt(p);
}

// Gives a place's reward (the first-time one, or the later one) and says what it was.
function placeReward(p) {
  const first = !placeDone(p);
  const r = first ? p.reward : p.again || {};
  const got = [];
  if (r.minutes) {
    const coins = giftCoins(r.minutes);
    earn(coins);
    got.push({ icon: '✦', label: format(coins), kind: 'coins' });
  }
  if (r.diamonds) {
    state.diamonds += r.diamonds;
    got.push({ icon: '◆', label: `+${r.diamonds}`, kind: 'diamonds' });
  }
  if (r.bricks && state.city.open) {
    const n = addBricks(r.bricks);
    got.push({ icon: BRICK_ICON, label: `+${n}`, kind: 'bricks' });
  }
  state.places.done[p.id] = (state.places.done[p.id] || 0) + 1;
  state.places.at[p.id] = Date.now();
  placeStamps(p.n);
  save();
  refresh();
  return got;
}

// All ten stamps on a planet: a bonus for good, and Pip is proud.
function placeStamps(n) {
  const list = placesOf(n);
  if (list.length < GLOBE.places || state.places.full.includes(n) || !list.every(placeDone)) return;
  state.places.full.push(n);
  afterTalk(() => pipSay(T`All ten stamps on ${worldInfo(n).name}! +3% taps and income for good.`, 'happy', 3600, true));
  sfx('fanfare');
}

/* The globe window. */
let globeN = 1;
let globeSel = '';
let globeFresh = false;
let globeView = null;

function openGlobe(n) {
  const want = n || (placesOf(state.world).length ? state.world : 1);
  globeN = Math.min(Math.max(1, want), Math.max(1, state.stats.bestWorld));
  const list = placesOf(globeN);
  if (!list.some(p => p.id === globeSel) && !(globeSel === 'home' && globeN === 1)) globeSel = (list.find(p => placeReady(p)) || list[0] || { id: '' }).id;
  globeFresh = true;
  openModal('globe', true);
}

// Pip stands on the ground like everything else and turns with the planet.
// When a place is picked he walks there (on its left, or beside Coinbury,
// which is wider), his friend at his side and a little dust at his feet.
const pvDeg = u => (u / GLOBE.R) * 57.3;
const pvPipLon = id => (globePlace(id) ? globePlace(id).lon : 0) - pvDeg(id === 'home' ? 44 : 26);

function pvWalk(v) {
  const p = v.pip;
  const { pip, buddy } = v.els;
  if (!p || !pip) return false;
  const calm = calmMotion();
  const d = ((p.target - p.lon) % 360 + 540) % 360 - 180;
  let walking = false;
  if (Math.abs(d) > 0.05 && !calm) {
    p.lon += Math.sign(d) * Math.min(Math.abs(d), Math.max(0.45, Math.min(2.2, Math.abs(d) * 0.055)));
    p.dir = Math.sign(d);
    walking = true;
  } else p.lon = p.target;
  const bd = ((p.lon - pvDeg(15) - p.blon) % 360 + 540) % 360 - 180;
  let tagging = false;
  if (Math.abs(bd) > 0.05 && !calm) {
    p.blon += Math.sign(bd) * Math.min(Math.abs(bd), Math.max(0.35, Math.abs(bd) * 0.09));
    tagging = true;
  } else p.blon += bd;
  pip.style.setProperty('--lon', p.lon.toFixed(2));
  if (buddy) buddy.style.setProperty('--lon', p.blon.toFixed(2));
  const look = (el, on, left) => {
    const key = `${on}${left}`;
    if (el.dataset.walk === key) return;
    el.dataset.walk = key;
    el.classList.toggle('walk', on);
    el.classList.toggle('to-l', left);
  };
  look(pip, walking, p.dir < 0);
  if (buddy) look(buddy, tagging, bd < 0);
  if (walking && state.settings.effects !== 'off' && ++p.puff % 8 === 0) pvPuff(v, p.lon - p.dir * pvDeg(5));
  return walking || tagging;
}

function pvPuff(v, lon) {
  const el = document.createElement('i');
  el.className = 'pv-puff';
  el.style.setProperty('--lon', lon.toFixed(1));
  el.innerHTML = '<b></b>';
  v.els.pip.before(el);
  setTimeout(() => el.remove(), 700);
}

function globeHtml() {
  const info = worldInfo(globeN);
  const list = placesOf(globeN);
  const stamps = list.filter(placeDone).length;
  const sky = planetWeather(globeN);
  const night = pvNight();
  const L = pvLook(globeN, sky, night);
  const uid = `pv${++planetUid}`;
  const rand = globeRand(L.seed);
  const home = globeN === 1;
  const reached = Math.min(PLANETS.length, Math.max(1, state.stats.bestWorld));
  const sel = id => (id === globeSel ? ' sel' : '');
  const pins = list.map(q => `<button class="globe-pin k-${q.kind}${sel(q.id)}${placeDone(q) ? ' stamped' : ''}" data-action="globe-place" data-id="${q.id}" data-lon="${q.lon}" aria-label="${q.name}" style="--lon:${q.lon};--top:${PLACE_TOP[q.art] || 20}">
      <svg class="planet-svg" viewBox="-14 -28 28 30" aria-hidden="true">${PLACE_ART[q.art]}</svg>${night ? `<svg class="planet-svg pv-dark" viewBox="-14 -28 28 30" opacity=".45" aria-hidden="true">${PLACE_ART[q.art]}</svg>` : ''}<i class="globe-badge"><svg viewBox="0 0 24 24" aria-hidden="true">${PLACE_ICONS[q.kind]}</svg></i></button>`).join('');
  const homePin = home ? `<button class="globe-pin pv-home k-home${sel('home')}" data-action="globe-place" data-id="home" data-lon="0" aria-label="${tr('Coinbury')}" style="--lon:0">${globeHomeSvg(night)}</button>` : '';
  const { S } = GLOBE;
  const box = n => `${-n} ${-n} ${2 * n} ${2 * n}`;
  const pipLon = globeView && globeView.n === globeN && globeView.pip ? globeView.pip.lon : pvPipLon(globeSel);
  const walkers = `<div class="globe-pip" style="--lon:${r1(pipLon)}">${pipSvg('happy', globeN)}</div>${state.buddy && FRIEND_BY_ID[state.buddy] ? `<div class="pv-buddy" style="--lon:${r1(pipLon - pvDeg(15))}">${friendSvg(state.buddy, 'happy')}</div>` : ''}`;
  let html = `<div class="globe-top"><div class="eyebrow">${T`WORLD ${globeN}`}${list.length ? ` · ${T`${stamps} of ${list.length} places`}` : ''}</div>
    <h2 id="modal-title">${info.name}<span>.</span></h2></div>
    <div class="globe-stage${night ? ' pv-night' : ''}" id="globe-stage" data-sky="${sky}" style="--glow:${PLANETS[(globeN - 1) % PLANETS.length].glow};--r:${GLOBE.R};--cy:${GLOBE.top + GLOBE.R}">
      <div class="pv-sky" style="background:linear-gradient(180deg, ${L.sky[0]} 0%, ${L.sky[1]} 24%, ${L.sky[2]} 46%, ${L.sky[3]} 58%)">${pvSkyArt(sky, night)}<i class="pv-next">${planetSvg((globeN % PLANETS.length) + 1, 'still')}</i></div>
      ${globeSkyHtml(L)}
      <div class="pv-layer pv-mtn" style="--s:${S.mtn}"><svg viewBox="${box(S.mtn)}" aria-hidden="true">${pvMountains(L, rand)}</svg></div>
      ${pvCloudsHtml(sky, night)}
      <div class="pv-layer pv-far" style="--s:${S.far}"><svg viewBox="${box(S.far)}" aria-hidden="true">${pvFar(L, rand, uid)}</svg></div>
      <div class="pv-layer pv-ground" style="--s:${S.ground}"><svg class="globe-svg" viewBox="${box(S.ground)}" aria-hidden="true">${pvGround(L, rand, uid, list, home, sky)}</svg><div class="globe-pins">${homePin}${pins}${walkers}</div></div>
      <div class="pv-front"><svg viewBox="0 0 480 22" aria-hidden="true">${pvFront(L)}</svg></div>
      ${pvAirHtml(sky, night, L)}
      ${list.length ? '' : `<p class="globe-soon">${tr('The places on this planet come in a later version. Spin it all you like!')}</p>`}
    </div>`;
  if (list.length) {
    const dot = (id, kind, name, done) => `<button class="globe-dot k-${kind}${sel(id)}${done ? ' stamped' : ''}" data-action="globe-place" data-id="${id}" role="tab" aria-selected="${id === globeSel}" aria-label="${name}"><svg viewBox="0 0 24 24" aria-hidden="true">${PLACE_ICONS[kind]}</svg></button>`;
    html += `<div class="globe-dots" role="tablist" style="--n:${list.length + (home ? 1 : 0)}">${home ? dot('home', 'home', tr('Coinbury'), false) : ''}${list.map(q => dot(q.id, q.kind, q.name, placeDone(q))).join('')}</div>`;
    html += `<div class="globe-card" id="globe-card">${globeCardHtml()}</div>`;
  }
  const shown = Array.from({ length: reached }, (_, k) => k + 1).filter(m => placesOf(m).length);
  if (shown.length > 1) html += `<div class="globe-planets">${shown.map(m => `<button class="globe-planet${m === globeN ? ' on' : ''}${placesOf(m).length ? ' has' : ''}" data-action="open-globe" data-n="${m}" aria-label="${worldInfo(m).name}">${planetSvg(m, 'still')}</button>`).join('')}</div>`;
  html += `<p class="note">${tr('Tap a place, or spin the planet with your finger.')}</p>`;
  return html;
}

function globeCardHtml() {
  const p = globePlace(globeSel);
  if (!p) return '';
  if (p.kind === 'home') {
    return `<div class="globe-card-head"><span class="globe-kind k-home"><svg viewBox="0 0 24 24" aria-hidden="true">${PLACE_ICONS.home}</svg>${tr('City')}</span></div>
    <h3>${tr('Coinbury')}</h3><p class="modal-copy">${tr('Welcome to Coinbury! Critters and bosses drop bricks, and with them we build our city.')}</p>
    ${state.city.open ? `<button class="modal-action" data-action="globe-go" data-id="home">${tr('Visit')}</button>` : ''}`;
  }
  const now = Date.now();
  const ready = placeReady(p, now);
  const first = !placeDone(p);
  const r = first ? p.reward : p.again || {};
  const chips = [r.minutes ? `<span class="pill">✦ ${format(giftCoins(r.minutes))}</span>` : '', r.diamonds ? `<span class="pill purple">+${r.diamonds} ◆</span>` : '',
    r.bricks && state.city.open ? `<span class="pill">+${r.bricks} ${BRICK_ICON}</span>` : ''].join('');
  let status = '';
  if (p.kind === 'friend' && placeDone(p)) status = T`${FRIEND_BY_ID[p.friend].name} lives with you now.`;
  else if (placeOnce(p) && placeDone(p)) status = tr('✓ Visited');
  else if (placeNeeds(p)) status = T`Help ${p.needs} places on ${worldInfo(p.n).name} first (${p.needs - placeNeeds(p)} of ${p.needs}).`;
  else if (!ready) status = T`Back in ${formatDuration((placeReadyAt(p) - now) / 1000)}`;
  const dig = globeView && globeView.dig && globeView.dig.id === p.id ? globeView.dig.n : 0;
  const button = ready ? `<button class="modal-action" data-action="globe-go" data-id="${p.id}">${PLACE_GO[p.kind]}${p.kind === 'treasure' && dig ? ` ${'•'.repeat(dig)}` : ''}</button>` : '';
  return `<div class="globe-card-head"><span class="globe-kind k-${p.kind}"><svg viewBox="0 0 24 24" aria-hidden="true">${PLACE_ICONS[p.kind]}</svg>${PLACE_KIND_NAMES[p.kind]}</span>${placeDone(p) ? '<span class="globe-stamp">✓</span>' : ''}</div>
    <h3>${p.name}</h3><p class="modal-copy">${p.text}</p>
    ${ready && chips ? `<div class="globe-chips">${first ? `<small>${tr('First time:')}</small>` : ''}${chips}</div>` : ''}
    ${status ? `<p class="globe-status">${status}</p>` : ''}${button}`;
}

// The planet turns: the ground and its places at full speed, the hills and the
// mountains behind slower, the grass up front faster. Every layer is turned
// whole, so a frame only moves a few pictures. While the window is open, the
// world sound is this planet's.
function globeStart() {
  const stage = $('globe-stage');
  if (!stage) return;
  const sel = globePlace(globeSel);
  const keep = globeView && globeView.n === globeN;
  const lon0 = pvPipLon(globeSel);
  const pip = keep && globeView.pip ? { ...globeView.pip, puff: 0 } : { lon: lon0, target: lon0, blon: lon0 - pvDeg(15), dir: 1, puff: 0 };
  globeView = { n: globeN, rot: keep ? globeView.rot : -(sel ? sel.lon : 0), target: keep ? globeView.target : null, vel: 0, raf: 0, drag: null, dig: keep ? globeView.dig : null, w: 0, u: 2, swallow: false, pip,
    els: { stage, ground: stage.querySelector('.pv-ground'), far: stage.querySelector('.pv-far'), mtn: stage.querySelector('.pv-mtn'), front: stage.querySelector('.pv-front'),
      pins: [...stage.querySelectorAll('.globe-pin')], pip: stage.querySelector('.globe-pip'), buddy: stage.querySelector('.pv-buddy') } };
  Ambience.planet = globeN;
  Ambience.sync();
  // A tap picks a place; a swipe anywhere turns the planet (and is not a tap).
  stage.onpointerdown = event => {
    globeView.drag = { x: event.clientX, last: event.clientX, t: performance.now(), on: false, id: event.pointerId };
  };
  stage.onpointermove = event => {
    const v = globeView;
    const d = v && v.drag;
    if (!d) return;
    if (!d.on) {
      if (Math.abs(event.clientX - d.x) < 7) return;
      d.on = true;
      v.target = null;
      v.vel = 0;
      stage.setPointerCapture?.(d.id);
    }
    const now = performance.now();
    // The ground under the finger follows it.
    const deg = ((event.clientX - d.last) * 180) / (Math.PI * GLOBE.R * v.u);
    v.rot += deg;
    v.vel = (deg * 16) / Math.max(8, now - d.t);
    d.last = event.clientX;
    d.t = now;
    globeDraw();
  };
  stage.onpointerup = stage.onpointercancel = () => {
    const v = globeView;
    if (!v || !v.drag) return;
    const was = v.drag.on;
    v.drag = null;
    if (!was) return;
    v.swallow = true;
    setTimeout(() => { v.swallow = false; }, 60);
    if (calmMotion()) v.vel = 0;
    globeLoop();
  };
  stage.addEventListener('click', event => {
    if (!globeView || !globeView.swallow) return;
    event.stopPropagation();
    event.preventDefault();
  }, true);
  globeDraw();
  globeLoop();
}

function globeLoop() {
  cancelAnimationFrame(globeView.raf);
  const step = () => {
    const v = globeView;
    if (!v || modalType !== 'globe' || !$('globe-stage')) return;
    let busy = false;
    if (v.target !== null) {
      const diff = ((v.target - v.rot) % 360 + 540) % 360 - 180;
      if (calmMotion() || Math.abs(diff) < 0.2) {
        v.rot += diff;
        v.target = null;
      } else {
        v.rot += diff * 0.1;
        busy = true;
      }
    } else if (!(v.drag && v.drag.on) && Math.abs(v.vel) > 0.05) {
      v.rot += v.vel;
      v.vel *= GLOBE.friction;
      busy = true;
    }
    const walking = pvWalk(v);
    globeDraw();
    if (busy || walking) v.raf = requestAnimationFrame(step);
  };
  globeView.raf = requestAnimationFrame(step);
}

// The window closes: the world sound goes back to the world you're in.
function globeClosed() {
  if (globeView) cancelAnimationFrame(globeView.raf);
  if (!Ambience.planet) return;
  Ambience.planet = 0;
  Ambience.sync();
}

function globeDraw() {
  const v = globeView;
  if (!v || !v.els || !v.els.stage.isConnected) return;
  const { stage, ground, far, mtn, front, pins } = v.els;
  if (stage.clientWidth !== v.w) {
    v.w = stage.clientWidth;
    v.u = Math.max(1, v.w / 160);
    stage.style.setProperty('--u', `${v.u.toFixed(4)}px`);
  }
  const r = v.rot;
  ground.style.transform = `rotate(${r.toFixed(2)}deg)`;
  far.style.transform = `rotate(${(r * 0.55).toFixed(2)}deg)`;
  mtn.style.transform = `rotate(${(r * 0.3).toFixed(2)}deg)`;
  const P = 160 * v.u;
  const dx = ((r * Math.PI) / 180) * GLOBE.R * 1.5 * v.u;
  front.style.transform = `translateX(${((((dx % P) + P) % P) - P).toFixed(1)}px)`;
  // Places round the back can't be tapped (or reached by keyboard).
  for (const pin of pins) {
    const off = pvGap(Number(pin.dataset.lon) + r, 0) > 58;
    if (pin.dataset.off !== String(off)) {
      pin.dataset.off = String(off);
      pin.style.visibility = off ? 'hidden' : '';
    }
  }
}

function globeSelect(id) {
  const p = globePlace(id);
  if (!p) return;
  globeSel = id;
  if (globeView) {
    globeView.target = -p.lon;
    globeView.vel = 0;
    if (globeView.pip) globeView.pip.target = pvPipLon(id);
    if (globeView.dig && globeView.dig.id !== id) globeView.dig = null;
  }
  for (const el of document.querySelectorAll('#modal-content .globe-pin, #modal-content .globe-dot')) {
    el.classList.toggle('sel', el.dataset.id === id);
    if (el.classList.contains('globe-dot')) el.setAttribute('aria-selected', String(el.dataset.id === id));
  }
  setHtml('globe-card', globeCardHtml());
  sfx('pop');
  if (globeView) globeLoop();
}

// Doing what the place is for.
function globeGo(id) {
  if (id === 'home') {
    if (!state.city.open) return;
    closeModal();
    go('city');
    return;
  }
  const p = PLACE_BY_ID[id];
  if (!p || !placeReady(p)) return;
  if (p.kind === 'story' || p.kind === 'friend') {
    const lines = p.lines.map(([who, text]) => ({ who, text, mood: 'happy' }));
    closeModal();
    dialogue(lines.slice(0, -1), { auto: true }).then(() => {
      if (p.kind === 'friend' && !state.friends.includes(p.friend)) {
        state.friends.push(p.friend);
        sfx('fanfare');
      }
      const got = placeReward(p);
      return dialogue([{ ...lines[lines.length - 1], gifts: got }], { auto: true });
    }).then(() => openGlobe(p.n));
    return;
  }
  if (p.kind === 'fight') {
    closeModal();
    if (monster) clearMonster();
    monster = { el: document.createElement('div'), kind: p.critters[Math.floor(Math.random() * p.critters.length)], variant: p.variant || '', until: Date.now() + 60000 };
    startFight();
    if (fight) {
      fight.place = p.id;
      modalQueue.push('globe');
      globeFresh = true;
    } else openGlobe(p.n);
    return;
  }
  if (p.kind === 'game') {
    placeRound = { id: p.id };
    gameStop();
    gameShown = p.game;
    gameFresh = true;
    openModal('game', true);
    return;
  }
  if (p.kind === 'treasure') {
    const v = globeView;
    if (!v.dig || v.dig.id !== p.id) v.dig = { id: p.id, n: 0 };
    v.dig.n++;
    const pin = document.querySelector(`#globe-stage .globe-pin[data-id="${p.id}"]`);
    if (pin) {
      pin.classList.remove('dig');
      void pin.offsetWidth;
      pin.classList.add('dig');
    }
    sfx('clack');
    buzz(15);
    if (v.dig.n < 3) {
      setHtml('globe-card', globeCardHtml());
      return;
    }
    v.dig = null;
    const got = placeReward(p);
    if (pin) pin.classList.add('found');
    sfx('loot');
    globePrize(p, got);
    return;
  }
  if (p.kind === 'gather') {
    const got = placeReward(p);
    sfx('claim');
    buzz(20);
    globePrize(p, got);
  }
}

// What a place gave, rising from it, and the card and the stamps updated.
function globePrize(p, got) {
  const stage = $('globe-stage');
  const pin = stage && stage.querySelector(`.globe-pin[data-id="${p.id}"]`);
  if (stage && pin) {
    const s = stage.getBoundingClientRect();
    const r = pin.getBoundingClientRect();
    const el = document.createElement('div');
    el.className = 'globe-prize';
    el.innerHTML = got.map(g => `<span>${g.label} ${g.icon}</span>`).join('');
    el.style.left = `${(r.left - s.left + r.width / 2).toFixed(1)}px`;
    el.style.top = `${(r.top - s.top).toFixed(1)}px`;
    stage.appendChild(el);
    setTimeout(() => el.remove(), 1800);
  }
  globeRefresh();
}

function globeRefresh() {
  if (modalType !== 'globe') return;
  setHtml('globe-card', globeCardHtml());
  const list = placesOf(globeN);
  for (const el of document.querySelectorAll('#modal-content .globe-pin, #modal-content .globe-dot')) {
    if (PLACE_BY_ID[el.dataset.id]) el.classList.toggle('stamped', placeDone(PLACE_BY_ID[el.dataset.id]));
  }
  const eyebrow = document.querySelector('#modal-content .globe-top .eyebrow');
  if (eyebrow && list.length) eyebrow.textContent = `${T`WORLD ${globeN}`} · ${T`${list.filter(placeDone).length} of ${list.length} places`}`;
}

// A minigame played at a place: its prize instead of the city's.
let placeRound = null;
function placeGameOver(result) {
  const p = PLACE_BY_ID[placeRound.id];
  const g = GAME_BY_ID[p.game];
  // A round counts when it went well enough: some buns, the pairs, a few bricks.
  const good = g.id === 'memory' ? result.score > 0 : result.score >= 4;
  if (!good || !placeReady(p)) return { prize: '', p };
  const got = placeReward(p);
  return { prize: got.map(x => `${x.label} ${x.icon}`).join(' · '), p };
}

// The fight at a place was won: its reward on top of the critter's loot.
function placeFightWon(id) {
  const p = PLACE_BY_ID[id];
  if (!p) return;
  const got = placeReward(p);
  // (A toast shows plain text: bricks by name.)
  if (got.length) notify(`${p.name}: ${got.map(x => `${x.label} ${x.kind === 'bricks' ? tr('Bricks') : x.icon}`).join(' · ')}`);
}

// Pollen, the Meadow's friend, wears clothes too.
FRIEND_METALS.pollen = { light: '#fff1b8', mid: '#f2b632', dark: '#8a5a0a', cheek: '#ff9a6a' };

// The way to the planets, at the top of the Worlds screen.
function exploreCardHtml() {
  const n = placesOf(state.world).length ? state.world : 1;
  const list = placesOf(n);
  const stamps = list.filter(placeDone).length;
  const ready = list.filter(p => placeReady(p)).length;
  return `<button class="explore-card" data-action="open-globe" data-n="${n}"><span class="explore-planet">${planetSvg(n)}</span>
    <span class="explore-text"><b>${tr('Explore the planets')}</b><small>${T`${stamps} of ${list.length} places on ${worldInfo(n).name}`}</small></span>
    ${ready ? `<i class="explore-dot">${ready}</i>` : ''}<span class="explore-go" aria-hidden="true">›</span></button>`;
}

// Your planet floats in a corner of the sky by the coin: a tap goes exploring,
// and a dot says how many places are waiting.
let scenePlanetKey = '';
function scenePlanetUpdate() {
  const el = $('scene-planet');
  if (!el) return;
  const n = placesOf(state.world).length ? state.world : 1;
  const ready = placesOf(n).filter(p => placeReady(p)).length;
  const key = `${n}:${ready}`;
  if (key === scenePlanetKey) return;
  scenePlanetKey = key;
  el.dataset.n = n;
  el.setAttribute('aria-label', tr('Explore the planets'));
  el.innerHTML = `${planetSvg(n)}${ready ? `<i class="explore-dot">${ready}</i>` : ''}`;
}
// Lets native app code (ads, store) talk to the game.
window.Coinfolk = { Monetization, grantProduct, products };

start();
